  description = "Tags to apply to all resources"
  type        = map(string)
  default = {
    Name        = "illumidesk-eks"
    Environment = "dev"
  }
}

resource "aws_ecr_repository" "illumidesk_repo" {
  name                 = var.repository_name
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = var.resource_tags
}

resource "aws_ecr_lifecycle_policy" "illumidesk_policy" {
  repository = aws_ecr_repository.illumidesk_repo.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images older than 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = "expire"
        }
      },
      {
        rulePriority = 2
        description  = "Expire images when total count exceeds 30"
        selection = {
          tagStatus   = "any"
          countType   = "imageCountMoreThan"
          countNumber = 30
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

