variable "aws_region" {
  description = "AWS region for resource deployment"
  type        = string
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "availability_zones" {
  description = "List of availability zones to create subnets in. Defaults to the first two AZs in the region."
  type        = list(string)
  default     = null
}

variable "subnet_cidrs" {
  description = "CIDR blocks for each subnet, corresponding to each AZ."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  effective_azs = var.availability_zones != null ? var.availability_zones : slice(data.aws_availability_zones.available.names, 0, 2)
  subnet_map = {
    for idx, az in local.effective_azs : idx => {
      az   = az
      cidr = var.subnet_cidrs[idx]
    }
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_subnet" "main" {
  for_each = local.subnet_map

  vpc_id            = aws_vpc.main.id
  cidr_block        = each.value.cidr
  availability_zone = each.value.az

  tags = {
    Name = "main-subnet-${each.key + 1}"
  }

  lifecycle {
    create_before_destroy = true
  }
}

