data "aws_caller_identity" "current" {}

resource "aws_kms_key" "sqs_encryption" {
  description             = "Customer-managed key for SQS SSE"
  key_usage               = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-policy-sqs"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow SQS service to use the key"
        Effect = "Allow"
        Principal = {
          Service = "sqs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

locals {
  queue_names = toset(["test-sqs", "test-sqs1"])
}

resource "aws_sqs_queue" "this" {
  for_each = local.queue_names

  name                       = each.key
  delay_seconds              = 90
  max_message_size           = 2048
  message_retention_seconds  = 86400
  receive_wait_time_seconds  = 10
  kms_master_key_id          = aws_kms_key.sqs_encryption.arn

  tags = {
    Environment = "production"
    Name        = each.key
  }

  lifecycle {
    prevent_destroy = true
  }
}

