variable "base_bucket_name" {
  description = "Base name for the S3 bucket"
  type        = string
  default     = "doc-io-files"
}

variable "force_destroy" {
  description = "Force destroy the bucket even if it contains objects"
  type        = bool
  default     = true
}

variable "allowed_account_id" {
  description = "AWS account ID allowed full S3 access"
  type        = string
  default     = "566373416292"
}

resource "random_integer" "bucket_suffix" {
  min = 1
  max = 50000
}

data "aws_caller_identity" "current" {}

resource "aws_kms_key" "doc_key" {
  description             = "Customer-managed KMS key for S3 SSE-KMS encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = data.aws_iam_policy_document.kms_key_policy.json
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type = "AWS"
      identifiers = [
        "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root",
        "arn:aws:iam::${var.allowed_account_id}:root"
      ]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
}

resource "aws_s3_bucket" "doc_bucket" {
  bucket        = "${random_integer.bucket_suffix.result}-${var.base_bucket_name}"
  force_destroy = var.force_destroy
}

resource "aws_s3_bucket_public_access_block" "doc_bucket" {
  bucket                  = aws_s3_bucket.doc_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "doc_bucket" {
  bucket = aws_s3_bucket.doc_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.doc_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

data "aws_iam_policy_document" "bucket_policy" {
  statement {
    sid    = "GrantFullS3AccessToAllowedAccount"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${var.allowed_account_id}:root"]
    }
    actions   = ["s3:*"]
    resources = [
      aws_s3_bucket.doc_bucket.arn,
      "${aws_s3_bucket.doc_bucket.arn}/*"
    ]
  }
}

resource "aws_s3_bucket_policy" "doc_bucket" {
  bucket = aws_s3_bucket.doc_bucket.id
  policy = data.aws_iam_policy_document.bucket_policy.json
}

