}

locals {
  account_id   = data.aws_caller_identity.current.account_id
  policy_name  = "${local.account_id}-powerscale-node-runtime-policy"
  role_name    = "${local.account_id}-powerscale-node-runtime-role"
  profile_name = "${local.account_id}-powerscale-node-runtime-instance-profile"

  # Build network interface ARNs for each region
  network_interface_arns = [
    for region in var.regions : "arn:aws:ec2:${region}:${local.account_id}:network-interface/*"
  ]
}

resource "aws_iam_policy" "powerscale_node_runtime" {
  name        = local.policy_name
  description = "Custom policy for PowerScale node runtime operations"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "ec2:AssignPrivateIpAddresses"
        Resource = local.network_interface_arns
      }
    ]
  })
}

resource "aws_iam_role" "powerscale_node_runtime" {
  name = local.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_instance_profile" "powerscale_node_runtime" {
  name = local.profile_name
  role = aws_iam_role.powerscale_node_runtime.name
}

resource "aws_iam_role_policy_attachment" "powerscale_node_runtime" {
  policy_arn = aws_iam_policy.powerscale_node_runtime.arn
  role       = aws_iam_role.powerscale_node_runtime.name
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "192.168.0.0/16"
}

