provider "aws" {
  region = "us-east-1"
}

data "aws_partition" "current" {}

variable "role_name" {
  description = "Name of the IAM role and instance profile"
  type        = string
  default     = "ec2-role"
}

variable "inline_policies" {
  description = "List of inline policies to attach to the IAM role"
  type = list(object({
    name   = string
    policy = string
  }))
  default = []
}

variable "managed_policy_arns" {
  description = "List of IAM managed policy ARNs to attach to the role"
  type        = list(string)
  default     = []
}

resource "aws_iam_role" "this" {
  name = var.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.${data.aws_partition.current.dns_suffix}"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_instance_profile" "this" {
  name = var.role_name
  role = aws_iam_role.this.name
}

resource "aws_iam_role_policy" "inline" {
  count  = length(var.inline_policies)
  name   = var.inline_policies[count.index].name
  role   = aws_iam_role.this.name
  policy = var.inline_policies[count.index].policy
}

resource "aws_iam_role_policy_attachment" "managed" {
  for_each   = toset(var.managed_policy_arns)
  role       = aws_iam_role.this.name
  policy_arn = each.value
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "availability_zone_count" {
  description = "Number of availability zones to use (minimum 1)"
  type        = number
  default     = 2
  validation {
    condition     = var.availability_zone_count >= 1
    error_message = "availability_zone_count must be at least 1."
  }
}

locals {
  cluster_name = "Fast-App"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "fast_app" {
  cidr_block = var.vpc_cidr
  tags = {
    Name    = "${local.cluster_name}-vpc"
    Cluster = local.cluster_name
  }
}

resource "aws_internet_gateway" "fast_app" {
  vpc_id = aws_vpc.fast_app.id
  tags = {
    Name    = "${local.cluster_name}-igw"
    Cluster = local.cluster_name
  }
}

resource "aws_subnet" "public" {
  count = var.availability_zone_count

  vpc_id                  = aws_vpc.fast_app.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name    = "${local.cluster_name}-public-${data.aws_availability_zones.available.names[count.index]}"
    Tier    = "public"
    Cluster = local.cluster_name
  }
}

resource "aws_subnet" "private" {
  count = var.availability_zone_count

  vpc_id            = aws_vpc.fast_app.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, (count.index + 1) * 10)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name    = "${local.cluster_name}-private-${data.aws_availability_zones.available.names[count.index]}"
    Tier    = "private"
    Cluster = local.cluster_name
  }
}

resource "aws_route_table" "fast_app_public" {
  vpc_id = aws_vpc.fast_app.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.fast_app.id
  }

  tags = {
    Name    = "${local.cluster_name}-public-rt"
    Cluster = local.cluster_name
  }
}

resource "aws_route_table" "fast_app_private" {
  vpc_id = aws_vpc.fast_app.id

  tags = {
    Name    = "${local.cluster_name}-private-rt"
    Cluster = local.cluster_name
  }
}

resource "aws_route_table_association" "public" {
  count = var.availability_zone_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.fast_app_public.id
}

resource "aws_route_table_association" "private" {
  count = var.availability_zone_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.fast_app_private.id
}

resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.fast_app.default_network_acl_id

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = aws_vpc.fast_app.cidr_block
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name    = "${local.cluster_name}-default-nacl"
    Cluster = local.cluster_name
  }
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.fast_app.id

  tags = {
    Name    = "${local.cluster_name}-default-sg"
    Cluster = local.cluster_name
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0"
    }
  }
}

variable "monitoring_account_ids" {
  description = "List of AWS account IDs allowed to assume the Grafana IAM role"
  type        = list(string)
  default     = ["123456789012"]
}

variable "grafana_workspace_name" {
  description = "Name of the Grafana workspace used for tagging"
  type        = string
  default     = "Grafana"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "grafana_role" {
  name               = "GrafanaIntegrationRole-${var.grafana_workspace_name}"
  assume_role_policy = data.aws_iam_policy_document.grafana_assume_role.json
  tags = {
    Name        = var.grafana_workspace_name
    Environment = "Production"
    ManagedBy   = "Terraform"
  }
  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "grafana_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["grafana.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = var.monitoring_account_ids
    }
  }
}

resource "aws_iam_policy" "grafana_policy" {
  name        = "GrafanaIntegrationPolicy-${var.grafana_workspace_name}"
  description = "Policy granting Grafana access to Amazon Managed Service for Prometheus and CloudWatch"
  policy      = data.aws_iam_policy_document.grafana_permissions.json
  tags = {
    Name        = var.grafana_workspace_name
    Environment = "Production"
    ManagedBy   = "Terraform"
  }
}

data "aws_iam_policy_document" "grafana_permissions" {
  statement {
    sid    = "AMPPermissions"
    effect = "Allow"
    actions = [
      "aps:QueryMetrics",
      "aps:GetSeries",
      "aps:GetLabels",
      "aps:GetMetricMetadata"
    ]
    resources = ["arn:aws:aps:*:${data.aws_caller_identity.current.account_id}:workspace/*"]
  }
  statement {
    sid    = "CloudWatchPermissions"
    effect = "Allow"
    actions = [
      "cloudwatch:GetMetricData",
      "cloudwatch:GetMetricStatistics",
      "cloudwatch:ListMetrics",
      "cloudwatch:DescribeAlarms"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy_attachment" "grafana_policy_attachment" {
  role       = aws_iam_role.grafana_role.name
  policy_arn = aws_iam_policy.grafana_policy.arn
}

