terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  environment = "development"
  common_tags = {
    Environment = local.environment
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "trade-tariff-development-vpc"
  })
}

# Public subnets
resource "aws_subnet" "public" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = count.index == 0 ? "10.0.1.0/24" : "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[count.index]

  # map_public_ip_on_launch removed to comply with AWS-0164 (no automatic public IP assignment)
  tags = merge(local.common_tags, {
    Name = "trade-tariff-dev-public-${count.index + 1}"
    Tier = "public"
  })
}

# Private subnets
resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = count.index == 0 ? "10.0.10.0/24" : "10.0.20.0/24"
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "trade-tariff-dev-private-${count.index + 1}"
    Tier = "private"
  })
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "trade-tariff-dev-igw"
  })
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "trade-tariff-dev-nat-eip"
  })
}

# NAT Gateway
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "trade-tariff-dev-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "trade-tariff-dev-public-rt"
  })
}

# Private route table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "trade-tariff-dev-private-rt"
  })
}

# Route table associations
resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Security group "allow-ssh"
resource "aws_security_group" "allow_ssh" {
  name        = "allow-ssh"
  description = "Allow SSH inbound and outbound traffic within VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "allow-ssh"
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data sources for dynamic values
data "aws_caller_identity" "current" {}

# Variables
variable "repository_name" {
  description = "Name of the ECR repository"
  type        = string
  default     = "my-ecr-repo"
}

variable "environment" {
  description = "Environment tag value"
  type        = string
  default     = "dev"
}

variable "image_tag_mutability" {
  description = "ECR image tag mutability (IMMUTABLE or MUTABLE)"
  type        = string
  default     = "IMMUTABLE"

  validation {
    condition     = contains(["IMMUTABLE", "MUTABLE"], var.image_tag_mutability)
    error_message = "image_tag_mutability must be either IMMUTABLE or MUTABLE."
  }
}

variable "encryption_type" {
  description = "Encryption type for ECR repository (AES256 or KMS)"
  type        = string
  default     = "AES256"

  validation {
    condition     = contains(["AES256", "KMS"], var.encryption_type)
    error_message = "Encryption type must be either AES256 or KMS."
  }
}

variable "enable_repository_policy" {
  description = "Enable repository policy to restrict pull access"
  type        = bool
  default     = false
}

variable "allowed_principals" {
  description = "List of AWS principal ARNs allowed to pull images (used when enable_repository_policy is true)"
  type        = list(string)
  default     = []
}

variable "enable_lifecycle_policy" {
  description = "Enable lifecycle policy for image cleanup"
  type        = bool
  default     = false
}

variable "lifecycle_policy" {
  description = "Lifecycle policy JSON (default removes untagged images older than 14 days)"
  type        = string
  default     = <<EOF
{
  "rules": [
    {
      "rulePriority": 1,
      "description": "Expire untagged images older than 14 days",
      "selection": {
        "tagStatus": "untagged",
        "countType": "sinceImagePushed",
        "countUnit": "days",
        "countNumber": 14
      },
      "action": {
        "type": "expire"
      }
    }
  ]
}
EOF
}

# Local values
locals {
  common_tags = {
    Name        = var.repository_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
  kms_key_arn = var.encryption_type == "KMS" ? aws_kms_key.ecr[0].arn : null
}

# KMS key (conditional)
resource "aws_kms_key" "ecr" {
  count = var.encryption_type == "KMS" ? 1 : 0

  description             = "KMS key for ECR repository ${var.repository_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = data.aws_iam_policy_document.kms_key_policy[0].json
  tags                    = local.common_tags
}

resource "aws_kms_alias" "ecr" {
  count = var.encryption_type == "KMS" ? 1 : 0

  name          = "alias/ecr-${var.repository_name}"
  target_key_id = aws_kms_key.ecr[0].key_id
}

data "aws_iam_policy_document" "kms_key_policy" {
  count = var.encryption_type == "KMS" ? 1 : 0

  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "Allow ECR Service to Use Key"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ecr.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }
}

# ECR Repository
resource "aws_ecr_repository" "main" {
  name                 = var.repository_name
  image_tag_mutability = var.image_tag_mutability
  force_delete         = false

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = var.encryption_type
    kms_key         = local.kms_key_arn
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# Repository Policy (conditional)
resource "aws_ecr_repository_policy" "main" {
  count = var.enable_repository_policy ? 1 : 0

  repository = aws_ecr_repository.main.name
  policy     = data.aws_iam_policy_document.repository_policy[0].json
}

data "aws_iam_policy_document" "repository_policy" {
  count = var.enable_repository_policy ? 1 : 0

  statement {
    sid    = "AllowPullAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = var.allowed_principals
    }
    actions = [
      "ecr:BatchGetImage",
      "ecr:GetDownloadUrlForLayer",
      "ecr:DescribeImages",
      "ecr:ListImages"
    ]
    resources = [aws_ecr_repository.main.arn]
  }
}

# Lifecycle Policy (conditional)
resource "aws_ecr_lifecycle_policy" "main" {
  count = var.enable_lifecycle_policy ? 1 : 0

  repository = aws_ecr_repository.main.name
  policy     = var.lifecycle_policy
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "environment" {
  description = "Deployment environment"
  type        = string
  default     = "development"
}

variable "queue_name_prefix" {
  description = "Prefix for the SQS queue name"
  type        = string
  default     = "app-queue"
}

variable "is_fifo" {
  description = "Whether the queue is FIFO"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication (FIFO only)"
  type        = bool
  default     = false
}

variable "principal_arn" {
  description = "ARN of the principal allowed to send messages (leave empty to disable policy)"
  type        = string
  default     = ""
}

variable "tags" {
  description = "Tags to apply to resources"
  type        = map(string)
  default     = {}
}

# Locals
locals {
  queue_name = var.is_fifo ? "${var.queue_name_prefix}.fifo" : var.queue_name_prefix
  common_tags = merge(var.tags, {
    Name        = local.queue_name
    Environment = var.environment
  })
}

# SQS Queue
resource "aws_sqs_queue" "this" {
  name                        = local.queue_name
  fifo_queue                  = var.is_fifo
  content_based_deduplication = var.content_based_deduplication
  sqs_managed_sse_enabled     = true
  tags                        = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# Conditional queue policy
data "aws_iam_policy_document" "sqs_policy" {
  count = var.principal_arn != "" ? 1 : 0

  statement {
    effect    = "Allow"
    actions   = ["sqs:SendMessage"]
    resources = [aws_sqs_queue.this.arn]

    principals {
      type        = "AWS"
      identifiers = [var.principal_arn]
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count     = var.principal_arn != "" ? 1 : 0
  queue_url = aws_sqs_queue.this.id
  policy    = data.aws_iam_policy_document.sqs_policy[0].json
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_count = length(data.aws_availability_zones.available.names)
  az_names = data.aws_availability_zones.available.names
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "dsql-vpc"
  }
}

# Subnets
resource "aws_subnet" "private" {
  count             = local.az_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone = local.az_names[count.index]

  tags = {
    Name = "dsql-private-${count.index}"
  }
}

resource "aws_subnet" "public" {
  count             = local.az_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, local.az_count + count.index)
  availability_zone = local.az_names[count.index]

  tags = {
    Name = "dsql-public-${count.index}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "dsql-igw"
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "dsql-nat-eip"
  }
}

# NAT Gateway
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "dsql-nat"
  }
}

# Route Tables
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "dsql-public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "dsql-private-rt"
  }
}

# Route Table Associations
resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = local.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Security Group
resource "aws_security_group" "dsql" {
  name        = "dsql-security-group"
  description = "Security group for DSQL cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from VPC"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Outbound traffic to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "dsql-sg"
  }
}

# DB Subnet Group
resource "aws_db_subnet_group" "dsql" {
  name       = "dsql-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "dsql-subnet-group"
  }
}

# KMS Key
resource "aws_kms_key" "dsql" {
  description             = "KMS key for DSQL cluster encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow DSQL Service to Use Key"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

# IAM Role
resource "aws_iam_role" "dsql_cluster" {
  name = "dsql-cluster-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "dsql_cluster" {
  name        = "dsql-cluster-policy"
  description = "Policy for DSQL cluster to use KMS and publish logs"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:Encrypt"
        ]
        Resource = aws_kms_key.dsql.arn
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "dsql_cluster" {
  role       = aws_iam_role.dsql_cluster.name
  policy_arn = aws_iam_policy.dsql_cluster.arn
}

# Random password for master user
resource "random_password" "master" {
  length  = 16
  special = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

# Secrets Manager secret for master password
resource "aws_secretsmanager_secret" "master" {
  name        = "${var.cluster_identifier}-master-password"
  description = "Master password for Aurora cluster"
}

resource "aws_secretsmanager_secret_version" "master" {
  secret_id     = aws_secretsmanager_secret.master.id
  secret_string = random_password.master.result
}

# Primary Aurora Cluster
resource "aws_rds_cluster" "primary" {
  cluster_identifier = var.cluster_identifier
  engine             = var.engine
  engine_version     = var.engine_version
  master_username    = var.master_username
  master_password    = aws_secretsmanager_secret_version.master.secret_string
  vpc_security_group_ids = [aws_security_group.dsql.id]
  db_subnet_group_name   = aws_db_subnet_group.dsql.name
  deletion_protection    = var.deletion_protection
  skip_final_snapshot    = var.skip_final_snapshot
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.dsql.arn

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [aws_secretsmanager_secret_version.master]
}

# Secondary Aurora Cluster (for multi-region support)
resource "aws_rds_cluster" "secondary" {
  count = var.enable_multi_region ? 1 : 0

  cluster_identifier = "${var.cluster_identifier}-secondary"
  engine             = var.engine
  engine_version     = var.engine_version
  master_username    = var.master_username
  master_password    = aws_secretsmanager_secret_version.master.secret_string
  vpc_security_group_ids = [aws_security_group.dsql.id]
  db_subnet_group_name   = aws_db_subnet_group.dsql.name
  deletion_protection    = var.deletion_protection
  skip_final_snapshot    = var.skip_final_snapshot
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.dsql.arn

  # Uncomment below lines for true cross-region read replica:
  # replication_source_identifier = aws_rds_cluster.primary.arn
  # source_region                 = var.secondary_region

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [aws_secretsmanager_secret_version.master, aws_rds_cluster.primary]
}

# Variables
variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "cluster_identifier" {
  description = "Identifier for the primary Aurora cluster"
  type        = string
  default     = "aurora-cluster-primary"
}

variable "engine" {
  description = "Database engine (e.g., aurora-mysql, aurora-postgresql, mysql, postgres)"
  type        = string
  default     = "aurora-mysql"
}

variable "engine_version" {
  description = "Engine version (compatible with aurora-mysql)"
  type        = string
  default     = "8.0.mysql_aurora.3.04.0"
}

variable "master_username" {
  description = "Master username for the cluster"
  type        = string
  default     = "admin"
}

variable "deletion_protection" {
  description = "Enable deletion protection for the cluster"
  type        = bool
  default     = true
}

variable "skip_final_snapshot" {
  description = "Skip final snapshot on cluster deletion (use only in non-production)"
  type        = bool
  default     = false
}

variable "enable_multi_region" {
  description = "Enable multi-region (creates a secondary cluster in the same region)"
  type        = bool
  default     = false
}

# Data sources
data "aws_caller_identity" "current" {}

# Terraform configuration
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Variables
variable "bucket_name" {
  description = "Name prefix for the S3 bucket (a unique suffix will be appended)"
  type        = string
  default     = "my-custom-bucket"
}

variable "object_lock_enabled" {
  description = "Enable object lock on the bucket"
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags to apply to the bucket and related resources"
  type        = map(string)
  default     = {}
}

variable "force_destroy" {
  description = "Allow deletion of non-empty bucket"
  type        = bool
  default     = false
}

variable "bucket_policies" {
  description = "Map of bucket policy configurations. Each key is a policy identifier. Each value contains version (optional) and a list of statements."
  type = map(object({
    version = optional(string, "2012-10-17")
    statements = list(object({
      sid        = string
      actions    = list(string)
      effect     = optional(string, "Allow")
      resources  = list(string)
      principals = map(list(string))
    }))
  }))
  default = {}
}

# Random suffix for globally unique bucket name
resource "random_id" "suffix" {
  byte_length = 4
}

# KMS key for S3 default encryption
resource "aws_kms_key" "s3" {
  description             = "S3 encryption key"
  deletion_window_in_days = 7
  tags                    = var.tags
}

# S3 bucket
resource "aws_s3_bucket" "this" {
  bucket        = "${var.bucket_name}-${random_id.suffix.hex}"
  force_destroy = var.force_destroy
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Block public access
resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Server-side encryption configuration
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# Bucket versioning
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = "Enabled"
  }
}

# Object lock configuration (only if enabled)
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode = "GOVERNANCE"
      days = 7
    }
  }
}

# Flatten bucket_policies for dynamic IAM policy document construction
locals {
  flattened_policy_statements = flatten([
    for policy_id, policy in var.bucket_policies : [
      for stmt in policy.statements : {
        policy_id = policy_id
        version   = policy.version
        statement = stmt
      }
    ]
  ])

  policies_map = {
    for ps in local.flattened_policy_statements :
    ps.policy_id => {
      version    = ps.version
      statements = [for s in local.flattened_policy_statements : s.statement if s.policy_id == ps.policy_id]
    }
  }
}

# IAM policy document per bucket policy identifier
data "aws_iam_policy_document" "bucket_policies" {
  for_each = local.policies_map

  version = each.value.version

  dynamic "statement" {
    for_each = each.value.statements
    content {
      sid       = statement.value.sid
      actions   = statement.value.actions
      effect    = statement.value.effect
      resources = statement.value.resources

      dynamic "principals" {
        for_each = statement.value.principals
        content {
          type        = principals.key
          identifiers = principals.value
        }
      }
    }
  }
}

# Attach bucket policies
resource "aws_s3_bucket_policy" "this" {
  for_each = var.bucket_policies

  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket_policies[each.key].json
}

# Outputs
output "bucket_id" {
  value = aws_s3_bucket.this.id
}

output "bucket_arn" {
  value = aws_s3_bucket.this.arn
}

output "kms_key_arn" {
  value = aws_kms_key.s3.arn
}

# main.tf

terraform {
  required_version = "~> 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# ---------------------------------------------------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------------------------------------------------

variable "create_sns_topic" {
  description = "Main toggle to create all SNS-related resources"
  type        = bool
  default     = true
}

variable "topic_name" {
  description = "The name of the SNS topic. Exactly one of topic_name or name_prefix must be provided when create_sns_topic is true."
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "Prefix for the SNS topic name. Exactly one of topic_name or name_prefix must be provided when create_sns_topic is true."
  type        = string
  default     = null
}

variable "display_name" {
  description = "The display name for the SNS topic"
  type        = string
  default     = null
}

variable "fifo_topic" {
  description = "Set to true to create a FIFO topic"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO topics"
  type        = bool
  default     = false
}

variable "kms_master_key_id" {
  description = "The ID of a customer-managed KMS key to use for encryption. If null, the default AWS managed key is used."
  type        = string
  default     = null
}

variable "enable_delivery_status_iam_role" {
  description = "Whether to create an IAM role and CloudWatch log groups for delivery status feedback"
  type        = bool
  default     = false
}

variable "source_statements" {
  description = "List of policy statements (each as a map with keys: Sid, Effect, Principal, Action, Resource) to include as source in the topic policy. Use only actions valid for an SNS topic (e.g., SNS:Publish, SNS:Subscribe). Do not include the Version key."
  type        = list(any)
  default     = []
}

variable "override_statements" {
  description = "List of policy statements (each as a map with keys: Sid, Effect, Principal, Action, Resource) to include as override in the topic policy. Use only actions valid for an SNS topic (e.g., SNS:Publish, SNS:Subscribe). Do not include the Version key."
  type        = list(any)
  default     = []
}

variable "user_defined_statements" {
  description = "List of additional policy statements (each as a map with keys: Sid, Effect, Principal, Action, Resource) to include in the topic policy. Use only actions valid for an SNS topic (e.g., SNS:Publish, SNS:Subscribe). Do not include the Version key."
  type        = list(any)
  default     = []
}

variable "subscriptions" {
  description = "Map of subscriptions to create on the SNS topic"
  type = map(object({
    protocol         = string
    endpoint         = string
    filter_policy    = optional(string)
    auto_confirm     = optional(bool, false)
    delivery_policy  = optional(string)
  }))
  default = {}
}

# ---------------------------------------------------------------------------------------------------------------------
# Local values
# ---------------------------------------------------------------------------------------------------------------------

locals {
  # For non-FIFO, we want to preserve the name_prefix attribute if provided
  use_name_prefix = var.fifo_topic ? false : (var.name_prefix != null ? true : false)
  final_name      = local.use_name_prefix ? null : (
    var.fifo_topic ? (
      coalesce(var.topic_name, "default-topic") == var.topic_name && var.topic_name != null ? "${var.topic_name}.fifo" : "default-topic.fifo"
    ) : (
      var.topic_name != null ? var.topic_name : (var.name_prefix != null ? var.name_prefix : "default-topic")
    )
  )
  final_prefix    = local.use_name_prefix ? (
    var.fifo_topic ? null : var.name_prefix
  ) : null

  # Protocols for delivery feedback
  delivery_protocols = ["SQS", "Lambda", "HTTP", "Firehose", "Application"]

  # Delivery status log group names
  log_group_names = {
    for p in local.delivery_protocols : p => "/aws/sns/${p}/Delivery"
  }

  # SNS Topic Policy JSON constructed from default owner statement and user statements
  topic_policy_json = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Sid    = "DefaultOwnerAccess"
          Effect = "Allow"
          Principal = {
            AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
          }
          Action = [
            "SNS:Publish",
            "SNS:Subscribe",
            "SNS:GetTopicAttributes",
            "SNS:SetTopicAttributes",
            "SNS:DeleteTopic",
            "SNS:AddPermission",
            "SNS:RemovePermission"
          ]
          Resource = aws_sns_topic.this[0].arn
        }
      ],
      var.source_statements,
      var.override_statements,
      var.user_defined_statements
    )
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# KMS Key (conditionally created if kms_master_key_id is provided)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_kms_key" "this" {
  count = var.create_sns_topic && var.kms_master_key_id != null ? 1 : 0
  description             = "KMS key for SNS topic encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

# ---------------------------------------------------------------------------------------------------------------------
# SNS Topic
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_sns_topic" "this" {
  count = var.create_sns_topic ? 1 : 0

  name                       = local.final_name
  name_prefix                = local.final_prefix
  display_name               = var.display_name
  fifo_topic                 = var.fifo_topic
  content_based_deduplication = var.content_based_deduplication
  kms_master_key_id          = var.kms_master_key_id != null ? aws_kms_key.this[0].arn : null

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# Delivery Status IAM Role and Policies
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_iam_role" "sns_delivery_status" {
  count = var.create_sns_topic && var.enable_delivery_status_iam_role ? 1 : 0

  name = "sns-delivery-status-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM policies per protocol
resource "aws_iam_policy" "delivery_status" {
  for_each = var.create_sns_topic && var.enable_delivery_status_iam_role ? toset(local.delivery_protocols) : toset([])

  name = "sns-delivery-status-${each.key}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${local.log_group_names[each.key]}:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "delivery_status" {
  for_each = var.create_sns_topic && var.enable_delivery_status_iam_role ? toset(local.delivery_protocols) : toset([])

  role       = aws_iam_role.sns_delivery_status[0].name
  policy_arn = aws_iam_policy.delivery_status[each.key].arn
}

# CloudWatch log groups for delivery feedback
resource "aws_cloudwatch_log_group" "delivery_status" {
  for_each = var.create_sns_topic && var.enable_delivery_status_iam_role ? toset(local.delivery_protocols) : toset([])

  name              = local.log_group_names[each.key]
  retention_in_days = 14
}

# ---------------------------------------------------------------------------------------------------------------------
# SNS Topic Policy
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_sns_topic_policy" "this" {
  count = var.create_sns_topic ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = local.topic_policy_json
}

# ---------------------------------------------------------------------------------------------------------------------
# SNS Topic Subscriptions
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_sns_topic_subscription" "this" {
  for_each = var.create_sns_topic ? var.subscriptions : {}

  topic_arn = aws_sns_topic.this[0].arn
  protocol  = each.value.protocol
  endpoint  = each.value.endpoint

  filter_policy               = each.value.filter_policy
  delivery_policy             = each.value.delivery_policy
  confirmation_timeout_in_minutes = each.value.auto_confirm ? 1 : 0
}

