terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 6.0, < 6.70.0"
    }
  }
}

variable "tags" {
  type        = map(string)
  default     = { Environment = "dev" }
}

variable "vpc_config" {
  type = list(object({
    vpc_cidr = string
    vpc_name = string
    subnets  = list(object({
      cidr = string
      type = string
    }))
  }))
  default = [
    {
      vpc_cidr = "10.0.0.0/16"
      vpc_name = "main"
      subnets = [
        { cidr = "10.0.1.0/24", type = "public" },
        { cidr = "10.0.2.0/24", type = "private" },
      ]
    }
  ]
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_subnets_flat = flatten([
    for vpc in var.vpc_config : [
      for subnet in vpc.subnets : {
        vpc_key  = vpc.vpc_name
        cidr     = subnet.cidr
        type     = subnet.type
        vpc_cidr = vpc.vpc_cidr
        vpc_name = vpc.vpc_name
      }
    ]
  ])

  azs             = data.aws_availability_zones.available.names
  subnet_az_index = { for i, s in local.vpc_subnets_flat : "${s.vpc_key}-${s.cidr}" => i % length(local.azs) }

  vpc_has_public = {
    for vpc in var.vpc_config : vpc.vpc_name => length([for s in vpc.subnets : s if s.type == "public"]) > 0
  }

  vpc_first_private_subnet_id = {
    for vpc in var.vpc_config : vpc.vpc_name => try(
      [for s in vpc.subnets : aws_subnet.this["${vpc.vpc_name}-${s.cidr}"].id if s.type == "private"][0],
      null
    )
  }

  vpc_first_public_subnet_id = {
    for vpc in var.vpc_config : vpc.vpc_name => try(
      [for s in vpc.subnets : aws_subnet.this["${vpc.vpc_name}-${s.cidr}"].id if s.type == "public"][0],
      null
    )
  }

  vpc_attachment_subnet_id = {
    for vpc in var.vpc_config : vpc.vpc_name => coalesce(
      local.vpc_first_private_subnet_id[vpc.vpc_name],
      local.vpc_first_public_subnet_id[vpc.vpc_name]
    )
  }
}

resource "aws_vpc" "this" {
  for_each = { for vpc in var.vpc_config : vpc.vpc_name => vpc }
  cidr_block = each.value.vpc_cidr
  tags = merge(var.tags, { Name = each.value.vpc_name })
  lifecycle { prevent_destroy = true }
}

resource "aws_subnet" "this" {
  for_each = { for s in local.vpc_subnets_flat : "${s.vpc_key}-${s.cidr}" => s }
  vpc_id            = aws_vpc.this[each.value.vpc_key].id
  cidr_block        = each.value.cidr
  availability_zone = local.azs[local.subnet_az_index[each.key]]
  tags = merge(var.tags, {
    Name = "${each.value.vpc_key}-${each.value.type}-subnet"
    Type = each.value.type
  })
}

resource "aws_internet_gateway" "this" {
  for_each = { for vpc in var.vpc_config : vpc.vpc_name => vpc if local.vpc_has_public[vpc.vpc_name] }
  vpc_id = aws_vpc.this[each.key].id
  tags   = merge(var.tags, { Name = "${each.key}-igw" })
}

resource "aws_route_table" "public" {
  for_each = { for vpc in var.vpc_config : vpc.vpc_name => vpc if local.vpc_has_public[vpc.vpc_name] }
  vpc_id = aws_vpc.this[each.key].id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this[each.key].id
  }
  tags = merge(var.tags, { Name = "${each.key}-public-rt" })
}

resource "aws_route_table" "private" {
  for_each = { for vpc in var.vpc_config : vpc.vpc_name => vpc }
  vpc_id = aws_vpc.this[each.key].id
  tags   = merge(var.tags, { Name = "${each.key}-private-rt" })
}

resource "aws_route_table_association" "public" {
  for_each = { for s in local.vpc_subnets_flat : "${s.vpc_key}-${s.cidr}" => s if s.type == "public" && local.vpc_has_public[s.vpc_key] }
  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public[each.value.vpc_key].id
}

resource "aws_route_table_association" "private" {
  for_each = { for s in local.vpc_subnets_flat : "${s.vpc_key}-${s.cidr}" => s if s.type == "private" }
  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.private[each.value.vpc_key].id
}

resource "aws_ec2_transit_gateway" "this" {
  default_route_table_association  = "enable"
  default_route_table_propagation  = "enable"
  tags = merge(var.tags, { Name = "main-tgw" })
  lifecycle { prevent_destroy = true }
}

resource "aws_ec2_transit_gateway_vpc_attachment" "this" {
  for_each = { for vpc in var.vpc_config : vpc.vpc_name => vpc }
  subnet_ids                                    = [local.vpc_attachment_subnet_id[each.key]]
  transit_gateway_id                            = aws_ec2_transit_gateway.this.id
  vpc_id                                        = aws_vpc.this[each.key].id
  transit_gateway_default_route_table_association = true
  transit_gateway_default_route_table_propagation  = true
  tags = merge(var.tags, { Name = "${each.key}-tgw-attachment" })
}

resource "aws_route" "private_to_tgw" {
  for_each = { for vpc in var.vpc_config : vpc.vpc_name => vpc }
  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  transit_gateway_id     = aws_ec2_transit_gateway.this.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main"
  }
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "main"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main"
