  }
}

resource "aws_vpc_security_group_egress_rule" "main" {
  security_group_id = aws_security_group.dragondrop_compute_ecs_fargate.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "-1"
