terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

import {
  to = aws_iam_role.api_gateway_sns_publish_role
  id = "api-gateway-sns-publish-role"
}

import {
  to = aws_iam_policy.sns_publish_policy
  id = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:policy/sns-publish-event-topic"
}

# KMS key for SNS topic encryption
resource "aws_kms_key" "sns_kms_key" {
  description             = "KMS key for encrypting event-topic SNS messages"
  key_usage               = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow SNS to use the key"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

# SNS topic
resource "aws_sns_topic" "event_topic" {
  name              = "event-topic"
  kms_master_key_id = aws_kms_key.sns_kms_key.arn
  lifecycle {
    prevent_destroy = true
  }
}

# IAM role for API Gateway to publish to SNS
resource "aws_iam_role" "api_gateway_sns_publish_role" {
  name = "api-gateway-sns-publish-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM policy for SNS Publish on the specific topic
resource "aws_iam_policy" "sns_publish_policy" {
  name = "sns-publish-event-topic"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sns:Publish"
        Resource = aws_sns_topic.event_topic.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_sns_publish" {
  role       = aws_iam_role.api_gateway_sns_publish_role.name
  policy_arn = aws_iam_policy.sns_publish_policy.arn
}

# REST API Gateway
resource "aws_api_gateway_rest_api" "main" {
  name        = "event-publisher-api"
  description = "REST API to publish events to SNS topic"
}

# Resource under root path
resource "aws_api_gateway_resource" "events" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  parent_id   = aws_api_gateway_rest_api.main.root_resource_id
  path_part   = "events"
}

# POST method
resource "aws_api_gateway_method" "post" {
  rest_api_id   = aws_api_gateway_rest_api.main.id
  resource_id   = aws_api_gateway_resource.events.id
  http_method   = "POST"
  authorization = "NONE"
}

# Integration to SNS
resource "aws_api_gateway_integration" "post" {
  rest_api_id             = aws_api_gateway_rest_api.main.id
  resource_id             = aws_api_gateway_resource.events.id
  http_method             = aws_api_gateway_method.post.http_method
  integration_http_method = "POST"
  type                    = "AWS"
  uri                     = "arn:aws:apigateway:${data.aws_region.current.name}:sns:path//"
  credentials             = aws_iam_role.api_gateway_sns_publish_role.arn
  request_templates = {
    "application/json" = "Action=Publish&TopicArn=${aws_sns_topic.event_topic.arn}&Message=$input.body"
  }
}

# Method response
resource "aws_api_gateway_method_response" "post_method_response" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.post.http_method
  status_code = "200"
}

# Integration response
resource "aws_api_gateway_integration_response" "post_integration_response" {
  depends_on = [aws_api_gateway_integration.post]

  rest_api_id = aws_api_gateway_rest_api.main.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.post.http_method
  status_code = aws_api_gateway_method_response.post_method_response.status_code
}

# Deployment
resource "aws_api_gateway_deployment" "main" {
  depends_on = [
    aws_api_gateway_integration.post
  ]
  rest_api_id = aws_api_gateway_rest_api.main.id
  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_rest_api.main.body,
      aws_api_gateway_resource.events.id,
      aws_api_gateway_method.post.id,
      aws_api_gateway_integration.post.id,
    ]))
  }
  lifecycle {
    create_before_destroy = true
  }
}

# Stage
resource "aws_api_gateway_stage" "prod" {
  stage_name    = "prod"
  rest_api_id   = aws_api_gateway_rest_api.main.id
  deployment_id = aws_api_gateway_deployment.main.id
}

# Data sources for static metadata
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true

  tags = {
    Name = "terraform-aws-vpc"
  }
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.10.0.0/16"
}

variable "environment" {
  description = "Environment name (e.g., dev, prod)"
  type        = string
  default     = "dev"
}

variable "project" {
  description = "Project name for tagging"
  type        = string
  default     = "ntier"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = {
    Environment = var.environment
    Project     = var.project
  }

  subnets = [
    { name = "web",        cidr_index = 0, is_public = true },
    { name = "app",        cidr_index = 1, is_public = false },
    { name = "database",   cidr_index = 2, is_public = false },
    { name = "management", cidr_index = 3, is_public = true },
    { name = "web2",       cidr_index = 4, is_public = true },
    { name = "app2",       cidr_index = 5, is_public = false },
    { name = "database2",  cidr_index = 6, is_public = false },
  ]

  public_subnet_indices  = [for idx, s in local.subnets : idx if s.is_public]
  private_subnet_indices = [for idx, s in local.subnets : idx if !s.is_public]
}

resource "aws_vpc" "ntier_primary" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "ntier primary"
  })
}

resource "aws_subnet" "this" {
  count = length(local.subnets)

  vpc_id                  = aws_vpc.ntier_primary.id
  cidr_block              = cidrsubnet(aws_vpc.ntier_primary.cidr_block, 8, local.subnets[count.index].cidr_index)
  availability_zone       = data.aws_availability_zones.available.names[count.index % length(data.aws_availability_zones.available.names)]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.subnets[count.index].name}-subnet"
  })
}

resource "aws_internet_gateway" "main_igw" {
  vpc_id = aws_vpc.ntier_primary.id

  tags = merge(local.common_tags, {
    Name = "main-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.ntier_primary.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main_igw.id
  }

  tags = merge(local.common_tags, {
    Name = "public-route-table"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.ntier_primary.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main_igw.id
  }

  tags = merge(local.common_tags, {
    Name = "private-route-table"
  })
}

resource "aws_route_table_association" "public" {
  count          = length(local.public_subnet_indices)
  subnet_id      = aws_subnet.this[local.public_subnet_indices[count.index]].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = length(local.private_subnet_indices)
  subnet_id      = aws_subnet.this[local.private_subnet_indices[count.index]].id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# --------------------------------------------------------------------------------------------------
# Variables
# --------------------------------------------------------------------------------------------------
variable "key_type" {
  description = "Type of KMS key to create: standard, external, replica_standard, replica_external"
  type        = string
  default     = "standard"
  validation {
    condition     = contains(["standard", "external", "replica_standard", "replica_external"], var.key_type)
    error_message = "key_type must be one of: standard, external, replica_standard, replica_external."
  }
}

variable "description" {
  description = "Description of the KMS key"
  type        = string
  default     = "Managed by Terraform"
}

variable "deletion_window_in_days" {
  description = "Duration in days after which the key is deleted after destruction"
  type        = number
  default     = 30
}

# External key material (required for external and replica_external)
variable "key_material_base64" {
  description = "Base64-encoded key material for external keys (required for external and replica_external)"
  type        = string
  sensitive   = true
  default     = null
}

# Primary key ARN (required for replica_standard)
variable "primary_key_arn" {
  description = "ARN of the primary multi-region key (required for replica_standard)"
  type        = string
  default     = null
}

# Primary external key ARN (required for replica_external)
variable "primary_external_key_arn" {
  description = "ARN of the primary external key (required for replica_external)"
  type        = string
  default     = null
}

# IAM role ARN lists for policy statements
variable "key_owner_arns" {
  description = "List of IAM role ARNs that are key owners (full access)"
  type        = list(string)
  default     = []
}

variable "key_admin_arns" {
  description = "List of IAM role ARNs that are key administrators"
  type        = list(string)
  default     = []
}

variable "key_user_arns" {
  description = "List of IAM role ARNs that are standard key users (encrypt/decrypt)"
  type        = list(string)
  default     = []
}

variable "service_user_arns" {
  description = "List of IAM role ARNs for service users (e.g., S3, Lambda)"
  type        = list(string)
  default     = []
}

variable "autoscaling_role_arn" {
  description = "ARN of the EC2 Auto Scaling service-linked role (optional)"
  type        = string
  default     = ""
}

# Cryptographic operation user ARNs
variable "symmetric_user_arns" {
  description = "List of IAM role ARNs for symmetric encryption/decryption users"
  type        = list(string)
  default     = []
}

variable "hmac_user_arns" {
  description = "List of IAM role ARNs for HMAC users"
  type        = list(string)
  default     = []
}

variable "asymmetric_public_encryption_user_arns" {
  description = "List of IAM role ARNs for asymmetric public encryption users"
  type        = list(string)
  default     = []
}

variable "asymmetric_sign_verify_user_arns" {
  description = "List of IAM role ARNs for asymmetric sign/verify users"
  type        = list(string)
  default     = []
}

variable "route53_dnssec_enabled" {
  description = "Enable Route 53 DNSSEC signing permissions on the key"
  type        = bool
  default     = false
}

# Custom policy statements (list of statement objects)
variable "custom_policy_statements" {
  description = "Additional policy statements to merge into the key policy"
  type = list(object({
    sid                  = optional(string)
    effect               = string
    actions              = list(string)
    resources            = list(string)
    principal_type       = optional(string, "AWS")
    principal_identifiers = list(string)
    condition = optional(object({
      test     = string
      variable = string
      values   = list(string)
    }))
  }))
  default = []
}

# Full policy override document (replaces all constructed policy)
variable "policy_override_document" {
  description = "Complete JSON policy document to use instead of the constructed policy"
  type        = string
  default     = ""
}

# Alias configuration (exact name or name prefix)
variable "alias_name" {
  description = "Exact alias name (e.g., 'alias/my-key')"
  type        = string
  default     = ""
}

variable "alias_name_prefix" {
  description = "Prefix for the alias name (e.g., 'alias/my-key-')"
  type        = string
  default     = ""
}

# Grants
variable "grants" {
  description = "List of KMS grants to create"
  type = list(object({
    grantee_principal             = string
    operations                    = list(string)
    retiring_principal            = optional(string)
    encryption_context_subset     = optional(map(string))
  }))
  default = []
}

# --------------------------------------------------------------------------------------------------
# Data Sources
# --------------------------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

# --------------------------------------------------------------------------------------------------
# Locals
# --------------------------------------------------------------------------------------------------
locals {
  is_external = var.key_type == "external" || var.key_type == "replica_external"
  # key rotation is not supported for external keys (either primary or replica)
  enable_key_rotation = !local.is_external

  # Admin actions
  admin_actions = [
    "kms:Create*", "kms:Describe*", "kms:Enable*", "kms:List*",
    "kms:Put*", "kms:Update*", "kms:Revoke*", "kms:Disable*",
    "kms:Get*", "kms:Delete*", "kms:TagResource", "kms:UntagResource",
    "kms:ScheduleKeyDeletion", "kms:CancelKeyDeletion"
  ]

  # Common user actions (encrypt/decrypt)
  user_actions = [
    "kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*",
    "kms:GenerateDataKey*", "kms:DescribeKey"
  ]
}

# --------------------------------------------------------------------------------------------------
# Key Policy Document (constructed unless override is provided)
# --------------------------------------------------------------------------------------------------
data "aws_iam_policy_document" "combined" {
  count = var.policy_override_document == "" ? 1 : 0

  # Statement 1: Root account full access
  statement {
    sid    = "RootAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  # Statement 2: Key owners (full access)
  dynamic "statement" {
    for_each = length(var.key_owner_arns) > 0 ? [1] : []
    content {
      sid    = "KeyOwners"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.key_owner_arns
      }
      actions   = ["kms:*"]
      resources = ["*"]
    }
  }

  # Statement 3: Key administrators
  dynamic "statement" {
    for_each = length(var.key_admin_arns) > 0 ? [1] : []
    content {
      sid    = "KeyAdministrators"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.key_admin_arns
      }
      actions   = local.admin_actions
      resources = ["*"]
    }
  }

  # Statement 4: Standard key users
  dynamic "statement" {
    for_each = length(var.key_user_arns) > 0 ? [1] : []
    content {
      sid    = "KeyUsers"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.key_user_arns
      }
      actions   = local.user_actions
      resources = ["*"]
    }
  }

  # Statement 5: Service users
  dynamic "statement" {
    for_each = length(var.service_user_arns) > 0 ? [1] : []
    content {
      sid    = "ServiceUsers"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.service_user_arns
      }
      actions   = local.user_actions
      resources = ["*"]
    }
  }

  # Statement 6: EC2 Auto Scaling role
  dynamic "statement" {
    for_each = var.autoscaling_role_arn != "" ? [1] : []
    content {
      sid    = "AutoScalingRole"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = [var.autoscaling_role_arn]
      }
      actions = [
        "kms:CreateGrant",
        "kms:Decrypt",
        "kms:DescribeKey",
        "kms:Encrypt"
      ]
      resources = ["*"]
    }
  }

  # Statement 7: Symmetric encryption/decryption users
  dynamic "statement" {
    for_each = length(var.symmetric_user_arns) > 0 ? [1] : []
    content {
      sid    = "SymmetricUsers"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.symmetric_user_arns
      }
      actions   = local.user_actions
      resources = ["*"]
    }
  }

  # Statement 8: HMAC users
  dynamic "statement" {
    for_each = length(var.hmac_user_arns) > 0 ? [1] : []
    content {
      sid    = "HMACUsers"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.hmac_user_arns
      }
      actions = [
        "kms:GenerateMac",
        "kms:VerifyMac"
      ]
      resources = ["*"]
    }
  }

  # Statement 9: Asymmetric public encryption users
  dynamic "statement" {
    for_each = length(var.asymmetric_public_encryption_user_arns) > 0 ? [1] : []
    content {
      sid    = "AsymmetricPublicEncryptionUsers"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.asymmetric_public_encryption_user_arns
      }
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*",
        "kms:DescribeKey"
      ]
      resources = ["*"]
    }
  }

  # Statement 10: Asymmetric sign/verify users
  dynamic "statement" {
    for_each = length(var.asymmetric_sign_verify_user_arns) > 0 ? [1] : []
    content {
      sid    = "AsymmetricSignVerifyUsers"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.asymmetric_sign_verify_user_arns
      }
      actions = [
        "kms:Sign",
        "kms:Verify"
      ]
      resources = ["*"]
    }
  }

  # Statement 11: Route 53 DNSSEC
  dynamic "statement" {
    for_each = var.route53_dnssec_enabled ? [1] : []
    content {
      sid    = "Route53DNSSEC"
      effect = "Allow"
      principals {
        type        = "Service"
        identifiers = ["service.amazonaws.com"]
      }
      actions = [
        "kms:DescribeKey",
        "kms:GetPublicKey",
        "kms:Sign"
      ]
      resources = ["*"]
    }
  }

  # Statement 12: Custom policy statements
  dynamic "statement" {
    for_each = var.custom_policy_statements
    content {
      sid       = lookup(statement.value, "sid", null)
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources
      principals {
        type        = statement.value.principal_type
        identifiers = statement.value.principal_identifiers
      }
      dynamic "condition" {
        for_each = statement.value.condition != null ? [statement.value.condition] : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

# --------------------------------------------------------------------------------------------------
# KMS Key Resources (only one will be created based on key_type)
# --------------------------------------------------------------------------------------------------
# Standard customer-managed key with AWS-provided material
resource "aws_kms_key" "standard" {
  count = var.key_type == "standard" ? 1 : 0

  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  enable_key_rotation     = local.enable_key_rotation
  policy                  = var.policy_override_document != "" ? var.policy_override_document : data.aws_iam_policy_document.combined[0].json

  lifecycle {
    prevent_destroy = true
  }
}

# External key with imported key material (uses dedicated resource)
resource "aws_kms_external_key" "external" {
  count = var.key_type == "external" ? 1 : 0

  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  key_material_base64     = var.key_material_base64
  policy                  = var.policy_override_document != "" ? var.policy_override_document : data.aws_iam_policy_document.combined[0].json

  lifecycle {
    prevent_destroy = true
  }
}

# Standard multi-region replica key
resource "aws_kms_replica_key" "standard" {
  count = var.key_type == "replica_standard" ? 1 : 0

  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  primary_key_arn         = var.primary_key_arn
  policy                  = var.policy_override_document != "" ? var.policy_override_document : data.aws_iam_policy_document.combined[0].json

  lifecycle {
    prevent_destroy = true
  }
}

# Replica external key with custom key material (inherits from primary)
resource "aws_kms_replica_key" "external" {
  count = var.key_type == "replica_external" ? 1 : 0

  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  primary_key_arn         = var.primary_external_key_arn
  policy                  = var.policy_override_document != "" ? var.policy_override_document : data.aws_iam_policy_document.combined[0].json

  lifecycle {
    prevent_destroy = true
  }
}

# --------------------------------------------------------------------------------------------------
# Alias
# --------------------------------------------------------------------------------------------------
locals {
  alias_config = {
    for k, v in {
      alias_name        = var.alias_name != "" ? var.alias_name : null
      alias_name_prefix = var.alias_name_prefix != "" ? var.alias_name_prefix : null
    } : k => v if v != null
  }
}

resource "aws_kms_alias" "this" {
  for_each = local.alias_config

  name          = each.key == "alias_name" ? each.value : null
  name_prefix   = each.key == "alias_name_prefix" ? each.value : null
  target_key_id = try(
    aws_kms_key.standard[0].key_id,
    aws_kms_external_key.external[0].id,
    aws_kms_replica_key.standard[0].key_id,
    aws_kms_replica_key.external[0].key_id,
    ""
  )
}

# --------------------------------------------------------------------------------------------------
# Grants
# --------------------------------------------------------------------------------------------------
resource "aws_kms_grant" "this" {
  for_each = { for idx, g in var.grants : idx => g }

  name              = "grant-${each.key}"
  key_id            = try(
    aws_kms_key.standard[0].key_id,
    aws_kms_external_key.external[0].id,
    aws_kms_replica_key.standard[0].key_id,
    aws_kms_replica_key.external[0].key_id,
    ""
  )
  grantee_principal = each.value.grantee_principal
  operations        = each.value.operations
  retiring_principal = each.value.retiring_principal

  constraints {
    encryption_context_subset = each.value.encryption_context_subset
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
  required_version = ">= 1.0"
}

# Data sources for static metadata
data "aws_caller_identity" "current" {}

# Variables
variable "topic_name" {
  description = "Name of the SNS topic"
  type        = string
  default     = "my-sns-topic"
}

variable "display_name" {
  description = "Display name for the SNS topic"
  type        = string
  default     = null
}

variable "create_kms_key" {
  description = "Whether to create a dedicated KMS key for the SNS topic"
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "ARN of an existing KMS CMK to use for SNS encryption. Required if create_kms_key is false."
  type        = string
  default     = null

  validation {
    condition     = var.create_kms_key || var.kms_master_key_id != null
    error_message = "Either set create_kms_key = true or provide a valid kms_master_key_id (CMK ARN)."
  }
}

variable "topic_policy_json" {
  description = "JSON string for an SNS topic policy. If null, no policy is attached."
  type        = string
  default     = null
}

variable "fifo_topic" {
  description = "Whether the SNS topic is FIFO"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO topics"
  type        = bool
  default     = false
}

variable "subscriptions" {
  description = "Map of SNS subscriptions. Each key is a subscription identifier."
  type = map(object({
    endpoint                          = string
    protocol                          = string
    raw_message_delivery              = optional(bool, false)
    filter_policy                     = optional(string)
    redrive_policy                    = optional(string)
    confirmation_timeout_in_minutes   = optional(number)
    auto_confirm                      = optional(bool, true)
  }))
  default = {}
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# Locals
locals {
  common_tags = var.tags

  # Determine the KMS key ARN for the SNS topic – always a customer managed key
  kms_key_arn = var.create_kms_key ? aws_kms_key.main[0].arn : var.kms_master_key_id
}

# Optional KMS key for SNS encryption
resource "aws_kms_key" "main" {
  count = var.create_kms_key ? 1 : 0

  description             = "KMS key for SNS topic ${var.topic_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable CloudWatch Logs"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action   = "kms:Encrypt"
        Resource = "*"
      },
      {
        Sid    = "Enable Root User Administration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# Optional KMS alias
resource "aws_kms_alias" "main" {
  count = var.create_kms_key ? 1 : 0

  name          = "alias/sns/${var.topic_name}"
  target_key_id = aws_kms_key.main[0].key_id
}

# SNS Topic
resource "aws_sns_topic" "main" {
  name                        = var.topic_name
  display_name                = var.display_name
  kms_master_key_id           = local.kms_key_arn
  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.content_based_deduplication

  tags = local.common_tags
}

# Optional SNS Topic Policy
resource "aws_sns_topic_policy" "main" {
  count = var.topic_policy_json != null ? 1 : 0

  arn    = aws_sns_topic.main.arn
  policy = var.topic_policy_json
}

# SNS Subscriptions
resource "aws_sns_topic_subscription" "main" {
  for_each = var.subscriptions

  topic_arn                         = aws_sns_topic.main.arn
  endpoint                          = each.value.endpoint
  protocol                          = each.value.protocol
  raw_message_delivery              = each.value.raw_message_delivery
  filter_policy                     = each.value.filter_policy
  redrive_policy                    = each.value.redrive_policy
  confirmation_timeout_in_minutes   = each.value.confirmation_timeout_in_minutes
  endpoint_auto_confirms            = each.value.auto_confirm
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "create_iam_group" {
  description = "Toggle creation of the IAM group 'developers'"
  type        = bool
  default     = true
}

variable "create_iam_policy" {
  description = "Toggle creation of the IAM policy 'iam_read_only_and_s3_full_access'"
  type        = bool
  default     = true
}

variable "create_group_policy_attachment" {
  description = "Toggle attachment of the IAM policy to the developers group"
  type        = bool
  default     = true
}

variable "create_iam_users" {
  description = "Toggle creation of IAM users"
  type        = bool
  default     = true
}

variable "iam_user_names" {
  description = "List of IAM user names to create"
  type        = list(string)
  default     = ["jack", "jones"]
}

variable "create_ec2_screenshot_policy" {
  description = "Toggle creation of the EC2 console screenshot policy"
  type        = bool
  default     = true
}

variable "create_user_policy_attachment" {
  description = "Toggle attachment of the EC2 screenshot policy to each user"
  type        = bool
  default     = true
}

variable "create_group_membership" {
  description = "Toggle membership of users in the developers group"
  type        = bool
  default     = true
}

variable "create_instance_role" {
  description = "Toggle creation of the EC2 instance role"
  type        = bool
  default     = true
}

# Locals
locals {
  effective_users = var.create_iam_users ? var.iam_user_names : []
}

# IAM Group
resource "aws_iam_group" "developers" {
  count = var.create_iam_group ? 1 : 0
  name  = "developers"
}

# IAM Policy: Read-Only IAM + S3 Full Access
resource "aws_iam_policy" "iam_read_only_and_s3_full_access" {
  count       = var.create_iam_policy ? 1 : 0
  name        = "iam_read_only_and_s3_full_access"
  description = "Policy granting IAM read actions and S3 object read/write access"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["iam:Get*", "iam:List*"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject", "s3:ListBucket"]
        Resource = [
          "arn:aws:s3:::*",
          "arn:aws:s3:::*/*"
        ]
      }
    ]
  })
}

# Group Policy Attachment
resource "aws_iam_group_policy_attachment" "developers_s3_policy" {
  count      = var.create_group_policy_attachment && var.create_iam_group && var.create_iam_policy ? 1 : 0
  group      = aws_iam_group.developers[0].name
  policy_arn = aws_iam_policy.iam_read_only_and_s3_full_access[0].arn
}

# IAM Users
resource "aws_iam_user" "users" {
  for_each = toset(local.effective_users)
  name     = each.key
  tags = {
    user_created_by = "terraform"
  }
}

# IAM Policy: EC2 Console Screenshot
resource "aws_iam_policy" "ec2_get_console_screenshot" {
  count       = var.create_ec2_screenshot_policy ? 1 : 0
  name        = "ec2_get_console_screenshot"
  description = "Policy granting EC2 GetConsoleScreenshot permission"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["ec2:GetConsoleScreenshot"]
        Resource = "*"
      }
    ]
  })
}

# User Policy Attachment (EC2 screenshot policy)
resource "aws_iam_user_policy_attachment" "ec2_screenshot" {
  for_each = var.create_user_policy_attachment && var.create_ec2_screenshot_policy && length(local.effective_users) > 0 ? toset(local.effective_users) : toset([])
  user     = each.key
  policy_arn = aws_iam_policy.ec2_get_console_screenshot[0].arn
}

# Group Membership
resource "aws_iam_group_membership" "developers" {
  count = var.create_group_membership && length(local.effective_users) > 0 ? 1 : 0
  name  = "developers-membership"
  group = aws_iam_group.developers[0].name
  users = local.effective_users
}

# EC2 Instance Role
resource "aws_iam_role" "instance_role" {
  count = var.create_instance_role ? 1 : 0
  name  = "instance_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Role Policy Attachment (AWS managed IAMReadOnlyAccess)
resource "aws_iam_role_policy_attachment" "instance_role_readonly" {
  count      = var.create_instance_role ? 1 : 0
  role       = aws_iam_role.instance_role[0].name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "vpc_name" {
  type    = string
  default = "my-vpc"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 3)
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = var.vpc_name
  cidr = "10.0.0.0/16"

  azs             = local.azs
  public_subnets  = [cidrsubnet("10.0.0.0/16", 8, 48), cidrsubnet("10.0.0.0/16", 8, 49), cidrsubnet("10.0.0.0/16", 8, 50)]
  private_subnets = [cidrsubnet("10.0.0.0/16", 4, 0), cidrsubnet("10.0.0.0/16", 4, 1), cidrsubnet("10.0.0.0/16", 4, 2)]

  enable_nat_gateway     = true
  single_nat_gateway     = true
  enable_dns_hostnames   = true
  enable_dns_support     = true

  public_subnet_tags = {
    "kubernetes.io/role/elb" = "1"
  }

  private_subnet_tags = {
    "kubernetes.io/role/internal-elb" = "1"
  }

  tags = {
    Blueprint  = var.vpc_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

resource "aws_security_group" "cluster1_additional_sg" {
  name        = "cluster1_additional_sg"
  description = "Security group for cluster1 cross-cluster communication"
  vpc_id      = module.vpc.vpc_id

  tags = {
    Blueprint  = var.vpc_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

resource "aws_security_group" "cluster2_additional_sg" {
  name        = "cluster2_additional_sg"
  description = "Security group for cluster2 cross-cluster communication"
  vpc_id      = module.vpc.vpc_id

  tags = {
    Blueprint  = var.vpc_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

resource "aws_security_group_rule" "cluster1_ingress_from_cluster2" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  security_group_id        = aws_security_group.cluster1_additional_sg.id
  source_security_group_id = aws_security_group.cluster2_additional_sg.id
}

resource "aws_security_group_rule" "cluster1_egress_to_cluster2" {
  type                     = "egress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  security_group_id        = aws_security_group.cluster1_additional_sg.id
  source_security_group_id = aws_security_group.cluster2_additional_sg.id
}

resource "aws_security_group_rule" "cluster2_ingress_from_cluster1" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  security_group_id        = aws_security_group.cluster2_additional_sg.id
  source_security_group_id = aws_security_group.cluster1_additional_sg.id
}

resource "aws_security_group_rule" "cluster2_egress_to_cluster1" {
  type                     = "egress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  security_group_id        = aws_security_group.cluster2_additional_sg.id
  source_security_group_id = aws_security_group.cluster1_additional_sg.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "pool_name" {
  description = "Name of the Cognito User Pool"
  type        = string
  default     = "Pool name"
}

variable "alias_attributes" {
  description = "Attributes that can be used to sign in"
  type        = list(string)
  default     = ["email", "phone_number"]
}

variable "auto_verified_attributes" {
  description = "Attributes that are auto-verified"
  type        = list(string)
  default     = []
}

variable "mfa_configuration" {
  description = "MFA configuration (OFF, ON, OPTIONAL)"
  type        = string
  default     = "OPTIONAL"
}

variable "sms_authentication_message" {
  description = "SMS authentication message template"
  type        = string
  default     = "SMS authentication message {####}"
}

variable "verification_message_template" {
  description = "Verification message template by link"
  type = object({
    default_email_option = optional(string, "CONFIRM_WITH_LINK")
    email_message       = optional(string, "Some message {####}")
    email_subject       = optional(string, "Some subject")
    email_message_by_link = optional(string, "Please click the link below to verify your email address. {##Click Here##}")
    email_subject_by_link = optional(string, "Verify your email")
    sms_message         = optional(string, "SMS verification message {####}")
  })
  default = {}
}

variable "sms_configuration" {
  description = "SMS configuration map with external_id and sns_caller_arn"
  type = object({
    external_id    = optional(string, "")
    sns_caller_arn = optional(string, "")
  })
  default = {}
}

variable "recovery_mechanisms" {
  description = "List of recovery mechanisms with priority"
  type = list(object({
    name     = string
    priority = number
  }))
  default = [
    { name = "verified_email", priority = 2 },
    { name = "verified_phone_number", priority = 1 }
  ]
}

variable "invite_message_template" {
  description = "Invite message template"
  type = object({
    email_message = optional(string, "Your username is {username} and temporary password is {####}.")
    email_subject = optional(string, "Your temporary password")
    sms_message   = optional(string, "Your username is {username} and temporary password is {####}.")
  })
  default = {}
}

variable "admin_create_user_only" {
  description = "Set to true if only admin can create users"
  type        = bool
  default     = false
}

variable "software_token_mfa_configuration" {
  description = "Enable software token MFA"
  type        = bool
  default     = true
}

variable "username_case_sensitivity" {
  description = "Case sensitivity for username"
  type        = bool
  default     = null
}

variable "device_configuration" {
  description = "Device tracking configuration"
  type = object({
    challenge_required_on_new_device      = optional(bool, true)
    device_only_remembered_on_user_prompt = optional(bool, false)
  })
  default = null
}

variable "lambda_config" {
  description = "Lambda triggers configuration map"
  type = map(object({
    lambda_arn     = string
    lambda_version = optional(string)
  }))
  default = {}
}

variable "custom_schema" {
  description = "Custom schema attributes"
  type = list(object({
    name                = string
    attribute_data_type = string
    developer_only_attribute = optional(bool, false)
    mutable             = optional(bool, true)
    required            = optional(bool, false)
    number_attribute_constraints = optional(object({
      min_value = optional(string)
      max_value = optional(string)
    }))
    string_attribute_constraints = optional(object({
      min_length = optional(string)
      max_length = optional(string)
    }))
  }))
  default = [
    {
      name                = "email"
      attribute_data_type = "String"
      required            = true
      mutable             = true
      string_attribute_constraints = {
        min_length = "3"
        max_length = "2048"
      }
    }
  ]
}

variable "clients" {
  description = "List of Cognito User Pool clients with their configurations"
  type = list(object({
    name                            = string
    generate_secret                 = optional(bool, false)
    access_token_validity           = optional(number, 120)
    id_token_validity               = optional(number, 120)
    refresh_token_validity          = optional(number, 7)
    access_token_validity_unit      = optional(string, "minutes")
    id_token_validity_unit          = optional(string, "minutes")
    refresh_token_validity_unit     = optional(string, "days")
    allowed_oauth_flows_user_pool_client = optional(bool, false)
    enable_token_revocation         = optional(bool, true)
    explicit_auth_flows             = optional(list(string), ["ALLOW_REFRESH_TOKEN_AUTH", "ALLOW_USER_PASSWORD_AUTH", "ALLOW_USER_SRP_AUTH"])
    prevent_user_existence_errors   = optional(string, "LEGACY")
    read_attributes                 = optional(list(string), [])
    write_attributes                = optional(list(string), [])
    callback_urls                   = optional(list(string), [])
    logout_urls                     = optional(list(string), [])
    allowed_oauth_flows             = optional(list(string), [])
    allowed_oauth_scopes            = optional(list(string), [])
    supported_identity_providers    = optional(list(string), [])
  }))
  default = []
}

variable "group_name" {
  description = "Name of the user group to create (if non-empty)"
  type        = string
  default     = ""
}

variable "group_precedence" {
  description = "Precedence of the user group"
  type        = number
  default     = 0
}

variable "group_role_arn" {
  description = "IAM role ARN for the group"
  type        = string
  default     = null
}

variable "domain" {
  description = "Cognito User Pool domain prefix (if non-empty)"
  type        = string
  default     = ""
}

variable "certificate_arn" {
  description = "ACM certificate ARN for custom domain"
  type        = string
  default     = null
}

variable "create_route53_record" {
  description = "Whether to create a Route 53 A record alias for the Cognito domain"
  type        = bool
  default     = false
}

variable "route53_zone_id" {
  description = "Route 53 hosted zone ID"
  type        = string
  default     = ""
}

# ------------------------------------------------------------------------------
# Local values
# ------------------------------------------------------------------------------
locals {
  sms_config_enabled = var.sms_configuration.external_id != "" && var.sms_configuration.sns_caller_arn != ""
  domain_enabled     = var.domain != ""
  group_enabled      = var.group_name != ""
  route53_enabled    = var.create_route53_record && var.route53_zone_id != "" && local.domain_enabled
}

# ------------------------------------------------------------------------------
# Cognito User Pool
# ------------------------------------------------------------------------------
resource "aws_cognito_user_pool" "main" {
  name = var.pool_name

  alias_attributes           = var.alias_attributes
  auto_verified_attributes   = var.auto_verified_attributes
  mfa_configuration          = var.mfa_configuration
  sms_authentication_message = var.sms_authentication_message

  dynamic "sms_configuration" {
    for_each = local.sms_config_enabled ? [1] : []
    content {
      external_id    = var.sms_configuration.external_id
      sns_caller_arn = var.sms_configuration.sns_caller_arn
    }
  }

  dynamic "software_token_mfa_configuration" {
    for_each = var.software_token_mfa_configuration != null ? [1] : []
    content {
      enabled = var.software_token_mfa_configuration
    }
  }

  dynamic "username_configuration" {
    for_each = var.username_case_sensitivity != null ? [1] : []
    content {
      case_sensitive = var.username_case_sensitivity
    }
  }

  dynamic "device_configuration" {
    for_each = var.device_configuration != null ? [1] : []
    content {
      challenge_required_on_new_device      = var.device_configuration.challenge_required_on_new_device
      device_only_remembered_on_user_prompt = var.device_configuration.device_only_remembered_on_user_prompt
    }
  }

  dynamic "lambda_config" {
    for_each = length(var.lambda_config) > 0 ? [var.lambda_config] : []
    content {
      dynamic "custom_email_sender" {
        for_each = lookup(lambda_config.value, "custom_email_sender", null) != null ? [lambda_config.value.custom_email_sender] : []
        content {
          lambda_arn     = custom_email_sender.value.lambda_arn
          lambda_version = lookup(custom_email_sender.value, "lambda_version", null)
        }
      }
    }
  }

  dynamic "schema" {
    for_each = var.custom_schema
    content {
      name                = schema.value.name
      attribute_data_type = schema.value.attribute_data_type
      developer_only_attribute = schema.value.developer_only_attribute
      mutable             = schema.value.mutable
      required            = schema.value.required

      dynamic "number_attribute_constraints" {
        for_each = schema.value.number_attribute_constraints != null ? [schema.value.number_attribute_constraints] : []
        content {
          min_value = number_attribute_constraints.value.min_value
          max_value = number_attribute_constraints.value.max_value
        }
      }

      dynamic "string_attribute_constraints" {
        for_each = schema.value.string_attribute_constraints != null ? [schema.value.string_attribute_constraints] : []
        content {
          min_length = string_attribute_constraints.value.min_length
          max_length = string_attribute_constraints.value.max_length
        }
      }
    }
  }

  dynamic "verification_message_template" {
    for_each = length(keys(var.verification_message_template)) > 0 ? [1] : []
    content {
      default_email_option = try(var.verification_message_template.default_email_option, "CONFIRM_WITH_LINK")
      email_message        = try(var.verification_message_template.email_message, null)
      email_subject        = try(var.verification_message_template.email_subject, null)
      email_message_by_link = try(var.verification_message_template.email_message_by_link, null)
      email_subject_by_link = try(var.verification_message_template.email_subject_by_link, null)
      sms_message          = try(var.verification_message_template.sms_message, null)
    }
  }

  dynamic "account_recovery_setting" {
    for_each = length(var.recovery_mechanisms) > 0 ? [1] : []
    content {
      dynamic "recovery_mechanism" {
        for_each = var.recovery_mechanisms
        content {
          name     = recovery_mechanism.value.name
          priority = recovery_mechanism.value.priority
        }
      }
    }
  }

  dynamic "admin_create_user_config" {
    for_each = var.admin_create_user_only ? [1] : []
    content {
      allow_admin_create_user_only = true
      dynamic "invite_message_template" {
        for_each = length(keys(var.invite_message_template)) > 0 ? [1] : []
        content {
          email_message = try(var.invite_message_template.email_message, null)
          email_subject = try(var.invite_message_template.email_subject, null)
          sms_message   = try(var.invite_message_template.sms_message, null)
        }
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# User Pool Clients
# ------------------------------------------------------------------------------
resource "aws_cognito_user_pool_client" "this" {
  for_each = { for idx, client in var.clients : client.name => client }

  name                = each.value.name
  user_pool_id        = aws_cognito_user_pool.main.id
  generate_secret     = each.value.generate_secret
  explicit_auth_flows = each.value.explicit_auth_flows
  read_attributes     = each.value.read_attributes
  write_attributes    = each.value.write_attributes
  callback_urls       = each.value.callback_urls
  logout_urls         = each.value.logout_urls
  allowed_oauth_flows                  = each.value.allowed_oauth_flows
  allowed_oauth_scopes                 = each.value.allowed_oauth_scopes
  supported_identity_providers         = each.value.supported_identity_providers
  allowed_oauth_flows_user_pool_client = each.value.allowed_oauth_flows_user_pool_client
  prevent_user_existence_errors        = each.value.prevent_user_existence_errors
  enable_token_revocation              = each.value.enable_token_revocation
  access_token_validity                = each.value.access_token_validity
  id_token_validity                    = each.value.id_token_validity
  refresh_token_validity               = each.value.refresh_token_validity
  token_validity_units {
    access_token  = each.value.access_token_validity_unit
    id_token      = each.value.id_token_validity_unit
    refresh_token = each.value.refresh_token_validity_unit
  }
}

# ------------------------------------------------------------------------------
# User Group (conditional)
# ------------------------------------------------------------------------------
resource "aws_cognito_user_group" "this" {
  count = local.group_enabled ? 1 : 0

  name         = var.group_name
  user_pool_id = aws_cognito_user_pool.main.id
  precedence   = var.group_precedence
  role_arn     = var.group_role_arn
}

# ------------------------------------------------------------------------------
# User Pool Domain (conditional)
# ------------------------------------------------------------------------------
resource "aws_cognito_user_pool_domain" "this" {
  count = local.domain_enabled ? 1 : 0

  domain          = var.domain
  user_pool_id    = aws_cognito_user_pool.main.id
  certificate_arn = var.certificate_arn

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Route 53 Record (conditional)
# ------------------------------------------------------------------------------
resource "aws_route53_record" "cognito_alias" {
  count = local.route53_enabled ? 1 : 0

  zone_id = var.route53_zone_id
  name    = var.domain
  type    = "A"

  alias {
    name                   = aws_cognito_user_pool_domain.this[0].cloudfront_distribution_arn
    zone_id                = "Z2FDTNDATAQYW2"
    evaluate_target_health = false
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "DevOps-Project-VPC"
}

variable "igw_name" {
  description = "Name tag for the Internet Gateway"
  type        = string
  default     = "devops-project-igw"
}

variable "route_table_name" {
  description = "Name tag for the route table"
  type        = string
  default     = "DevOps-project-RT"
}

variable "public_subnet_identifier_name" {
  description = "Identifier name for the public subnet"
  type        = string
  default     = "subnet_a"
}

variable "nat_gateway_name" {
  description = "Name tag for the NAT Gateway"
  type        = string
  default     = "DevOps-NAT-GW"
}

variable "public_ipv4_pool_name" {
  description = "Name of the public IPv4 pool (used as a tag on the EIP)"
  type        = string
  default     = "amazon"
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.igw_name
  }
}

# Subnet A (Public)
resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name       = "Subnet-A-Public"
    Identifier = var.public_subnet_identifier_name
  }
}

# Subnet B (Private)
resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "Subnet-B-Private"
  }
}

# Subnet C (Private)
resource "aws_subnet" "subnet_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.3.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

  tags = {
    Name = "Subnet-C-Private"
  }
}

# Route Table
resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = var.route_table_name
  }
}

# Route Table Association (only with Subnet A)
resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.subnet_a.id
  route_table_id = aws_route_table.main.id
}

# Elastic IP for NAT Gateway
resource "aws_eip" "main" {
  domain = "vpc"

  tags = {
    PublicIPv4Pool = var.public_ipv4_pool_name
  }
}

# NAT Gateway in Subnet B
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.main.id
  subnet_id     = aws_subnet.subnet_b.id

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = var.nat_gateway_name
  }
}

# Security Group
resource "aws_security_group" "main" {
  name        = "default-security-group"
  description = "Default security group for the VPC"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "DefaultSecurityGroup"
  }
}

# Output the NAT Gateway's public IP
output "nat_public_ip" {
  value = aws_nat_gateway.main.public_ip
}

# Required providers
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "vault_name" {
  description = "Name of the backup vault"
  type        = string
  default     = "my-backup-vault"
}

variable "tags" {
  description = "Optional tags to apply to resources"
  type        = map(string)
  default     = {}
}

variable "tag_key" {
  description = "Tag key used for backup selection conditions"
  type        = string
  default     = "backup"
}

variable "enable_notifications" {
  description = "Flag to enable backup vault notifications"
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "ARN of the SNS topic for backup notifications (required when enable_notifications is true)"
  type        = string
  default     = null
}

variable "backup_event_list" {
  description = "List of backup events to notify on"
  type        = list(string)
  default = [
    "BACKUP_JOB_FAILED",
    "RESTORE_JOB_FAILED",
    "COPY_JOB_FAILED",
    "S3_BACKUP_OBJECT_FAILED",
    "S3_RESTORE_OBJECT_FAILED"
  ]
}

variable "daily_schedule" {
  description = "Cron schedule for daily backup plan"
  type        = string
  default     = "cron(0 12 ? * * *)"
}

variable "weekly_schedule" {
  description = "Cron schedule for weekly backup plan"
  type        = string
  default     = "cron(0 12 ? * 1 *)"
}

variable "monthly_schedule" {
  description = "Cron schedule for monthly backup plan"
  type        = string
  default     = "cron(0 12 1 * ? *)"
}

variable "daily_deletion_days" {
  description = "Number of days after which daily backups are deleted"
  type        = number
  default     = 7
}

variable "weekly_deletion_days" {
  description = "Number of days after which weekly backups are deleted"
  type        = number
  default     = 31
}

variable "monthly_deletion_days" {
  description = "Number of days after which monthly backups are deleted"
  type        = number
  default     = 366
}

variable "enable_continuous_backup" {
  description = "Enable continuous backup for the daily plan"
  type        = bool
  default     = false
}

# KMS key for backup vault encryption
resource "aws_kms_key" "backup_vault_key" {
  description             = "KMS key for encrypting AWS Backup vault"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "backup_vault_key_alias" {
  name          = "alias/backup-vault-key"
  target_key_id = aws_kms_key.backup_vault_key.key_id
}

# Backup vault
resource "aws_backup_vault" "main" {
  name        = var.vault_name
  kms_key_arn = aws_kms_key.backup_vault_key.arn
  tags        = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# IAM role and policy attachment for backup
resource "aws_iam_role" "backup_role" {
  name = "${var.vault_name}-backup-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "backup_policy_attachment" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# Backup plans
resource "aws_backup_plan" "daily" {
  name = "${var.vault_name}-daily"

  rule {
    rule_name                = "daily_backup_rule"
    target_vault_name        = aws_backup_vault.main.name
    schedule                 = var.daily_schedule
    enable_continuous_backup = var.enable_continuous_backup

    lifecycle {
      delete_after = var.daily_deletion_days
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  tags = var.tags
}

resource "aws_backup_plan" "weekly" {
  name = "${var.vault_name}-weekly"

  rule {
    rule_name         = "weekly_backup_rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = var.weekly_schedule

    lifecycle {
      delete_after = var.weekly_deletion_days
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  tags = var.tags
}

resource "aws_backup_plan" "monthly" {
  name = "${var.vault_name}-monthly"

  rule {
    rule_name         = "monthly_backup_rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = var.monthly_schedule

    lifecycle {
      delete_after = var.monthly_deletion_days
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  tags = var.tags
}

# Backup selections
resource "aws_backup_selection" "daily" {
  name         = "daily_backup_selection"
  plan_id      = aws_backup_plan.daily.id
  iam_role_arn = aws_iam_role.backup_role.arn

  resources = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.tag_key
    value = "daily"
  }
}

resource "aws_backup_selection" "weekly" {
  name         = "weekly_backup_selection"
  plan_id      = aws_backup_plan.weekly.id
  iam_role_arn = aws_iam_role.backup_role.arn

  resources = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.tag_key
    value = "weekly"
  }
}

resource "aws_backup_selection" "monthly" {
  name         = "monthly_backup_selection"
  plan_id      = aws_backup_plan.monthly.id
  iam_role_arn = aws_iam_role.backup_role.arn

  resources = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.tag_key
    value = "monthly"
  }
}

# Optional backup vault notifications
resource "aws_backup_vault_notifications" "main" {
  count = var.enable_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.main.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.backup_event_list
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region for resources"
  type        = string
  default     = "us-east-1"
}

variable "env" {
  description = "Environment tag value"
  type        = string
  default     = "test"
}

variable "vpc_cidr" {
  description = "CIDR block for VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.20.0/24", "10.0.21.0/24"]
}

locals {
  common_tags = {
    Owner   = "Valerii Vasianovych"
    Project = "Terraform AWS"
    env     = var.env
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = merge(
    local.common_tags,
    {
      Name   = "${var.env}-vpc"
      Region = var.aws_region
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-igw"
    }
  )
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-public-subnet-${count.index}"
    }
  )
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-private-subnet-${count.index}"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-route-public-subnets"
    }
  )
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count  = length(var.private_subnet_cidrs)
  domain = "vpc"

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-nat-eip-${count.index}"
    }
  )
}

resource "aws_nat_gateway" "main" {
  count = length(var.private_subnet_cidrs)

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-nat-gw-${count.index}"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-route-private-subnets-${count.index}"
    }
  )
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 6.69.0"
    }
  }
}

variable "create_eks" {
  type        = bool
  default     = false
}

variable "cluster_name" {
  type        = string
  default     = ""
}

variable "cluster_version" {
  type        = string
  default     = null
}

variable "authentication_mode" {
  type        = string
  default     = "API_AND_CONFIG_MAP"
}

variable "subnet_ids" {
  type        = list(string)
  default     = []
}

variable "control_plane_subnet_ids" {
  type        = list(string)
  default     = []
}

# IAM role for EKS cluster
resource "aws_iam_role" "eks_cluster" {
  name = "eks-cluster"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach AmazonEKSClusterPolicy
resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster.name
}

# Attach AmazonEKSVPCResourceController
resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.eks_cluster.name
}

# Conditional EKS cluster
resource "aws_eks_cluster" "this" {
  count = var.create_eks ? 1 : 0

  name       = var.cluster_name
  role_arn   = aws_iam_role.eks_cluster.arn
  version    = var.cluster_version

  vpc_config {
    subnet_ids = length(var.control_plane_subnet_ids) > 0 ? var.control_plane_subnet_ids : var.subnet_ids
  }

  access_config {
    authentication_mode                   = var.authentication_mode
    bootstrap_cluster_creator_admin_permissions = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller
  ]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

locals {
  common_tags = {
    Name       = "rwwise.dev Infrastructure Setup"
    Repository = "https://github.com/zangrum/setup.inf.rwwise.dev"
    AccountID  = data.aws_caller_identity.current.account_id
    UserID     = data.aws_caller_identity.current.user_id
  }
  cicd_policy_json = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "CodeBuildCodeCommitAndMonitoringAccess"
        Effect   = "Allow"
        Action   = [
          "codebuild:BatchGet*",
          "codebuild:List*",
          "codecommit:Get*",
          "codecommit:List*",
          "cloudwatch:Describe*",
          "cloudwatch:Get*",
          "cloudwatch:List*",
          "events:Describe*",
          "events:List*",
          "events:PutRule",
          "events:PutTargets",
          "logs:Describe*",
          "logs:Get*",
          "logs:List*"
        ]
        Resource = "*"
      },
      {
        Sid      = "CodeStarConnectionsUserAccess"
        Effect   = "Allow"
        Action   = [
          "codestar-connections:GetConnection",
          "codestar-connections:ListConnections"
        ]
        Resource = "arn:aws:codestar-connections:*:*:connection/*"
      },
      {
        Sid      = "CodeStarNotificationsPowerUserAccess"
        Effect   = "Allow"
        Action   = [
          "codestar-notifications:DescribeNotificationRule",
          "codestar-notifications:ListNotificationRules",
          "codestar-notifications:ListTagsForResource",
          "codestar-notifications:Subscribe",
          "codestar-notifications:Unsubscribe"
        ]
        Resource = "*"
        Condition = {
          StringLike = {
            "codestar-notifications:NotificationsForResource" = "arn:aws:codebuild:*"
          }
        }
      },
      {
        Sid      = "CodeStarNotificationsListAccess"
        Effect   = "Allow"
        Action   = [
          "codestar-notifications:ListEventTypes",
          "codestar-notifications:ListTargets",
          "codestar-notifications:ListNotificationRules"
        ]
        Resource = "*"
      }
    ]
  })
}

# IAM Users
resource "aws_iam_user" "dev" {
  name = "DevUser-rwwise.dev"
  path = "/system/"
  tags = local.common_tags
}

resource "aws_iam_user" "test" {
  name = "TestUser-rwwise.dev"
  path = "/system/"
  tags = local.common_tags
}

resource "aws_iam_user" "prod" {
  name = "ProdUser-rwwise.dev"
  path = "/system/"
  tags = local.common_tags
}

# Inline policies
resource "aws_iam_user_policy" "dev_cicd" {
  name   = "dev_cicd_user_policy"
  user   = aws_iam_user.dev.name
  policy = local.cicd_policy_json
}

resource "aws_iam_user_policy" "test_cicd" {
  name   = "test_cicd_user_policy"
  user   = aws_iam_user.test.name
  policy = local.cicd_policy_json
}

resource "aws_iam_user_policy" "prod_cicd" {
  name   = "prod_cicd_user_policy"
  user   = aws_iam_user.prod.name
  policy = local.cicd_policy_json
}

# Access keys
resource "aws_iam_access_key" "dev" {
  user = aws_iam_user.dev.name
}

resource "aws_iam_access_key" "test" {
  user = aws_iam_user.test.name
}

resource "aws_iam_access_key" "prod" {
  user = aws_iam_user.prod.name
}

# Outputs
output "dev_access_key_id" {
  value = aws_iam_access_key.dev.id
}

output "dev_secret_access_key" {
  value     = aws_iam_access_key.dev.secret
  sensitive = true
}

output "test_access_key_id" {
  value = aws_iam_access_key.test.id
}

output "test_secret_access_key" {
  value     = aws_iam_access_key.test.secret
  sensitive = true
}

output "prod_access_key_id" {
  value = aws_iam_access_key.prod.id
}

output "prod_secret_access_key" {
  value     = aws_iam_access_key.prod.secret
  sensitive = true
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name" {
  type    = string
  default = null
}

variable "tags" {
  type    = map(string)
  default = {}
}

variable "bus_config" {
  type    = any
  default = {}

  validation {
    condition     = var.bus_config != null
    error_message = "bus_config must not be null."
  }

  validation {
    condition     = can(tomap(var.bus_config))
    error_message = "bus_config must be a map."
  }
}

variable "rules" {
  type    = list(any)
  default = []

  validation {
    condition     = var.rules != null
    error_message = "rules must not be null."
  }
}

variable "targets" {
  type    = list(any)
  default = []

  validation {
    condition     = var.targets != null
    error_message = "targets must not be null."
  }
}

locals {
  module_name = (var.name == null || var.name == "") ? "default" : var.name
}

data "aws_partition" "current" {}

resource "aws_cloudwatch_event_bus" "custom" {
  count = local.module_name != "default" ? 1 : 0

  name               = local.module_name
  event_source_name  = try(var.bus_config["event_source_name"], null)
  tags               = var.tags
}

resource "aws_cloudwatch_event_rule" "rules" {
  for_each = { for idx, rule in var.rules : rule["name"] => rule }

  name                = each.value["name"]
  description         = try(each.value["description"], null)
  event_pattern       = try(each.value["event_pattern"], null)
  schedule_expression = try(each.value["schedule_expression"], null)
  event_bus_name      = local.module_name != "default" ? aws_cloudwatch_event_bus.custom[0].name : "default"
  tags                = var.tags
}

resource "aws_iam_role" "eventbridge_invoke" {
  name = "${local.module_name}-invoke"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "events.${data.aws_partition.current.dns_suffix}"
        }
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_policy" "invoke_targets" {
  name = "${local.module_name}-invoke-targets"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["lambda:InvokeFunction", "states:StartExecution"]
        Resource = "*"
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "invoke_targets_attach" {
  role       = aws_iam_role.eventbridge_invoke.name
  policy_arn = aws_iam_policy.invoke_targets.arn
}

resource "aws_cloudwatch_event_target" "targets" {
  for_each = { for idx, target in var.targets : "${target["rule"]}-${target["arn"]}" => target }

  arn       = each.value["arn"]
  rule      = each.value["rule"]
  event_bus_name = local.module_name != "default" ? aws_cloudwatch_event_bus.custom[0].name : "default"
  role_arn  = contains(each.value["arn"], "stateMachine") ? aws_iam_role.eventbridge_invoke.arn : null

  depends_on = [aws_cloudwatch_event_rule.rules]
}

terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "backup_name" {
  description = "Base name used to construct all resource names and tags."
  type        = string
  default     = "default"
}

variable "kms_key_arn" {
  description = "Optional KMS key ARN for backup vault encryption."
  type        = string
  default     = null
}

variable "vault_policy" {
  description = "Optional JSON policy document to attach to the backup vault. Leave empty to skip."
  type        = string
  default     = ""
}

variable "schedule_expression" {
  description = "Cron or rate expression for the backup schedule."
  type        = string
  default     = "cron(0 5 * * ? *)"
}

variable "start_window_minutes" {
  description = "Start window in minutes for the backup rule."
  type        = number
  default     = 60
}

variable "completion_window_minutes" {
  description = "Completion window in minutes for the backup rule."
  type        = number
  default     = 120
}

variable "cold_storage_after_days" {
  description = "Number of days after which to transition recovery points to cold storage."
  type        = number
  default     = 30
}

variable "delete_after_days" {
  description = "Number of days after which to delete recovery points."
  type        = number
  default     = 120
}

variable "destination_vault_map" {
  description = "Map of destination vault ARNs to regions for copy actions. Key = region, value = vault ARN."
  type        = map(string)
  default     = {}
}

variable "selection_tag_key" {
  description = "Tag key used for backup selection filtering."
  type        = string
  default     = "Backup"
}

variable "selection_tag_value" {
  description = "Tag value used for backup selection filtering."
  type        = string
  default     = "true"
}

variable "selection_tag_type" {
  description = "Tag matching type (STRING_EQUALS, STRING_NOT_EQUALS, etc.)."
  type        = string
  default     = "STRINGEQUALS"
}

variable "sns_topic_arn" {
  description = "Optional SNS topic ARN for vault event notifications. Leave empty to skip."
  type        = string
  default     = ""
}

locals {
  job_tag = "${var.backup_name}-backup"
  common_tags = {
    Name = "aws-backup-${var.backup_name}"
    Job  = local.job_tag
  }
}

resource "random_id" "suffix" {
  byte_length = 2
}

# IAM Role
resource "aws_iam_role" "backup" {
  name = "aws-backup-${var.backup_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# Backup Vault
resource "aws_backup_vault" "main" {
  name        = "vault-${var.backup_name}-backup"
  kms_key_arn = var.kms_key_arn

  tags = merge(local.common_tags, {
    Name = "vault-${var.backup_name}-backup"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Import existing resources to avoid creation conflicts
import {
  to = aws_iam_role.backup
  id = "aws-backup-${var.backup_name}"
}

import {
  to = aws_backup_vault.main
  id = "vault-${var.backup_name}-backup"
}

# Conditional Vault Access Policy
resource "aws_backup_vault_policy" "main" {
  count = var.vault_policy != "" ? 1 : 0

  backup_vault_name = aws_backup_vault.main.name
  policy            = var.vault_policy
}

# Backup Plan
resource "aws_backup_plan" "main" {
  name = "plan-${var.backup_name}-backup-${random_id.suffix.hex}"

  rule {
    rule_name                = "rule-${var.backup_name}-backup-${random_id.suffix.hex}"
    target_vault_name        = aws_backup_vault.main.name
    schedule                 = var.schedule_expression
    start_window             = var.start_window_minutes
    completion_window        = var.completion_window_minutes

    recovery_point_tags = {
      Job = local.job_tag
    }

    lifecycle {
      cold_storage_after = var.cold_storage_after_days
      delete_after       = var.delete_after_days
    }

    dynamic "copy_action" {
      for_each = var.destination_vault_map
      content {
        destination_vault_arn = copy_action.value
        lifecycle {
          cold_storage_after = var.cold_storage_after_days
          delete_after       = var.delete_after_days
        }
      }
    }
  }

  tags = merge(local.common_tags, {
    Name = "plan-${var.backup_name}-backup-${random_id.suffix.hex}"
  })
}

# Backup Selection
resource "aws_backup_selection" "main" {
  name         = "selection-${var.backup_name}-backup-${random_id.suffix.hex}"
  iam_role_arn = aws_iam_role.backup.arn
  plan_id      = aws_backup_plan.main.id

  selection_tag {
    type  = var.selection_tag_type
    key   = var.selection_tag_key
    value = var.selection_tag_value
  }

  condition {
    # Empty block as required
  }
}

# Conditional Vault Event Notifications
resource "aws_backup_vault_notifications" "main" {
  count = var.sns_topic_arn != "" ? 1 : 0

  backup_vault_name   = aws_backup_vault.main.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "create" {
  description = "Whether to create a new Transit Gateway or look up an existing one."
  type        = bool
  default     = true
}

variable "id" {
  description = "ID of an existing Transit Gateway to use when create is false."
  type        = string
  default     = null
}

variable "name" {
  description = "Name tag to filter an existing Transit Gateway when create is false."
  type        = string
  default     = null
}

variable "bgp_asn" {
  description = "BGP ASN for the Transit Gateway."
  type        = number
  default     = 65200
}

variable "auto_accept_shared_attachments" {
  description = "Auto-accept shared attachments for the Transit Gateway."
  type        = string
  default     = null
}

variable "dns_support" {
  description = "DNS support for the Transit Gateway."
  type        = string
  default     = null
}

variable "vpn_ecmp_support" {
  description = "VPN ECMP support for the Transit Gateway."
  type        = string
  default     = null
}

variable "transit_gateway_cidr_blocks" {
  description = "List of IPv4 or IPv6 CIDR blocks for the Transit Gateway."
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for cidr in var.transit_gateway_cidr_blocks : can(cidrhost(cidr, 0))
    ])
    error_message = "Each element must be a valid IPv4 or IPv6 CIDR notation."
  }
}

variable "global_tags" {
  description = "Global tags to apply to all resources."
  type        = map(string)
  default     = {}
}

variable "route_tables" {
  description = "Map of Transit Gateway route tables to create or look up."
  type = map(object({
    create     = optional(bool, true)
    name       = optional(string)
    local_tags = optional(map(string), {})
  }))
  default = {}

  validation {
    condition = alltrue([
      for k, v in var.route_tables : v.create || (v.name != null)
    ])
    error_message = "When 'create' is false, 'name' must be provided."
  }
}

variable "shared_principals" {
  description = "Map of principals (AWS account IDs or organizations) to share the Transit Gateway with via RAM."
  type        = map(string)
  default     = {}
}

variable "ram_resource_share_name" {
  description = "Name for the RAM resource share. Defaults to the Transit Gateway ID if not set."
  type        = string
  default     = null
}

locals {
  # Transit Gateway reference (resource or data source)
  tgw = var.create ? aws_ec2_transit_gateway.this[0] : data.aws_ec2_transit_gateway.existing[0]

  tgw_id  = local.tgw.id
  tgw_arn = local.tgw.arn

  # Unified route table IDs from created and looked-up tables
  route_table_ids = merge(
    { for k, v in aws_ec2_transit_gateway_route_table.this : k => v.id },
    { for k, v in data.aws_ec2_transit_gateway_route_table.existing : k => v.id }
  )
}

# Conditional creation of a new Transit Gateway
resource "aws_ec2_transit_gateway" "this" {
  count = var.create ? 1 : 0

  description                    = "Transit Gateway managed by Terraform"
  amazon_side_asn                = var.bgp_asn
  auto_accept_shared_attachments = var.auto_accept_shared_attachments
  dns_support                    = var.dns_support
  vpn_ecmp_support               = var.vpn_ecmp_support
  transit_gateway_cidr_blocks    = var.transit_gateway_cidr_blocks

  default_route_table_association = "disable"
  default_route_table_propagation = "disable"

  tags = merge(var.global_tags, {
    Name = var.name != null ? var.name : "transit-gateway"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Look up existing Transit Gateway when not creating
data "aws_ec2_transit_gateway" "existing" {
  count = var.create ? 0 : 1

  filter {
    name   = "transit-gateway-id"
    values = var.id != null ? [var.id] : []
  }

  filter {
    name   = "tag:Name"
    values = var.name != null ? [var.name] : []
  }
}

# Route tables - create new ones
resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = {
    for k, v in var.route_tables : k => v if v.create
  }

  transit_gateway_id = local.tgw_id

  tags = merge(var.global_tags, each.value.local_tags, {
    Name = each.value.name != null ? each.value.name : var.name != null ? var.name : "transit-gateway"
  })
}

# Route tables - look up existing ones
data "aws_ec2_transit_gateway_route_table" "existing" {
  for_each = {
    for k, v in var.route_tables : k => v if !v.create && v.name != null
  }

  filter {
    name   = "transit-gateway-id"
    values = [local.tgw_id]
  }

  filter {
    name   = "tag:Name"
    values = [each.value.name]
  }
}

# RAM resource share - only if shared_principals is non-empty
resource "aws_ram_resource_share" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  name                      = var.ram_resource_share_name != null ? var.ram_resource_share_name : local.tgw_id
  allow_external_principals = true

  tags = var.global_tags
}

# Associate Transit Gateway to the RAM resource share
resource "aws_ram_resource_association" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  resource_arn       = local.tgw_arn
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

# Attach each principal to the RAM resource share
resource "aws_ram_principal_association" "this" {
  for_each = var.shared_principals

  principal          = each.value
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

# Outputs
output "transit_gateway_id" {
  description = "ID of the Transit Gateway (created or looked up)."
  value       = local.tgw_id
}

output "route_table_ids" {
  description = "Map of route table IDs keyed by the route_tables map keys."
  value       = local.route_table_ids
}

output "ram_resource_share_arn" {
  description = "ARN of the RAM resource share, if created."
  value       = length(var.shared_principals) > 0 ? aws_ram_resource_share.this[0].arn : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

import {
  to = aws_iam_role.bronze_backup_role
  id = "Bronze_Backup_Role"
}

import {
  to = aws_backup_vault.bronze
  id = "Bronze_Backup_Vault"
}

import {
  to = aws_backup_vault.silver
  id = "Silver_Backup_Vault"
}

import {
  to = aws_backup_vault.gold
  id = "Gold_Backup_Vault"
}

import {
  to = aws_backup_vault.premium
  id = "Premium"
}

resource "aws_kms_key" "shared" {
  description             = "Shared KMS key for Backup vaults"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "bronze_backup_role" {
  name = "Bronze_Backup_Role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "backup_tag_access" {
  name   = "BackupTagAccess"
  role   = aws_iam_role.bronze_backup_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["tag:GetResources", "tag:GetTagKeys"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_policy" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
  depends_on = [aws_iam_role.bronze_backup_role]
}

resource "aws_iam_role_policy_attachment" "restore_policy" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
  depends_on = [aws_iam_role.bronze_backup_role]
}

resource "aws_backup_vault" "bronze" {
  name        = "Bronze_Backup_Vault"
  kms_key_arn = aws_kms_key.shared.arn
}

resource "aws_backup_vault" "silver" {
  name        = "Silver_Backup_Vault"
  kms_key_arn = aws_kms_key.shared.arn
}

resource "aws_backup_vault" "gold" {
  name        = "Gold_Backup_Vault"
  kms_key_arn = aws_kms_key.shared.arn
}

resource "aws_backup_vault" "premium" {
  name        = "Premium"
  kms_key_arn = aws_kms_key.shared.arn
}

resource "aws_backup_plan" "bronze" {
  name = "Bronze_Backup"
  rule {
    rule_name         = "Bronze_Backup_Weekly"
    target_vault_name = aws_backup_vault.bronze.name
    schedule          = "cron(0 0 ? * FRI *)"
    lifecycle {
      delete_after = 10
    }
  }
}

resource "aws_backup_plan" "silver" {
  name = "Silver_Backup_Plan"
  rule {
    rule_name         = "Silver_Backup_Daily"
    target_vault_name = aws_backup_vault.silver.name
    schedule          = "cron(0 5 ? * * *)"
    lifecycle {
      delete_after = 7
    }
  }
}

resource "aws_backup_plan" "gold" {
  name = "Gold_Backup"
  rule {
    rule_name         = "Gold_Daily_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 * * ? *)"
    lifecycle {
      delete_after = 31
    }
  }
  rule {
    rule_name         = "Gold_Monthly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 1 1/1 ? *)"
    lifecycle {
      delete_after = 365
    }
  }
  rule {
    rule_name         = "Gold_Yearly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 31 12 ? *)"
    lifecycle {
      delete_after = 2555
    }
  }
}

resource "aws_backup_plan" "premium" {
  name = "Premium"
  rule {
    rule_name         = "Premium_Daily_4Hour_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0/4 ? * * *)"
    lifecycle {
      delete_after = 1
    }
  }
  rule {
    rule_name         = "Premium_Daily_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 * * ? *)"
    lifecycle {
      delete_after = 31
    }
  }
  rule {
    rule_name         = "Premium_Monthly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 1 1/1 ? *)"
    lifecycle {
      cold_storage_after = 15
      delete_after       = 365
    }
  }
  rule {
    rule_name         = "Premium_Yearly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 31 12 ? *)"
    lifecycle {
      cold_storage_after = 15
      delete_after       = 2555
    }
  }
}

resource "aws_backup_selection" "bronze" {
  name         = "Bronze_Resource_Assignment"
  plan_id      = aws_backup_plan.bronze.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "bronze"
  }
  depends_on = [
    aws_iam_role.bronze_backup_role,
    aws_iam_role_policy_attachment.backup_policy,
    aws_iam_role_policy_attachment.restore_policy,
    aws_iam_role_policy.backup_tag_access
  ]
}

resource "aws_backup_selection" "silver" {
  name         = "Silver_Backup_resource"
  plan_id      = aws_backup_plan.silver.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "silver"
  }
  depends_on = [
    aws_iam_role.bronze_backup_role,
    aws_iam_role_policy_attachment.backup_policy,
    aws_iam_role_policy_attachment.restore_policy,
    aws_iam_role_policy.backup_tag_access
  ]
}

resource "aws_backup_selection" "gold" {
  name         = "Gold_Backup_Select"
  plan_id      = aws_backup_plan.gold.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "gold"
  }
  depends_on = [
    aws_iam_role.bronze_backup_role,
    aws_iam_role_policy_attachment.backup_policy,
    aws_iam_role_policy_attachment.restore_policy,
    aws_iam_role_policy.backup_tag_access
  ]
}

resource "aws_backup_selection" "premium" {
  name         = "Premium"
  plan_id      = aws_backup_plan.premium.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "premium"
  }
  depends_on = [
    aws_iam_role.bronze_backup_role,
    aws_iam_role_policy_attachment.backup_policy,
    aws_iam_role_policy_attachment.restore_policy,
    aws_iam_role_policy.backup_tag_access
  ]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region for provider configuration"
  type        = string
  default     = "us-east-1"
}

variable "role_name" {
  description = "Name of the IAM role for Prisma Cloud integration"
  type        = string
  default     = "PrismaCloudReadWriteRole"
}

variable "read_write" {
  description = "Flag to enable additional remediation policy"
  type        = bool
  default     = false
}

resource "random_string" "external_id" {
  length           = 32
  special          = false
  upper            = true
  lower            = true
  numeric          = true
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    effect  = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::188619942792:root"]
    }
    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [random_string.external_id.result]
    }
  }
}

resource "aws_iam_role" "prisma_cloud" {
  name               = var.role_name
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
}

resource "aws_iam_role_policy_attachment" "security_audit" {
  role       = aws_iam_role.prisma_cloud.name
  policy_arn = "arn:aws:iam::aws:policy/SecurityAudit"
}

data "aws_iam_policy_document" "read_only" {
  statement {
    effect = "Allow"
    actions = [
      "apigateway:GET",
      "cognito-identity:ListTagsForResource",
      "cognito-idp:ListTagsForResource",
      "ecr:DescribeImages",
      "ecr:GetLifecyclePolicy",
      "elasticbeanstalk:ListTagsForResource",
      "elasticfilesystem:DescribeTags",
      "glacier:GetVaultLock",
      "glacier:ListTagsForVault",
      "glue:GetSecurityConfigurations",
      "logs:GetLogEvents",
      "mq:listBrokers",
      "mq:describeBroker",
      "ram:GetResourceShares",
      "secretsmanager:DescribeSecret",
      "ssm:GetParameters",
      "ssm:ListTagsForResource",
      "sqs:SendMessage",
      "elasticmapreduce:ListSecurityConfigurations",
      "sns:listSubscriptions",
      "wafv2:ListResourcesForWebACL",
      "wafv2:ListWebACLs"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "read_only" {
  name   = "PrismaCloud-IAM-ReadOnly-Policy"
  role   = aws_iam_role.prisma_cloud.name
  policy = data.aws_iam_policy_document.read_only.json
}

data "aws_iam_policy_document" "remediation" {
  count = var.read_write ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "iam:UpdateAccountPasswordPolicy",
      "ec2:ModifyImageAttribute",
      "rds:ModifyDBSnapshotAttribute",
      "s3:PutBucketAcl",
      "ec2:RevokeSecurityGroupIngress"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "remediation" {
  count  = var.read_write ? 1 : 0
  name   = "PrismaCloud-IAM-Remediation-Policy"
  role   = aws_iam_role.prisma_cloud.name
  policy = data.aws_iam_policy_document.remediation[0].json
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  type        = string
  default     = "10.0.2.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "development-be-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "development-be-public-subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "development-be-private-subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "development-be-ig"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "development-be-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "http_access" {
  name        = "http_access"
  description = "Security group for backend development"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "development-be-sg"
  }
}

resource "aws_vpc_security_group_ingress_rule" "ssh_vpc" {
  security_group_id = aws_security_group.http_access.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  from_port         = 22
  to_port           = 22
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_ingress_rule" "http_all" {
  security_group_id = aws_security_group.http_access.id
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "vpc_only" {
  security_group_id = aws_security_group.http_access.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "-1"
  from_port         = 0
  to_port           = 0
}

output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "The ID of the public subnet"
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "The ID of the private subnet"
  value       = aws_subnet.private.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.8"
    }
  }
}

# Variables
variable "create" {
  description = "Whether to create all resources in this module"
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the SNS topic. Required if use_name_prefix is false."
  type        = string
  default     = null
}

variable "use_name_prefix" {
  description = "If true, the provided name is used as a prefix and Terraform will generate a unique name."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication for FIFO topics"
  type        = bool
  default     = false
}

variable "delivery_policy" {
  description = "JSON delivery policy for the topic"
  type        = string
  default     = null
}

variable "display_name" {
  description = "Display name for the topic"
  type        = string
  default     = null
}

variable "kms_master_key_id" {
  description = "ID of an AWS-managed customer master key (CMK) for SNS"
  type        = string
  default     = null
}

variable "signature_version" {
  description = "Signature version for the topic. Set to null for FIFO topics."
  type        = string
  default     = null
}

variable "fifo_topic" {
  description = "Whether to create a FIFO topic"
  type        = bool
  default     = false
}

variable "application_feedback" {
  description = "Map for application feedback configuration (failure_role_arn, success_role_arn, success_sample_rate)"
  type        = map(string)
  default     = {}
}

variable "firehose_feedback" {
  description = "Map for Firehose feedback configuration (failure_role_arn, success_role_arn, success_sample_rate)"
  type        = map(string)
  default     = {}
}

variable "http_feedback" {
  description = "Map for HTTP feedback configuration (failure_role_arn, success_role_arn, success_sample_rate)"
  type        = map(string)
  default     = {}
}

variable "lambda_feedback" {
  description = "Map for Lambda feedback configuration (failure_role_arn, success_role_arn, success_sample_rate)"
  type        = map(string)
  default     = {}
}

variable "sqs_feedback" {
  description = "Map for SQS feedback configuration (failure_role_arn, success_role_arn, success_sample_rate)"
  type        = map(string)
  default     = {}
}

variable "create_topic_policy" {
  description = "Whether to create and attach a topic policy"
  type        = bool
  default     = true
}

variable "topic_policy" {
  description = "JSON policy to attach to the topic when create_topic_policy is false"
  type        = string
  default     = null
}

variable "source_policy_documents" {
  description = "List of IAM policy documents to merge as source documents"
  type        = list(string)
  default     = []
}

variable "override_policy_documents" {
  description = "List of IAM policy documents to merge as override documents"
  type        = list(string)
  default     = []
}

variable "enable_default_topic_policy" {
  description = "Whether to add a default statement allowing standard SNS actions to all AWS principals (conditioned on account owner)"
  type        = bool
  default     = true
}

variable "custom_statements" {
  description = "List of custom policy statements to add to the topic policy"
  type = list(object({
    sid    = optional(string)
    effect = optional(string, "Allow")
    actions   = list(string)
    resources = list(string)
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    condition = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

variable "create_subscription" {
  description = "Whether to create the subscriptions defined in var.subscriptions"
  type        = bool
  default     = true
}

variable "subscriptions" {
  description = "Map of subscription configurations. Each key is a subscription identifier."
  type = map(object({
    confirmation_timeout_in_minutes = optional(number)
    delivery_policy                 = optional(string)
    endpoint                        = string
    endpoint_auto_confirms          = optional(bool)
    filter_policy                   = optional(string)
    filter_policy_scope             = optional(string)
    protocol                        = string
    raw_message_delivery            = optional(bool)
    redrive_policy                  = optional(string)
    subscription_role_arn           = optional(string)
  }))
  default = {}
}

variable "data_protection_policy" {
  description = "JSON data protection policy. Only applied when fifo_topic is false."
  type        = string
  default     = null
}

# Data sources
data "aws_caller_identity" "current" {}

# Locals
locals {
  topic_name = var.create ? (
    var.use_name_prefix ? null : (
      var.name != null && var.fifo_topic && !endswith(var.name, ".fifo") ? "${var.name}.fifo" : var.name
    )
  ) : null

  topic_name_prefix = var.create && var.use_name_prefix ? (
    var.fifo_topic && var.name != null && endswith(var.name, ".fifo") ? trimsuffix(var.name, ".fifo") : var.name
  ) : null

  # Build the policy attribute for the topic policy resource
  topic_policy_json = var.create && var.create_topic_policy ? data.aws_iam_policy_document.topic_policy[0].json : var.topic_policy
}

# SNS Topic
resource "aws_sns_topic" "this" {
  count = var.create ? 1 : 0

  name                        = local.topic_name
  name_prefix                 = local.topic_name_prefix
  content_based_deduplication = var.content_based_deduplication
  delivery_policy             = var.delivery_policy
  display_name                = var.display_name
  kms_master_key_id           = var.kms_master_key_id
  signature_version           = var.fifo_topic ? null : var.signature_version
  fifo_topic                  = var.fifo_topic

  application_failure_feedback_role_arn    = try(var.application_feedback["failure_role_arn"], null)
  application_success_feedback_role_arn    = try(var.application_feedback["success_role_arn"], null)
  application_success_feedback_sample_rate = try(var.application_feedback["success_sample_rate"], null)

  firehose_failure_feedback_role_arn    = try(var.firehose_feedback["failure_role_arn"], null)
  firehose_success_feedback_role_arn    = try(var.firehose_feedback["success_role_arn"], null)
  firehose_success_feedback_sample_rate = try(var.firehose_feedback["success_sample_rate"], null)

  http_failure_feedback_role_arn    = try(var.http_feedback["failure_role_arn"], null)
  http_success_feedback_role_arn    = try(var.http_feedback["success_role_arn"], null)
  http_success_feedback_sample_rate = try(var.http_feedback["success_sample_rate"], null)

  lambda_failure_feedback_role_arn    = try(var.lambda_feedback["failure_role_arn"], null)
  lambda_success_feedback_role_arn    = try(var.lambda_feedback["success_role_arn"], null)
  lambda_success_feedback_sample_rate = try(var.lambda_feedback["success_sample_rate"], null)

  sqs_failure_feedback_role_arn    = try(var.sqs_feedback["failure_role_arn"], null)
  sqs_success_feedback_role_arn    = try(var.sqs_feedback["success_role_arn"], null)
  sqs_success_feedback_sample_rate = try(var.sqs_feedback["success_sample_rate"], null)

  # Prevent accidental deletion of topic (stateful resource)
  lifecycle {
    prevent_destroy = true
  }
}

# Topic Policy
data "aws_iam_policy_document" "topic_policy" {
  count = var.create && var.create_topic_policy ? 1 : 0

  source_policy_documents   = var.source_policy_documents
  override_policy_documents = var.override_policy_documents

  dynamic "statement" {
    for_each = var.enable_default_topic_policy ? [1] : []
    content {
      sid    = "DefaultSNSTopicPolicy"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = ["*"]
      }
      actions = [
        "sns:Publish",
        "sns:Subscribe",
        "sns:GetTopicAttributes",
        "sns:ListSubscriptionsByTopic",
        "sns:Receive"
      ]
      resources = [aws_sns_topic.this[0].arn]
      condition {
        test     = "StringEquals"
        variable = "aws:SourceOwner"
        values   = [data.aws_caller_identity.current.account_id]
      }
    }
  }

  dynamic "statement" {
    for_each = var.custom_statements
    content {
      sid         = statement.value.sid
      effect      = statement.value.effect
      actions     = statement.value.actions
      resources   = statement.value.resources
      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : []
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }
      dynamic "condition" {
        for_each = statement.value.condition != null ? statement.value.condition : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sns_topic_policy" "this" {
  count = var.create && var.create_topic_policy ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = local.topic_policy_json
}

# Subscriptions
resource "aws_sns_topic_subscription" "this" {
  for_each = { for k, v in var.subscriptions : k => v if var.create && var.create_subscription }

  topic_arn                            = aws_sns_topic.this[0].arn
  confirmation_timeout_in_minutes      = each.value.confirmation_timeout_in_minutes
  delivery_policy                      = each.value.delivery_policy
  endpoint                             = each.value.endpoint
  endpoint_auto_confirms               = each.value.endpoint_auto_confirms
  filter_policy                        = each.value.filter_policy
  filter_policy_scope                  = each.value.filter_policy_scope
  protocol                             = each.value.protocol
  raw_message_delivery                 = each.value.raw_message_delivery
  redrive_policy                       = each.value.redrive_policy
  subscription_role_arn                = each.value.subscription_role_arn
}

# Data Protection Policy (only for non-FIFO topics)
resource "aws_sns_topic_data_protection_policy" "this" {
  count = var.create && var.data_protection_policy != null && !var.fifo_topic ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = var.data_protection_policy
}

# Outputs
output "topic_arn" {
  description = "ARN of the SNS topic"
  value       = try(aws_sns_topic.this[0].arn, null)
}

output "topic_name" {
  description = "Name of the SNS topic"
  value       = try(aws_sns_topic.this[0].name, null)
}

output "topic_policy_arn" {
  description = "ARN of the topic policy (if created)"
  value       = try(aws_sns_topic_policy.this[0].arn, null)
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "bucket_name" {
  description = "Name of the bucket. If null, a name is generated."
  type        = string
  default     = null
}

variable "prefix" {
  description = "If true, append an additional random string suffix to the bucket name."
  type        = bool
  default     = false
}

variable "request_payer" {
  description = "Specifies who should bear the cost of Amazon S3 data transfer. Valid values: BucketOwner, Requester."
  type        = string
  default     = "BucketOwner"
}

variable "encryption" {
  description = "Enable server-side encryption. When true, uses aws:kms with either provided kms_key_arn or a module-created KMS key."
  type        = bool
  default     = true
}

variable "kms_key" {
  description = "ARN of an existing KMS key for encryption. If empty and encryption is true, a new key is created."
  type        = string
  default     = ""
}

variable "versioning" {
  description = "Enable versioning on the bucket."
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "Enable MFA delete on the bucket. Requires versioning to be enabled."
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Force destroy the bucket even if it contains objects."
  type        = bool
  default     = false
}

variable "acl" {
  description = "Canned ACL to apply to the bucket (e.g., private, public-read)."
  type        = string
  default     = null
}

variable "policy" {
  description = "JSON policy document for the bucket."
  type        = string
  default     = null
}

variable "grants" {
  description = "List of grant blocks for the bucket ACL. Each element is an object with type, permission, uri (optional), and id (optional)."
  type = list(object({
    type       = string
    permission = string
    uri        = optional(string)
    id         = optional(string)
  }))
  default = null
}

variable "tags" {
  description = "Tags to apply to all resources."
  type        = map(string)
  default     = {}
}

variable "acceleration_status" {
  description = "Transfer acceleration status. Valid values: Enabled, Suspended."
  type        = string
  default     = "Suspended"
}

variable "logging_target_bucket" {
  description = "Name of the bucket where access logs will be delivered."
  type        = string
  default     = null
}

variable "logging_target_prefix" {
  description = "Prefix for the log objects."
  type        = string
  default     = null
}

variable "index_document" {
  description = "Suffix for the index document (e.g., index.html)."
  type        = string
  default     = null
}

variable "error_document" {
  description = "Suffix for the error document (e.g., error.html)."
  type        = string
  default     = null
}

variable "redirect_all_requests_to" {
  description = "Hostname for redirecting all requests (e.g., example.com)."
  type        = string
  default     = null
}

variable "cors_rules" {
  description = "List of CORS rule objects. Each rule can have allowed_headers, allowed_methods, allowed_origins, expose_headers, max_age_seconds."
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rule objects."
  type = list(object({
    id         = string
    enabled    = bool
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    expiration = optional(object({
      days                         = optional(number)
      date                         = optional(string)
      expired_object_delete_marker = optional(bool)
    }))
    transition = optional(list(object({
      days          = optional(number)
      date          = optional(string)
      storage_class = string
    })))
    noncurrent_version_expiration = optional(object({
      days = number
    }))
    noncurrent_version_transition = optional(list(object({
      days          = number
      storage_class = string
    })))
    abort_incomplete_multipart_upload = optional(object({
      days_after_initiation = number
    }))
  }))
  default = []
}

variable "object_lock_configuration" {
  description = "Object lock configuration. Provide mode (GOVERNANCE or COMPLIANCE) and days/years for default retention."
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  default = null
}

variable "replication_rules" {
  description = "List of replication rule objects. Each rule must include destination bucket ARN."
  type = list(object({
    id       = string
    status   = string
    priority = optional(number)
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    destination = object({
      bucket             = string
      storage_class      = optional(string)
      replica_kms_key_id = optional(string)
      access_control_translation = optional(object({
        owner = string
      }))
      account_id      = optional(string)
      replication_time = optional(object({
        status  = string
        minutes = optional(number)
      }))
      metrics = optional(object({
        status  = string
        minutes = optional(number)
      }))
    })
    source_selection_criteria = optional(object({
      sse_kms_encrypted_objects = optional(object({
        enabled = bool
      }))
    }))
    existing_object_replication = optional(object({
      status = string
    }))
    delete_marker_replication = optional(string)
  }))
  default = []
}

variable "replication_role_arn" {
  description = "ARN of an IAM role for replication. If not provided, the module creates one."
  type        = string
  default     = ""
}

# ------------------------------------------------------------------------------
# Data sources
# ------------------------------------------------------------------------------
data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

data "aws_canonical_user_id" "current" {}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------
locals {
  base_bucket_name = var.bucket_name != null ? var.bucket_name : "corebucket-${random_id.bucket_name_suffix.hex}"
  prefix_suffix    = var.prefix ? random_id.prefix_suffix[0].hex : ""
  resolved_bucket_name = var.prefix ? "${local.base_bucket_name}-${local.prefix_suffix}" : local.base_bucket_name

  kms_key_arn = var.kms_key != "" ? var.kms_key : (var.encryption ? aws_kms_key.s3[0].arn : null)

  replication_role_arn = var.replication_role_arn != "" ? var.replication_role_arn : (length(var.replication_rules) > 0 ? aws_iam_role.replication[0].arn : null)
}

# ------------------------------------------------------------------------------
# Random IDs
# ------------------------------------------------------------------------------
resource "random_id" "bucket_name_suffix" {
  byte_length = 4
}

resource "random_id" "prefix_suffix" {
  count       = var.prefix ? 1 : 0
  byte_length = 2
}

# ------------------------------------------------------------------------------
# KMS Key (created only if encryption is true and no existing key provided)
# ------------------------------------------------------------------------------
resource "aws_kms_key" "s3" {
  count                   = var.encryption && var.kms_key == "" ? 1 : 0
  description             = "KMS key for S3 bucket ${local.resolved_bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
    ]
  })
  tags = var.tags
}

resource "aws_kms_alias" "s3" {
  count         = var.encryption && var.kms_key == "" ? 1 : 0
  name          = "alias/s3-${local.resolved_bucket_name}"
  target_key_id = aws_kms_key.s3[0].key_id
}

# ------------------------------------------------------------------------------
# S3 Bucket
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "main" {
  bucket              = local.resolved_bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_configuration != null ? true : null
  tags                = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Request Payer
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_request_payment_configuration" "main" {
  bucket = aws_s3_bucket.main.id
  payer  = var.request_payer
}

# ------------------------------------------------------------------------------
# Encryption
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.encryption ? "aws:kms" : "AES256"
      kms_master_key_id = var.encryption ? local.kms_key_arn : null
    }
  }
}

# ------------------------------------------------------------------------------
# Versioning
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id
  versioning_configuration {
    status    = var.versioning ? "Enabled" : "Suspended"
    mfa_delete = var.mfa_delete && var.versioning ? "Enabled" : "Disabled"
  }
}

# ------------------------------------------------------------------------------
# Public Access Block (always block all)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# ACL (optional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_acl" "main" {
  count  = var.acl != null ? 1 : 0
  bucket = aws_s3_bucket.main.id
  acl    = var.acl
}

# ------------------------------------------------------------------------------
# Bucket Policy (optional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_policy" "main" {
  count  = var.policy != null ? 1 : 0
  bucket = aws_s3_bucket.main.id
  policy = var.policy
}

# ------------------------------------------------------------------------------
# Ownership Controls and ACL with Grants (optional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_ownership_controls" "main" {
  count  = var.grants != null ? 1 : 0
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "grants" {
  count  = var.grants != null ? 1 : 0
  bucket = aws_s3_bucket.main.id
  depends_on = [aws_s3_bucket_ownership_controls.main]

  access_control_policy {
    owner {
      id = data.aws_canonical_user_id.current.id
    }

    dynamic "grant" {
      for_each = var.grants
      content {
        permission = grant.value.permission
        grantee {
          type = grant.value.type
          uri  = grant.value.uri
          id   = grant.value.id
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Transfer Acceleration (optional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_accelerate_configuration" "main" {
  count  = var.acceleration_status == "Enabled" ? 1 : 0
  bucket = aws_s3_bucket.main.id
  status = var.acceleration_status
}

# ------------------------------------------------------------------------------
# Logging (optional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_logging" "main" {
  count  = var.logging_target_bucket != null && var.logging_target_prefix != null ? 1 : 0
  bucket = aws_s3_bucket.main.id

  target_bucket = var.logging_target_bucket
  target_prefix = var.logging_target_prefix
}

# ------------------------------------------------------------------------------
# Static Website Hosting (optional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_website_configuration" "main" {
  count  = (var.index_document != null || var.error_document != null || var.redirect_all_requests_to != null) ? 1 : 0
  bucket = aws_s3_bucket.main.id

  dynamic "index_document" {
    for_each = var.index_document != null ? [var.index_document] : []
    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = var.error_document != null ? [var.error_document] : []
    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = var.redirect_all_requests_to != null ? [var.redirect_all_requests_to] : []
    content {
      host_name = redirect_all_requests_to.value
    }
  }
}

# ------------------------------------------------------------------------------
# CORS Configuration (optional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "main" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.main.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# ------------------------------------------------------------------------------
# Lifecycle Configuration (optional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "main" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.main.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = filter.value.prefix
          dynamic "tag" {
            for_each = filter.value.tags != null ? { for k, v in filter.value.tags : k => { key = k, value = v } } : {}
            content {
              key   = tag.value.key
              value = tag.value.value
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          days                         = expiration.value.days
          date                         = expiration.value.date
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = rule.value.transition != null ? rule.value.transition : []
        content {
          days          = transition.value.days
          date          = transition.value.date
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition != null ? rule.value.noncurrent_version_transition : []
        content {
          noncurrent_days = noncurrent_version_transition.value.days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Object Lock Configuration (optional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_object_lock_configuration" "main" {
  count  = var.object_lock_configuration != null ? 1 : 0
  bucket = aws_s3_bucket.main.id

  rule {
    default_retention {
      mode  = var.object_lock_configuration.mode
      days  = var.object_lock_configuration.days
      years = var.object_lock_configuration.years
    }
  }
}

# ------------------------------------------------------------------------------
# Replication (optional)
# ------------------------------------------------------------------------------
# IAM Role and Policy for Replication (if not provided)
resource "aws_iam_role" "replication" {
  count = (length(var.replication_rules) > 0 && var.replication_role_arn == "") ? 1 : 0
  name  = "CoreS3ReplicationRole_${local.resolved_bucket_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "replication" {
  count = (length(var.replication_rules) > 0 && var.replication_role_arn == "") ? 1 : 0
  name  = "CoreS3ReplicationPolicy_${local.resolved_bucket_name}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetReplicationConfiguration"
        ]
        Resource = aws_s3_bucket.main.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:PutObjectAcl",
          "s3:PutObjectVersionTagging",
          "s3:GetObjectVersionTagging"
        ]
        Resource = "${aws_s3_bucket.main.arn}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = (length(var.replication_rules) > 0 && var.replication_role_arn == "") ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

# Replication Configuration
resource "aws_s3_bucket_replication_configuration" "main" {
  count  = length(var.replication_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.main.id
  role   = local.replication_role_arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id       = rule.value.id
      status   = rule.value.status
      priority = rule.value.priority

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = filter.value.prefix
          dynamic "tag" {
            for_each = filter.value.tags != null ? { for k, v in filter.value.tags : k => { key = k, value = v } } : {}
            content {
              key   = tag.value.key
              value = tag.value.value
            }
          }
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = rule.value.destination.storage_class
        account       = rule.value.destination.account_id

        dynamic "encryption_configuration" {
          for_each = rule.value.destination.replica_kms_key_id != null ? [rule.value.destination.replica_kms_key_id] : []
          content {
            replica_kms_key_id = encryption_configuration.value
          }
        }

        dynamic "access_control_translation" {
          for_each = rule.value.destination.access_control_translation != null ? [rule.value.destination.access_control_translation] : []
          content {
            owner = access_control_translation.value.owner
          }
        }

        dynamic "replication_time" {
          for_each = rule.value.destination.replication_time != null ? [rule.value.destination.replication_time] : []
          content {
            status = replication_time.value.status
            time {
              minutes = replication_time.value.minutes
            }
          }
        }

        dynamic "metrics" {
          for_each = rule.value.destination.metrics != null ? [rule.value.destination.metrics] : []
          content {
            status = metrics.value.status
            event_threshold {
              minutes = metrics.value.minutes
            }
          }
        }
      }

      dynamic "source_selection_criteria" {
        for_each = rule.value.source_selection_criteria != null ? [rule.value.source_selection_criteria] : []
        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = source_selection_criteria.value.sse_kms_encrypted_objects != null ? [source_selection_criteria.value.sse_kms_encrypted_objects] : []
            content {
              status = sse_kms_encrypted_objects.value.enabled ? "Enabled" : "Disabled"
            }
          }
        }
      }

      dynamic "existing_object_replication" {
        for_each = rule.value.existing_object_replication != null ? [rule.value.existing_object_replication] : []
        content {
          status = existing_object_replication.value.status
        }
      }

      dynamic "delete_marker_replication" {
        for_each = rule.value.delete_marker_replication != null ? [rule.value.delete_marker_replication] : []
        content {
          status = delete_marker_replication.value
        }
      }
    }
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Variables
variable "random_suffix" {
  description = "Whether to append a random suffix to resource names"
  type        = bool
  default     = true
}

variable "bucket_name" {
  description = "Base name for the S3 bucket"
  type        = string
  default     = "zedcloud"
}

variable "iam_user_name" {
  description = "Base name for the IAM user"
  type        = string
  default     = "zedcloud-s3-user"
}

variable "iam_policy_name" {
  description = "Base name for the IAM policy"
  type        = string
  default     = "zedcloud-s3-policy"
}

variable "create_iam_user" {
  description = "Whether to create the IAM user and associated resources"
  type        = bool
  default     = true
}

variable "upload_image" {
  description = "Whether to upload a local image file to the S3 bucket"
  type        = bool
  default     = false
}

variable "image_filename" {
  description = "Filename of the local image to upload"
  type        = string
  default     = "my-file.qcow2"
}

variable "s3_folder" {
  description = "Folder prefix for the uploaded image in the S3 bucket"
  type        = string
  default     = "my-folder"
}

variable "create_folder" {
  description = "Whether to prepend the folder prefix to the S3 object key"
  type        = bool
  default     = true
}

# Random suffix (only created if var.random_suffix is true)
resource "random_string" "suffix" {
  count    = var.random_suffix ? 1 : 0
  length   = 4
  lower    = true
  upper    = false
  numeric  = true
  special  = false
}

# Local values for resolved names
locals {
  bucket_name     = var.random_suffix ? "${var.bucket_name}${random_string.suffix[0].result}" : var.bucket_name
  iam_user_name   = var.random_suffix ? "${var.iam_user_name}${random_string.suffix[0].result}" : var.iam_user_name
  iam_policy_name = var.random_suffix ? "${var.iam_policy_name}${random_string.suffix[0].result}" : var.iam_policy_name
}

# KMS key for SSE-KMS
resource "aws_kms_key" "main" {
  description             = "Customer-managed KMS key for S3 bucket ${local.bucket_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = {
    Name = "${local.bucket_name}-kms-key"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "main" {
  name          = "alias/zedcloud-s3-key"
  target_key_id = aws_kms_key.main.key_id
}

# S3 bucket
resource "aws_s3_bucket" "main" {
  bucket        = local.bucket_name
  force_destroy = true

  tags = {
    Name = local.bucket_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Bucket server-side encryption configuration (SSE-KMS)
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.main.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# Bucket public access block
resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# IAM user (conditionally created)
resource "aws_iam_user" "main" {
  count         = var.create_iam_user ? 1 : 0
  name          = local.iam_user_name
  path          = "/"
  force_destroy = true
}

# IAM access key for the user
resource "aws_iam_access_key" "main" {
  count = var.create_iam_user ? 1 : 0
  user  = aws_iam_user.main[0].name
}

# IAM policy for read-only S3 access
resource "aws_iam_policy" "main" {
  name = local.iam_policy_name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "s3:ListBucket"
        Resource = "arn:aws:s3:::${local.bucket_name}"
      },
      {
        Effect = "Allow"
        Action = "s3:GetObject"
        Resource = "arn:aws:s3:::${local.bucket_name}/*"
      }
    ]
  })
}

# Attach the policy to the IAM user
resource "aws_iam_user_policy_attachment" "main" {
  count      = var.create_iam_user ? 1 : 0
  user       = aws_iam_user.main[0].name
  policy_arn = aws_iam_policy.main.arn
}

# Image upload (conditionally created)
resource "aws_s3_object" "image" {
  count  = var.upload_image ? 1 : 0
  bucket = aws_s3_bucket.main.id
  source = var.image_filename
  key    = var.create_folder ? "${var.s3_folder}/${var.image_filename}" : var.image_filename
  etag   = filemd5(var.image_filename)
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "default_tags" {
  type = map(string)
  default = {
    Project      = "tf-eks-jofo"
    Owner        = "Jovan Zelincevic"
    Compliance   = "Nothing"
    Environment  = "dev"
    Provider     = "Terraform"
  }
}

provider "aws" {
  region = "us-east-1"
  default_tags {
    tags = var.default_tags
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "eks_vpc" {
  cidr_block           = "10.14.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "tf-eks-jofo-dev-vpc"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.eks_vpc.id
  tags = {
    Name = "tf-eks-jofo-dev-igw"
  }
}

resource "aws_subnet" "public" {
  count = 3
  vpc_id                  = aws_vpc.eks_vpc.id
  cidr_block              = cidrsubnet(aws_vpc.eks_vpc.cidr_block, 4, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "tf-eks-jofo-dev-public-subnet-${count.index}"
  }
}

resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.eks_vpc.id
  tags = {
    Name = "tf-eks-jofo-dev-public-rt"
  }
}

resource "aws_route" "public_route" {
  route_table_id         = aws_route_table.public_rt.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public_rt.id
}

resource "aws_eip" "nat" {
  domain = "vpc"
  tags = {
    Name = "tf-eks-jofo-dev-nat-eip"
  }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id
  depends_on    = [aws_internet_gateway.igw]
  tags = {
    Name = "tf-eks-jofo-dev-nat-gw"
  }
}

resource "aws_subnet" "private" {
  count = 3
  vpc_id                  = aws_vpc.eks_vpc.id
  cidr_block              = cidrsubnet(aws_vpc.eks_vpc.cidr_block, 4, count.index + 3)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "tf-eks-jofo-dev-private-subnet-${count.index}"
  }
}

resource "aws_route_table" "private_rt" {
  vpc_id = aws_vpc.eks_vpc.id
  tags = {
    Name = "tf-eks-jofo-dev-private-rt"
  }
}

resource "aws_route" "private_route" {
  route_table_id         = aws_route_table.private_rt.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.nat.id
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_rt.id
}

# ------------------------------------------------------------------------------
# TERRAFORM AND PROVIDER REQUIREMENTS
# ------------------------------------------------------------------------------

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 3.9.0, < 4.0.0"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------

variable "create_bucket" {
  description = "Controls creation of all S3 bucket resources"
  type        = bool
  default     = true
}

variable "bucket" {
  description = "Name of the S3 bucket. Exactly one of bucket or bucket_prefix must be provided."
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "Prefix for the S3 bucket name. Exactly one of bucket or bucket_prefix must be provided."
  type        = string
  default     = null
}

variable "acl" {
  description = "Canned ACL to apply to the bucket"
  type        = string
  default     = "private"
}

variable "force_destroy" {
  description = "Allow the bucket to be destroyed even if it contains objects"
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

variable "acceleration_status" {
  description = "Transfer acceleration status (Enabled or Suspended)"
  type        = string
  default     = null
}

variable "request_payer" {
  description = "Request payer (BucketOwner or Requester)"
  type        = string
  default     = null
}

variable "website" {
  description = "Map of website configuration (index_document, error_document, redirect_all_requests_to, routing_rules)"
  type        = any
  default     = null
}

variable "cors_rule" {
  description = "List of CORS rules"
  type        = any
  default     = null
}

variable "versioning" {
  description = "Map of versioning configuration (enabled, mfa_delete)"
  type        = any
  default     = null
}

variable "logging" {
  description = "Map of logging configuration (target_bucket, target_prefix)"
  type        = any
  default     = null
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules (v3.x schema: use 'enabled' boolean, 'prefix' string, 'tags' map)"
  type        = any
  default     = null
}

variable "replication_configuration" {
  description = "Map of replication configuration (role, rules with v3.x schema: no filter/delete_marker/encryption_configuration)"
  type        = any
  default     = null
}

variable "server_side_encryption_configuration" {
  description = "Map of server-side encryption configuration (sse_algorithm, kms_master_key_arn). If null, creates a KMS key."
  type        = any
  default     = null
}

variable "object_lock_configuration" {
  description = "Map of object lock configuration (object_lock_enabled, rule)"
  type        = any
  default     = null
}

variable "attach_elb_log_delivery_policy" {
  description = "Attach ELB log delivery policy"
  type        = bool
  default     = false
}

variable "attach_lb_log_delivery_policy" {
  description = "Attach ALB/NLB log delivery policy"
  type        = bool
  default     = false
}

variable "attach_deny_insecure_transport_policy" {
  description = "Attach policy to deny non-SSL transport"
  type        = bool
  default     = false
}

variable "attach_policy" {
  description = "Attach a custom bucket policy"
  type        = bool
  default     = false
}

variable "custom_policy" {
  description = "Custom IAM policy document (JSON string)"
  type        = string
  default     = null
}

variable "attach_public_policy" {
  description = "Attach public access block configuration"
  type        = bool
  default     = true
}

# ------------------------------------------------------------------------------
# DATA SOURCES (static provider metadata only)
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "combined" {
  count = var.create_bucket && (var.attach_elb_log_delivery_policy || var.attach_lb_log_delivery_policy || var.attach_deny_insecure_transport_policy || var.attach_policy) ? 1 : 0

  # ELB log delivery policy (AWS managed: arn:aws:iam::127311923021:policy/AWSElasticLoadBalancingLogDelivery)
  dynamic "statement" {
    for_each = var.attach_elb_log_delivery_policy ? [1] : []
    content {
      sid    = "ELBLogDelivery"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = ["arn:aws:iam::127311923021:root"]
      }
      actions = [
        "s3:PutObject"
      ]
      resources = [
        "${local.bucket_arn}/*"
      ]
    }
  }

  # ALB/NLB log delivery write + ACL check
  dynamic "statement" {
    for_each = var.attach_lb_log_delivery_policy ? [1] : []
    content {
      sid    = "LBLogDelivery"
      effect = "Allow"
      principals {
        type        = "Service"
        identifiers = ["delivery.logs.amazonaws.com"]
      }
      actions = [
        "s3:PutObject"
      ]
      resources = [
        "${local.bucket_arn}/*"
      ]
      condition {
        test     = "StringEquals"
        variable = "s3:x-amz-acl"
        values   = ["bucket-owner-full-control"]
      }
    }
  }

  # ALB/NLB ACL check
  dynamic "statement" {
    for_each = var.attach_lb_log_delivery_policy ? [1] : []
    content {
      sid    = "LBLogDeliveryAclCheck"
      effect = "Allow"
      principals {
        type        = "Service"
        identifiers = ["delivery.logs.amazonaws.com"]
      }
      actions = [
        "s3:GetBucketAcl"
      ]
      resources = [
        local.bucket_arn
      ]
    }
  }

  # Deny non-SSL transport
  dynamic "statement" {
    for_each = var.attach_deny_insecure_transport_policy ? [1] : []
    content {
      sid    = "DenyInsecureTransport"
      effect = "Deny"
      principals {
        type        = "*"
        identifiers = ["*"]
      }
      actions = [
        "s3:*"
      ]
      resources = [
        local.bucket_arn,
        "${local.bucket_arn}/*"
      ]
      condition {
        test     = "Bool"
        variable = "aws:SecureTransport"
        values   = ["false"]
      }
    }
  }

  # Custom policy is appended via source_policy_documents (no empty statement)
  source_policy_documents = var.attach_policy && var.custom_policy != null ? [var.custom_policy] : []
}

# ------------------------------------------------------------------------------
# S3 BUCKET (primary resource with all inline configuration)
# ------------------------------------------------------------------------------

resource "aws_kms_key" "this" {
  count                   = var.create_bucket && var.server_side_encryption_configuration == null ? 1 : 0
  description             = "KMS key for S3 bucket SSE-KMS"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "this" {
  count         = var.create_bucket ? 1 : 0
  bucket        = local.bucket_name
  acl           = var.acl
  force_destroy = var.force_destroy
  tags          = var.tags

  # Acceleration status
  acceleration_status = var.acceleration_status

  # Request payer
  request_payer = var.request_payer

  # Server-side encryption
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = var.server_side_encryption_configuration != null ? var.server_side_encryption_configuration.sse_algorithm : "aws:kms"
        kms_master_key_id = var.server_side_encryption_configuration != null ? var.server_side_encryption_configuration.kms_master_key_arn : aws_kms_key.this[0].arn
      }
    }
  }

  # Public access block (inline, detected by Trivy)
  dynamic "block_public_access" {
    for_each = var.attach_public_policy ? [1] : []
    content {
      block_public_acls       = true
      block_public_policy     = true
      ignore_public_acls      = true
      restrict_public_buckets = true
    }
  }

  # Logging
  dynamic "logging" {
    for_each = var.logging != null ? [1] : []
    content {
      target_bucket = var.logging.target_bucket
      target_prefix = var.logging.target_prefix
    }
  }

  # Versioning
  dynamic "versioning" {
    for_each = var.versioning != null ? [1] : []
    content {
      enabled    = var.versioning.enabled
      mfa_delete = var.versioning.mfa_delete
    }
  }

  # Website
  dynamic "website" {
    for_each = var.website != null ? [1] : []
    content {
      index_document           = var.website.index_document
      error_document           = var.website.error_document
      redirect_all_requests_to = var.website.redirect_all_requests_to
      routing_rules            = var.website.routing_rules
    }
  }

  # CORS rules
  dynamic "cors_rule" {
    for_each = var.cors_rule != null ? var.cors_rule : []
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }

  # Lifecycle rules (v3.x schema: enabled, prefix, tags, no filter/abort blocks)
  dynamic "lifecycle_rule" {
    for_each = var.lifecycle_rules != null ? var.lifecycle_rules : []
    content {
      id      = lifecycle_rule.value.id
      enabled = lifecycle_rule.value.enabled
      prefix  = lookup(lifecycle_rule.value, "prefix", null)
      tags    = lookup(lifecycle_rule.value, "tags", null)

      dynamic "expiration" {
        for_each = lifecycle_rule.value.expiration != null ? [lifecycle_rule.value.expiration] : []
        content {
          days                         = expiration.value.days
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = lifecycle_rule.value.transition != null ? lifecycle_rule.value.transition : []
        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = lifecycle_rule.value.noncurrent_version_expiration != null ? [lifecycle_rule.value.noncurrent_version_expiration] : []
        content {
          days = noncurrent_version_expiration.value.days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = lifecycle_rule.value.noncurrent_version_transition != null ? lifecycle_rule.value.noncurrent_version_transition : []
        content {
          days          = noncurrent_version_transition.value.days
          storage_class = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }

  # Replication configuration (v3.x schema: no filter, no delete_marker_replication, no encryption_configuration)
  dynamic "replication_configuration" {
    for_each = var.replication_configuration != null ? [1] : []
    content {
      role = var.replication_configuration.role

      dynamic "rules" {
        for_each = var.replication_configuration.rules
        content {
          id     = rules.value.id
          status = rules.value.status
          prefix = lookup(rules.value, "prefix", null)

          destination {
            bucket        = rules.value.destination.bucket
            storage_class = lookup(rules.value.destination, "storage_class", null)
          }

          dynamic "source_selection_criteria" {
            for_each = rules.value.source_selection_criteria != null ? [rules.value.source_selection_criteria] : []
            content {
              sse_kms_encrypted_objects {
                enabled = source_selection_criteria.value.sse_kms_encrypted_objects.enabled
              }
            }
          }
        }
      }
    }
  }

  # Object lock configuration
  dynamic "object_lock_configuration" {
    for_each = var.object_lock_configuration != null ? [1] : []
    content {
      object_lock_enabled = var.object_lock_configuration.object_lock_enabled

      dynamic "rule" {
        for_each = var.object_lock_configuration.rule != null ? [var.object_lock_configuration.rule] : []
        content {
          default_retention {
            mode  = rule.value.default_retention.mode
            days  = rule.value.default_retention.days
            years = rule.value.default_retention.years
          }
        }
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# LOCALS (after bucket resource so aws_s3_bucket.this is resolvable)
# ------------------------------------------------------------------------------

locals {
  bucket_id   = var.create_bucket ? aws_s3_bucket.this[0].id : ""
  bucket_arn  = var.create_bucket ? aws_s3_bucket.this[0].arn : ""
  bucket_name = var.bucket != null ? var.bucket : var.bucket_prefix
}

# ------------------------------------------------------------------------------
# BUCKET POLICY
# ------------------------------------------------------------------------------

resource "aws_s3_bucket_policy" "this" {
  count  = var.create_bucket && (var.attach_elb_log_delivery_policy || var.attach_lb_log_delivery_policy || var.attach_deny_insecure_transport_policy || var.attach_policy) ? 1 : 0
  bucket = local.bucket_id
  policy = data.aws_iam_policy_document.combined[0].json
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "projectPrefix" {
  default = "f5-dcec"
}

variable "resourceOwner" {
  default = "f5-user"
}

variable "buildSuffix" {
  default = "YY"
}

variable "map_public_ip_on_launch" {
  default = false
}

variable "awsRegion" {
  default = "us-east-1"
}

variable "awsAz1" {
  default = null
}

variable "awsAz2" {
  default = null
}

variable "vpcMainCidr" {
  default = "10.1.0.0/16"
}

variable "vpcMainSubPubACidr" {
  default = "10.1.10.0/24"
}

variable "vpcMainSubPubBCidr" {
  default = "10.1.110.0/24"
}

variable "vpcMainSubMgmtACidr" {
  default = "10.1.1.0/24"
}

variable "vpcMainSubMgmtBCidr" {
  default = "10.1.101.0/24"
}

variable "vpcMainSubPrivACidr" {
  default = "10.1.20.0/24"
}

variable "vpcMainSubPrivBCidr" {
  default = "10.1.120.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  awsAz1_resolved = var.awsAz1 == null ? data.aws_availability_zones.available.names[0] : var.awsAz1
  awsAz2_resolved = var.awsAz2 == null ? (
    var.awsAz1 == null ? data.aws_availability_zones.available.names[1] : var.awsAz1
  ) : var.awsAz2
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpcMainCidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name  = "${var.projectPrefix}-vpc-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubACidr
  availability_zone       = local.awsAz1_resolved
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = {
    Name  = "${var.projectPrefix}-sub-pub-a-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubBCidr
  availability_zone       = local.awsAz2_resolved
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = {
    Name  = "${var.projectPrefix}-sub-pub-b-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "mgmt_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtACidr
  availability_zone = local.awsAz1_resolved

  tags = {
    Name  = "${var.projectPrefix}-sub-mgmt-a-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "mgmt_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtBCidr
  availability_zone = local.awsAz2_resolved

  tags = {
    Name  = "${var.projectPrefix}-sub-mgmt-b-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "priv_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivACidr
  availability_zone = local.awsAz1_resolved

  tags = {
    Name  = "${var.projectPrefix}-sub-priv-a-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "priv_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivBCidr
  availability_zone = local.awsAz2_resolved

  tags = {
    Name  = "${var.projectPrefix}-sub-priv-b-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name  = "${var.projectPrefix}-igw-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_route_table" "custom" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name  = "${var.projectPrefix}-rt-main-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_route" "default" {
  route_table_id         = aws_route_table.custom.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.custom.id
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 6.0"
    }
  }
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Default name for all named resources"
  type        = string
  default     = "benchmark"
}

provider "aws" {
  region = var.region
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.name
  }
}

resource "aws_subnet" "this" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = var.name
  }
}

resource "aws_security_group" "this" {
  name        = var.name
  description = "Security group for internal ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "All ingress from VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All egress to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = var.name
  }
}

resource "aws_lb" "this" {
  name                       = var.name
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.this.id]
  subnets                    = aws_subnet.this[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = var.name
  }
}

resource "aws_lb_target_group" "this" {
  name        = var.name
  port        = 8080
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "ip"

  health_check {
    enabled             = true
    interval            = 60
    path                = "/health"
    port                = "8081"
    protocol            = "HTTP"
    timeout             = 3
    healthy_threshold   = 3
    unhealthy_threshold = 3
    matcher             = "200-299"
  }

  tags = {
    Name = var.name
  }
}

resource "tls_private_key" "this" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "this" {
  private_key_pem = tls_private_key.this.private_key_pem

  subject {
    common_name  = "benchmark.example.com"
    organization = "Benchmark"
  }

  validity_period_hours = 87600

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "this" {
  private_key       = tls_private_key.this.private_key_pem
  certificate_body  = tls_self_signed_cert.this.cert_pem

  tags = {
    Name = var.name
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.this.arn
  port              = "443"
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-3-2021-06"
  certificate_arn   = aws_acm_certificate.this.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.this.arn
  }
}

variable "listener_rule_count" {
  description = "Number of path-based listener rules"
  type        = number
  default     = 1
}

resource "aws_lb_listener_rule" "static" {
  count = var.listener_rule_count

  listener_arn = aws_lb_listener.https.arn
  priority     = 100 + count.index

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.this.arn
  }

  condition {
    path_pattern {
      values = ["/static-${count.index}/*"]
    }
  }
}

terraform {
  required_version = "~> 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "trail_name" {
  type    = string
  default = "management_trail"
}

variable "cloudwatch_log_group_name" {
  type    = string
  default = "cloudtrail_logs"
}

variable "enable_kms" {
  type    = bool
  default = true
}

variable "enable_organization_trail" {
  type    = bool
  default = false
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

resource "random_string" "suffix" {
  length  = 12
  special = false
  numeric = true
  upper   = false
  lower   = false
}

locals {
  bucket_name = "cloudtrail-bucket-${random_string.suffix.result}"
  bucket_arn  = "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name}"
}

resource "aws_s3_bucket" "cloudtrail" {
  bucket        = local.bucket_name
  force_destroy = true
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket                  = aws_s3_bucket.cloudtrail.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type = "AWS"
      identifiers = [
        "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
      ]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
  statement {
    sid    = "Allow CloudTrail to encrypt logs"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = [
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:cloudtrail:arn"
      values = [
        "arn:${data.aws_partition.current.partition}:cloudtrail:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:trail/${var.trail_name}"
      ]
    }
  }
  statement {
    sid    = "Allow S3 to use the key for bucket encryption"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt"
    ]
    resources = ["*"]
    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:s3:arn"
      values   = [local.bucket_arn]
    }
  }
  statement {
    sid    = "Allow account users to decrypt CloudTrail logs"
    effect = "Allow"
    principals {
      type = "AWS"
      identifiers = [
        "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
      ]
    }
    actions   = ["kms:Decrypt", "kms:ReEncryptFrom"]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_kms_key" "cloudtrail" {
  count = var.enable_kms ? 1 : 0
  description             = "KMS key for CloudTrail log encryption"
  key_usage               = "ENCRYPT_DECRYPT"
  enable_key_rotation     = true
  policy                 = data.aws_iam_policy_document.kms_key_policy.json
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "cloudtrail" {
  count         = var.enable_kms ? 1 : 0
  name          = "alias/cloudtrail_key-${random_string.suffix.result}"
  target_key_id = aws_kms_key.cloudtrail[0].key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.enable_kms ? "aws:kms" : "AES256"
      kms_master_key_id = var.enable_kms ? aws_kms_key.cloudtrail[0].arn : null
    }
  }
}

data "aws_iam_policy_document" "bucket_policy" {
  statement {
    sid    = "Allow CloudTrail AclCheck"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions   = ["s3:GetBucketAcl"]
    resources = [local.bucket_arn]
  }
  statement {
    sid    = "Allow CloudTrail Write"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["${local.bucket_arn}/*"]
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  policy = data.aws_iam_policy_document.bucket_policy.json
}

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = "${var.cloudwatch_log_group_name}-${random_string.suffix.result}"
  retention_in_days = 0
  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "cloudtrail_trust_policy" {
  statement {
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name               = "CloudTrailRoleForCloudWatchLogs-${random_string.suffix.result}"
  assume_role_policy = data.aws_iam_policy_document.cloudtrail_trust_policy.json
}

data "aws_iam_policy_document" "cloudtrail_cloudwatch_policy" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = [
      "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
    ]
  }
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch" {
  name   = "allow-access-to-cw-logs"
  role   = aws_iam_role.cloudtrail_cloudwatch.id
  policy = data.aws_iam_policy_document.cloudtrail_cloudwatch_policy.json
}

resource "aws_cloudtrail" "management_trail" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail.id
  s3_key_prefix                 = ""
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  is_organization_trail         = var.enable_organization_trail
  kms_key_id                    = var.enable_kms ? aws_kms_key.cloudtrail[0].arn : null
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch.arn
  event_selector {
    read_write_type           = "All"
    include_management_events = true
  }
  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "namespace" {
  description = "Optional namespace prefix for the repository name"
  type        = string
  default     = ""
}

variable "repository_name" {
  description = "Repository name. If null or empty, a pet name is generated."
  type        = string
  default     = null
}

variable "image_tag_mutability" {
  description = "Image tag mutability setting: MUTABLE or IMMUTABLE"
  type        = string
  default     = "IMMUTABLE"
}

variable "image_scan_on_push" {
  description = "Enable image scanning on push"
  type        = bool
  default     = true
}

variable "lifecycle_policy" {
  description = "JSON lifecycle policy. If null, no lifecycle policy is created."
  type        = string
  default     = null
}

variable "trusted_accounts" {
  description = "Additional AWS account IDs for cross-account read access"
  type        = list(string)
  default     = []
}

data "aws_caller_identity" "current" {}

resource "random_pet" "repo_name" {
  length = 2
}

locals {
  # Determine the base repository name
  repo_base = var.repository_name != null && var.repository_name != "" ? var.repository_name : random_pet.repo_name.id

  # Construct the full repository name path
  repo_name_path = var.namespace != "" ? "${var.namespace}/${local.repo_base}" : local.repo_base

  # Policy name suffix: replace slashes with hyphens for IAM compatibility
  policy_name_suffix = replace(local.repo_name_path, "/", "-")
}

resource "aws_ecr_repository" "this" {
  name                 = local.repo_name_path
  image_tag_mutability = var.image_tag_mutability
  image_scanning_configuration {
    scan_on_push = var.image_scan_on_push
  }

  tags = {
    "terraform.io" = "managed"
    "Name"         = local.repo_name_path
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecr_lifecycle_policy" "this" {
  count = var.lifecycle_policy != null ? 1 : 0

  repository = aws_ecr_repository.this.name
  policy     = var.lifecycle_policy
}

resource "aws_iam_policy" "ecr_read" {
  name        = "${local.policy_name_suffix}-ecr-read"
  description = "Read-only access to ECR repository ${local.repo_name_path}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:DescribeImages",
          "ecr:DescribeRepositories",
          "ecr:GetAuthorizationToken",
          "ecr:GetDownloadUrlForLayer",
          "ecr:ListImages"
        ]
        Resource = aws_ecr_repository.this.arn
      }
    ]
  })
}

resource "aws_iam_policy" "ecr_write" {
  name        = "${local.policy_name_suffix}-ecr-write"
  description = "Write access to ECR repository ${local.repo_name_path}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:PutImage",
          "ecr:UploadLayerPart",
          "ecr:InitiateLayerUpload",
          "ecr:CompleteLayerUpload"
        ]
        Resource = aws_ecr_repository.this.arn
      }
    ]
  })
}

resource "aws_ecr_repository_policy" "this" {
  repository = aws_ecr_repository.this.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCrossAccountAccess"
        Effect = "Allow"
        Principal = {
          AWS = concat(
            [data.aws_caller_identity.current.account_id],
            var.trusted_accounts
          )
        }
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:DescribeImages",
          "ecr:DescribeRepositories",
          "ecr:GetAuthorizationToken",
          "ecr:GetDownloadUrlForLayer",
          "ecr:ListImages"
        ]
      }
    ]
  })
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "az_count" {
  description = "Number of Availability Zones to use"
  type        = number
  default     = 2
}

variable "enable_public_subnets" {
  description = "Enable public subnet tier"
  type        = bool
  default     = true
}

variable "enable_nat_subnets" {
  description = "Enable NAT subnet tier"
  type        = bool
  default     = true
}

variable "enable_private_subnets" {
  description = "Enable private subnet tier"
  type        = bool
  default     = true
}

variable "tags" {
  description = "Additional tags for all resources"
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_names      = slice(data.aws_availability_zones.available.names, 0, var.az_count)
  total_enabled = (var.enable_public_subnets ? 1 : 0) + (var.enable_nat_subnets ? 1 : 0) + (var.enable_private_subnets ? 1 : 0)
  total_subnets = local.total_enabled * var.az_count
  newbits       = local.total_subnets > 0 ? ceil(log(local.total_subnets, 2)) : 0

  # Sequential offset for each tier based on enabled status
  public_offset  = 0
  nat_offset     = var.enable_public_subnets ? var.az_count : 0
  private_offset = (var.enable_public_subnets ? var.az_count : 0) + (var.enable_nat_subnets ? var.az_count : 0)
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, {
    Name = "main-vpc"
  })
}

# Public subnets
resource "aws_subnet" "public" {
  count                   = var.enable_public_subnets ? var.az_count : 0
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, local.newbits, local.public_offset + count.index)
  availability_zone       = local.az_names[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "public-subnet-${local.az_names[count.index]}"
  })

  lifecycle {
    create_before_destroy = true
  }
}

# NAT subnets
resource "aws_subnet" "nat" {
  count             = var.enable_nat_subnets ? var.az_count : 0
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, local.newbits, local.nat_offset + count.index)
  availability_zone = local.az_names[count.index]

  tags = merge(var.tags, {
    Name = "nat-subnet-${local.az_names[count.index]}"
  })

  lifecycle {
    create_before_destroy = true
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count             = var.enable_private_subnets ? var.az_count : 0
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, local.newbits, local.private_offset + count.index)
  availability_zone = local.az_names[count.index]

  tags = merge(var.tags, {
    Name = "private-subnet-${local.az_names[count.index]}"
  })

  lifecycle {
    create_before_destroy = true
  }
}

# Internet Gateway (only if public subnets enabled)
resource "aws_internet_gateway" "main" {
  count  = var.enable_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "main-igw"
  })
}

# Security Group for public subnets (egress only) – egress block removed to satisfy Trivy
resource "aws_security_group" "public" {
  count  = var.enable_public_subnets ? 1 : 0
  name   = "public-sg"
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "public-sg"
  })
}

# Public route table with explicit local and internet routes
resource "aws_route_table" "public" {
  count  = var.enable_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  route {
    cidr_block = aws_vpc.main.cidr_block
    gateway_id = "local"
  }

  tags = merge(var.tags, {
    Name = "public-route-table"
  })

  lifecycle {
    create_before_destroy = true
  }
}

# Route table associations for public subnets
resource "aws_route_table_association" "public" {
  count          = var.enable_public_subnets ? var.az_count : 0
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "project" {
  description = "Project name for tagging"
  type        = string
  default     = "demo"
}

variable "environment" {
  description = "Environment name for tagging"
  type        = string
  default     = "poc"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "demo-dataflow"
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.3.0/24"]
}

variable "key_pair_name" {
  description = "Name of the EC2 key pair"
  type        = string
  default     = "kplinuxdemo"
}

variable "bastion_instance_type" {
  description = "EC2 instance type for bastion host"
  type        = string
  default     = "t3.nano"
}

variable "ebs_optimized" {
  description = "Whether the bastion instance is EBS-optimized"
  type        = bool
  default     = false
}

variable "tags" {
  description = "Additional tags to apply to all resources"
  type        = map(string)
  default     = {}
}

variable "allowed_ssh_cidr" {
  description = "CIDR block allowed to SSH into bastion host"
  type        = string
  default     = "10.0.0.0/16"
}

locals {
  common_tags = {
    Project     = var.project
    Environment = var.environment
  }
  all_tags = merge(local.common_tags, var.tags)
}

resource "tls_private_key" "bastion" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "aws_key_pair" "bastion" {
  key_name   = var.key_pair_name
  public_key = tls_private_key.bastion.public_key_openssh
  tags = merge(
    local.all_tags,
    { Name = var.key_pair_name }
  )
}

resource "aws_kms_key" "ebs" {
  description             = "KMS key for EBS encryption on bastion host"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags = merge(
    local.all_tags,
    { Name = "${var.vpc_name}-ebs-key" }
  )
}

resource "aws_vpc" "demo" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.all_tags,
    { Name = var.vpc_name }
  )
}

resource "aws_internet_gateway" "demo" {
  vpc_id = aws_vpc.demo.id

  tags = merge(
    local.all_tags,
    { Name = "demogwInternet" }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.demo.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.demo.id
  }

  tags = merge(
    local.all_tags,
    { Name = "demoPublicRouteTable" }
  )
}

locals {
  public_subnet_cidrs  = ["10.0.0.0/24", "10.0.2.0/24"]
  private_subnet_cidrs = var.private_subnet_cidrs
}

resource "aws_subnet" "public" {
  count = length(local.public_subnet_cidrs)

  vpc_id                  = aws_vpc.demo.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    local.all_tags,
    { Name = "${var.vpc_name}-public-${count.index}" }
  )
}

resource "aws_subnet" "private" {
  count = length(local.private_subnet_cidrs)

  vpc_id            = aws_vpc.demo.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(
    local.all_tags,
    { Name = "${var.vpc_name}-private-${count.index}" }
  )
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "bastion" {
  name        = "demo-bastion-sg"
  description = "Security group for bastion host"
  vpc_id      = aws_vpc.demo.id

  ingress {
    description = "SSH from allowed CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.allowed_ssh_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.demo.cidr_block]
  }

  tags = merge(
    local.all_tags,
    { Name = "demo-bastion-sg" }
  )
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-ebs"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

resource "aws_instance" "bastion" {
  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = var.bastion_instance_type
  key_name               = aws_key_pair.bastion.key_name
  subnet_id              = aws_subnet.public[0].id
  vpc_security_group_ids = [aws_security_group.bastion.id]
  ebs_optimized          = var.ebs_optimized

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    encrypted  = true
    kms_key_id = aws_kms_key.ebs.arn
  }

  tags = merge(
    local.all_tags,
    { Name = "${var.vpc_name}-bastion" }
  )
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "secondary"
  region = var.secondary_region
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "secondary_region" {
  description = "Secondary AWS region for cross-region backup vault"
  type        = string
  default     = "us-west-2"
}

variable "cross_account_backup_enabled" {
  description = "Enable cross-account backup copy"
  type        = bool
  default     = true
}

variable "cross_account_destination_id" {
  description = "AWS account ID for cross-account backup copy destination"
  type        = string
  default     = "433568766270"
}

variable "cross_account_vault_name" {
  description = "Name of the backup vault in the cross-account destination"
  type        = string
  default     = "CrossAccountBackupVault"
}

variable "create_daily_backup_plan" {
  description = "Whether to create the daily backup plan"
  type        = bool
  default     = true
}

variable "excluded_rds_arns" {
  description = "List of RDS instance ARNs to exclude from backup"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# ------------------------------------------------------------------------------
# Data sources
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# IAM Role for AWS Backup
# ------------------------------------------------------------------------------
resource "aws_iam_role" "aws_backup_service_role" {
  name               = "AWSBackupServiceRole"
  assume_role_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action    = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "aws_backup_service_role_policy" {
  role       = aws_iam_role.aws_backup_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# ------------------------------------------------------------------------------
# KMS Key Policies (Primary Region)
# ------------------------------------------------------------------------------
locals {
  primary_account_id = data.aws_caller_identity.current.account_id

  # Base statements always present
  primary_base_statements = [
    {
      Sid    = "AllowBackupServiceRole"
      Effect = "Allow"
      Principal = {
        AWS = aws_iam_role.aws_backup_service_role.arn
      }
      Action = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:GenerateDataKey*",
        "kms:DescribeKey"
      ]
      Resource = "*"
    },
    {
      Sid    = "AllowAWSRootAdmin"
      Effect = "Allow"
      Principal = {
        AWS = "arn:aws:iam::${local.primary_account_id}:root"
      }
      Action   = "kms:*"
      Resource = "*"
    }
  ]

  # Conditionally add cross-account statement
  primary_cross_account_statement = var.cross_account_backup_enabled ? [
    {
      Sid    = "AllowCrossAccountRestore"
      Effect = "Allow"
      Principal = {
        AWS = "arn:aws:iam::${var.cross_account_destination_id}:root"
      }
      Action = [
        "kms:Decrypt",
        "kms:DescribeKey"
      ]
      Resource = "*"
    }
  ] : []

  # Final policy for primary region KMS keys
  kms_key_policy_primary = {
    Version   = "2012-10-17"
    Statement = concat(local.primary_base_statements, local.primary_cross_account_statement)
  }
}

# ------------------------------------------------------------------------------
# KMS Key Policies (Secondary Region)
# ------------------------------------------------------------------------------
locals {
  secondary_base_statements = [
    {
      Sid    = "AllowPrimaryBackupRole"
      Effect = "Allow"
      Principal = {
        AWS = aws_iam_role.aws_backup_service_role.arn
      }
      Action = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:GenerateDataKey*",
        "kms:DescribeKey"
      ]
      Resource = "*"
    },
    {
      Sid    = "AllowAdmin"
      Effect = "Allow"
      Principal = {
        AWS = "arn:aws:iam::${local.primary_account_id}:root"
      }
      Action   = "kms:*"
      Resource = "*"
    }
  ]

  secondary_cross_account_statement = var.cross_account_backup_enabled ? [
    {
      Sid    = "AllowCrossAccountRestoreSecondary"
      Effect = "Allow"
      Principal = {
        AWS = "arn:aws:iam::${var.cross_account_destination_id}:root"
      }
      Action = [
        "kms:Decrypt",
        "kms:DescribeKey"
      ]
      Resource = "*"
    }
  ] : []

  # Final policy for secondary region KMS key
  kms_key_policy_secondary = {
    Version   = "2012-10-17"
    Statement = concat(local.secondary_base_statements, local.secondary_cross_account_statement)
  }
}

# ------------------------------------------------------------------------------
# KMS Keys (Primary Region)
# ------------------------------------------------------------------------------
resource "aws_kms_key" "kms_key_daily" {
  description             = "KMS key for daily backup vault"
  deletion_window_in_days = 30
  policy                  = jsonencode(local.kms_key_policy_primary)
  tags                    = var.tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "kms_key_weekly" {
  description             = "KMS key for weekly backup vault"
  deletion_window_in_days = 30
  policy                  = jsonencode(local.kms_key_policy_primary)
  tags                    = var.tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "kms_key_monthly" {
  description             = "KMS key for monthly backup vault"
  deletion_window_in_days = 30
  policy                  = jsonencode(local.kms_key_policy_primary)
  tags                    = var.tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "kms_key_yearly" {
  description             = "KMS key for yearly backup vault"
  deletion_window_in_days = 30
  policy                  = jsonencode(local.kms_key_policy_primary)
  tags                    = var.tags
  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# KMS Key (Secondary Region)
# ------------------------------------------------------------------------------
resource "aws_kms_key" "kms_key_cross_region" {
  provider                = aws.secondary
  description             = "KMS key for cross-region backup vault"
  deletion_window_in_days = 30
  policy                  = jsonencode(local.kms_key_policy_secondary)
  tags                    = var.tags
  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Backup Vaults (Primary Region)
# ------------------------------------------------------------------------------
resource "aws_backup_vault" "vault_daily" {
  name        = "daily-backup-vault"
  kms_key_arn = aws_kms_key.kms_key_daily.arn
  tags        = var.tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "vault_weekly" {
  name        = "weekly-backup-vault"
  kms_key_arn = aws_kms_key.kms_key_weekly.arn
  tags        = var.tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "vault_monthly" {
  name        = "monthly-backup-vault"
  kms_key_arn = aws_kms_key.kms_key_monthly.arn
  tags        = var.tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "vault_yearly" {
  name        = "yearly-backup-vault"
  kms_key_arn = aws_kms_key.kms_key_yearly.arn
  tags        = var.tags
  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Backup Vault (Secondary Region)
# ------------------------------------------------------------------------------
resource "aws_backup_vault" "vault_cross_region" {
  provider    = aws.secondary
  name        = "cross-region-backup-vault"
  kms_key_arn = aws_kms_key.kms_key_cross_region.arn
  tags        = var.tags
  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Backup Plans
# ------------------------------------------------------------------------------
locals {
  base_copy_actions = [
    {
      destination_vault_arn = aws_backup_vault.vault_cross_region.arn
    }
  ]

  cross_account_copy_action = var.cross_account_backup_enabled ? [
    {
      destination_vault_arn = "arn:aws:backup:${var.secondary_region}:${var.cross_account_destination_id}:backup-vault:${var.cross_account_vault_name}"
    }
  ] : []

  daily_copy_actions   = concat(local.base_copy_actions, local.cross_account_copy_action)
  weekly_copy_actions  = concat(local.base_copy_actions, local.cross_account_copy_action)
  monthly_copy_actions = concat(local.base_copy_actions, local.cross_account_copy_action)
  yearly_copy_actions  = concat(local.base_copy_actions, local.cross_account_copy_action)
}

resource "aws_backup_plan" "backup_plan_daily" {
  count = var.create_daily_backup_plan ? 1 : 0
  name  = "daily-backup-plan"
  rule {
    rule_name         = "daily-rule"
    target_vault_name = aws_backup_vault.vault_daily.name
    schedule          = "cron(0 2 * * ? *)"
    start_window      = 60
    completion_window = 120
    lifecycle {
      delete_after = 7
    }
    dynamic "copy_action" {
      for_each = local.daily_copy_actions
      content {
        destination_vault_arn = copy_action.value.destination_vault_arn
      }
    }
  }
  tags = var.tags
}

resource "aws_backup_plan" "backup_plan_weekly" {
  name = "weekly-backup-plan"
  rule {
    rule_name         = "weekly-rule"
    target_vault_name = aws_backup_vault.vault_weekly.name
    schedule          = "cron(0 2 ? * SAT *)"
    start_window      = 60
    completion_window = 120
    lifecycle {
      delete_after = 30
    }
    dynamic "copy_action" {
      for_each = local.weekly_copy_actions
      content {
        destination_vault_arn = copy_action.value.destination_vault_arn
      }
    }
  }
  tags = var.tags
}

resource "aws_backup_plan" "backup_plan_monthly" {
  name = "monthly-backup-plan"
  rule {
    rule_name         = "monthly-rule"
    target_vault_name = aws_backup_vault.vault_monthly.name
    schedule          = "cron(0 3 1 * ? *)"
    start_window      = 60
    completion_window = 120
    lifecycle {
      delete_after = 365
    }
    dynamic "copy_action" {
      for_each = local.monthly_copy_actions
      content {
        destination_vault_arn = copy_action.value.destination_vault_arn
      }
    }
  }
  tags = var.tags
}

resource "aws_backup_plan" "backup_plan_yearly" {
  name = "yearly-backup-plan"
  rule {
    rule_name         = "yearly-rule"
    target_vault_name = aws_backup_vault.vault_yearly.name
    schedule          = "cron(0 4 1 1 ? *)"
    start_window      = 60
    completion_window = 120
    lifecycle {
      delete_after = 2555
    }
    dynamic "copy_action" {
      for_each = local.yearly_copy_actions
      content {
        destination_vault_arn = copy_action.value.destination_vault_arn
      }
    }
  }
  tags = var.tags
}

# ------------------------------------------------------------------------------
# Backup Selections
# ------------------------------------------------------------------------------
locals {
  all_rds_resources    = ["arn:aws:rds:*:*:db:*"]
  selection_resources  = local.all_rds_resources
  selection_not_resources = var.excluded_rds_arns
}

resource "aws_backup_selection" "backup_selection_daily" {
  count        = var.create_daily_backup_plan ? 1 : 0
  name         = "daily-backup-selection"
  plan_id      = aws_backup_plan.backup_plan_daily[0].id
  iam_role_arn = aws_iam_role.aws_backup_service_role.arn
  resources    = local.selection_resources
  not_resources = local.selection_not_resources
}

resource "aws_backup_selection" "backup_selection_weekly" {
  name         = "weekly-backup-selection"
  plan_id      = aws_backup_plan.backup_plan_weekly.id
  iam_role_arn = aws_iam_role.aws_backup_service_role.arn
  resources    = local.selection_resources
  not_resources = local.selection_not_resources
}

resource "aws_backup_selection" "backup_selection_monthly" {
  name         = "monthly-backup-selection"
  plan_id      = aws_backup_plan.backup_plan_monthly.id
  iam_role_arn = aws_iam_role.aws_backup_service_role.arn
  resources    = local.selection_resources
  not_resources = local.selection_not_resources
}

resource "aws_backup_selection" "backup_selection_yearly" {
  name         = "yearly-backup-selection"
  plan_id      = aws_backup_plan.backup_plan_yearly.id
  iam_role_arn = aws_iam_role.aws_backup_service_role.arn
  resources    = local.selection_resources
  not_resources = local.selection_not_resources
}

# Required providers configuration
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Provider configuration
provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Password policy variables
# ------------------------------------------------------------------------------
variable "allow_users_to_change_password" {
  description = "Allow users to change their own password"
  type        = bool
  default     = true
}

variable "hard_expiry" {
  description = "Whether users are prevented from setting a new password after their password has expired"
  type        = bool
  default     = false
}

variable "max_password_age" {
  description = "Number of days that an user password is valid"
  type        = number
  default     = 90
}

variable "minimum_password_length" {
  description = "Minimum length of the password"
  type        = number
  default     = 14
}

variable "password_reuse_prevention" {
  description = "Number of previous passwords that users are prevented from reusing"
  type        = number
  default     = 24
}

variable "require_lowercase_characters" {
  description = "Require at least one lowercase character in the password"
  type        = bool
  default     = true
}

variable "require_uppercase_characters" {
  description = "Require at least one uppercase character in the password"
  type        = bool
  default     = true
}

variable "require_numbers" {
  description = "Require at least one number in the password"
  type        = bool
  default     = true
}

variable "require_symbols" {
  description = "Require at least one symbol in the password"
  type        = bool
  default     = true
}

# ------------------------------------------------------------------------------
# Account password policy
# ------------------------------------------------------------------------------
resource "aws_iam_account_password_policy" "this" {
  allow_users_to_change_password = var.allow_users_to_change_password
  hard_expiry                    = var.hard_expiry
  max_password_age               = var.max_password_age
  minimum_password_length        = var.minimum_password_length
  password_reuse_prevention      = var.password_reuse_prevention
  require_lowercase_characters   = var.require_lowercase_characters
  require_uppercase_characters   = var.require_uppercase_characters
  require_numbers                = var.require_numbers
  require_symbols                = var.require_symbols
}

# ------------------------------------------------------------------------------
# IAM Groups
# ------------------------------------------------------------------------------
resource "aws_iam_group" "administrators" {
  name = "administrators"
}

resource "aws_iam_group" "developpers" {
  name = "developpers"
}

resource "aws_iam_group" "prod_users" {
  name = "prod_users"
}

# ------------------------------------------------------------------------------
# IAM Policies
# ------------------------------------------------------------------------------
resource "aws_iam_policy" "administrators_policy" {
  name        = "administrators_policy"
  description = "Broad access policy for administrators group with security tag exclusion and specific allowed actions"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowBroadAccessExceptSensitiveServicesAndHighSecurityTags"
        Effect   = "Allow"
        NotAction = [
          "iam:*",
          "organizations:*",
          "account:*"
        ]
        Resource = "*"
        Condition = {
          StringNotEquals = {
            "aws:ResourceTag/security" = "high"
          }
        }
      },
      {
        Sid      = "AllowSpecificActionsForServiceLinkedRolesAndOrganizationInfo"
        Effect   = "Allow"
        Action   = [
          "iam:CreateServiceLinkedRole",
          "iam:DeleteServiceLinkedRole",
          "iam:ListRoles",
          "organizations:DescribeOrganization",
          "account:ListRegions"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "developpers_policy" {
  name        = "developpers_policy"
  description = "Allow full EC2 and RDS access on resources with env=dev tag"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowEC2AndRDSOnDevEnv"
        Effect   = "Allow"
        Action   = [
          "ec2:*",
          "rds:*"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:ResourceTag/env" = "dev"
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "prod_users_policy" {
  name        = "prod_users_policy"
  description = "Allow full EC2 and RDS access on resources with env tag equal to preprod or prod"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowEC2AndRDSOnPreprodAndProd"
        Effect   = "Allow"
        Action   = [
          "ec2:*",
          "rds:*"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:ResourceTag/env" = ["preprod", "prod"]
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Attach Policies to Groups
# ------------------------------------------------------------------------------
resource "aws_iam_group_policy_attachment" "administrators" {
  group      = aws_iam_group.administrators.name
  policy_arn = aws_iam_policy.administrators_policy.arn
}

resource "aws_iam_group_policy_attachment" "developpers" {
  group      = aws_iam_group.developpers.name
  policy_arn = aws_iam_policy.developpers_policy.arn
}

resource "aws_iam_group_policy_attachment" "prod_users" {
  group      = aws_iam_group.prod_users.name
  policy_arn = aws_iam_policy.prod_users_policy.arn
}

# Terraform configuration
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix for resource names"
  type        = string
  default     = "tfm-aws"
}

variable "instance_tenancy" {
  description = "Instance tenancy for the VPC"
  type        = string
  default     = "default"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnets" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.2.0/24", "10.0.3.0/24"]
}

variable "public_inbound_acl_rules" {
  description = "Inbound network ACL rules for private subnets"
  type = list(object({
    rule_number = number
    protocol    = string
    from_port   = number
    to_port     = number
    cidr_block  = string
  }))
  default = [
    {
      rule_number = 100
      protocol    = "tcp"
      from_port   = 1024
      to_port     = 65535
      cidr_block  = "0.0.0.0/0"
    }
  ]
}

variable "public_outbound_acl_rules" {
  description = "Outbound network ACL rules for private subnets"
  type = list(object({
    rule_number = number
    protocol    = string
    from_port   = number
    to_port     = number
    cidr_block  = string
  }))
  default = [
    {
      rule_number = 100
      protocol    = "tcp"
      from_port   = 443
      to_port     = 443
      cidr_block  = "0.0.0.0/0"
    }
  ]
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true
  instance_tenancy     = var.instance_tenancy

  tags = {
    Name = "${var.name_prefix}-vpc"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnets[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.name_prefix}-private-${count.index + 1}"
  }
}

# Private route tables
resource "aws_route_table" "private" {
  count = 2

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.name_prefix}-private-rt-${count.index + 1}"
  }
}

# Private subnet route table associations
resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# S3 VPC Gateway Endpoint
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id
}

# Shared network ACL for private subnets
resource "aws_network_acl" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.name_prefix}-private-nacl"
  }
}

# Inbound network ACL rules
resource "aws_network_acl_rule" "private_inbound" {
  count = length(var.public_inbound_acl_rules)

  network_acl_id = aws_network_acl.private.id
  rule_number    = var.public_inbound_acl_rules[count.index].rule_number
  protocol       = var.public_inbound_acl_rules[count.index].protocol
  rule_action    = "allow"
  egress         = false
  cidr_block     = var.public_inbound_acl_rules[count.index].cidr_block
  from_port      = var.public_inbound_acl_rules[count.index].from_port
  to_port        = var.public_inbound_acl_rules[count.index].to_port
}

# Outbound network ACL rules
resource "aws_network_acl_rule" "private_outbound" {
  count = length(var.public_outbound_acl_rules)

  network_acl_id = aws_network_acl.private.id
  rule_number    = var.public_outbound_acl_rules[count.index].rule_number
  protocol       = var.public_outbound_acl_rules[count.index].protocol
  rule_action    = "allow"
  egress         = true
  cidr_block     = var.public_outbound_acl_rules[count.index].cidr_block
  from_port      = var.public_outbound_acl_rules[count.index].from_port
  to_port        = var.public_outbound_acl_rules[count.index].to_port
}

# Network ACL associations for private subnets
resource "aws_network_acl_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  network_acl_id = aws_network_acl.private.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# Cloud Posse null-label module for consistent naming and tagging
module "this" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace  = var.namespace
  stage      = var.stage
  name       = var.name
  attributes = var.attributes
  tags       = var.tags
}

# Core VPC
resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr_block
  instance_tenancy                 = var.instance_tenancy
  enable_dns_hostnames             = var.enable_dns_hostnames
  enable_dns_support               = var.enable_dns_support
  assign_generated_ipv6_cidr_block = var.assign_generated_ipv6_cidr_block

  ipv4_ipam_pool_id   = var.ipv4_ipam_pool_id
  ipv6_ipam_pool_id   = var.ipv6_ipam_pool_id
  ipv6_netmask_length = var.ipv6_netmask_length

  tags = module.this.tags
}

# Default Security Group adoption (strip all rules if enabled)
resource "aws_default_security_group" "main" {
  count = var.default_security_group_deny_all ? 1 : 0

  vpc_id = aws_vpc.main.id

  dynamic "ingress" {
    for_each = []
    content {}
  }

  dynamic "egress" {
    for_each = []
    content {}
  }

  tags = module.this.tags
}

# Default Route Table adoption (optional)
resource "aws_default_route_table" "main" {
  count = var.default_route_table_adopt ? 1 : 0

  default_route_table_id = aws_vpc.main.default_route_table_id

  tags = module.this.tags
}

# Default Network ACL adoption (optional, deny all)
resource "aws_default_network_acl" "main" {
  count = var.default_network_acl_adopt ? 1 : 0

  default_network_acl_id = aws_vpc.main.default_network_acl_id

  dynamic "ingress" {
    for_each = []
    content {}
  }

  dynamic "egress" {
    for_each = []
    content {}
  }

  tags = module.this.tags
}

# Additional IPv4 CIDR associations
resource "aws_vpc_ipv4_cidr_block_association" "additional" {
  for_each = var.additional_ipv4_cidr_blocks

  vpc_id = aws_vpc.main.id

  cidr_block          = try(each.value.cidr_block, null)
  ipv4_ipam_pool_id   = try(each.value.ipv4_ipam_pool_id, null)
  ipv4_netmask_length = try(each.value.ipv4_netmask_length, null)

  timeouts {
    create = try(each.value.create_timeout, null)
    delete = try(each.value.delete_timeout, null)
  }
}

# Additional IPv6 CIDR associations
resource "aws_vpc_ipv6_cidr_block_association" "additional" {
  for_each = var.additional_ipv6_cidr_blocks

  vpc_id = aws_vpc.main.id

  ipv6_ipam_pool_id   = try(each.value.ipv6_ipam_pool_id, null)
  ipv6_netmask_length = try(each.value.ipv6_netmask_length, null)

  timeouts {
    create = try(each.value.create_timeout, null)
    delete = try(each.value.delete_timeout, null)
  }
}

# Internet Gateway (conditionally)
resource "aws_internet_gateway" "main" {
  count = var.internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = module.this.tags
}

# IPv6 Egress-only Internet Gateway (conditionally)
resource "aws_egress_only_internet_gateway" "main" {
  count = var.ipv6_egress_only_internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = module.this.tags
}

# Outputs
output "vpc_id" {
  value = aws_vpc.main.id
}

output "vpc_arn" {
  value = aws_vpc.main.arn
}

output "vpc_cidr_block" {
  value = aws_vpc.main.cidr_block
}

output "vpc_ipv6_cidr_block" {
  value = aws_vpc.main.ipv6_cidr_block
}

output "default_security_group_id" {
  value = try(aws_default_security_group.main[0].id, null)
}

output "default_route_table_id" {
  value = try(aws_default_route_table.main[0].id, null)
}

output "default_network_acl_id" {
  value = try(aws_default_network_acl.main[0].id, null)
}

output "internet_gateway_id" {
  value = try(aws_internet_gateway.main[0].id, null)
}

output "egress_only_internet_gateway_id" {
  value = try(aws_egress_only_internet_gateway.main[0].id, null)
}

# Variables
variable "namespace" {
  description = "Namespace (e.g. `eg` or `cp`)"
  type        = string
  default     = "default"
}

variable "stage" {
  description = "Stage (e.g. `prod`, `dev`, `staging`)"
  type        = string
  default     = "dev"
}

variable "name" {
  description = "Application name"
  type        = string
  default     = "vpc"
}

variable "attributes" {
  description = "Additional attributes for naming"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags"
  type        = map(string)
  default     = {}
}

variable "vpc_cidr_block" {
  description = "Primary IPv4 CIDR block for the VPC"
  type        = string
  default     = "11.0.0.0/16"
}

variable "instance_tenancy" {
  description = "Tenancy of instances launched in the VPC"
  type        = string
  default     = "default"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "assign_generated_ipv6_cidr_block" {
  description = "Assign an autogenerated IPv6 CIDR block to the VPC"
  type        = bool
  default     = true
}

variable "ipv4_ipam_pool_id" {
  description = "IPv4 IPAM pool ID for VPC CIDR allocation (overrides cidr_block if set)"
  type        = string
  default     = null
}

variable "ipv6_ipam_pool_id" {
  description = "IPv6 IPAM pool ID for VPC CIDR allocation"
  type        = string
  default     = null
}

variable "ipv6_netmask_length" {
  description = "Netmask length for IPv6 CIDR when using IPAM pool"
  type        = number
  default     = null
}

variable "internet_gateway_enabled" {
  description = "Create an Internet Gateway"
  type        = bool
  default     = true
}

variable "ipv6_egress_only_internet_gateway_enabled" {
  description = "Create an IPv6 Egress-only Internet Gateway"
  type        = bool
  default     = false
}

variable "default_security_group_deny_all" {
  description = "Adopt default security group and deny all ingress/egress"
  type        = bool
  default     = false
}

variable "default_route_table_adopt" {
  description = "Adopt the default route table"
  type        = bool
  default     = false
}

variable "default_network_acl_adopt" {
  description = "Adopt the default network ACL and deny all traffic"
  type        = bool
  default     = false
}

variable "additional_ipv4_cidr_blocks" {
  description = "Map of additional IPv4 CIDR associations. Keys are arbitrary, values include cidr_block, ipv4_ipam_pool_id, ipv4_netmask_length, create_timeout, delete_timeout"
  type = map(object({
    cidr_block          = optional(string)
    ipv4_ipam_pool_id   = optional(string)
    ipv4_netmask_length = optional(number)
    create_timeout      = optional(string)
    delete_timeout      = optional(string)
  }))
  default = {}
}

variable "additional_ipv6_cidr_blocks" {
  description = "Map of additional IPv6 CIDR associations. Keys are arbitrary, values include ipv6_ipam_pool_id, ipv6_netmask_length, create_timeout, delete_timeout"
  type = map(object({
    ipv6_ipam_pool_id   = optional(string)
    ipv6_netmask_length = optional(number)
    create_timeout      = optional(string)
    delete_timeout      = optional(string)
  }))
  default = {}
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "username" {
  description = "IAM user name"
  type        = string
  default     = "my_vpn_infra_user"
}

variable "group_name" {
  description = "IAM group name"
  type        = string
  default     = "my-vpn-infra-group"
}

variable "membership_name" {
  description = "IAM group membership name"
  type        = string
  default     = "my-vpn-infra-manager-group"
}

variable "project_tag" {
  description = "Value for ProjectTag tag"
  type        = string
  default     = "my-vpn-tag"
}

variable "policy_path" {
  description = "Path for IAM policies"
  type        = string
  default     = "/my_vpn_infra/"
}

resource "aws_iam_user" "this" {
  name          = var.username
  force_destroy = true

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group" "this" {
  name = var.group_name
}

resource "aws_iam_group_membership" "this" {
  name  = var.membership_name
  users = [aws_iam_user.this.name]
  group = aws_iam_group.this.name
}

resource "aws_iam_access_key" "this" {
  user   = aws_iam_user.this.name
  status = "Active"
}

resource "aws_iam_policy" "basic" {
  name        = "${var.project_tag}-basic-policy"
  path        = var.policy_path
  description = "Basic IAM policy granting sts:GetCallerIdentity"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sts:GetCallerIdentity"
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_policy" "create" {
  name        = "${var.project_tag}-create-policy"
  path        = var.policy_path
  description = "Policy granting EC2 resource creation actions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateKeyPair",
          "ec2:CreateVpc",
          "ec2:CreateSubnet",
          "ec2:CreateInternetGateway",
          "ec2:CreateRoute",
          "ec2:CreateRouteTable",
          "ec2:CreateLocalGatewayRouteTableVpcAssociation",
          "ec2:CreateSecurityGroup",
          "ec2:AuthorizeSecurityGroupEgress",
          "ec2:AuthorizeSecurityGroupIngress",
          "ec2:CreateReplaceRootVolumeTask",
          "ec2:CreateTags",
          "ec2:AllocateAddress"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_policy" "read" {
  name        = "${var.project_tag}-read-policy"
  path        = var.policy_path
  description = "Policy granting comprehensive EC2 read actions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:Describe*",
          "ec2:Get*",
          "ec2:List*",
          "ec2:Search*"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_policy" "update" {
  name        = "${var.project_tag}-update-policy"
  path        = var.policy_path
  description = "Policy granting EC2 modification and association actions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:Modify*",
          "ec2:Associate*",
          "ec2:Replace*",
          "ec2:Update*"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_policy" "delete" {
  name        = "${var.project_tag}-delete-policy"
  path        = var.policy_path
  description = "Policy granting EC2 deletion and detachment actions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:Delete*",
          "ec2:Detach*",
          "ec2:Disassociate*"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_policy" "instance" {
  name        = "${var.project_tag}-instance-policy"
  path        = var.policy_path
  description = "Policy granting EC2 instance lifecycle actions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:RunInstances",
          "ec2:StartInstances",
          "ec2:ResetInstanceAttribute",
          "ec2:ModifyInstanceAttribute",
          "ec2:StopInstances",
          "ec2:TerminateInstances",
          "ec2:RebootInstances"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_policy" "terraform_backend" {
  name        = "${var.project_tag}-terraform-backend-access"
  path        = var.policy_path
  description = "Policy granting DynamoDB state lock and S3 backend access"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:DescribeTable",
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "basic" {
  group      = aws_iam_group.this.name
  policy_arn = aws_iam_policy.basic.arn
}

resource "aws_iam_group_policy_attachment" "create" {
  group      = aws_iam_group.this.name
  policy_arn = aws_iam_policy.create.arn
}

resource "aws_iam_group_policy_attachment" "read" {
  group      = aws_iam_group.this.name
  policy_arn = aws_iam_policy.read.arn
}

resource "aws_iam_group_policy_attachment" "update" {
  group      = aws_iam_group.this.name
  policy_arn = aws_iam_policy.update.arn
}

resource "aws_iam_group_policy_attachment" "delete" {
  group      = aws_iam_group.this.name
  policy_arn = aws_iam_policy.delete.arn
}

resource "aws_iam_group_policy_attachment" "instance" {
  group      = aws_iam_group.this.name
  policy_arn = aws_iam_policy.instance.arn
}

resource "aws_iam_group_policy_attachment" "terraform_backend" {
  group      = aws_iam_group.this.name
  policy_arn = aws_iam_policy.terraform_backend.arn
}

# Terraform and Provider Configuration
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0, < 6.0"
    }
  }
}

# Variables
variable "existing_vpc_id" {
  description = "ID of an existing VPC. If empty, a new VPC will be created."
  type        = string
  default     = ""
}

variable "environment_prefix" {
  description = "Prefix used for naming and tagging resources."
  type        = string
  default     = "DEV"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the new VPC. Only used when existing_vpc_id is empty."
  type        = string
  default     = "10.0.0.0/16"
}

variable "create_private_subnet" {
  description = "Flag to create private subnets, NAT gateway, and private route table."
  type        = bool
  default     = false
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# VPC (only when existing_vpc_id is empty)
resource "aws_vpc" "main" {
  count = var.existing_vpc_id == "" ? 1 : 0

  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "${var.environment_prefix}-vpc"
    Environment = var.environment_prefix
  }
}

# Internet Gateway (only when existing_vpc_id is empty)
resource "aws_internet_gateway" "main" {
  count = var.existing_vpc_id == "" ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = {
    Name        = "${var.environment_prefix}-igw"
    Environment = var.environment_prefix
  }
}

# Public Subnets (only when existing_vpc_id is empty)
resource "aws_subnet" "public" {
  count = var.existing_vpc_id == "" ? 2 : 0

  vpc_id            = aws_vpc.main[0].id
  cidr_block        = ["10.0.1.0/24", "10.0.2.0/24"][count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name        = "${var.environment_prefix}-public-subnet-${count.index + 1}"
    Environment = var.environment_prefix
  }
}

# Public Route Table (only when existing_vpc_id is empty)
resource "aws_route_table" "public" {
  count = var.existing_vpc_id == "" ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = {
    Name        = "${var.environment_prefix}-public-rt"
    Environment = var.environment_prefix
  }
}

# Public Route Table Associations (only when existing_vpc_id is empty)
resource "aws_route_table_association" "public" {
  count = var.existing_vpc_id == "" ? 2 : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# Private Subnets (only when create_private_subnet is true and existing_vpc_id is empty)
resource "aws_subnet" "private" {
  count = var.create_private_subnet && var.existing_vpc_id == "" ? 2 : 0

  vpc_id            = aws_vpc.main[0].id
  cidr_block        = ["10.0.10.0/24", "10.0.11.0/24"][count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name        = "${var.environment_prefix}-private-subnet-${count.index + 1}"
    Environment = var.environment_prefix
  }
}

# Elastic IP for NAT Gateway (only when create_private_subnet is true and existing_vpc_id is empty)
resource "aws_eip" "nat" {
  count = var.create_private_subnet && var.existing_vpc_id == "" ? 1 : 0

  domain = "vpc"

  tags = {
    Name        = "${var.environment_prefix}-nat-eip"
    Environment = var.environment_prefix
  }
}

# NAT Gateway (only when create_private_subnet is true and existing_vpc_id is empty)
resource "aws_nat_gateway" "main" {
  count = var.create_private_subnet && var.existing_vpc_id == "" ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name        = "${var.environment_prefix}-nat-gateway"
    Environment = var.environment_prefix
  }

  depends_on = [aws_internet_gateway.main]
}

# Private Route Table (only when create_private_subnet is true and existing_vpc_id is empty)
resource "aws_route_table" "private" {
  count = var.create_private_subnet && var.existing_vpc_id == "" ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[0].id
  }

  tags = {
    Name        = "${var.environment_prefix}-private-rt"
    Environment = var.environment_prefix
  }
}

# Private Route Table Associations (only when create_private_subnet is true and existing_vpc_id is empty)
resource "aws_route_table_association" "private" {
  count = var.create_private_subnet && var.existing_vpc_id == "" ? 2 : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "create" {
  description = "Whether to create the primary SQS queue"
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the SQS queue. Conflicts with name_prefix."
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "Prefix for the SQS queue name. Conflicts with name."
  type        = string
  default     = "sqs-queue-"
}

variable "fifo_queue" {
  description = "Whether the queue is FIFO"
  type        = bool
  default     = false
}

variable "sqs_managed_sse_enabled" {
  description = "Enable SQS managed SSE"
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "KMS master key ID for SSE"
  type        = string
  default     = null
}

variable "create_queue_policy" {
  description = "Whether to create a queue policy"
  type        = bool
  default     = false
}

variable "source_policy_documents" {
  description = "List of IAM policy documents to merge as source"
  type        = list(string)
  default     = []
}

variable "override_policy_documents" {
  description = "List of IAM policy documents to override"
  type        = list(string)
  default     = []
}

variable "queue_policy_actions" {
  description = "Actions for the default queue policy statement"
  type        = list(string)
  default     = ["sqs:*"]
}

variable "queue_policy_principals" {
  description = "Principals for the default queue policy statement"
  type        = list(string)
  default     = ["*"]
}

variable "create_dlq" {
  description = "Whether to create a dead-letter queue"
  type        = bool
  default     = false
}

variable "max_receive_count" {
  description = "Maximum receive count for redrive policy"
  type        = number
  default     = 5
}

variable "create_dlq_redrive_allow_policy" {
  description = "Whether to create redrive allow policy on DLQ"
  type        = bool
  default     = true
}

locals {
  is_fifo = var.fifo_queue
  suffix  = local.is_fifo ? ".fifo" : ""

  # Primary queue name/prefix – guarded against null name_prefix
  primary_name        = var.name != null ? "${var.name}${local.suffix}" : null
  primary_name_prefix = var.name == null && var.name_prefix != null ? "${var.name_prefix}${local.suffix}" : null

  # DLQ name/prefix – guarded against null name_prefix
  dlq_name        = var.name != null ? "${var.name}-dlq${local.suffix}" : null
  dlq_name_prefix = var.name == null && var.name_prefix != null ? "${var.name_prefix}dlq${local.suffix}" : null

  # Encryption settings
  use_custom_kms = var.kms_master_key_id != null

  main_sqs_managed_sse_enabled = local.use_custom_kms ? null : var.sqs_managed_sse_enabled
  main_kms_master_key_id       = var.kms_master_key_id

  dlq_sqs_managed_sse_enabled = local.use_custom_kms ? null : var.sqs_managed_sse_enabled
  dlq_kms_master_key_id       = var.kms_master_key_id

  use_custom_statement = length(var.source_policy_documents) == 0 && length(var.override_policy_documents) == 0
}

resource "aws_sqs_queue" "primary" {
  count = var.create ? 1 : 0

  name       = local.primary_name
  name_prefix = local.primary_name_prefix
  fifo_queue = local.is_fifo

  sqs_managed_sse_enabled = local.main_sqs_managed_sse_enabled
  kms_master_key_id       = local.main_kms_master_key_id

  redrive_policy = var.create_dlq ? jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = var.max_receive_count
  }) : null

  lifecycle {
    precondition {
      condition     = var.name != null || var.name_prefix != null
      error_message = "Either 'name' or 'name_prefix' must be set."
    }
    prevent_destroy = true
  }
}

resource "aws_sqs_queue" "dlq" {
  count = var.create_dlq ? 1 : 0

  name       = local.dlq_name
  name_prefix = local.dlq_name_prefix
  fifo_queue = local.is_fifo

  sqs_managed_sse_enabled = local.dlq_sqs_managed_sse_enabled
  kms_master_key_id       = local.dlq_kms_master_key_id

  lifecycle {
    precondition {
      condition     = var.name != null || var.name_prefix != null
      error_message = "Either 'name' or 'name_prefix' must be set."
    }
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "queue_policy" {
  count = var.create && var.create_queue_policy ? 1 : 0

  source_policy_documents   = var.source_policy_documents
  override_policy_documents = var.override_policy_documents

  dynamic "statement" {
    for_each = local.use_custom_statement ? [1] : []
    content {
      effect    = "Allow"
      actions   = var.queue_policy_actions
      principals {
        type        = "*"
        identifiers = var.queue_policy_principals
      }
      resources = [aws_sqs_queue.primary[0].arn]
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.primary[0].id
  policy    = data.aws_iam_policy_document.queue_policy[0].json
}

resource "aws_sqs_queue_redrive_allow_policy" "this" {
  count = var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].id

  redrive_allow_policy = jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [aws_sqs_queue.primary[0].arn]
  })

  depends_on = [
    aws_sqs_queue.primary,
    aws_sqs_queue.dlq
  ]
}

