  user   = aws_iam_user.loadbalancer3.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = "ec2:Describe*"
      Resource = "*"
    }]
  })
}

resource "aws_iam_user_policy" "loadbalancer3_test34" {
  name   = "test34"
  user   = aws_iam_user.loadbalancer3.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = "ec2:Describe*"
      Resource = "*"
    }]
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Variables
variable "backup_name" {
  description = "Name for the backup vault and related resources"
  type        = string
  default     = "example-backup"
}

variable "account_type" {
  description = "Account type: 'workload' or 'backup'"
  type        = string
  default     = "workload"

  validation {
    condition     = contains(["workload", "backup"], var.account_type)
    error_message = "account_type must be either 'workload' or 'backup'."
  }
}

variable "kms_key_arn" {
  description = "Optional KMS key ARN for vault encryption"
  type        = string
  default     = ""
}

variable "vault_policy" {
  description = "Optional JSON policy for the backup vault"
  type        = string
  default     = ""
}

variable "min_retention_days" {
  description = "Minimum retention days for vault lock (0 means not set)"
  type        = number
  default     = 0
}

variable "max_retention_days" {
  description = "Maximum retention days for vault lock (0 means not set)"
  type        = number
  default     = 0
}

variable "changeable_for_days" {
  description = "Number of days the lock configuration is changeable (0 means not set)"
  type        = number
  default     = 0
}

variable "enable_aws_backup_vault_notifications" {
  description = "Enable SNS notifications for backup vault events"
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "ARN of SNS topic for backup vault notifications"
  type        = string
  default     = ""
}

variable "backup_schedule" {
  description = "Cron schedule for backup rule"
  type        = string
  default     = "cron(0 5 * * ? *)"
}

variable "copy_actions" {
  description = "List of cross-region/cross-account copy actions"
  type = list(object({
    destination_region     = string
    destination_vault_arn  = string
    lifecycle = optional(object({
      delete_after_days             = number
      move_to_cold_storage_after_days = number
    }))
  }))
  default = []
}

variable "selection_resources" {
  description = "List of resource ARNs for resource-based backup selection"
  type        = list(string)
  default     = []
}

# Random suffix for unique resource names
resource "random_id" "suffix" {
  byte_length = 4
}

# Backup vault
resource "aws_backup_vault" "this" {
  name        = "${var.backup_name}-${random_id.suffix.hex}"
  kms_key_arn = var.kms_key_arn != "" ? var.kms_key_arn : null

  lifecycle {
    prevent_destroy = true
  }
}

# Vault policy (optional)
resource "aws_backup_vault_policy" "this" {
  count = var.vault_policy != "" ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  policy           = var.vault_policy
}

# Vault lock configuration (optional)
resource "aws_backup_vault_lock_configuration" "this" {
  count = var.min_retention_days > 0 ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days > 0 ? var.max_retention_days : null
  changeable_for_days = var.changeable_for_days > 0 ? var.changeable_for_days : null
}

# Vault notifications (optional)
resource "aws_backup_vault_notifications" "this" {
  count = var.enable_aws_backup_vault_notifications && var.sns_topic_arn != "" ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  sns_topic_arn     = var.sns_topic_arn
  backup_vault_events = [
    "BACKUP_JOB_FAILED",
    "COPY_JOB_FAILED",
  ]
}

# IAM role and policy for workload accounts
data "aws_iam_policy_document" "backup_assume_role" {
  count = var.account_type == "workload" ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  count = var.account_type == "workload" ? 1 : 0

  name               = "aws-backup-${var.backup_name}-${random_id.suffix.hex}"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role[0].json
}

# Inline policy for backup role – replaces the missing managed policy
resource "aws_iam_role_policy" "backup_inline" {
  count = var.account_type == "workload" ? 1 : 0

  name   = "aws-backup-inline-policy"
  role   = aws_iam_role.backup[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "backup:*",
          "tag:GetResources",
          "tag:GetTagKeys",
          "tag:GetTagValues",
          "ec2:DescribeInstances",
          "ec2:DescribeSnapshots",
          "ec2:DescribeVolumes",
          "rds:DescribeDBInstances",
          "rds:DescribeDBSnapshots",
          "dynamodb:DescribeTable",
          "dynamodb:ListTables",
          "storagegateway:Describe*",
          "storagegateway:List*",
          "ds:DescribeDirectories",
          "fsx:DescribeFileSystems",
          "fsx:DescribeBackups"
        ]
        Resource = "*"
      }
    ]
  })
}

# Backup plan (only for workload accounts)
resource "aws_backup_plan" "this" {
  count = var.account_type == "workload" ? 1 : 0

  name = "plan-${var.backup_name}-backup"

  rule {
    rule_name         = "default"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.backup_schedule
    start_window      = 60
    completion_window = 120

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    recovery_point_tags = {
      "Backup" = "true"
    }

    dynamic "copy_action" {
      for_each = var.copy_actions
      content {
        destination_vault_arn = copy_action.value.destination_vault_arn

        dynamic "lifecycle" {
          for_each = copy_action.value.lifecycle != null ? [copy_action.value.lifecycle] : []
          content {
            delete_after       = lifecycle.value.delete_after_days
            cold_storage_after = lifecycle.value.move_to_cold_storage_after_days
          }
        }
      }
    }
  }
}

# Tag-based backup selection (only for workload accounts)
resource "aws_backup_selection" "tag" {
  count = var.account_type == "workload" ? 1 : 0

  name         = "tag-${var.backup_name}"
  iam_role_arn = aws_iam_role.backup[0].arn
  plan_id      = aws_backup_plan.this[0].id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "true"
  }
}

# Resource-based backup selection (only for workload accounts and if resources are provided)
resource "aws_backup_selection" "resource" {
  count = var.account_type == "workload" && length(var.selection_resources) > 0 ? 1 : 0

  name         = "resource-${var.backup_name}"
  iam_role_arn = aws_iam_role.backup[0].arn
  plan_id      = aws_backup_plan.this[0].id
  resources    = var.selection_resources
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.75.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

variable "config_role_name" {
  type        = string
  default     = ""
  description = "Name for the IAM Config role; if empty a random pet name is used"
}

resource "random_pet" "config_role" {
  length    = 2
  separator = "-"
}

data "aws_caller_identity" "current" {}

resource "aws_s3_bucket" "config_snapshot" {
  bucket        = "aws-config-snapshot-${data.aws_caller_identity.current.account_id}"
  force_destroy = true
}

resource "aws_s3_bucket_versioning" "config_snapshot" {
  bucket = aws_s3_bucket.config_snapshot.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config_snapshot" {
  bucket = aws_s3_bucket.config_snapshot.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.config_sns.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "config_snapshot" {
  bucket                  = aws_s3_bucket.config_snapshot.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "config_snapshot" {
  bucket = aws_s3_bucket.config_snapshot.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = [
          "s3:PutObject",
          "s3:GetBucketAcl",
          "s3:GetBucketLocation",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.config_snapshot.arn,
          "${aws_s3_bucket.config_snapshot.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_kms_key" "config_sns" {
  description             = "KMS key for AWS Config SNS topic encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "kms:*"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_sns_topic" "config" {
  name              = "config-sns-topic"
  kms_master_key_id = aws_kms_key.config_sns.arn
}

resource "aws_iam_role" "config" {
  name = var.config_role_name != "" ? var.config_role_name : random_pet.config_role.id
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "config_managed" {
  role       = aws_iam_role.config.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWS_ConfigRole"
}

resource "aws_iam_role_policy" "config_sns_publish" {
  name = "config-sns-publish"
  role = aws_iam_role.config.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sns:Publish"
        Resource = aws_sns_topic.config.arn
      }
    ]
  })
}

resource "aws_config_configuration_recorder" "main" {
  name     = "default"
  role_arn = aws_iam_role.config.arn
  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

resource "aws_config_delivery_channel" "main" {
  name           = "default"
  s3_bucket_name = aws_s3_bucket.config_snapshot.bucket
  s3_key_prefix  = "awsconfig/records"
  s3_kms_key_arn = aws_kms_key.config_sns.arn
  sns_topic_arn  = aws_sns_topic.config.arn
  depends_on     = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "cloudtrail_enabled" {
  name                        = "cloudtrail-enabled"
  description                 = "Checks that AWS CloudTrail is enabled"
  maximum_execution_frequency = "TwentyFour_Hours"
  source {
    owner            = "AWS"
    source_identifier = "CLOUD_TRAIL_ENABLED"
  }
  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "iam_pw_policy" {
  name                        = "iam-pw-policy"
  description                 = "Checks the IAM password policy"
  maximum_execution_frequency = "TwentyFour_Hours"
  source {
    owner            = "AWS"
    source_identifier = "IAM_PASSWORD_POLICY"
  }
  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "ec2_vpc" {
  name        = "ec2-vpc"
  description = "Checks that EC2 instances are in a VPC"
  source {
    owner            = "AWS"
    source_identifier = "INSTANCES_IN_VPC"
  }
  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "root_mfa_enabled" {
  name                        = "root-mfa-enabled"
  description                 = "Checks that the root account has MFA enabled"
  maximum_execution_frequency = "TwentyFour_Hours"
  source {
    owner            = "AWS"
    source_identifier = "ROOT_ACCOUNT_MFA_ENABLED"
  }
  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "acm_expiration_check" {
  name                        = "acm-expiration-check"
  description                 = "Checks ACM certificates for expiration"
  maximum_execution_frequency = "TwentyFour_Hours"
  source {
    owner            = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }
  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "ebs_inuse_check" {
  name        = "ebs-inuse-check"
  description = "Checks that EBS volumes are attached to EC2 instances"
  source {
    owner            = "AWS"
    source_identifier = "EC2_VOLUME_INUSE_CHECK"
  }
  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "ec2_imdsv2_check" {
  name        = "ec2-imdsv2-check"
  description = "Checks that EC2 instances use IMDSv2"
  source {
    owner            = "AWS"
    source_identifier = "EC2_IMDSV2_CHECK"
  }
  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "rds_encrypted" {
  name        = "rds-encrypted"
  description = "Checks that RDS instances have storage encryption enabled"
  source {
    owner            = "AWS"
    source_identifier = "RDS_STORAGE_ENCRYPTED"
  }
  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "rds_private" {
  name        = "rds-private"
  description = "Checks that RDS instances are not publicly accessible"
  source {
    owner            = "AWS"
    source_identifier = "RDS_INSTANCE_PUBLIC_ACCESS_CHECK"
  }
  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "rds_private_snapshots" {
  name        = "rds-private-snapshots"
  description = "Checks that RDS snapshots are not public"
  source {
    owner            = "AWS"
    source_identifier = "RDS_SNAPSHOTS_PUBLIC_PROHIBITED"
  }
  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "required_tags" {
  name        = "required-tags"
  description = "Checks that required tags are present on S3 buckets"
  scope {
    compliance_resource_types = ["AWS::S3::Bucket"]
  }
  source {
    owner            = "AWS"
    source_identifier = "REQUIRED_TAGS"
  }
  input_parameters = jsonencode({
    tag1Key = "terraform.io"
    tag2Key = "environment"
  })
  depends_on = [aws_config_configuration_recorder.main]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

locals {
  common_tags = {
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
  public_subnet_cidrs  = ["10.0.4.0/24", "10.0.6.0/24", "10.0.8.0/24"]
  private_subnet_cidrs = ["10.0.10.0/24", "10.0.12.0/24", "10.0.14.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "bjit-vpc"
  })
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "bjit-public-subnet-${count.index + 1}"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "bjit-private-subnet-${count.index + 1}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "bjit-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "bjit-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "bjit-private-rt-${count.index + 1}"
  })
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.us-east-1.s3"
  route_table_ids = [
    aws_route_table.private[0].id,
    aws_route_table.private[1].id,
    aws_route_table.private[2].id,
  ]

  tags = merge(local.common_tags, {
    Name = "bjit-s3-gateway-endpoint"
  })
}

resource "aws_security_group" "alb" {
  name        = "bjit-api-server-ALB-SG"
  description = "Security group for API server ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-api-server-ALB-SG"
  })
}

