terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100"
    }
  }
}

variable "create" {
  description = "Whether to create SQS queue resources"
  type        = bool
  default     = true
}

variable "queue_name" {
  description = "Human-readable queue name (do not include .fifo suffix)"
  type        = string
  default     = "my-queue"
}

variable "use_name_prefix" {
  description = "If true, use the queue name as a name prefix (allows multiple versions)"
  type        = bool
  default     = false
}

variable "fifo_queue" {
  description = "If true, create a FIFO queue"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO queues"
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  description = "Specifies whether message deduplication occurs at the message group or queue level"
  type        = string
  default     = null
}

variable "fifo_throughput_limit" {
  description = "Specifies the throughput limit for FIFO queues"
  type        = string
  default     = null
}

variable "delay_seconds" {
  description = "Time in seconds that delivery of all messages is delayed"
  type        = number
  default     = 0
}

variable "max_message_size" {
  description = "Maximum message size in bytes"
  type        = number
  default     = 262144
}

variable "message_retention_seconds" {
  description = "Number of seconds SQS retains a message"
  type        = number
  default     = 345600
}

variable "receive_wait_time_seconds" {
  description = "Time for which a ReceiveMessage call will wait for a message to arrive"
  type        = number
  default     = 0
}

variable "visibility_timeout_seconds" {
  description = "Visibility timeout for the queue"
  type        = number
  default     = 30
}

variable "sqs_managed_sse_enabled" {
  description = "If true, use SQS-managed encryption keys (default)"
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "ID of a customer-managed KMS key for encryption"
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "Length of time in seconds for which SQS can reuse a data key"
  type        = number
  default     = null
}

variable "create_queue_policy" {
  description = "If true, create a separate queue policy for the main queue"
  type        = bool
  default     = false
}

variable "queue_policy" {
  description = "JSON policy document for the main queue (used when create_queue_policy is true)"
  type        = string
  default     = null
}

variable "queue_policy_statements" {
  description = "List of additional IAM policy statements for the main queue"
  type = list(object({
    sid       = optional(string)
    effect    = string
    actions   = list(string)
    resources = list(string)
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    condition = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

variable "create_dlq" {
  description = "If true, create a dead-letter queue"
  type        = bool
  default     = false
}

variable "dlq_name_suffix" {
  description = "Suffix to append to the main queue name for the DLQ"
  type        = string
  default     = "-dlq"
}

variable "dlq_kms_master_key_id" {
  description = "KMS key ID for the DLQ (overrides main queue encryption)"
  type        = string
  default     = null
}

variable "dlq_sqs_managed_sse_enabled" {
  description = "If true, use SQS-managed encryption for DLQ (overrides main queue)"
  type        = bool
  default     = true
}

variable "dlq_max_receive_count" {
  description = "Max receive count before moving to DLQ"
  type        = number
  default     = 5
}

variable "create_dlq_redrive_allow_policy" {
  description = "If true, attach a redrive allow policy to the DLQ"
  type        = bool
  default     = true
}

variable "create_dlq_queue_policy" {
  description = "If true, create a separate queue policy for the DLQ"
  type        = bool
  default     = false
}

variable "dlq_queue_policy" {
  description = "JSON policy document for the DLQ (used when create_dlq_queue_policy is true)"
  type        = string
  default     = null
}

variable "dlq_queue_policy_statements" {
  description = "List of additional IAM policy statements for the DLQ"
  type = list(object({
    sid       = optional(string)
    effect    = string
    actions   = list(string)
    resources = list(string)
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    condition = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

locals {
  base_name = replace(var.queue_name, ".fifo", "")
  # Main queue name (with FIFO suffix if applicable)
  main_queue_name = var.fifo_queue ? "${local.base_name}.fifo" : local.base_name
  # Main queue name prefix logic
  main_queue_name_prefix_or_name = var.use_name_prefix ? (
    var.fifo_queue ? "${local.base_name}.fifo" : local.base_name
  ) : null

  # DLQ naming
  dlq_base_name = "${local.base_name}${var.dlq_name_suffix}"
  dlq_queue_name = var.fifo_queue ? "${local.dlq_base_name}.fifo" : local.dlq_base_name
  dlq_queue_name_prefix = var.use_name_prefix ? (
    var.fifo_queue ? "${local.dlq_base_name}.fifo" : local.dlq_base_name
  ) : null

  # Encryption for main queue
  main_sqs_managed_sse = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : false
  main_kms_key_id = var.kms_master_key_id
  main_kms_reuse_period = var.kms_data_key_reuse_period_seconds

  # Encryption for DLQ (inherit or override)
  dlq_sqs_managed_sse = var.dlq_kms_master_key_id == null ? var.dlq_sqs_managed_sse_enabled : false
  dlq_kms_key_id = var.dlq_kms_master_key_id != null ? var.dlq_kms_master_key_id : local.main_kms_key_id
  dlq_kms_reuse_period = var.dlq_kms_master_key_id != null ? var.kms_data_key_reuse_period_seconds : local.main_kms_reuse_period
}

resource "aws_sqs_queue" "main" {
  count = var.create ? 1 : 0

  name                        = var.use_name_prefix ? null : local.main_queue_name
  name_prefix                 = var.use_name_prefix ? local.main_queue_name_prefix_or_name : null
  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null
  delay_seconds               = var.delay_seconds
  max_message_size            = var.max_message_size
  message_retention_seconds   = var.message_retention_seconds
  receive_wait_time_seconds   = var.receive_wait_time_seconds
  visibility_timeout_seconds  = var.visibility_timeout_seconds
  sqs_managed_sse_enabled     = local.main_sqs_managed_sse
  kms_master_key_id           = local.main_kms_key_id
  kms_data_key_reuse_period_seconds = local.main_kms_reuse_period

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  name                        = var.use_name_prefix ? null : local.dlq_queue_name
  name_prefix                 = var.use_name_prefix ? local.dlq_queue_name_prefix : null
  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null
  delay_seconds               = var.delay_seconds
  max_message_size            = var.max_message_size
  message_retention_seconds   = var.message_retention_seconds
  receive_wait_time_seconds   = var.receive_wait_time_seconds
  visibility_timeout_seconds  = var.visibility_timeout_seconds
  sqs_managed_sse_enabled     = local.dlq_sqs_managed_sse
  kms_master_key_id           = local.dlq_kms_key_id
  kms_data_key_reuse_period_seconds = local.dlq_kms_reuse_period

  lifecycle {
    prevent_destroy = true
  }
}

# Redrive policy on main queue pointing to DLQ
resource "aws_sqs_queue_redrive_policy" "main" {
  count = var.create && var.create_dlq ? 1 : 0

  queue_url = aws_sqs_queue.main[0].id
  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = var.dlq_max_receive_count
  })
}

# Redrive allow policy on DLQ (allow only source queue)
resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].id
  redrive_allow_policy = jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [aws_sqs_queue.main[0].arn]
  })
}

# Combined policy document for main queue
data "aws_iam_policy_document" "main_queue_policy" {
  count = var.create && var.create_queue_policy ? 1 : 0

  source_policy_documents = var.queue_policy != null ? [var.queue_policy] : []

  dynamic "statement" {
    for_each = var.queue_policy_statements
    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources
      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : []
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }
      dynamic "condition" {
        for_each = statement.value.condition != null ? statement.value.condition : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "main" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.main[0].id
  policy    = data.aws_iam_policy_document.main_queue_policy[0].json
}

# Combined policy document for DLQ
data "aws_iam_policy_document" "dlq_queue_policy" {
  count = var.create && var.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  source_policy_documents = var.dlq_queue_policy != null ? [var.dlq_queue_policy] : []

  dynamic "statement" {
    for_each = var.dlq_queue_policy_statements
    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources
      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : []
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }
      dynamic "condition" {
        for_each = statement.value.condition != null ? statement.value.condition : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].id
  policy    = data.aws_iam_policy_document.dlq_queue_policy[0].json
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.50.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
  }
}

# Top-level control variable
variable "create" {
  type    = bool
  default = true
}

# Core Lambda deployment variables
variable "function_name" {
  type = string
}

variable "alias_name" {
  type = string
}

variable "current_version" {
  type = string
}

variable "target_version" {
  type = string
}

variable "before_allow_traffic_hook_arn" {
  type    = string
  default = null
}

variable "after_allow_traffic_hook_arn" {
  type    = string
  default = null
}

# Application variables
variable "app_name" {
  type    = string
  default = ""
}

variable "create_app" {
  type    = bool
  default = false
}

variable "use_existing_app" {
  type    = bool
  default = false
}

# Deployment group variables
variable "deployment_config_name" {
  type    = string
  default = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "create_deployment_group" {
  type    = bool
  default = false
}

variable "use_existing_deployment_group" {
  type    = bool
  default = false
}

variable "deployment_group_name" {
  type    = string
  default = ""
}

variable "existing_deployment_group_name" {
  type    = string
  default = ""
}

variable "existing_service_role_arn" {
  type    = string
  default = null
}

# Alarms and triggers (optional)
variable "alarms" {
  type = list(object({
    alarm_name = string
    enabled    = optional(bool, true)
  }))
  default = []
}

variable "triggers" {
  type = list(object({
    trigger_events     = list(string)
    trigger_name       = string
    trigger_target_arn = string
  }))
  default = []
}

# IAM role variables
variable "create_codedeploy_role" {
  type    = bool
  default = true
}

variable "codedeploy_service_principals" {
  type    = list(string)
  default = ["codedeploy.amazonaws.com"]
}

variable "attach_hooks_policy" {
  type    = bool
  default = true
}

variable "attach_triggers_policy" {
  type    = bool
  default = false
}

# Deployment execution variables
variable "create_deployment" {
  type    = bool
  default = false
}

variable "aws_cli_command" {
  type    = string
  default = "aws"
}

variable "get_deployment_sleep_timer" {
  type    = number
  default = 5
}

variable "save_deploy_script" {
  type    = bool
  default = false
}

variable "run_deployment" {
  type    = bool
  default = false
}

# Locals
locals {
  create_app_resources         = var.create && var.create_app && !var.use_existing_app
  create_deployment_group_res  = var.create && var.create_deployment_group && !var.use_existing_deployment_group
  create_iam_role              = var.create && var.create_codedeploy_role
  create_deployment            = var.create && var.create_deployment
  save_script                  = local.create_deployment && var.save_deploy_script
  run_deployment               = local.create_deployment && var.run_deployment

  # AppSpec JSON content
  appspec_json = jsonencode({
    version = "0.0"
    Resources = [
      {
        myLambdaFunction = {
          Type = "AWS::Lambda::Function"
          Properties = {
            Name           = var.function_name
            Alias          = var.alias_name
            CurrentVersion = var.current_version
            TargetVersion  = var.target_version
          }
        }
      }
    ]
    Hooks = [
      for hook in [
        var.before_allow_traffic_hook_arn != null ? { BeforeAllowTraffic = var.before_allow_traffic_hook_arn } : null,
        var.after_allow_traffic_hook_arn != null ? { AfterAllowTraffic = var.after_allow_traffic_hook_arn } : null,
      ] : hook if hook != null
    ]
  })

  # Deployment script content (inline)
  deploy_script_content = <<-EOT
#!/bin/bash
set -e
APPSPEC='${local.appspec_json}'
DEPLOYMENT_ID=$(${var.aws_cli_command} deploy create-deployment \
  --application-name "${try(aws_codedeploy_app.this[0].name, var.app_name)}" \
  --deployment-group-name "${try(aws_codedeploy_deployment_group.this[0].deployment_group_name, var.deployment_group_name)}" \
  --revision '{"revisionType":"String","string": "'"${APPSPEC}"'"}' \
  --query 'deploymentId' --output text)
echo "Deployment ID: $DEPLOYMENT_ID"
STATUS="InProgress"
while [ "$STATUS" = "InProgress" ] || [ "$STATUS" = "Pending" ]; do
  sleep ${var.get_deployment_sleep_timer}
  STATUS=$(${var.aws_cli_command} deploy get-deployment --deployment-id $DEPLOYMENT_ID --query 'deploymentInfo.status' --output text)
  echo "Status: $STATUS"
done
echo "Deployment finished with status: $STATUS"
EOT
}

# Random UUID for forced re-execution of deployment
resource "random_uuid" "deploy_trigger" {
  count = local.run_deployment ? 1 : 0
}

# CodeDeploy Application
resource "aws_codedeploy_app" "this" {
  count = local.create_app_resources ? 1 : 0

  compute_platform = "Lambda"
  name             = var.app_name
}

# CodeDeploy Deployment Group
resource "aws_codedeploy_deployment_group" "this" {
  count = local.create_deployment_group_res ? 1 : 0

  app_name              = try(aws_codedeploy_app.this[0].name, var.app_name)
  deployment_group_name = var.use_existing_deployment_group ? var.existing_deployment_group_name : var.deployment_group_name
  service_role_arn      = try(aws_iam_role.codedeploy[0].arn, var.existing_service_role_arn)

  deployment_config_name = var.deployment_config_name

  deployment_style {
    deployment_option = "WITH_TRAFFIC_CONTROL"
    deployment_type   = "BLUE_GREEN"
  }

  auto_rollback_configuration {
    enabled = true
    events  = ["DEPLOYMENT_STOP_ON_ALARM"]
  }

  dynamic "alarm_configuration" {
    for_each = length(var.alarms) > 0 ? [1] : []
    content {
      alarms  = var.alarms[*].alarm_name
      enabled = true
    }
  }

  dynamic "trigger_configuration" {
    for_each = var.triggers
    content {
      trigger_events     = trigger_configuration.value.trigger_events
      trigger_name       = trigger_configuration.value.trigger_name
      trigger_target_arn = trigger_configuration.value.trigger_target_arn
    }
  }

  dynamic "lifecycle_hook" {
    for_each = var.before_allow_traffic_hook_arn != null ? [var.before_allow_traffic_hook_arn] : []
    content {
      lifecycle_event = "BeforeAllowTraffic"
      hook_arn        = lifecycle_hook.value
    }
  }

  dynamic "lifecycle_hook" {
    for_each = var.after_allow_traffic_hook_arn != null ? [var.after_allow_traffic_hook_arn] : []
    content {
      lifecycle_event = "AfterAllowTraffic"
      hook_arn        = lifecycle_hook.value
    }
  }
}

# IAM Role for CodeDeploy
resource "aws_iam_role" "codedeploy" {
  count = local.create_iam_role ? 1 : 0

  name               = "CodeDeployLambdaRole"
  assume_role_policy = data.aws_iam_policy_document.codedeploy_assume[0].json

  tags = {
    Name = "CodeDeployLambdaRole"
  }
}

data "aws_iam_policy_document" "codedeploy_assume" {
  count = local.create_iam_role ? 1 : 0

  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = var.codedeploy_service_principals
    }
  }
}

# Attach AWS managed policy for Lambda
resource "aws_iam_role_policy_attachment" "codedeploy_lambda" {
  count = local.create_iam_role ? 1 : 0

  role       = aws_iam_role.codedeploy[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRoleForLambda"
}

# Inline policy for hook invocation
resource "aws_iam_role_policy" "hooks" {
  count = local.create_iam_role && var.attach_hooks_policy ? 1 : 0

  name   = "CodeDeployHookInvocation"
  role   = aws_iam_role.codedeploy[0].name
  policy = data.aws_iam_policy_document.hooks[0].json
}

data "aws_iam_policy_document" "hooks" {
  count = local.create_iam_role && var.attach_hooks_policy ? 1 : 0

  statement {
    actions   = ["lambda:InvokeFunction"]
    resources = compact([var.before_allow_traffic_hook_arn, var.after_allow_traffic_hook_arn])
  }
}

# Inline policy for SNS publish (triggers)
resource "aws_iam_role_policy" "triggers" {
  count = local.create_iam_role && var.attach_triggers_policy ? 1 : 0

  name   = "CodeDeployTriggerSNSPublish"
  role   = aws_iam_role.codedeploy[0].name
  policy = data.aws_iam_policy_document.triggers[0].json
}

data "aws_iam_policy_document" "triggers" {
  count = local.create_iam_role && var.attach_triggers_policy ? 1 : 0

  statement {
    actions   = ["sns:Publish"]
    resources = var.triggers[*].trigger_target_arn
  }
}

# Local file for deployment script
resource "local_file" "deploy_script" {
  count = local.save_script ? 1 : 0

  content  = local.deploy_script_content
  filename = "${path.module}/deploy_lambda.sh"
}

# Null resource to run deployment
resource "null_resource" "run_deployment" {
  count = local.run_deployment ? 1 : 0

  triggers = {
    always_run = random_uuid.deploy_trigger[0].result
  }

  provisioner "local-exec" {
    command = local.deploy_script_content
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Random integer for VPC name tag suffix
resource "random_integer" "vpc_suffix" {
  min = 1
  max = 100
}

# Fetch all available AZs in the region
data "aws_availability_zones" "available" {
  state = "available"
}

# Shuffle the AZ list to randomize subnet mapping
resource "random_shuffle" "azs" {
  input        = data.aws_availability_zones.available.names
  keepers = {
    # Force re-shuffle if AZ list changes
    az_list = join(",", data.aws_availability_zones.available.names)
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.project_name_prefix}-${random_integer.vpc_suffix.result}"
  }
}

# Web subnets
resource "aws_subnet" "web" {
  count = var.web_subnet_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.web_subnet_cidrs[count.index]
  availability_zone = element(random_shuffle.azs.result, count.index % local.effective_max_subnet_count)

  tags = {
    Name = "${var.project_name_prefix}-web-${count.index + 1}"
    Tier = "web"
  }
}

# App subnets
resource "aws_subnet" "app" {
  count = var.app_subnet_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.app_subnet_cidrs[count.index]
  availability_zone = element(random_shuffle.azs.result, count.index % local.effective_max_subnet_count)

  tags = {
    Name = "${var.project_name_prefix}-app-${count.index + 1}"
    Tier = "app"
  }
}

# Database subnets
resource "aws_subnet" "database" {
  count = var.database_subnet_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.database_subnet_cidrs[count.index]
  availability_zone = element(random_shuffle.azs.result, count.index % local.effective_max_subnet_count)

  tags = {
    Name = "${var.project_name_prefix}-database-${count.index + 1}"
    Tier = "database"
  }
}

# Reserved subnets
resource "aws_subnet" "reserved" {
  count = var.reserved_subnet_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.reserved_subnet_cidrs[count.index]
  availability_zone = element(random_shuffle.azs.result, count.index % local.effective_max_subnet_count)

  tags = {
    Name = "${var.project_name_prefix}-reserved-${count.index + 1}"
    Tier = "reserved"
  }
}

# Internet Gateway (conditional)
resource "aws_internet_gateway" "main" {
  count = var.create_igw ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.project_name_prefix}-igw"
  }
}

# Public route table
resource "aws_route_table" "public" {
  count = var.create_igw ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.project_name_prefix}-public-rt"
  }
}

# Default route to IGW
resource "aws_route" "public_default" {
  count = var.create_igw ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main[0].id
}

# Public route table associations for web subnets
resource "aws_route_table_association" "web_public" {
  count = var.create_igw ? var.web_subnet_count : 0

  subnet_id      = aws_subnet.web[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# Private route table (shared by all private subnets)
resource "aws_route_table" "private" {
  count = (var.app_subnet_count + var.database_subnet_count + var.reserved_subnet_count) > 0 ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.project_name_prefix}-private-rt"
  }
}

# Private route table associations (for app, database, reserved)
locals {
  private_subnet_ids = concat(
    aws_subnet.app[*].id,
    aws_subnet.database[*].id,
    aws_subnet.reserved[*].id
  )
  effective_max_subnet_count = var.max_subnet_count != null ? var.max_subnet_count : length(data.aws_availability_zones.available.names)
}

resource "aws_route_table_association" "private" {
  count          = length(local.private_subnet_ids)
  subnet_id      = local.private_subnet_ids[count.index]
  route_table_id = aws_route_table.private[0].id
}

# Interface VPC Endpoints (optional)
resource "aws_vpc_endpoint" "interface" {
  for_each = var.vpc_endpoints

  vpc_id              = aws_vpc.main.id
  service_name        = each.value.service_name
  vpc_endpoint_type   = "Interface"
  subnet_ids          = each.value.subnet_ids != null ? each.value.subnet_ids : local.private_subnet_ids
  security_group_ids  = []  # No default SG; user can attach separately

  tags = {
    Name = "${var.project_name_prefix}-vpce-${each.key}"
  }
}

# Gateway VPC Endpoint (optional)
resource "aws_vpc_endpoint" "gateway" {
  count = var.gateway_vpc_endpoint_service != null && var.gateway_vpc_endpoint_service != "" ? 1 : 0

  vpc_id            = aws_vpc.main.id
  service_name      = var.gateway_vpc_endpoint_service
  vpc_endpoint_type = "Gateway"

  tags = {
    Name = "${var.project_name_prefix}-vpce-gateway"
  }
}

# Associate gateway endpoint with private route table
resource "aws_vpc_endpoint_route_table_association" "gateway_private" {
  count = var.gateway_vpc_endpoint_service != null && var.gateway_vpc_endpoint_service != "" && length(aws_route_table.private) > 0 ? 1 : 0

  route_table_id  = aws_route_table.private[0].id
  vpc_endpoint_id = aws_vpc_endpoint.gateway[0].id
}

# Variables
variable "project_name_prefix" {
  description = "Prefix for naming resources"
  type        = string
  default     = "tf-project"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.16.0.0/16"
}

variable "create_igw" {
  description = "Whether to create an Internet Gateway and public route table"
  type        = bool
  default     = true
}

variable "max_subnet_count" {
  description = "Maximum number of unique availability zones to use for subnet distribution"
  type        = number
  default     = null
}

variable "web_subnet_count" {
  description = "Number of web subnets"
  type        = number
  default     = 2
}

variable "app_subnet_count" {
  description = "Number of app subnets"
  type        = number
  default     = 2
}

variable "database_subnet_count" {
  description = "Number of database subnets"
  type        = number
  default     = 2
}

variable "reserved_subnet_count" {
  description = "Number of reserved subnets"
  type        = number
  default     = 2
}

variable "web_subnet_cidrs" {
  description = "List of CIDR blocks for web subnets"
  type        = list(string)
  default = [
    "10.16.1.0/24",
    "10.16.2.0/24",
    "10.16.3.0/24",
    "10.16.4.0/24",
    "10.16.5.0/24",
    "10.16.6.0/24",
  ]
}

variable "app_subnet_cidrs" {
  description = "List of CIDR blocks for app subnets"
  type        = list(string)
  default = [
    "10.16.11.0/24",
    "10.16.12.0/24",
    "10.16.13.0/24",
    "10.16.14.0/24",
    "10.16.15.0/24",
    "10.16.16.0/24",
  ]
}

variable "database_subnet_cidrs" {
  description = "List of CIDR blocks for database subnets"
  type        = list(string)
  default = [
    "10.16.21.0/24",
    "10.16.22.0/24",
    "10.16.23.0/24",
    "10.16.24.0/24",
    "10.16.25.0/24",
    "10.16.26.0/24",
  ]
}

variable "reserved_subnet_cidrs" {
  description = "List of CIDR blocks for reserved subnets"
  type        = list(string)
  default = [
    "10.16.31.0/24",
    "10.16.32.0/24",
    "10.16.33.0/24",
    "10.16.34.0/24",
    "10.16.35.0/24",
    "10.16.36.0/24",
  ]
}

variable "vpc_endpoints" {
  description = "Map of interface VPC endpoints to create. Key is the endpoint name. Each value must include 'service_name' and optionally 'subnet_ids' (defaults to all private subnets)."
  type = map(object({
    service_name = string
    subnet_ids   = optional(list(string))
  }))
  default = {}
}

variable "gateway_vpc_endpoint_service" {
  description = "Service name for a gateway VPC endpoint (e.g., 'com.amazonaws.us-east-1.s3'). If set, a gateway endpoint is created and associated with the private route table."
  type        = string
  default     = null
}

# Outputs
output "vpc_id" {
  description = "ID of the created VPC"
  value       = aws_vpc.main.id
}

output "web_subnet_ids" {
  description = "IDs of web subnets"
  value       = aws_subnet.web[*].id
}

output "app_subnet_ids" {
  description = "IDs of app subnets"
  value       = aws_subnet.app[*].id
}

output "database_subnet_ids" {
  description = "IDs of database subnets"
  value       = aws_subnet.database[*].id
}

output "reserved_subnet_ids" {
  description = "IDs of reserved subnets"
  value       = aws_subnet.reserved[*].id
}

output "private_route_table_id" {
  description = "ID of the private route table"
  value       = length(aws_route_table.private) > 0 ? aws_route_table.private[0].id : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.50.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "admin_cidrs" {
  description = "List of CIDR blocks allowed SSH access to Home SSH security group"
  type        = list(string)
  default     = ["203.0.113.0/24"]
}

variable "internal_domain" {
  description = "Internal domain name for DHCP options and private Route 53 hosted zone"
  type        = string
  default     = "internal"
}

locals {
  vpc_cidr = "10.0.0.0/16"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_internet_gateway" "ig" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "ig"
  }
}

resource "aws_vpc_dhcp_options" "main" {
  domain_name         = var.internal_domain
  domain_name_servers = ["AmazonProvidedDNS", "8.8.8.8"]

  tags = {
    Name = "main-dhcp-options"
  }
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

resource "aws_route53_zone" "internal" {
  name = var.internal_domain

  vpc {
    vpc_id = aws_vpc.main.id
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "internal-zone"
  }
}

resource "aws_subnet" "reserved" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "reserved"
  }
}

resource "aws_subnet" "sandbox" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "sandbox"
  }
}

resource "aws_subnet" "web" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

