resource "aws_security_group" "home_ssh" {
  name        = "Home SSH"
  description = "Allow SSH from admin CIDRs and self, egress to VPC CIDR only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from admin CIDRs"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.admin_cidrs
  }

  ingress {
    description = "SSH from self"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "All traffic to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "Home SSH"
  }
}

resource "aws_security_group" "packer_ssh" {
  name        = "Packer SSH"
  description = "Allow SSH from VPC CIDR and self, egress to VPC CIDR only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  ingress {
    description = "SSH from self"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "All traffic to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "Packer SSH"
  }
}

terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0"
    }
  }
}

variable "env" {
  description = "Environment name for prefixing resource Name tags"
  type        = string
  default     = ""
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = var.env != "" ? "${var.env}-" : ""
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${local.name_prefix}vpc"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}igw"
  }
}

# Elastic IPs for NAT Gateways
resource "aws_eip" "nat" {
  count = 3

  tags = {
    Name = "${local.name_prefix}nat-eip-${count.index + 1}"
  }
}

# Public Subnets
resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"][count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}public-${count.index + 1}"
  }
}

# NAT Gateways
resource "aws_nat_gateway" "nat" {
  count = 3

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${local.name_prefix}nat-gw-${count.index + 1}"
  }
}

# Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}public-rt"
  }
}

# Public Route to Internet Gateway
resource "aws_route" "public" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

# Public Route Table Associations
resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private Application Subnets
resource "aws_subnet" "private_app" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24"][count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.name_prefix}private-app-${count.index + 1}"
  }
}

# Private Application Route Tables (one per AZ)
resource "aws_route_table" "private_app" {
  count = 3

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}private-app-rt-${count.index + 1}"
  }
}

# Private Application Routes to respective NAT Gateways
resource "aws_route" "private_app" {
  count = 3

  route_table_id         = aws_route_table.private_app[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.nat[count.index].id
}

# Private Application Route Table Associations
resource "aws_route_table_association" "private_app" {
  count = 3

  subnet_id      = aws_subnet.private_app[count.index].id
  route_table_id = aws_route_table.private_app[count.index].id
}

# Database Subnets
resource "aws_subnet" "database" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = ["10.0.100.0/24", "10.0.110.0/24", "10.0.120.0/24"][count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.name_prefix}database-${count.index + 1}"
  }
}

# Database Route Table (shared)
resource "aws_route_table" "database" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}database-rt"
  }
}

# Database Route Table Associations
resource "aws_route_table_association" "database" {
  count = 3

  subnet_id      = aws_subnet.database[count.index].id
  route_table_id = aws_route_table.database.id
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Variables
variable "bucket_name" {
  description = "Base name for the S3 bucket"
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "use_account_alias_prefix" {
  description = "Whether to prefix the bucket name with the AWS IAM account alias"
  type        = bool
  default     = false
}

variable "use_random_suffix" {
  description = "Whether to append a random suffix to the bucket name"
  type        = bool
  default     = false
}

variable "enable_s3_public_access_block" {
  description = "Enable S3 public access block settings"
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "KMS master key ID for SSE-KMS encryption. If null, AES256 is used."
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Enable S3 bucket key for SSE-KMS"
  type        = bool
  default     = false
}

variable "versioning_status" {
  description = "S3 bucket versioning status"
  type        = string
  default     = "Enabled"
}

variable "force_destroy" {
  description = "Force destroy the bucket even if it contains objects"
  type        = bool
  default     = false
}

variable "enable_analytics" {
  description = "Enable S3 storage class analytics"
  type        = bool
  default     = true
}

variable "enable_bucket_inventory" {
  description = "Enable S3 bucket inventory"
  type        = bool
  default     = false
}

variable "logging_bucket" {
  description = "Target bucket for S3 access logging. If null, logging is disabled."
  type        = string
  default     = null
}

variable "transfer_acceleration" {
  description = "Enable transfer acceleration. If null, acceleration is disabled."
  type        = string
  default     = null
}

variable "s3_bucket_acl" {
  description = "Canned ACL to apply to the bucket. If null, no ACL is applied."
  type        = string
  default     = null
}

variable "cors_rules" {
  description = "List of CORS rule maps. Each rule can contain allowed_headers, allowed_methods, allowed_origins, expose_headers, max_age_seconds."
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "custom_bucket_policy" {
  description = "Custom JSON bucket policy to be appended to the standard policy"
  type        = string
  default     = ""
}

# Data sources (conditional on use_account_alias_prefix)
data "aws_iam_account_alias" "current" {
  count = var.use_account_alias_prefix ? 1 : 0
}

# Random suffix resource (conditional)
resource "random_id" "this" {
  count       = var.use_random_suffix ? 1 : 0
  byte_length = 4
}

# Local values for bucket name construction
locals {
  account_alias = var.use_account_alias_prefix ? (
    try(data.aws_iam_account_alias.current[0].account_alias, "") != "" ? "${data.aws_iam_account_alias.current[0].account_alias}-" : ""
  ) : ""
  random_suffix = var.use_random_suffix ? "-${random_id.this[0].hex}" : ""
  bucket_name   = "${local.account_alias}${var.bucket_name}${local.random_suffix}"
}

# S3 Bucket
resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy
  tags = {
    Name = local.bucket_name
  }
}

# Bucket policy (combine custom policy with standard statements)
data "aws_iam_policy_document" "combined" {
  source_policy_documents = var.custom_bucket_policy != "" ? [var.custom_bucket_policy] : []

  statement {
    sid    = "DenyNonTLSRequests"
    effect = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*"
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
  }

  statement {
    sid    = "AllowInventoryAndAnalyticsReports"
    effect = "Allow"
    actions = [
      "s3:PutObject"
    ]
    resources = [
      "${aws_s3_bucket.this.arn}/*"
    ]
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.combined.json
}

# Public access block (conditional)
resource "aws_s3_bucket_public_access_block" "this" {
  count = var.enable_s3_public_access_block ? 1 : 0

  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Ownership controls
resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# Server-side encryption
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_master_key_id != null ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_master_key_id
    }
    bucket_key_enabled = var.kms_master_key_id != null ? var.bucket_key_enabled : null
  }
}

# Versioning
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_status
  }
}

# Lifecycle configuration (single resource with all rules)
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    abort_incomplete_multipart_upload {
      days_after_initiation = 14
    }
  }

  rule {
    id     = "noncurrent-version-transition-expiration"
    status = "Enabled"

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }

    noncurrent_version_expiration {
      noncurrent_days = 365
    }
  }

  dynamic "rule" {
    for_each = var.enable_analytics ? [1] : []
    content {
      id     = "analytics-export-lifecycle"
      status = "Enabled"

      filter {
        prefix = "_AWSBucketAnalytics/"
      }

      expiration {
        days = 30
      }
    }
  }

  dynamic "rule" {
    for_each = var.enable_bucket_inventory ? [1] : []
    content {
      id     = "inventory-export-lifecycle"
      status = "Enabled"

      filter {
        prefix = "_AWSBucketInventory/"
      }

      expiration {
        days = 14
      }
    }
  }

  transition_default_minimum_object_size = "all_storage_classes_128K"
}

# Analytics configuration (conditional)
resource "aws_s3_bucket_analytics_configuration" "this" {
  count = var.enable_analytics ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "${aws_s3_bucket.this.id}-analytics"

  storage_class_analysis {
    data_export {
      output_schema_version = "V_1"

      destination {
        s3_bucket_destination {
          bucket_arn = aws_s3_bucket.this.arn
          prefix     = "_AWSBucketAnalytics/"
          format     = "CSV"
        }
      }
    }
  }
}

# Inventory configuration (conditional)
resource "aws_s3_bucket_inventory" "this" {
  count = var.enable_bucket_inventory ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "${aws_s3_bucket.this.id}-inventory"

  included_object_versions = "All"
  optional_fields          = []

  schedule {
    frequency = "Weekly"
  }

  destination {
    bucket {
      format     = "ORC"
      bucket_arn = aws_s3_bucket.this.arn
      prefix     = "_AWSBucketInventory/"
    }
  }
}

# Logging (conditional)
resource "aws_s3_bucket_logging" "this" {
  count = var.logging_bucket != null ? 1 : 0

  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging_bucket
  target_prefix = "s3/${aws_s3_bucket.this.id}/"
}

# Transfer acceleration (conditional)
resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.transfer_acceleration != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration
}

# Bucket ACL (conditional)
resource "aws_s3_bucket_acl" "this" {
  count = var.s3_bucket_acl != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.s3_bucket_acl
}

# CORS configuration (conditional)
resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.15.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "bucket_name" {
  description = "Name of the S3 bucket"
  type        = string
  default     = "benchmark-access-logs-bkt"
}

variable "tags" {
  description = "Additional tags for the bucket"
  type        = map(string)
  default     = {}
}

variable "environment" {
  description = "Environment tag value"
  type        = string
  default     = "Development"
}

variable "block_public_access" {
  description = "Enable public access block settings"
  type        = bool
  default     = true
}

variable "block_public_acls" {
  description = "Block public ACLs"
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs"
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies"
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public buckets"
  type        = bool
  default     = true
}

variable "sse_algorithm" {
  description = "Server-side encryption algorithm (AES256, aws:kms, or none)"
  type        = string
  default     = "AES256"
}

variable "kms_key_id" {
  description = "KMS key ID for SSE-KMS encryption"
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Enable S3 bucket key for SSE-KMS"
  type        = bool
  default     = false
}

variable "versioning_status" {
  description = "Versioning status (Enabled, Suspended, Disabled)"
  type        = string
  default     = "Disabled"
}

variable "mfa_delete" {
  description = "MFA delete status (Enabled, Disabled)"
  type        = string
  default     = "Disabled"
}

variable "bucket_logging" {
  description = "Enable bucket logging"
  type        = bool
  default     = false
}

variable "log_bucket_name" {
  description = "Target bucket for server access logs"
  type        = string
  default     = null
}

variable "log_prefix" {
  description = "Prefix for log objects"
  type        = string
  default     = null
}

variable "object_lock_enabled" {
  description = "Enable S3 Object Lock"
  type        = bool
  default     = false
}

variable "object_lock_days" {
  description = "Default retention days for Object Lock"
  type        = number
  default     = 30
}

variable "control_object_ownership" {
  description = "Enable bucket ownership controls"
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership (BucketOwnerPreferred, ObjectWriter, BucketOwnerEnforced)"
  type        = string
  default     = "ObjectWriter"
}

variable "acl" {
  description = "Canned ACL to apply (e.g., private, public-read)"
  type        = string
  default     = null
}

variable "grants" {
  description = "List of grant objects for access control policy. Each object must include 'permission' and either 'type' or 'uri'."
  type = list(object({
    permission = string
    type       = string
    uri        = string
    id         = string
  }))
  default = []
}

variable "website_config" {
  description = "Website configuration map (supports index_document, error_document, redirect_all_requests_to, routing_rules)"
  type        = any
  default     = null
}

variable "intelligent_tiering_config" {
  description = "Intelligent tiering configuration map"
  type        = any
  default     = null
}

variable "cloudwatch_metrics" {
  description = "List of CloudWatch metric filter names (defaults to ['EntireBucket'])"
  type        = list(string)
  default     = ["EntireBucket"]
}

variable "cors_rules" {
  description = "List of CORS rule maps"
  type        = any
  default     = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rule maps"
  type        = any
  default     = []
}

locals {
  merged_tags = merge(
    {
      Environment      = var.environment
      ServiceProvider  = "Rackspace"
    },
    var.tags
  )
}

data "aws_caller_identity" "current" {}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

# S3 bucket
resource "aws_s3_bucket" "this" {
  bucket = "${var.bucket_name}-${random_id.bucket_suffix.hex}"
  tags   = local.merged_tags

  lifecycle {
    prevent_destroy = true
  }
}

# Public access block
resource "aws_s3_bucket_public_access_block" "this" {
  count = var.block_public_access ? 1 : 0

  bucket = aws_s3_bucket.this.id

  block_public_acls       = var.block_public_acls
  ignore_public_acls      = var.ignore_public_acls
  block_public_policy     = var.block_public_policy
  restrict_public_buckets = var.restrict_public_buckets
}

# KMS key if SSE-KMS and no key ID provided
resource "aws_kms_key" "this" {
  count = var.sse_algorithm == "aws:kms" && var.kms_key_id == null ? 1 : 0

  description             = "KMS key for S3 bucket ${var.bucket_name}"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = local.merged_tags
}

# SSE configuration
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = var.sse_algorithm != "none" ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.sse_algorithm
      kms_master_key_id = var.sse_algorithm == "aws:kms" ? (
        var.kms_key_id != null ? var.kms_key_id : aws_kms_key.this[0].arn
      ) : null
    }
    bucket_key_enabled = var.sse_algorithm == "aws:kms" ? var.bucket_key_enabled : null
  }
}

# Versioning
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = var.versioning_status
    mfa_delete = var.mfa_delete
  }
}

# Bucket logging
resource "aws_s3_bucket_logging" "this" {
  count = var.bucket_logging ? 1 : 0

  bucket = aws_s3_bucket.this.id

  target_bucket = var.log_bucket_name
  target_prefix = var.log_prefix
}

# Object lock configuration
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode = "GOVERNANCE"
      days = var.object_lock_days
    }
  }
}

# Ownership controls
resource "aws_s3_bucket_ownership_controls" "this" {
  count = var.control_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

# ACL
resource "aws_s3_bucket_acl" "this" {
  count = (var.acl != null) || (length(var.grants) > 0) ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "access_control_policy" {
    for_each = length(var.grants) > 0 ? [1] : []
    content {
      owner {
        id = data.aws_caller_identity.current.user_id
      }
      dynamic "grant" {
        for_each = var.grants
        content {
          permission = grant.value.permission
          grantee {
            type  = grant.value.type
            uri   = grant.value.uri
            id    = grant.value.id
          }
        }
      }
    }
  }

  acl = var.acl != null ? var.acl : null
}

# Website configuration
resource "aws_s3_bucket_website_configuration" "this" {
  count = var.website_config != null ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "index_document" {
    for_each = lookup(var.website_config, "index_document", null) != null ? [var.website_config.index_document] : []
    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = lookup(var.website_config, "error_document", null) != null ? [var.website_config.error_document] : []
    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = lookup(var.website_config, "redirect_all_requests_to", null) != null ? [var.website_config.redirect_all_requests_to] : []
    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = lookup(redirect_all_requests_to.value, "protocol", null)
    }
  }

  dynamic "routing_rule" {
    for_each = lookup(var.website_config, "routing_rules", [])
    content {
      dynamic "condition" {
        for_each = lookup(routing_rule.value, "condition", null) != null ? [routing_rule.value.condition] : []
        content {
          key_prefix_equals               = lookup(condition.value, "key_prefix_equals", null)
          http_error_code_returned_equals = lookup(condition.value, "http_error_code_returned_equals", null)
        }
      }
      dynamic "redirect" {
        for_each = lookup(routing_rule.value, "redirect", null) != null ? [routing_rule.value.redirect] : []
        content {
          protocol            = lookup(redirect.value, "protocol", null)
          host_name           = lookup(redirect.value, "host_name", null)
          replace_key_prefix_with = lookup(redirect.value, "replace_key_prefix_with", null)
          replace_key_with     = lookup(redirect.value, "replace_key_with", null)
          http_redirect_code   = lookup(redirect.value, "http_redirect_code", null)
        }
      }
    }
  }
}

# Intelligent tiering – using null_resource + AWS CLI to avoid provider cache issue
resource "null_resource" "intelligent_tiering" {
  count = var.intelligent_tiering_config != null ? 1 : 0

  triggers = {
    bucket = aws_s3_bucket.this.id
    config = jsonencode(var.intelligent_tiering_config)
  }

  provisioner "local-exec" {
    command = <<EOT
      aws s3api put-bucket-intelligent-tiering-configuration \
        --bucket ${aws_s3_bucket.this.id} \
        --id ${var.intelligent_tiering_config.name} \
        --intelligent-tiering-configuration '${jsonencode(var.intelligent_tiering_config)}'
    EOT
  }

  depends_on = [aws_s3_bucket.this]
}

# CloudWatch metrics
resource "aws_s3_bucket_metric" "this" {
  for_each = { for idx, name in var.cloudwatch_metrics : name => name }

  bucket = aws_s3_bucket.this.id
  name   = each.value
}

# CORS configuration
resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = lookup(cors_rule.value, "allowed_headers", null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = lookup(cors_rule.value, "expose_headers", null)
      max_age_seconds = lookup(cors_rule.value, "max_age_seconds", null)
    }
  }
}

# Lifecycle configuration
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = lookup(rule.value, "status", "Enabled")

      dynamic "abort_incomplete_multipart_upload" {
        for_each = lookup(rule.value, "abort_incomplete_multipart_upload", null) != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }

      dynamic "expiration" {
        for_each = lookup(rule.value, "expiration", null) != null ? [rule.value.expiration] : []
        content {
          date                         = lookup(expiration.value, "date", null)
          days                         = lookup(expiration.value, "days", null)
          expired_object_delete_marker = lookup(expiration.value, "expired_object_delete_marker", null)
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = lookup(rule.value, "noncurrent_version_expiration", null) != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.noncurrent_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = lookup(rule.value, "noncurrent_version_transitions", [])
        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "transition" {
        for_each = lookup(rule.value, "transitions", [])
        content {
          date          = lookup(transition.value, "date", null)
          days          = lookup(transition.value, "days", null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "filter" {
        for_each = lookup(rule.value, "filter", null) != null ? [rule.value.filter] : []
        content {
          prefix = lookup(filter.value, "prefix", null)
          tag {
            key   = filter.value.tag.key
            value = filter.value.tag.value
          }
        }
      }
    }
  }
}

# main.tf - Enterprise-grade S3 bucket architecture

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 6.0"
    }
  }
}

data "aws_partition" "current" {}

# ----------------------------------------------------------------------
# Provider alias for replication destination region
# ----------------------------------------------------------------------
provider "aws" {
  alias  = "destination"
  region = var.replication_destination_region
}

# ----------------------------------------------------------------------
# Variables
# ----------------------------------------------------------------------
variable "bucket_name" {
  description = "Name of the S3 bucket (max 63 chars). Conflicts with bucket_prefix."
  type        = string
  default     = null

  validation {
    condition     = var.bucket_name == null ? true : length(var.bucket_name) <= 63
    error_message = "bucket_name must be 63 characters or less."
  }
}

variable "bucket_prefix" {
  description = "Prefix for the S3 bucket name (max 37 chars). Conflicts with bucket_name."
  type        = string
  default     = null

  validation {
    condition     = var.bucket_prefix == null ? true : length(var.bucket_prefix) <= 37
    error_message = "bucket_prefix must be 37 characters or less."
  }
}

variable "force_destroy" {
  description = "Allow deletion of non-empty bucket."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership controls. Use 'BucketOwnerEnforced' or 'ObjectWriter'."
  type        = string
  default     = "BucketOwnerEnforced"

  validation {
    condition     = contains(["BucketOwnerEnforced", "ObjectWriter"], var.object_ownership)
    error_message = "object_ownership must be either 'BucketOwnerEnforced' or 'ObjectWriter'."
  }
}

variable "block_public_acls" {
  description = "Block public ACLs."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public buckets."
  type        = bool
  default     = true
}

variable "encryption_type" {
  description = "Server-side encryption algorithm. 'AES256' or 'aws:kms'."
  type        = string
  default     = "AES256"

  validation {
    condition     = contains(["AES256", "aws:kms"], var.encryption_type)
    error_message = "encryption_type must be 'AES256' or 'aws:kms'."
  }
}

variable "kms_key_arn" {
  description = "KMS key ARN for encryption. Required if encryption_type is 'aws:kms'."
  type        = string
  default     = null
}

variable "versioning_enabled" {
  description = "Enable bucket versioning."
  type        = bool
  default     = false
}

variable "custom_policy" {
  description = "Custom JSON policy to attach to the bucket."
  type        = string
  default     = ""
}

variable "logging_source_bucket_arns" {
  description = "List of source bucket ARNs that will deliver logs to this bucket."
  type        = list(string)
  default     = []
}

variable "eventbridge_enabled" {
  description = "Enable EventBridge notifications."
  type        = bool
  default     = false
}

variable "logging_target_bucket" {
  description = "Target bucket for server access logs."
  type        = string
  default     = null
}

variable "logging_target_prefix" {
  description = "Prefix for server access log objects."
  type        = string
  default     = null
}

variable "object_lock_enabled" {
  description = "Enable object lock on the bucket."
  type        = bool
  default     = false
}

variable "object_lock_mode" {
  description = "Object lock retention mode: GOVERNANCE or COMPLIANCE."
  type        = string
  default     = "GOVERNANCE"

  validation {
    condition     = contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_mode)
    error_message = "object_lock_mode must be 'GOVERNANCE' or 'COMPLIANCE'."
  }
}

variable "object_lock_days" {
  description = "Number of days for default retention."
  type        = number
  default     = null
}

variable "object_lock_years" {
  description = "Number of years for default retention."
  type        = number
  default     = null
}

variable "replication_enabled" {
  description = "Enable cross-region replication."
  type        = bool
  default     = false
}

variable "replication_destination_region" {
  description = "AWS region for replication destination bucket."
  type        = string
  default     = "us-west-2"
}

variable "replication_rules" {
  description = "List of replication rule configurations."
  type = list(object({
    priority            = number
    filter_prefix       = optional(string)
    filter_tags         = optional(map(string))
    destination_bucket  = string
    storage_class       = optional(string)
    replica_kms_key_id  = optional(string)
  }))
  default = []
}

variable "inventory_enabled" {
  description = "Enable bucket inventory."
  type        = bool
  default     = false
}

variable "inventory_destination_bucket_arn" {
  description = "ARN of the destination bucket for inventory reports."
  type        = string
  default     = null
}

variable "inventory_prefix" {
  description = "Prefix for inventory reports."
  type        = string
  default     = ""
}

variable "inventory_format" {
  description = "Format for inventory output: Parquet, CSV, ORC."
  type        = string
  default     = "Parquet"
}

variable "inventory_schedule" {
  description = "Frequency: Weekly or Daily."
  type        = string
  default     = "Weekly"
}

variable "inventory_encryption" {
  description = "Encryption for inventory: SSE_S3 or SSE_KMS."
  type        = string
  default     = "SSE_S3"
}

variable "inventory_kms_key_arn" {
  description = "KMS key ARN for inventory encryption (SSE_KMS)."
  type        = string
  default     = null
}

variable "cors_rules" {
  description = "List of CORS rules."
  type = list(object({
    allowed_headers = list(string)
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rule configurations."
  type = list(object({
    id                                     = string
    status                                 = optional(string, "Enabled")
    prefix                                 = optional(string)
    filter_and_prefix                      = optional(string)
    filter_and_tags                        = optional(map(string))
    expiration_days                        = optional(number)
    expiration_date                        = optional(string)
    expiration_expired_object_delete_marker = optional(bool)
    transition_days                        = optional(number)
    transition_date                        = optional(string)
    transition_storage_class               = optional(string)
    noncurrent_version_expiration_days     = optional(number)
    noncurrent_version_transition_days     = optional(number)
    noncurrent_version_transition_storage_class = optional(string)
    abort_incomplete_multipart_upload_days  = optional(number)
  }))
  default = []
}

# ----------------------------------------------------------------------
# Locals
# ----------------------------------------------------------------------
locals {
  bucket_name_or_prefix = var.bucket_name != null ? var.bucket_name : var.bucket_prefix

  # Combine policies: SSL-only + logging (if source ARNs provided) + custom
  ssl_policy_json = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name_or_prefix}",
          "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name_or_prefix}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  logging_policy_json = length(var.logging_source_bucket_arns) > 0 ? jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "S3ServerAccessLogs"
        Effect    = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name_or_prefix}/*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = var.logging_source_bucket_arns
          }
        }
      }
    ]
  }) : ""

  combined_policy = var.custom_policy != "" ? jsonencode(merge(
    jsondecode(var.custom_policy),
    jsondecode(local.ssl_policy_json),
    local.logging_policy_json != "" ? jsondecode(local.logging_policy_json) : {}
  )) : (local.logging_policy_json != "" ? jsonencode(merge(
    jsondecode(local.ssl_policy_json),
    jsondecode(local.logging_policy_json)
  )) : local.ssl_policy_json)

  use_acl = var.object_ownership == "ObjectWriter"
}

# ----------------------------------------------------------------------
# Main bucket
# ----------------------------------------------------------------------
resource "aws_s3_bucket" "this" {
  bucket        = var.bucket_name
  bucket_prefix = var.bucket_prefix
  force_destroy = var.force_destroy

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_acl" "this" {
  count  = local.use_acl ? 1 : 0
  bucket = aws_s3_bucket.this.id
  acl    = "private"
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.encryption_type
      kms_master_key_id = var.encryption_type == "aws:kms" ? var.kms_key_arn : null
    }
    bucket_key_enabled = var.encryption_type == "aws:kms" ? true : null
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration {
    status = var.versioning_enabled ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = local.combined_policy
}

# ----------------------------------------------------------------------
# EventBridge notifications
# ----------------------------------------------------------------------
resource "aws_s3_bucket_notification" "eventbridge" {
  count  = var.eventbridge_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id

  eventbridge = true
}

# ----------------------------------------------------------------------
# Server access logging
# ----------------------------------------------------------------------
resource "aws_s3_bucket_logging" "this" {
  count = var.logging_target_bucket != null ? 1 : 0

  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging_target_bucket
  target_prefix = var.logging_target_prefix

  lifecycle {
    precondition {
      condition     = !var.object_lock_enabled
      error_message = "Cannot enable logging when object lock is enabled."
    }
  }
}

# ----------------------------------------------------------------------
# Object lock configuration
# ----------------------------------------------------------------------
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.object_lock_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode = var.object_lock_mode
      days = var.object_lock_days
      years = var.object_lock_years
    }
  }

  lifecycle {
    precondition {
      condition     = var.logging_target_bucket == null
      error_message = "Cannot enable object lock when logging is enabled."
    }
  }
}

# ----------------------------------------------------------------------
# Cross-region replication
# ----------------------------------------------------------------------
# Destination bucket in replication region
resource "aws_s3_bucket" "destination" {
  provider = aws.destination
  count    = var.replication_enabled ? 1 : 0

  bucket        = "${var.bucket_name != null ? var.bucket_name : var.bucket_prefix}-destination"
  force_destroy = var.force_destroy

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "destination" {
  provider = aws.destination
  count    = var.replication_enabled ? 1 : 0

  bucket = aws_s3_bucket.destination[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_iam_role" "replication" {
  count = var.replication_enabled ? 1 : 0
  name  = "${local.bucket_name_or_prefix}-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "replication" {
  count = var.replication_enabled ? 1 : 0
  name  = "${local.bucket_name_or_prefix}-replication-policy"
  role  = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [aws_s3_bucket.this.arn]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = "${aws_s3_bucket.this.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = "${aws_s3_bucket.destination[0].arn}/*"
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count = var.replication_enabled && length(var.replication_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  role = aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id       = "rule-${rule.value.priority}"
      priority = rule.value.priority
      status   = "Enabled"

      filter {
        prefix = rule.value.filter_prefix
        dynamic "tag" {
          for_each = rule.value.filter_tags != null ? { for k, v in rule.value.filter_tags : k => v } : {}
          content {
            key   = tag.key
            value = tag.value
          }
        }
      }

      destination {
        bucket             = aws_s3_bucket.destination[0].arn
        storage_class      = rule.value.storage_class
        replica_kms_key_id = rule.value.replica_kms_key_id
      }
    }
  }
}

# ----------------------------------------------------------------------
# Inventory configuration
# ----------------------------------------------------------------------
resource "aws_s3_bucket_inventory" "this" {
  count  = var.inventory_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id

  name    = "DefaultInventory"
  enabled = true

  included_object_versions = "All"

  optional_fields = ["Size", "LastModifiedDate", "StorageClass", "ETag"]

  schedule {
    frequency = var.inventory_schedule
  }

  destination {
    bucket {
      format     = var.inventory_format
      bucket_arn = var.inventory_destination_bucket_arn
      prefix     = var.inventory_prefix

      dynamic "encryption" {
        for_each = var.inventory_encryption == "SSE_KMS" ? [1] : []
        content {
          sse_kms {
            key_id = var.inventory_kms_key_arn
          }
        }
      }

      dynamic "encryption" {
        for_each = var.inventory_encryption == "SSE_S3" ? [1] : []
        content {
          sse_s3 {}
        }
      }
    }
  }
}

# ----------------------------------------------------------------------
# CORS configuration
# ----------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# ----------------------------------------------------------------------
# Lifecycle configuration
# ----------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = { for idx, rule in var.lifecycle_rules : idx => rule }
    content {
      id     = rule.value.id
      status = rule.value.status

      filter {
        prefix = rule.value.filter_and_prefix != null ? rule.value.filter_and_prefix : (rule.value.prefix != null ? rule.value.prefix : "")
        dynamic "tag" {
          for_each = rule.value.filter_and_tags != null ? { for k, v in rule.value.filter_and_tags : k => v } : {}
          content {
            key   = tag.key
            value = tag.value
          }
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration_days != null || rule.value.expiration_date != null || rule.value.expiration_expired_object_delete_marker != null ? [1] : []
        content {
          days                         = rule.value.expiration_days
          date                         = rule.value.expiration_date
          expired_object_delete_marker = rule.value.expiration_expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = rule.value.transition_days != null || rule.value.transition_date != null ? [1] : []
        content {
          days          = rule.value.transition_days
          date          = rule.value.transition_date
          storage_class = rule.value.transition_storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration_days != null ? [1] : []
        content {
          noncurrent_days = rule.value.noncurrent_version_expiration_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition_days != null ? [1] : []
        content {
          noncurrent_days = rule.value.noncurrent_version_transition_days
          storage_class   = rule.value.noncurrent_version_transition_storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [1] : []
        content {
          days_after_initiation = rule.value.abort_incomplete_multipart_upload_days
        }
      }
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.50.0"
    }
  }
}

variable "group_name_prefix" {
  description = "Prefix for IAM group names"
  type        = string
  default     = "app"
}

variable "s3_allowed_region" {
  description = "AWS region where s3:CreateBucket is allowed"
  type        = string
  default     = "us-east-1"
}

variable "remote_state_bucket" {
  description = "Name of the remote state S3 bucket to restrict access to"
  type        = string
  default     = "remote-state-bucket"
}

data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# Account-wide security baselines
# ------------------------------------------------------------------------------
resource "aws_iam_account_password_policy" "this" {
  minimum_password_length        = 12
  require_uppercase_characters   = true
  require_lowercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  allow_users_to_change_password = true
}

resource "aws_s3_account_public_access_block" "this" {
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# IAM groups
# ------------------------------------------------------------------------------
resource "aws_iam_group" "developer" {
  name = "${var.group_name_prefix}_developer"
}

resource "aws_iam_group" "admin" {
  name = "${var.group_name_prefix}_admin"
}

# ------------------------------------------------------------------------------
# Managed policy attachments for developer group
# ------------------------------------------------------------------------------
resource "aws_iam_group_policy_attachment" "developer_readonly" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "developer_change_password" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserChangePassword"
}

resource "aws_iam_group_policy_attachment" "developer_ssh_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserSSHKeys"
}

# ------------------------------------------------------------------------------
# Custom policy: manage own access keys
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "developer_own_keys" {
  statement {
    effect = "Allow"
    actions = [
      "iam:CreateAccessKey",
      "iam:UpdateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys"
    ]
    resources = [
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
    ]
  }
}

resource "aws_iam_group_policy" "developer_own_keys" {
  group  = aws_iam_group.developer.name
  name   = "manage-own-access-keys"
  policy = data.aws_iam_policy_document.developer_own_keys.json
}

# ------------------------------------------------------------------------------
# Custom policy: manage virtual MFA devices
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "developer_mfa_device" {
  statement {
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ListVirtualMFADevices"
    ]
    resources = [
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}"
    ]
  }

  statement {
    effect = "Deny"
    actions = [
      "iam:DeactivateMFADevice"
    ]
    resources = [
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}"
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }
}

resource "aws_iam_group_policy" "developer_mfa_device" {
  group  = aws_iam_group.developer.name
  name   = "manage-virtual-mfa"
  policy = data.aws_iam_policy_document.developer_mfa_device.json
}

# ------------------------------------------------------------------------------
# Custom policy: MFA-gated S3 access
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "developer_s3_gate" {
  # Allow all S3 actions when MFA is present
  statement {
    effect = "Allow"
    actions = [
      "s3:*"
    ]
    resources = [
      "*"
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  # Unconditionally deny s3:CreateBucket outside the allowed region
  statement {
    effect = "Deny"
    actions = [
      "s3:CreateBucket"
    ]
    resources = [
      "*"
    ]
    condition {
      test     = "StringNotEquals"
      variable = "aws:RequestedRegion"
      values   = [var.s3_allowed_region]
    }
  }

  # Unconditionally deny all s3:* access to the remote state bucket
  statement {
    effect = "Deny"
    actions = [
      "s3:*"
    ]
    resources = [
      "arn:aws:s3:::${var.remote_state_bucket}",
      "arn:aws:s3:::${var.remote_state_bucket}/*"
    ]
  }
}

resource "aws_iam_group_policy" "developer_s3_gate" {
  group  = aws_iam_group.developer.name
  name   = "mfa-gated-s3"
  policy = data.aws_iam_policy_document.developer_s3_gate.json
}

# ------------------------------------------------------------------------------
# Custom policy: MFA-gated access to EC2, ELB, CloudWatch, AutoScaling
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "developer_ec2_gate" {
  # Allow EC2/ELB/AutoScaling/CloudWatch actions with MFA
  statement {
    effect = "Allow"
    actions = [
      "ec2:*",
      "elasticloadbalancing:*",
      "autoscaling:*",
      "cloudwatch:*"
    ]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  # Allow iam:PassRole with MFA
  statement {
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  # Deny EC2/ELB/AutoScaling/CloudWatch actions without MFA
  statement {
    effect = "Deny"
    actions = [
      "ec2:*",
      "elasticloadbalancing:*",
      "autoscaling:*",
      "cloudwatch:*"
    ]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }

  # Deny iam:PassRole on service-linked roles without MFA
  statement {
    effect = "Deny"
    actions = [
      "iam:PassRole"
    ]
    resources = [
      "arn:aws:iam::*:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling",
      "arn:aws:iam::*:role/aws-service-role/ec2.amazonaws.com/AWSServiceRoleForEC2"
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }
}

resource "aws_iam_group_policy" "developer_ec2_gate" {
  group  = aws_iam_group.developer.name
  name   = "mfa-gated-ec2-elb-cw-asg"
  policy = data.aws_iam_policy_document.developer_ec2_gate.json
}

# ------------------------------------------------------------------------------
# Admin role
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "admin" {
  name               = "admin"
  assume_role_policy = data.aws_iam_policy_document.admin_assume_role.json
}

# Custom policy for admin role: full admin access conditioned on MFA
data "aws_iam_policy_document" "admin_role_policy" {
  statement {
    effect = "Allow"
    actions = [
      "*"
    ]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role_policy" "admin" {
  name   = "admin-mfa"
  role   = aws_iam_role.admin.name
  policy = data.aws_iam_policy_document.admin_role_policy.json
}

# ------------------------------------------------------------------------------
# Admin group policy: allow assuming the admin role with MFA
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "admin_group_assume_role" {
  statement {
    effect = "Allow"
    actions = [
      "sts:AssumeRole"
    ]
    resources = [
      aws_iam_role.admin.arn
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_group_policy" "admin_group_assume_role" {
  group  = aws_iam_group.admin.name
  name   = "assume-admin-role"
  policy = data.aws_iam_policy_document.admin_group_assume_role.json
}

# ------------------------------------------------------------------------------
# TERRAFORM & PROVIDER CONFIGURATION
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.95.0"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------
variable "vpc_cidr" {
  description = "Primary CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_definitions" {
  description = "List of subnet definitions with CIDR, availability zone, and name"
  type = list(object({
    cidr_block        = string
    availability_zone = string
    name              = string
  }))
  default = [
    { cidr_block = "10.0.0.0/24",  availability_zone = "us-east-1a", name = "subnet-0" },
    { cidr_block = "10.0.1.0/24",  availability_zone = "us-east-1b", name = "subnet-1" },
    { cidr_block = "10.0.2.0/24",  availability_zone = "us-east-1c", name = "subnet-2" },
    { cidr_block = "10.0.3.0/24",  availability_zone = "us-east-1a", name = "subnet-3" },
    { cidr_block = "10.0.4.0/24",  availability_zone = "us-east-1b", name = "subnet-4" },
    { cidr_block = "10.0.5.0/24",  availability_zone = "us-east-1c", name = "subnet-5" },
    { cidr_block = "10.0.6.0/24",  availability_zone = "us-east-1a", name = "subnet-6" },
    { cidr_block = "10.0.7.0/24",  availability_zone = "us-east-1b", name = "subnet-7" },
    { cidr_block = "10.0.8.0/24",  availability_zone = "us-east-1c", name = "subnet-8" },
    { cidr_block = "10.0.9.0/24",  availability_zone = "us-east-1a", name = "subnet-9" },
    { cidr_block = "10.0.10.0/24", availability_zone = "us-east-1b", name = "subnet-10" },
    { cidr_block = "10.0.11.0/24", availability_zone = "us-east-1c", name = "subnet-11" },
    { cidr_block = "10.0.12.0/24", availability_zone = "us-east-1a", name = "subnet-12" },
    { cidr_block = "10.0.13.0/24", availability_zone = "us-east-1b", name = "subnet-13" },
    { cidr_block = "10.0.14.0/24", availability_zone = "us-east-1c", name = "subnet-14" },
    { cidr_block = "10.0.15.0/24", availability_zone = "us-east-1a", name = "subnet-15" },
  ]
}

# ------------------------------------------------------------------------------
# DATA SOURCES
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# ------------------------------------------------------------------------------
# LOCALS
# ------------------------------------------------------------------------------
locals {
  az_names = data.aws_availability_zones.available.names
  # Override availability zones from variable with actual AZ names from data source,
  # cycling through available AZs.
  subnet_map = {
    for idx, def in var.subnet_definitions :
    def.name => {
      cidr_block        = def.cidr_block
      availability_zone = local.az_names[idx % length(local.az_names)]
      name              = def.name
    }
  }
}

# ------------------------------------------------------------------------------
# VPC
# ------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true
  instance_tenancy                 = "default"

  tags = {
    Name = "my-deploy-me-vpc"
  }
}

# ------------------------------------------------------------------------------
# INTERNET GATEWAY
# ------------------------------------------------------------------------------
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "igw-deploy-me"
  }
}

# ------------------------------------------------------------------------------
# ELASTIC IP FOR NAT GATEWAY
# ------------------------------------------------------------------------------
resource "aws_eip" "nat_eip" {
  domain = "vpc"

  tags = {
    Name = "deployme-nat-eip"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# NAT GATEWAY
# ------------------------------------------------------------------------------
resource "aws_nat_gateway" "nat_gw" {
  allocation_id = aws_eip.nat_eip.id
  subnet_id     = aws_subnet.this["subnet-0"].id   # first private subnet (index 0)
  depends_on    = [aws_internet_gateway.igw]

  tags = {
    Name = "deployme-natgw"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# SUBNETS (16)
# ------------------------------------------------------------------------------
resource "aws_subnet" "this" {
  for_each = local.subnet_map

  vpc_id            = aws_vpc.main.id
  cidr_block        = each.value.cidr_block
  availability_zone = each.value.availability_zone

  # Public subnets (indices 8-11) do not auto-assign public IPv4 addresses
  map_public_ip_on_launch = tonumber(split("-", each.key)[1]) >= 8 && tonumber(split("-", each.key)[1]) <= 11 ? false : null

  tags = {
    Name = each.value.name
    Tier = (
      tonumber(split("-", each.key)[1]) < 4  ? "private-a" :
      tonumber(split("-", each.key)[1]) < 8  ? "private-b" :
      tonumber(split("-", each.key)[1]) < 12 ? "public"    : "spare"
    )
  }
}

# ------------------------------------------------------------------------------
# ROUTE TABLES
# ------------------------------------------------------------------------------
# Private route table
resource "aws_route_table" "private_rt" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_gw.id
  }

  tags = {
    Name = "rt-private-deploy-me"
  }
}

# Public route table
resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "rt-public-deploy-me"
  }
}

# Spare route table
resource "aws_route_table" "spare_rt" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "rt-spare-deploy-me"
  }
}

# ------------------------------------------------------------------------------
# MAIN ROUTE TABLE ASSOCIATION (set private route table as main)
# ------------------------------------------------------------------------------
resource "aws_main_route_table_association" "private_main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.private_rt.id
}

# ------------------------------------------------------------------------------
# ROUTE TABLE ASSOCIATIONS
# ------------------------------------------------------------------------------
# Private subnets (indices 0-7) -> private route table
resource "aws_route_table_association" "private" {
  for_each = {
    for key, subnet in aws_subnet.this :
    key => subnet
    if tonumber(split("-", key)[1]) >= 0 && tonumber(split("-", key)[1]) <= 7
  }

  subnet_id      = each.value.id
  route_table_id = aws_route_table.private_rt.id
}

# Public subnets (indices 8-11) -> public route table
resource "aws_route_table_association" "public" {
  for_each = {
    for key, subnet in aws_subnet.this :
    key => subnet
    if tonumber(split("-", key)[1]) >= 8 && tonumber(split("-", key)[1]) <= 11
  }

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public_rt.id
}

# Spare subnets (indices 12-15) -> spare route table
resource "aws_route_table_association" "spare" {
  for_each = {
    for key, subnet in aws_subnet.this :
    key => subnet
    if tonumber(split("-", key)[1]) >= 12 && tonumber(split("-", key)[1]) <= 15
  }

  subnet_id      = each.value.id
  route_table_id = aws_route_table.spare_rt.id
}

# ------------------------------------------------------------------------------
# SECURITY GROUP
# ------------------------------------------------------------------------------
resource "aws_security_group" "allow_web_traffic" {
  name        = "allow_web_traffic"
  description = "Allow HTTP, HTTPS, and SSH inbound from specific sources; outbound limited to VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic to VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "allow_web_traffic"
  }
}

# ------------------------------------------------------------------------------
# OUTPUT
# ------------------------------------------------------------------------------
output "server_public_ip" {
  description = "Public IP address of the NAT Gateway's Elastic IP"
  value       = aws_eip.nat_eip.public_ip
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.99.0"
    }
  }
}

# Input variables
variable "name" {
  description = "Name for the resources"
  type        = string
  default     = "default"
}

variable "environment" {
  description = "Environment (e.g., dev, prod)"
  type        = string
  default     = "dev"
}

variable "managedby" {
  description = "Managed by identifier"
  type        = string
  default     = "opsstation"
}

variable "label_order" {
  description = "Order of label elements"
  type        = list(string)
  default     = ["name", "environment"]
}

variable "repository" {
  description = "Repository URL"
  type        = string
  default     = "https://github.com/opsstation/terraform-aws-security_group"
}

variable "enable" {
  description = "Enable module execution"
  type        = bool
  default     = true
}

variable "new_sg" {
  description = "Create a new security group"
  type        = bool
  default     = true
}

variable "vpc_id" {
  description = "VPC ID for the security group"
  type        = string
  default     = null
}

variable "prefix_list_enabled" {
  description = "Enable creation of managed prefix list"
  type        = bool
  default     = false
}

variable "prefix_list_address_family" {
  description = "Address family for prefix list"
  type        = string
  default     = "IPv4"
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries for prefix list"
  type        = number
  default     = 5
}

variable "prefix_list_entries" {
  description = "List of prefix list entries"
  type = list(object({
    cidr        = string
    description = optional(string, "")
  }))
  default = []
}

variable "existing_sg_id" {
  description = "ID of an existing security group to use instead of creating a new one"
  type        = string
  default     = null
}

variable "ingress_rules" {
  description = "List of ingress rule maps"
  type = list(object({
    description              = optional(string, "")
    from_port                = number
    to_port                  = number
    protocol                 = string
    cidr_blocks              = optional(list(string), null)
    ipv6_cidr_blocks         = optional(list(string), null)
    self                     = optional(bool, null)
    source_security_group_id = optional(string, null)
    prefix_list_id           = optional(string, null)
  }))
  default = []
}

variable "egress_rules" {
  description = "List of egress rule maps"
  type = list(object({
    description              = optional(string, "")
    from_port                = number
    to_port                  = number
    protocol                 = string
    cidr_blocks              = optional(list(string), null)
    ipv6_cidr_blocks         = optional(list(string), null)
    self                     = optional(bool, null)
    source_security_group_id = optional(string, null)
    prefix_list_id           = optional(string, null)
  }))
  default = []
}

# Module for standard labels
module "labels" {
  source      = "cloudposse/label/null"
  version     = "0.25.0"
  name        = var.name
  environment = var.environment
  label_order = var.label_order
  tags = {
    repository = var.repository
    managedby  = var.managedby
  }
}

# Local values
locals {
  # VPC: use provided vpc_id or create a default VPC
  effective_vpc_id = var.vpc_id != null ? var.vpc_id : aws_vpc.this[0].id

  create_sg          = var.enable && var.new_sg
  create_prefix_list = var.enable && var.prefix_list_enabled

  # Security group ID to use in rules
  sg_id = var.existing_sg_id != null ? var.existing_sg_id : (local.create_sg ? aws_security_group.this[0].id : null)

  # Prefix list ID to use as default in rules
  prefix_list_id = local.create_prefix_list ? aws_ec2_managed_prefix_list.this[0].id : null

  # Build a unified map of all rules with a unique key and type
  ingress_rules_map = { for idx, rule in var.ingress_rules : "ingress-${idx}" => merge(rule, { type = "ingress" }) }
  egress_rules_map  = { for idx, rule in var.egress_rules : "egress-${idx}" => merge(rule, { type = "egress" }) }
  all_rules         = merge(local.ingress_rules_map, local.egress_rules_map)
}

# Default VPC when none provided
resource "aws_vpc" "this" {
  count      = var.vpc_id == null ? 1 : 0
  cidr_block = "10.0.0.0/16"
  tags       = module.labels.tags
}

# Security group (conditional)
resource "aws_security_group" "this" {
  count       = local.create_sg ? 1 : 0
  name        = "${module.labels.id}-sg"
  description = "Security group managed by Terraform"
  vpc_id      = local.effective_vpc_id
  tags        = module.labels.tags

  lifecycle {
    create_before_destroy = true
  }
}

# Managed prefix list (conditional)
resource "aws_ec2_managed_prefix_list" "this" {
  count          = local.create_prefix_list ? 1 : 0
  name           = "${module.labels.id}-prefix-list"
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = try(entry.value.description, "")
    }
  }
}

# Security group rules (dynamic)
resource "aws_security_group_rule" "this" {
  for_each = tomap(local.all_rules)

  type              = each.value.type
  security_group_id = local.sg_id

  description = try(each.value.description, "")
  from_port   = each.value.from_port
  to_port     = each.value.to_port
  protocol    = each.value.protocol

  cidr_blocks              = try(each.value.cidr_blocks, null)
  ipv6_cidr_blocks         = try(each.value.ipv6_cidr_blocks, null)
  self                     = try(each.value.self, null)
  source_security_group_id = try(each.value.source_security_group_id, null)
  prefix_list_ids          = each.value.prefix_list_id != null ? [each.value.prefix_list_id] : (local.prefix_list_id != null ? [local.prefix_list_id] : null)

  lifecycle {
    precondition {
      condition     = local.sg_id != null
      error_message = "Security group ID must be provided either via existing_sg_id or by creating a new security group (new_sg = true) when rules are specified."
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
  }
}

variable "env_name" {
  description = "Environment name used for constructing role and policy names"
  type        = string
  default     = "dev"
}

data "aws_caller_identity" "current" {}

# IAM account password policy
resource "aws_iam_account_password_policy" "main" {
  minimum_password_length      = 14
  require_lowercase_characters = true
  require_uppercase_characters = true
  require_numbers              = true
  require_symbols              = false
  allow_users_to_change_password = true
  max_password_age             = 90
  password_reuse_prevention    = 3
}

# ECS task role
resource "aws_iam_role" "ecs_task" {
  name = "ecs-task-role-for-${var.env_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_task_secretsmanager" {
  role       = aws_iam_role.ecs_task.name
  policy_arn = "arn:aws:iam::aws:policy/SecretsManagerReadWrite"
}

data "aws_iam_policy_document" "ecs_task_inline" {
  statement {
    actions   = ["ssmmessages:*"]
    resources = ["*"]
  }
  statement {
    actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]
    resources = ["arn:aws:s3:::*", "arn:aws:s3:::*/*"]
  }
}

resource "aws_iam_role_policy" "ecs_task_inline" {
  name   = "ecs-task-inline"
  role   = aws_iam_role.ecs_task.id
  policy = data.aws_iam_policy_document.ecs_task_inline.json
}

# ECS execution role
resource "aws_iam_role" "ecs_execution" {
  name = "ecs-execution-role-for-${var.env_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_execution_task_exec" {
  role       = aws_iam_role.ecs_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role_policy_attachment" "ecs_execution_ec2_container" {
  role       = aws_iam_role.ecs_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

data "aws_iam_policy_document" "ecs_execution_inline" {
  statement {
    actions   = ["secretsmanager:GetSecretValue"]
    resources = ["arn:aws:secretsmanager:*:${data.aws_caller_identity.current.account_id}:secret:*"]
  }
  statement {
    actions   = ["kms:Decrypt"]
    resources = ["arn:aws:kms:*:${data.aws_caller_identity.current.account_id}:key/*"]
  }
}

resource "aws_iam_role_policy" "ecs_execution_inline" {
  name   = "ecs-execution-inline"
  role   = aws_iam_role.ecs_execution.id
  policy = data.aws_iam_policy_document.ecs_execution_inline.json
}

# ECS events role (EventBridge assumable)
resource "aws_iam_role" "ecs_events" {
  name = "ecs_events_role-for-${var.env_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_events_task_exec" {
  role       = aws_iam_role.ecs_events.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role_policy_attachment" "ecs_events_ec2_container" {
  role       = aws_iam_role.ecs_events.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

# Public Lambda role
resource "aws_iam_role" "lambda_public" {
  name = "lambda-public-role-for-${var.env_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

data "aws_iam_policy_document" "lambda_public_inline" {
  statement {
    actions   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
    resources = ["arn:aws:logs:*:*:*"]
  }
}

resource "aws_iam_role_policy" "lambda_public_inline" {
  name   = "lambda-public-inline"
  role   = aws_iam_role.lambda_public.id
  policy = data.aws_iam_policy_document.lambda_public_inline.json
}

# VPC Lambda role
resource "aws_iam_role" "lambda_vpc" {
  name = "lambda-vpc-role-for-${var.env_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

data "aws_iam_policy_document" "lambda_vpc_inline" {
  statement {
    actions   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
    resources = ["arn:aws:logs:*:*:*"]
  }
  statement {
    actions   = ["ec2:CreateNetworkInterface", "ec2:DeleteNetworkInterface", "ec2:DescribeNetworkInterfaces"]
    resources = ["*"]
  }
  statement {
    actions   = ["secretsmanager:GetSecretValue"]
    resources = ["arn:aws:secretsmanager:*:${data.aws_caller_identity.current.account_id}:secret:*"]
  }
  statement {
    actions   = ["lambda:InvokeFunction"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "lambda_vpc_inline" {
  name   = "lambda-vpc-inline"
  role   = aws_iam_role.lambda_vpc.id
  policy = data.aws_iam_policy_document.lambda_vpc_inline.json
}

# Step Functions state machine role
resource "aws_iam_role" "step_functions" {
  name = "step-functions-role-for-${var.env_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "states.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

data "aws_iam_policy_document" "step_functions_inline" {
  statement {
    actions   = ["logs:PutLogEvents"]
    resources = ["arn:aws:logs:*:*:*"]
  }
  statement {
    actions   = ["iam:PutResourcePolicy", "iam:PassRole"]
    resources = ["*"]
  }
  statement {
    actions   = ["lambda:InvokeFunction"]
    resources = ["*"]
  }
  statement {
    actions   = ["cloudwatch:DescribeAlarms"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "step_functions_inline" {
  name   = "step-functions-inline"
  role   = aws_iam_role.step_functions.id
  policy = data.aws_iam_policy_document.step_functions_inline.json
}

# EventBridge execution role
resource "aws_iam_role" "eventbridge_exec" {
  name = "eventbridge-exec-role-for-${var.env_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

data "aws_iam_policy_document" "eventbridge_exec_inline" {
  statement {
    actions   = ["states:StartExecution", "states:DescribeExecution"]
    resources = ["arn:aws:states:*:${data.aws_caller_identity.current.account_id}:stateMachine:*"]
    condition {
      test     = "StringEquals"
      variable = "aws:ResourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_iam_role_policy" "eventbridge_exec_inline" {
  name   = "eventbridge-exec-inline"
  role   = aws_iam_role.eventbridge_exec.id
  policy = data.aws_iam_policy_document.eventbridge_exec_inline.json
}

# Developers policy (limited MFA)
data "aws_iam_policy_document" "developers_mfa" {
  # S3 object read/write/delete and bucket listing
  statement {
    sid       = "S3Access"
    actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]
    resources = ["arn:aws:s3:::*", "arn:aws:s3:::*/*"]
  }

  # MFA-conditioned Secrets Manager read-only
  statement {
    sid       = "SecretsManagerReadOnlyWithMFA"
    actions   = ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret", "secretsmanager:ListSecrets"]
    resources = ["*"]
    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  # MFA-conditioned CloudWatch and ECS read-only
  statement {
    sid       = "CloudWatchECSReadOnlyWithMFA"
    actions   = [
      "ecs:DescribeClusters",
      "ecs:DescribeServices",
      "ecs:DescribeTaskDefinition",
      "ecs:DescribeTasks",
      "ecs:ListClusters",
      "ecs:ListServices",
      "ecs:ListTaskDefinitions",
      "ecs:ListTasks",
      "cloudwatch:DescribeAlarms",
      "cloudwatch:GetMetricData",
      "cloudwatch:GetMetricStatistics",
      "cloudwatch:ListMetrics"
    ]
    resources = ["*"]
    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  # Self-service IAM, password, MFA, access keys, SSH keys
  statement {
    sid       = "SelfServiceIAM"
    actions   = [
      "iam:ChangePassword",
      "iam:CreateLoginProfile",
      "iam:UpdateLoginProfile",
      "iam:DeleteLoginProfile",
      "iam:CreateAccessKey",
      "iam:UpdateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
      "iam:CreateSSHPublicKey",
      "iam:UploadSSHPublicKey",
      "iam:DeleteSSHPublicKey",
      "iam:GetSSHPublicKey",
      "iam:ListSSHPublicKeys",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice",
      "iam:CreateVirtualMFADevice",
      "iam:ListVirtualMFADevices",
      "iam:GetUser",
      "iam:GetAccountPasswordPolicy",
      "iam:ListAccountAliases",
      "iam:ListUsers"
    ]
    resources = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"]
    condition {
      test     = "ForAllValues:StringEquals"
      variable = "aws:username"
      values   = ["$${aws:username}"]
    }
  }

  # Explicit MFA enforcement – deny if MFA not present
  statement {
    sid       = "DenyAllUnlessMFA"
    effect    = "Deny"
    actions   = ["*"]
    resources = ["*"]
    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }
}

resource "aws_iam_policy" "developers_mfa" {
  name        = "developers-policy-limited-mfa"
  description = "Policy for developers with MFA enforcement"
  policy      = data.aws_iam_policy_document.developers_mfa.json
}

# Billing policy (limited MFA)
data "aws_iam_policy_document" "billing_mfa" {
  # MFA-conditioned billing and cost management
  statement {
    sid       = "BillingAccessWithMFA"
    actions   = [
      "aws-portal:ViewBilling",
      "aws-portal:ModifyBilling",
      "aws-portal:ViewUsage",
      "aws-portal:ModifyPaymentMethods",
      "budgets:ViewBudget",
      "budgets:ModifyBudget",
      "ce:GetCostAndUsage",
      "ce:GetDimensionValues",
      "ce:GetReservationUtilization",
      "ce:GetTags",
      "payments:CreatePayment",
      "payments:UpdatePayment",
      "payments:GetPaymentStatus",
      "tax:GetTaxRegistration",
      "tax:UpdateTaxRegistration"
    ]
    resources = ["*"]
    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  # Self-service MFA and password management (same as developers)
  statement {
    sid       = "SelfServiceMFAAndPassword"
    actions   = [
      "iam:ChangePassword",
      "iam:CreateLoginProfile",
      "iam:UpdateLoginProfile",
      "iam:DeleteLoginProfile",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice",
      "iam:CreateVirtualMFADevice",
      "iam:ListVirtualMFADevices",
      "iam:GetUser",
      "iam:GetAccountPasswordPolicy",
      "iam:ListAccountAliases",
      "iam:ListUsers"
    ]
    resources = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"]
    condition {
      test     = "ForAllValues:StringEquals"
      variable = "aws:username"
      values   = ["$${aws:username}"]
    }
  }
}

resource "aws_iam_policy" "billing_mfa" {
  name        = "billing-policy-limited-mfa"
  description = "Policy for billing access with MFA enforcement"
  policy      = data.aws_iam_policy_document.billing_mfa.json
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.0.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-2"
}

variable "config" {
  description = "YAML configuration string for pipeline definitions"
  type        = string
  default     = <<-EOT
artifact_bucket_name: "my-pipeline-artifacts"
build_cache_bucket_name: "my-pipeline-cache"
create_default_role: true
connections:
  github-conn:
    provider_type: "GitHub"
  bitbucket-conn:
    provider_type: "Bitbucket"
pipelines:
  pipeline1:
    source:
      provider: "CodeStar"
      connection_name: "github-conn"
      repository: "my-org/my-repo"
      branch: "main"
    stages:
      - name: "Build"
        actions:
          - name: "BuildApp"
            provider: "CodeBuild"
            project_name: "my-build-project"
            input_artifacts: ["SourceArtifact"]
            output_artifacts: ["BuildArtifact"]
    triggers:
      - type: "Cron"
        expression: "rate(1 day)"
  pipeline2:
    source:
      provider: "CodeCommit"
      repository_name: "my-codecommit-repo"
      branch: "main"
    stages:
      - name: "Approve"
        actions:
          - name: "ManualApproval"
            provider: "Manual"
    triggers:
      - type: "CodeCommitBranch"
        branch: "main"
      - type: "CodeCommitTag"
        tag: "v1.0"
EOT
}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

locals {
  config_map = yamldecode(var.config)

  base_artifact_bucket_name    = local.config_map["artifact_bucket_name"]
  base_build_cache_bucket_name = local.config_map["build_cache_bucket_name"]
  artifact_bucket_name         = "${local.base_artifact_bucket_name}-${random_id.bucket_suffix.hex}"
  build_cache_bucket_name      = "${local.base_build_cache_bucket_name}-${random_id.bucket_suffix.hex}"
  create_default_role          = try(local.config_map["create_default_role"], false)
  connections                  = try(local.config_map["connections"], {})
  pipelines                    = try(local.config_map["pipelines"], {})

  # Flatten triggers for EventBridge rules
  triggers = flatten([
    for p_name, p_config in local.pipelines : [
      for idx, trigger in try(p_config["triggers"], []) : {
        pipeline_name   = p_name
        trigger_index   = idx
        trigger_type    = trigger["type"]
        branch          = try(trigger["branch"], null)
        tag             = try(trigger["tag"], null)
        expression      = try(trigger["expression"], null)
        event_pattern   = try(trigger["event_pattern"], null)
        source_provider = try(p_config["source"]["provider"], null)
        repo_name       = try(p_config["source"]["repository_name"], null)
      }
    ]
  ])

  # Common tags
  tags = {
    Environment = "pipeline-framework"
    ManagedBy   = "Terraform"
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# KMS Key for S3 Encryption
# ------------------------------------------------------------------------------
resource "aws_kms_key" "s3" {
  description             = "Customer-managed key for S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = merge(local.tags, { Name = "S3EncryptionKey" })
}

resource "aws_kms_alias" "s3" {
  name          = "alias/s3-encryption-key"
  target_key_id = aws_kms_key.s3.key_id
}

# ------------------------------------------------------------------------------
# S3 Artifact Bucket
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "artifacts" {
  bucket        = local.artifact_bucket_name
  force_destroy = false
  tags          = merge(local.tags, { Name = "ArtifactBucket" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# S3 Build Cache Bucket
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "build_cache" {
  bucket        = local.build_cache_bucket_name
  force_destroy = false
  tags          = merge(local.tags, { Name = "BuildCacheBucket" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# CodeStar Connections (Bitbucket, GitHub, GitHub Enterprise Server)
# ------------------------------------------------------------------------------
resource "aws_codestarconnections_connection" "this" {
  for_each = local.connections

  name          = each.key
  provider_type = each.value["provider_type"]
  host_arn      = try(each.value["host_arn"], null)
  tags          = local.tags
}

# ------------------------------------------------------------------------------
# CodeCommit Repositories (if used as pipeline source)
# ------------------------------------------------------------------------------
resource "aws_codecommit_repository" "this" {
  for_each = {
    for p_name, p_config in local.pipelines :
    p_name => p_config["source"]
    if try(p_config["source"]["provider"], "") == "CodeCommit"
  }

  repository_name = each.value["repository_name"]
  default_branch  = try(each.value["branch"], "main")
  description     = "CodeCommit repository for pipeline ${each.key}"
  tags            = merge(local.tags, { PipelineName = each.key })
}

# ------------------------------------------------------------------------------
# Default CodePipeline IAM Role (optional, path /terraforest/)
# ------------------------------------------------------------------------------
resource "aws_iam_role" "codepipeline_default" {
  count = local.create_default_role ? 1 : 0

  name = "CodePipelineDefaultRole"
  path = "/terraforest/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codepipeline.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = merge(local.tags, { Role = "CodePipelineDefault" })
}

resource "aws_iam_role_policy_attachment" "codepipeline_default" {
  count = local.create_default_role ? 1 : 0

  role       = aws_iam_role.codepipeline_default[0].name
  policy_arn = aws_iam_policy.codepipeline_default[0].arn
}

resource "aws_iam_policy" "codepipeline_default" {
  count = local.create_default_role ? 1 : 0

  name        = "CodePipelineDefaultPolicy"
  path        = "/terraforest/"
  description = "Policy for default CodePipeline role allowing CodeCommit, CodeBuild, and ECR actions"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeCommit"
        Effect = "Allow"
        Action = [
          "codecommit:GetBranch",
          "codecommit:GetCommit",
          "codecommit:UploadArchive",
          "codecommit:GetUploadArchiveStatus",
          "codecommit:CancelUploadArchive"
        ]
        Resource = "arn:aws:codecommit:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:*"
      },
      {
        Sid    = "CodeBuild"
        Effect = "Allow"
        Action = [
          "codebuild:StartBuild",
          "codebuild:StopBuild",
          "codebuild:RetryBuild",
          "codebuild:BatchGetBuilds",
          "codebuild:DescribeCodeCoverages"
        ]
        Resource = "arn:aws:codebuild:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:project/*"
      },
      {
        Sid    = "ECR"
        Effect = "Allow"
        Action = [
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:BatchCheckLayerAvailability",
          "ecr:PutImage",
          "ecr:InitiateLayerUpload",
          "ecr:UploadLayerPart",
          "ecr:CompleteLayerUpload"
        ]
        Resource = "arn:aws:ecr:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:repository/*"
      }
    ]
  })
  tags = merge(local.tags, { Policy = "CodePipelineDefault" })
}

# ------------------------------------------------------------------------------
# CodePipelines
# ------------------------------------------------------------------------------
resource "aws_codepipeline" "this" {
  for_each = local.pipelines

  name     = each.key
  role_arn = try(aws_iam_role.codepipeline_default[0].arn, null)  # Use default role if created, else must be provided externally

  artifact_store {
    location = aws_s3_bucket.artifacts.id
    type     = "S3"
  }

  # Source stage (first stage)
  stage {
    name = "Source"
    action {
      name = "Source"
      # Determine provider-specific configuration
      provider = lookup({
        CodeCommit = "CodeCommit"
        S3         = "S3"
        ECR        = "ECR"
        CodeStar   = "CodeStarSourceConnection"
      }, each.value["source"]["provider"], "CodeCommit")

      category = "Source"
      owner    = "AWS"

      version         = "1"
      output_artifacts = ["SourceArtifact"]

      configuration = merge(
        {
          BranchName = try(each.value["source"]["branch"], "main")
        },
        each.value["source"]["provider"] == "CodeStar" ? {
          ConnectionArn    = aws_codestarconnections_connection.this[each.value["source"]["connection_name"]].arn
          FullRepositoryId = each.value["source"]["repository"]
        } : {},
        each.value["source"]["provider"] == "CodeCommit" ? {
          RepositoryName = each.value["source"]["repository_name"]
        } : {}
      )
    }
  }

  # Dynamic stages (excluding the first source stage)
  dynamic "stage" {
    for_each = [for s in each.value["stages"] : s]

    content {
      name = stage.value["name"]

      dynamic "action" {
        for_each = stage.value["actions"]

        content {
          name     = action.value["name"]
          owner    = try(action.value["owner"], "AWS")
          version  = try(action.value["version"], "1")
          category = try(action.value["category"], lookup({
            CodeBuild = "Build"
            Manual    = "Approval"
            Lambda    = "Invoke"
          }, action.value["provider"], "Build"))
          provider = action.value["provider"]
          configuration = merge(
            {
              ProjectName = try(action.value["project_name"], null)
            },
            try(action.value["input_artifacts"], null) != null ? { InputArtifacts = join(",", action.value["input_artifacts"]) } : {},
            try(action.value["output_artifacts"], null) != null ? { OutputArtifacts = join(",", action.value["output_artifacts"]) } : {},
            try(action.value["function_name"], null) != null ? { FunctionName = action.value["function_name"] } : {}
          )
          input_artifacts  = try(action.value["input_artifacts"], null)
          output_artifacts = try(action.value["output_artifacts"], null)
          run_order        = try(action.value["run_order"], null)
        }
      }
    }
  }

  tags = merge(local.tags, { PipelineName = each.key })
}

# ------------------------------------------------------------------------------
# IAM Roles for EventBridge (terrabits-<pipeline_name>)
# ------------------------------------------------------------------------------
resource "aws_iam_role" "eventbridge_pipeline" {
  for_each = local.pipelines

  name = "terrabits-${each.key}"
  path = "/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = merge(local.tags, { PipelineName = each.key, Role = "EventBridgeTarget" })
}

resource "aws_iam_role_policy" "eventbridge_pipeline" {
  for_each = local.pipelines

  name = "terrabits-${each.key}-policy"
  role = aws_iam_role.eventbridge_pipeline[each.key].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "codepipeline:StartPipelineExecution"
        Resource = aws_codepipeline.this[each.key].arn
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# EventBridge Rules and Targets
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_event_rule" "pipeline_trigger" {
  for_each = {
    for t in local.triggers : "${t.pipeline_name}-${t.trigger_index}" => t
  }

  name          = "terrabits-${each.value.pipeline_name}-trigger-${each.value.trigger_index}"
  description   = "EventBridge rule for pipeline ${each.value.pipeline_name} trigger ${each.value.trigger_index}"
  schedule_expression = each.value.trigger_type == "Cron" ? each.value.expression : null

  # Consolidated event_pattern for all trigger types
  event_pattern = (
    each.value.trigger_type == "EventPattern" ? jsonencode(each.value.event_pattern) :
    each.value.trigger_type == "CodeCommitBranch" ? jsonencode({
      source        = ["aws.codecommit"]
      detail-type   = ["CodeCommit Repository State Change"]
      resources     = [aws_codecommit_repository.this[each.value.pipeline_name].arn]
      detail = {
        referenceType  = ["branch"]
        referenceName  = [each.value.branch]
      }
    }) :
    each.value.trigger_type == "CodeCommitTag" ? jsonencode({
      source        = ["aws.codecommit"]
      detail-type   = ["CodeCommit Repository State Change"]
      resources     = [aws_codecommit_repository.this[each.value.pipeline_name].arn]
      detail = {
        referenceType  = ["tag"]
        referenceName  = [each.value.tag]
      }
    }) :
    null
  )

  tags = merge(local.tags, { PipelineName = each.value.pipeline_name })
}

resource "aws_cloudwatch_event_target" "pipeline_trigger" {
  for_each = {
    for t in local.triggers : "${t.pipeline_name}-${t.trigger_index}" => t
  }

  rule      = aws_cloudwatch_event_rule.pipeline_trigger[each.key].name
  target_id = "CodePipelineTarget"
  arn       = aws_codepipeline.this[each.value.pipeline_name].arn
  role_arn  = aws_iam_role.eventbridge_pipeline[each.value.pipeline_name].arn
}

# ------------------------------------------------------------------------------
# Lifecycle rules for stateful resources (S3 buckets)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id
  rule {
    id     = "expire-old-versions"
    status = "Enabled"
    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id
  rule {
    id     = "expire-old-versions"
    status = "Enabled"
    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.80.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_id" {
  description = "VPC ID for deploying Transfer server and EFS mount targets. If empty, server is PUBLIC and no mount targets are created."
  type        = string
  default     = ""
}

variable "subnet_ids" {
  description = "List of subnet IDs for EFS mount targets and Transfer VPC endpoint. Required when vpc_id is provided."
  type        = list(string)
  default     = []
}

variable "server_name" {
  description = "Name for the Transfer server, used as prefix for IAM role and logging."
  type        = string
  default     = "sftp-server"
}

variable "is_public" {
  description = "Whether to allocate Elastic IPs and make Transfer server publicly accessible when using VPC endpoint type."
  type        = bool
  default     = false
}

variable "logging_enabled" {
  description = "Enable CloudWatch logging for Transfer server."
  type        = bool
  default     = false
}

variable "efs_performance_mode" {
  description = "EFS file system performance mode."
  type        = string
  default     = "generalPurpose"
}

variable "kms_key_id" {
  description = "KMS key ID for EFS encryption. If null, uses AWS managed key."
  type        = string
  default     = null
}

variable "sftp_users" {
  description = "Map of SFTP users. Each key is the username."
  type = map(object({
    uid              = number
    gid              = number
    home_directory   = string
    restricted       = bool
    ssh_public_key   = string
    role_arn         = optional(string)
  }))
  default = {}
}

variable "additional_access_points" {
  description = "Map of additional EFS access points. Keys are access point names."
  type = map(object({
    path = string
    uid  = number
    gid  = number
  }))
  default = {}
}

variable "sftp_security_group_rules" {
  description = "Security group rules for the SFTP interface."
  type = list(object({
    type        = string
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
    description = optional(string)
  }))
  default = [
    {
      type        = "ingress"
      from_port   = 22
      to_port     = 22
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
      description = "SFTP access"
    }
  ]
}

variable "efs_security_group_rules" {
  description = "Security group rules for the EFS mount targets."
  type = list(object({
    type        = string
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
    description = optional(string)
  }))
  default = [
    {
      type        = "ingress"
      from_port   = 2049
      to_port     = 2049
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
      description = "NFS access"
    }
  ]
}

locals {
  create_vpc_resources = var.vpc_id != ""
  use_generated_role   = length(var.sftp_users) > 0 && anytrue([for u in var.sftp_users : u.role_arn == null || u.role_arn == ""])
}

resource "aws_efs_file_system" "this" {
  creation_token   = var.server_name
  performance_mode = var.efs_performance_mode
  throughput_mode  = "bursting"
  encrypted        = true
  kms_key_id       = var.kms_key_id

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = var.server_name
  }
}

resource "aws_efs_mount_target" "this" {
  count = local.create_vpc_resources ? length(var.subnet_ids) : 0

  file_system_id = aws_efs_file_system.this.id
  subnet_id      = var.subnet_ids[count.index]
  security_groups = [aws_security_group.efs[0].id]
}

resource "aws_efs_access_point" "sftp_users" {
  for_each = var.sftp_users

  file_system_id = aws_efs_file_system.this.id
  posix_user {
    uid = each.value.uid
    gid = each.value.gid
  }
  root_directory {
    path = each.value.home_directory
    creation_info {
      owner_uid   = each.value.uid
      owner_gid   = each.value.gid
      permissions = "0755"
    }
  }
}

resource "aws_efs_access_point" "additional" {
  for_each = var.additional_access_points

  file_system_id = aws_efs_file_system.this.id
  posix_user {
    uid = each.value.uid
    gid = each.value.gid
  }
  root_directory {
    path = each.value.path
    creation_info {
      owner_uid   = each.value.uid
      owner_gid   = each.value.gid
      permissions = "0755"
    }
  }
}

resource "aws_security_group" "sftp" {
  count       = local.create_vpc_resources ? 1 : 0
  name        = "${var.server_name}-sftp"
  description = "Security group for Transfer SFTP server"
  vpc_id      = var.vpc_id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  dynamic "ingress" {
    for_each = var.sftp_security_group_rules
    content {
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
      description = lookup(ingress.value, "description", null)
    }
  }

  tags = {
    Name = "${var.server_name}-sftp"
  }
}

resource "aws_security_group" "efs" {
  count       = local.create_vpc_resources ? 1 : 0
  name        = "${var.server_name}-efs"
  description = "Security group for EFS mount targets"
  vpc_id      = var.vpc_id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  dynamic "ingress" {
    for_each = var.efs_security_group_rules
    content {
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
      description = lookup(ingress.value, "description", null)
    }
  }

  tags = {
    Name = "${var.server_name}-efs"
  }
}

resource "aws_transfer_server" "this" {
  identity_provider_type = "SERVICE_MANAGED"
  domain                 = "EFS"
  security_policy_name   = "TransferSecurityPolicy-2023-05"
  endpoint_type          = local.create_vpc_resources ? "VPC" : "PUBLIC"
  logging_role           = var.logging_enabled ? aws_iam_role.logging[0].arn : null

  dynamic "endpoint_details" {
    for_each = local.create_vpc_resources ? [1] : []
    content {
      vpc_id             = var.vpc_id
      subnet_ids         = var.subnet_ids
      address_allocation_ids = var.is_public ? aws_eip.transfer[*].id : []
      security_group_ids = [aws_security_group.sftp[0].id]
    }
  }

  tags = {
    Name = var.server_name
  }
}

resource "aws_eip" "transfer" {
  count  = (local.create_vpc_resources && var.is_public) ? length(var.subnet_ids) : 0
  domain = "vpc"

  tags = {
    Name = "${var.server_name}-eip-${count.index}"
  }
}

# IAM role for Transfer server if any user does not provide a role_arn
resource "aws_iam_role" "transfer" {
  count = local.use_generated_role ? 1 : 0
  name  = "${var.server_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "transfer_efs_access" {
  count       = local.use_generated_role ? 1 : 0
  name        = "${var.server_name}-efs-access"
  description = "Allow Transfer server to mount and write to EFS file system"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite"
        ]
        Resource = aws_efs_file_system.this.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "transfer_efs_access" {
  count      = local.use_generated_role ? 1 : 0
  role       = aws_iam_role.transfer[0].name
  policy_arn = aws_iam_policy.transfer_efs_access[0].arn
}

# CloudWatch logging role
resource "aws_cloudwatch_log_group" "transfer" {
  count = var.logging_enabled ? 1 : 0
  name  = "/aws/transfer/${var.server_name}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "logging" {
  count = var.logging_enabled ? 1 : 0
  name  = "${var.server_name}-logging"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "logging" {
  count       = var.logging_enabled ? 1 : 0
  name        = "${var.server_name}-logging-policy"
  description = "Allow Transfer server to write logs to CloudWatch"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.transfer[0].arn}:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "logging" {
  count      = var.logging_enabled ? 1 : 0
  role       = aws_iam_role.logging[0].name
  policy_arn = aws_iam_policy.logging[0].arn
}

# Transfer users
resource "aws_transfer_user" "this" {
  for_each = var.sftp_users

  server_id      = aws_transfer_server.this.id
  user_name      = each.key
  role           = each.value.role_arn != null && each.value.role_arn != "" ? each.value.role_arn : (local.use_generated_role ? aws_iam_role.transfer[0].arn : null)
  home_directory_type = each.value.restricted ? "PATH" : "LOGICAL"
  home_directory  = each.value.restricted ? aws_efs_access_point.sftp_users[each.key].id : "/${each.key}"

  posix_profile {
    uid = each.value.uid
    gid = each.value.gid
  }
}

resource "aws_transfer_ssh_key" "this" {
  for_each = var.sftp_users

  server_id = aws_transfer_server.this.id
  user_name = aws_transfer_user.this[each.key].user_name
  body      = each.value.ssh_public_key
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region (default, used for data sources)"
  type        = string
  default     = "us-east-1"
}

# ------------------------------------------------------------------------------
# Core toggle variables
# ------------------------------------------------------------------------------
variable "create_bucket" {
  description = "Whether to create the S3 bucket"
  type        = bool
  default     = true
}

variable "create_kms_key" {
  description = "Whether to create the customer-managed KMS key for SSE-KMS"
  type        = bool
  default     = true
}

# ------------------------------------------------------------------------------
# Bucket naming
# ------------------------------------------------------------------------------
variable "bucket_name" {
  description = "Explicit bucket name (overrides auto-generated name)"
  type        = string
  default     = ""
}

variable "bucket_name_prefix" {
  description = "Prefix for auto-generated bucket name"
  type        = string
  default     = ""
}

# ------------------------------------------------------------------------------
# Bucket configuration variables
# ------------------------------------------------------------------------------
variable "force_destroy" {
  description = "Allow bucket deletion with non-empty contents"
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags to apply to the bucket and KMS key"
  type        = map(string)
  default     = {}
}

variable "acl" {
  description = "Canned ACL to apply (e.g., private, public-read)"
  type        = string
  default     = null
}

variable "grants" {
  description = "List of grant blocks (uri, type, permissions)"
  type = list(object({
    uri         = string
    type        = string
    permissions = list(string)
  }))
  default = []
}

variable "versioning" {
  description = "Versioning configuration (enabled, mfa_delete)"
  type = object({
    enabled    = optional(bool, false)
    mfa_delete = optional(bool, false)
  })
  default = null
}

variable "logging" {
  description = "Access logging configuration (target_bucket, target_prefix)"
  type = object({
    target_bucket = string
    target_prefix = optional(string, "")
  })
  default = null
}

variable "acceleration_status" {
  description = "Transfer acceleration status (Enabled or Suspended)"
  type        = string
  default     = null
}

variable "request_payer" {
  description = "Requester pays (BucketOwner or Requester)"
  type        = string
  default     = null
}

variable "website" {
  description = "Static website hosting configuration (index_document, error_document, redirect_all_requests_to)"
  type = object({
    index_document           = optional(string)
    error_document           = optional(string)
    redirect_all_requests_to = optional(string)
  })
  default = null
}

variable "cors_rules" {
  description = "List of CORS rules"
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rule configurations"
  type = list(object({
    id      = optional(string)
    status  = string
    filter  = optional(object({
      prefix = optional(string)
    }))
    transition = optional(list(object({
      days          = optional(number)
      date          = optional(string)
      storage_class = string
    })))
    expiration = optional(object({
      days                         = optional(number)
      date                         = optional(string)
      expired_object_delete_marker = optional(bool)
    }))
    noncurrent_version_transition = optional(list(object({
      days          = number
      storage_class = string
    })))
    noncurrent_version_expiration = optional(object({
      days = number
    }))
    abort_incomplete_multipart_upload_days = optional(number)
  }))
  default = []
}

variable "replication_configuration" {
  description = "Cross-region replication configuration"
  type = any
  default = null
}

variable "intelligent_tiering" {
  description = "Intelligent tiering configuration"
  type = any
  default = null
}

variable "object_lock_configuration" {
  description = "Object lock configuration (default retention)"
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  default = null
}

variable "enable_object_ownership" {
  description = "Enable object ownership controls"
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership rule (e.g., ObjectWriter, BucketOwnerPreferred)"
  type        = string
  default     = "ObjectWriter"
}

variable "server_side_encryption_configuration" {
  description = "Override default SSE configuration (list of rule objects)"
  type = list(object({
    apply_server_side_encryption_by_default = object({
      sse_algorithm     = string
      kms_master_key_id = optional(string)
    })
    bucket_key_enabled = optional(bool)
  }))
  default = null
}

# ------------------------------------------------------------------------------
# Bucket policy toggles
# ------------------------------------------------------------------------------
variable "enable_elb_log_delivery" {
  description = "Grant ELB (classic) access log delivery to the bucket"
  type        = bool
  default     = false
}

variable "enable_alb_log_delivery" {
  description = "Grant ALB/NLB access log delivery to the bucket"
  type        = bool
  default     = false
}

variable "deny_insecure_transport" {
  description = "Deny requests without secure transport"
  type        = bool
  default     = false
}

variable "deny_tls_below_1_2" {
  description = "Deny requests using TLS versions older than 1.2"
  type        = bool
  default     = false
}

variable "attach_policy_json" {
  description = "User-supplied JSON policy to merge into the bucket policy"
  type        = string
  default     = ""
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------
locals {
  # Determine if any bucket policy statement is needed
  create_policy = var.enable_elb_log_delivery || var.enable_alb_log_delivery || var.deny_insecure_transport || var.deny_tls_below_1_2 || var.attach_policy_json != ""

  # Bucket name construction
  bucket_name = (
    var.bucket_name != "" ? var.bucket_name :
    var.bucket_name_prefix != "" ? "${var.bucket_name_prefix}${random_id.suffix.hex}" :
    "s3-bucket-${random_id.suffix.hex}"
  )

  # Default SSE configuration using KMS key (if created) or AES256
  default_sse_config = var.create_kms_key ? [
    {
      apply_server_side_encryption_by_default = {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = aws_kms_key.this[0].arn
      }
      bucket_key_enabled = false
    }
  ] : [
    {
      apply_server_side_encryption_by_default = {
        sse_algorithm     = "AES256"
        kms_master_key_id = null
      }
      bucket_key_enabled = false
    }
  ]

  # Effective SSE configuration: user-supplied or default
  sse_config = var.server_side_encryption_configuration != null ? var.server_side_encryption_configuration : local.default_sse_config
}

# ------------------------------------------------------------------------------
# Data sources
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

# Unified ELB service account – used for both classic ELB and ALB/NLB
data "aws_elb_service_account" "main" {
  count = (var.enable_elb_log_delivery || var.enable_alb_log_delivery) ? 1 : 0
}

# ------------------------------------------------------------------------------
# Random suffix for auto-generated bucket name
# ------------------------------------------------------------------------------
resource "random_id" "suffix" {
  byte_length = 8
}

# ------------------------------------------------------------------------------
# KMS Key (optional)
# ------------------------------------------------------------------------------
resource "aws_kms_key" "this" {
  count = var.create_kms_key ? 1 : 0

  description             = "S3 bucket encryption key"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
  tags = var.tags
}

resource "aws_kms_alias" "this" {
  count = var.create_kms_key ? 1 : 0

  name          = "alias/s3-bucket-${random_id.suffix.hex}"
  target_key_id = aws_kms_key.this[0].key_id
}

# ------------------------------------------------------------------------------
# S3 Bucket (optional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "this" {
  count = var.create_bucket ? 1 : 0

  bucket = local.bucket_name
  force_destroy = var.force_destroy

  # Object lock configuration (optional)
  dynamic "object_lock_configuration" {
    for_each = var.object_lock_configuration != null ? [var.object_lock_configuration] : []
    content {
      object_lock_enabled = "Enabled"
      rule {
        default_retention {
          mode = object_lock_configuration.value.mode
          days = object_lock_configuration.value.days
          years = object_lock_configuration.value.years
        }
      }
    }
  }

  tags = var.tags

  # Note: lifecycle block removed because prevent_destroy cannot be dynamic
}

# ------------------------------------------------------------------------------
# Bucket-level resources (separate resources for new AWS provider)
# ------------------------------------------------------------------------------

# Public Access Block
resource "aws_s3_bucket_public_access_block" "this" {
  count = var.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true

  depends_on = [aws_s3_bucket_policy.this]
}

# Server-side encryption configuration
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = var.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = local.sse_config
    content {
      apply_server_side_encryption_by_default {
        sse_algorithm     = rule.value.apply_server_side_encryption_by_default.sse_algorithm
        kms_master_key_id = rule.value.apply_server_side_encryption_by_default.kms_master_key_id
      }
      bucket_key_enabled = rule.value.bucket_key_enabled
    }
  }
}

# ACL (canned)
resource "aws_s3_bucket_acl" "this" {
  count = var.create_bucket && var.acl != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  acl    = var.acl
}

# ACL (explicit grants)
resource "aws_s3_bucket_acl" "grants" {
  count = var.create_bucket && length(var.grants) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "access_control_policy" {
    for_each = [1]
    content {
      dynamic "grant" {
        for_each = var.grants
        content {
          grantee {
            type = grant.value.type
            uri  = grant.value.uri
          }
          permission = grant.value.permissions
        }
      }
      owner {
        id = data.aws_caller_identity.current.account_id
      }
    }
  }
}

# Versioning
resource "aws_s3_bucket_versioning" "this" {
  count = var.create_bucket && var.versioning != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status     = var.versioning.enabled ? "Enabled" : "Suspended"
    mfa_delete = var.versioning.mfa_delete ? "Enabled" : "Disabled"
  }
}

# Logging
resource "aws_s3_bucket_logging" "this" {
  count = var.create_bucket && var.logging != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  target_bucket = var.logging.target_bucket
  target_prefix = var.logging.target_prefix
}

# Transfer acceleration
resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.create_bucket && var.acceleration_status != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  status = var.acceleration_status
}

# Requester pays
resource "aws_s3_bucket_request_payment_configuration" "this" {
  count = var.create_bucket && var.request_payer != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  payer  = var.request_payer
}

# Static website hosting (no routing_rules)
resource "aws_s3_bucket_website_configuration" "this" {
  count = var.create_bucket && var.website != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "index_document" {
    for_each = var.website.index_document != null ? [var.website.index_document] : []
    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = var.website.error_document != null ? [var.website.error_document] : []
    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = var.website.redirect_all_requests_to != null ? [var.website.redirect_all_requests_to] : []
    content {
      host_name = redirect_all_requests_to.value
    }
  }
}

# CORS rules
resource "aws_s3_bucket_cors_configuration" "this" {
  count = var.create_bucket && length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# Lifecycle rules (filter only supports prefix)
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = var.create_bucket && length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = filter.value.prefix
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          days                         = expiration.value.days
          date                         = expiration.value.date
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = rule.value.transition != null ? rule.value.transition : []
        content {
          days          = transition.value.days
          date          = transition.value.date
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition != null ? rule.value.noncurrent_version_transition : []
        content {
          noncurrent_days = noncurrent_version_transition.value.days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [rule.value.abort_incomplete_multipart_upload_days] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }
    }
  }
}

# Replication configuration
resource "aws_s3_bucket_replication_configuration" "this" {
  count = var.create_bucket && var.replication_configuration != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  role   = var.replication_configuration.role

  dynamic "rule" {
    for_each = var.replication_configuration.rules
    content {
      id       = rule.value.id
      status   = rule.value.status
      priority = rule.value.priority

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = lookup(filter.value, "prefix", null)
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = lookup(rule.value.destination, "storage_class", null)
        account       = lookup(rule.value.destination, "account_id", null)

        dynamic "encryption_configuration" {
          for_each = lookup(rule.value.destination, "replica_kms_key_id", null) != null ? [1] : []
          content {
            replica_kms_key_id = rule.value.destination.replica_kms_key_id
          }
        }

        dynamic "access_control_translation" {
          for_each = lookup(rule.value.destination, "access_control_translation", null) != null ? [rule.value.destination.access_control_translation] : []
          content {
            owner = access_control_translation.value.owner
          }
        }
      }

      delete_marker_replication {
        status = rule.value.delete_marker_replication.status
      }
    }
  }
}

# Intelligent tiering configuration (filter only supports prefix)
resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  count = var.create_bucket && var.intelligent_tiering != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  name   = var.intelligent_tiering.name

  dynamic "filter" {
    for_each = var.intelligent_tiering.filter != null ? [var.intelligent_tiering.filter] : []
    content {
      prefix = lookup(filter.value, "prefix", null)
    }
  }

  tiering {
    access_tier = "ARCHIVE_ACCESS"
    days        = var.intelligent_tiering.archive_access_days
  }

  tiering {
    access_tier = "DEEP_ARCHIVE_ACCESS"
    days        = var.intelligent_tiering.deep_archive_access_days
  }
}

# Object ownership controls
resource "aws_s3_bucket_ownership_controls" "this" {
  count = var.create_bucket && var.enable_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }

  depends_on = [aws_s3_bucket_policy.this]
}

# ------------------------------------------------------------------------------
# Bucket policy (conditional data sources and combined policy)
# ------------------------------------------------------------------------------

# ELB log delivery policy statement (used for both classic ELB and ALB/NLB)
data "aws_iam_policy_document" "elb_log_delivery" {
  count = var.create_bucket && var.enable_elb_log_delivery ? 1 : 0

  statement {
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.this[0].arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"]

    principals {
      type        = "AWS"
      identifiers = [data.aws_elb_service_account.main[0].arn]
    }
  }
}

# ALB/NLB log delivery policy statement (same service account)
data "aws_iam_policy_document" "alb_log_delivery" {
  count = var.create_bucket && var.enable_alb_log_delivery ? 1 : 0

  statement {
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.this[0].arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"]

    principals {
      type        = "AWS"
      identifiers = [data.aws_elb_service_account.main[0].arn]
    }
  }
}

# Deny insecure transport
data "aws_iam_policy_document" "deny_insecure_transport" {
  count = var.create_bucket && var.deny_insecure_transport ? 1 : 0

  statement {
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.this[0].arn, "${aws_s3_bucket.this[0].arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

# Deny TLS versions below 1.2
data "aws_iam_policy_document" "deny_tls_below_1_2" {
  count = var.create_bucket && var.deny_tls_below_1_2 ? 1 : 0

  statement {
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.this[0].arn, "${aws_s3_bucket.this[0].arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }
}

# Combined bucket policy
data "aws_iam_policy_document" "combined" {
  count = var.create_bucket && local.create_policy ? 1 : 0

  source_policy_documents = compact(
    concat(
      var.enable_elb_log_delivery ? [data.aws_iam_policy_document.elb_log_delivery[0].json] : [],
      var.enable_alb_log_delivery ? [data.aws_iam_policy_document.alb_log_delivery[0].json] : [],
      var.deny_insecure_transport ? [data.aws_iam_policy_document.deny_insecure_transport[0].json] : [],
      var.deny_tls_below_1_2 ? [data.aws_iam_policy_document.deny_tls_below_1_2[0].json] : [],
      var.attach_policy_json != "" ? [var.attach_policy_json] : []
    )
  )
}

resource "aws_s3_bucket_policy" "this" {
  count = var.create_bucket && local.create_policy ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined[0].json
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "bucket_id" {
  description = "The name of the S3 bucket"
  value       = var.create_bucket ? aws_s3_bucket.this[0].id : null
}

output "bucket_arn" {
  description = "The ARN of the S3 bucket"
  value       = var.create_bucket ? aws_s3_bucket.this[0].arn : null
}

output "bucket_domain_name" {
  description = "The bucket domain name"
  value       = var.create_bucket ? aws_s3_bucket.this[0].bucket_domain_name : null
}

output "kms_key_arn" {
  description = "The ARN of the KMS key (if created)"
  value       = var.create_kms_key ? aws_kms_key.this[0].arn : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.99.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "target_stack" {
  type    = string
  default = "benchmark"
}

variable "stack_githash" {
  type    = string
  default = "benchmark0000"
}

variable "stack_githash_long" {
  type    = string
  default = "benchmark0000000000000000000000000000000000"
}

variable "stack_s3_bucket" {
  type    = string
  default = "benchmark-stack-bucket"
}

variable "dataset_s3_object_key" {
  type    = string
  default = "dataset.csv"
}

variable "destigmatized_dataset_s3_object_key" {
  type    = string
  default = "destigmatized_dataset.csv"
}

variable "genomic_dataset_s3_object_key" {
  type    = string
  default = "genomic_dataset.csv"
}

locals {
  role_prefixes = [
    "wildfly-deployment-s3",
    "httpd-deployment-s3",
    "auth-hpds-deployment-s3",
    "open-hpds-deployment-s3",
    "dictionary-deployment-s3",
  ]

  role_names = {
    for p in local.role_prefixes : p => "${p}-${var.target_stack}-${var.stack_githash}"
  }

  dataset_keys = [
    var.dataset_s3_object_key,
    var.destigmatized_dataset_s3_object_key,
    var.genomic_dataset_s3_object_key,
  ]
}

# Random suffix for globally unique S3 bucket name
resource "random_id" "suffix" {
  byte_length = 4
}

# KMS customer managed key for S3 encryption
resource "aws_kms_key" "s3" {
  description             = "CMK for S3 bucket ${var.stack_s3_bucket}"
  key_usage               = "ENCRYPT_DECRYPT"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  is_enabled              = true
}

# S3 bucket for deployment artifacts, configs, certificates, and datasets
resource "aws_s3_bucket" "deployment" {
  bucket        = "${var.stack_s3_bucket}-${random_id.suffix.hex}"
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
  tags = {
    StackGitHashLong = var.stack_githash_long
  }
}

resource "aws_s3_bucket_public_access_block" "deployment" {
  bucket = aws_s3_bucket.deployment.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "deployment" {
  bucket = aws_s3_bucket.deployment.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "deployment" {
  bucket = aws_s3_bucket.deployment.id

  versioning_configuration {
    status = "Enabled"
  }
}

# IAM roles and instance profiles for EC2 microservices
resource "aws_iam_role" "ec2" {
  for_each = toset(local.role_prefixes)
  name     = local.role_names[each.key]

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "sts:AssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    StackGitHashLong = var.stack_githash_long
  }
}

resource "aws_iam_instance_profile" "ec2" {
  for_each = toset(local.role_prefixes)
  name     = local.role_names[each.key]
  role     = aws_iam_role.ec2[each.key].name
}

# Attach AWS managed policies
resource "aws_iam_role_policy_attachment" "cloudwatch" {
  for_each   = toset(local.role_prefixes)
  role       = aws_iam_role.ec2[each.key].name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "ssm" {
  for_each   = toset(local.role_prefixes)
  role       = aws_iam_role.ec2[each.key].name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# Inline policies with least‑privilege S3, EC2 tagging, and CloudWatch permissions
resource "aws_iam_role_policy" "inline" {
  for_each = toset(local.role_prefixes)
  name     = "inline-${local.role_names[each.key]}"
  role     = aws_iam_role.ec2[each.key].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Effect   = "Allow"
          Action   = "ec2:CreateTags"
          Resource = "arn:aws:ec2:*:*:instance/*"
        },
        {
          Effect   = "Allow"
          Action   = "cloudwatch:PutMetricData"
          Resource = "*"
        },
        {
          Effect   = "Allow"
          Action   = "s3:ListBucket"
          Resource = aws_s3_bucket.deployment.arn
        },
      ],
      [
        {
          Effect   = "Allow"
          Action   = "s3:GetObject"
          Resource = concat(
            [
              "${aws_s3_bucket.deployment.arn}/artifacts/${each.key}/*",
              "${aws_s3_bucket.deployment.arn}/config/${each.key}/*",
              "${aws_s3_bucket.deployment.arn}/ssl/${each.key}/*",
              "${aws_s3_bucket.deployment.arn}/security-tools/*",
            ],
            [for key in local.dataset_keys : "${aws_s3_bucket.deployment.arn}/datasets/${key}"]
          )
        }
      ]
    )
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region (injected by deployment harness)"
  type        = string
  default     = "us-east-1"
}

variable "create_module" {
  description = "Toggle overall module creation"
  type        = bool
  default     = true
}

variable "create_new_sg" {
  description = "Toggle between creating a new security group or using an existing one"
  type        = bool
  default     = true
}

variable "vpc_id" {
  description = "VPC ID for the new security group (optional, defaults to a new custom VPC)"
  type        = string
  default     = null
}

variable "existing_sg_id" {
  description = "Existing security group ID to add rules to (required if create_new_sg is false)"
  type        = string
  default     = null
}

variable "new_sg_name" {
  description = "Name tag for the new security group"
  type        = string
  default     = "terraform-sg"
}

variable "new_sg_description" {
  description = "Description for the new security group"
  type        = string
  default     = "Managed by Terraform"
}

variable "new_sg_tags" {
  description = "Additional tags for the new security group"
  type        = map(string)
  default     = {}
}

variable "new_sg_ingress_rules" {
  description = "List of ingress rules for the new security group"
  type = list(object({
    description              = optional(string, "")
    protocol                 = string
    from_port                = number
    to_port                  = number
    cidr_blocks              = optional(list(string))
    ipv6_cidr_blocks         = optional(list(string))
    source_security_group_id = optional(string)
    prefix_list_ids          = optional(list(string))
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.new_sg_ingress_rules :
      (rule.cidr_blocks != null ? 1 : 0) +
      (rule.ipv6_cidr_blocks != null ? 1 : 0) +
      (rule.source_security_group_id != null ? 1 : 0) +
      (rule.prefix_list_ids != null ? 1 : 0) == 1
    ])
    error_message = "Each ingress rule must specify exactly one of cidr_blocks, ipv6_cidr_blocks, source_security_group_id, or prefix_list_ids."
  }
}

variable "new_sg_egress_rules" {
  description = "List of egress rules for the new security group"
  type = list(object({
    description              = optional(string, "")
    protocol                 = string
    from_port                = number
    to_port                  = number
    cidr_blocks              = optional(list(string))
    ipv6_cidr_blocks         = optional(list(string))
    source_security_group_id = optional(string)
    prefix_list_ids          = optional(list(string))
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.new_sg_egress_rules :
      (rule.cidr_blocks != null ? 1 : 0) +
      (rule.ipv6_cidr_blocks != null ? 1 : 0) +
      (rule.source_security_group_id != null ? 1 : 0) +
      (rule.prefix_list_ids != null ? 1 : 0) == 1
    ])
    error_message = "Each egress rule must specify exactly one of cidr_blocks, ipv6_cidr_blocks, source_security_group_id, or prefix_list_ids."
  }
}

variable "existing_sg_ingress_rules" {
  description = "List of ingress rules to add to the existing security group"
  type = list(object({
    description              = optional(string, "")
    protocol                 = string
    from_port                = number
    to_port                  = number
    cidr_blocks              = optional(list(string))
    ipv6_cidr_blocks         = optional(list(string))
    source_security_group_id = optional(string)
    prefix_list_ids          = optional(list(string))
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.existing_sg_ingress_rules :
      (rule.cidr_blocks != null ? 1 : 0) +
      (rule.ipv6_cidr_blocks != null ? 1 : 0) +
      (rule.source_security_group_id != null ? 1 : 0) +
      (rule.prefix_list_ids != null ? 1 : 0) == 1
    ])
    error_message = "Each ingress rule must specify exactly one of cidr_blocks, ipv6_cidr_blocks, source_security_group_id, or prefix_list_ids."
  }
}

variable "existing_sg_egress_rules" {
  description = "List of egress rules to add to the existing security group"
  type = list(object({
    description              = optional(string, "")
    protocol                 = string
    from_port                = number
    to_port                  = number
    cidr_blocks              = optional(list(string))
    ipv6_cidr_blocks         = optional(list(string))
    source_security_group_id = optional(string)
    prefix_list_ids          = optional(list(string))
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.existing_sg_egress_rules :
      (rule.cidr_blocks != null ? 1 : 0) +
      (rule.ipv6_cidr_blocks != null ? 1 : 0) +
      (rule.source_security_group_id != null ? 1 : 0) +
      (rule.prefix_list_ids != null ? 1 : 0) == 1
    ])
    error_message = "Each egress rule must specify exactly one of cidr_blocks, ipv6_cidr_blocks, source_security_group_id, or prefix_list_ids."
  }
}

variable "create_prefix_list" {
  description = "Toggle creation of a customer-managed prefix list"
  type        = bool
  default     = false
}

variable "prefix_list_name" {
  description = "Name for the prefix list"
  type        = string
  default     = "terraform-prefix-list"
}

variable "prefix_list_address_family" {
  description = "Address family for the prefix list (IPv4 or IPv6)"
  type        = string
  default     = "IPv4"
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries for the prefix list"
  type        = number
  default     = 10
}

variable "prefix_list_entries" {
  description = "List of CIDR entries for the prefix list"
  type = list(object({
    cidr        = string
    description = optional(string, "")
  }))
  default = []
}

variable "prefix_list_tags" {
  description = "Tags for the prefix list"
  type        = map(string)
  default     = {}
}

variable "existing_prefix_list_ids" {
  description = "Existing prefix list IDs to use instead of creating a new one"
  type        = list(string)
  default     = null
}

locals {
  create_new_sg_resources = var.create_module && var.create_new_sg
  use_existing_sg         = var.create_module && !var.create_new_sg
  create_prefix_list_res  = var.create_module && var.create_prefix_list && (var.existing_prefix_list_ids == null || length(var.existing_prefix_list_ids) == 0)
  vpc_id_to_use           = var.vpc_id != null ? var.vpc_id : (
    local.create_new_sg_resources && var.vpc_id == null ? aws_vpc.this[0].id : null
  )
}

# Custom VPC for the new security group when no VPC ID is provided
resource "aws_vpc" "this" {
  count = local.create_new_sg_resources && var.vpc_id == null ? 1 : 0

  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = { Name = "terraform-vpc" }
}

# New security group
resource "aws_security_group" "this" {
  count       = local.create_new_sg_resources ? 1 : 0
  name        = var.new_sg_name
  description = var.new_sg_description
  vpc_id      = local.vpc_id_to_use
  tags        = merge({ Name = var.new_sg_name }, var.new_sg_tags)

  revoke_rules_on_delete = true

  lifecycle {
    create_before_destroy = true
  }
}

# Ingress rules for new security group
resource "aws_security_group_rule" "new_sg_ingress" {
  count = local.create_new_sg_resources ? length(var.new_sg_ingress_rules) : 0

  security_group_id = aws_security_group.this[0].id
  type              = "ingress"
  description       = var.new_sg_ingress_rules[count.index].description
  protocol          = var.new_sg_ingress_rules[count.index].protocol
  from_port         = var.new_sg_ingress_rules[count.index].from_port
  to_port           = var.new_sg_ingress_rules[count.index].to_port
  cidr_blocks       = var.new_sg_ingress_rules[count.index].cidr_blocks
  ipv6_cidr_blocks  = var.new_sg_ingress_rules[count.index].ipv6_cidr_blocks
  source_security_group_id = var.new_sg_ingress_rules[count.index].source_security_group_id
  prefix_list_ids   = var.new_sg_ingress_rules[count.index].prefix_list_ids
}

# Egress rules for new security group (user-defined)
resource "aws_security_group_rule" "new_sg_egress" {
  count = local.create_new_sg_resources ? length(var.new_sg_egress_rules) : 0

  security_group_id = aws_security_group.this[0].id
  type              = "egress"
  description       = var.new_sg_egress_rules[count.index].description
  protocol          = var.new_sg_egress_rules[count.index].protocol
  from_port         = var.new_sg_egress_rules[count.index].from_port
  to_port           = var.new_sg_egress_rules[count.index].to_port
  cidr_blocks       = var.new_sg_egress_rules[count.index].cidr_blocks
  ipv6_cidr_blocks  = var.new_sg_egress_rules[count.index].ipv6_cidr_blocks
  source_security_group_id = var.new_sg_egress_rules[count.index].source_security_group_id
  prefix_list_ids   = var.new_sg_egress_rules[count.index].prefix_list_ids
}

# Ingress rules for existing security group
resource "aws_security_group_rule" "existing_sg_ingress" {
  count = local.use_existing_sg ? length(var.existing_sg_ingress_rules) : 0

  security_group_id = var.existing_sg_id
  type              = "ingress"
  description       = var.existing_sg_ingress_rules[count.index].description
  protocol          = var.existing_sg_ingress_rules[count.index].protocol
  from_port         = var.existing_sg_ingress_rules[count.index].from_port
  to_port           = var.existing_sg_ingress_rules[count.index].to_port
  cidr_blocks       = var.existing_sg_ingress_rules[count.index].cidr_blocks
  ipv6_cidr_blocks  = var.existing_sg_ingress_rules[count.index].ipv6_cidr_blocks
  source_security_group_id = var.existing_sg_ingress_rules[count.index].source_security_group_id
  prefix_list_ids   = var.existing_sg_ingress_rules[count.index].prefix_list_ids
}

# Egress rules for existing security group
resource "aws_security_group_rule" "existing_sg_egress" {
  count = local.use_existing_sg ? length(var.existing_sg_egress_rules) : 0

  security_group_id = var.existing_sg_id
  type              = "egress"
  description       = var.existing_sg_egress_rules[count.index].description
  protocol          = var.existing_sg_egress_rules[count.index].protocol
  from_port         = var.existing_sg_egress_rules[count.index].from_port
  to_port           = var.existing_sg_egress_rules[count.index].to_port
  cidr_blocks       = var.existing_sg_egress_rules[count.index].cidr_blocks
  ipv6_cidr_blocks  = var.existing_sg_egress_rules[count.index].ipv6_cidr_blocks
  source_security_group_id = var.existing_sg_egress_rules[count.index].source_security_group_id
  prefix_list_ids   = var.existing_sg_egress_rules[count.index].prefix_list_ids
}

# Customer-managed prefix list
resource "aws_ec2_managed_prefix_list" "this" {
  count = local.create_prefix_list_res ? 1 : 0

  name           = var.prefix_list_name
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }

  tags = merge({ Name = var.prefix_list_name }, var.prefix_list_tags)

  lifecycle {
    create_before_destroy = true
  }
}

# Terraform required version and providers
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Import existing IAM roles and instance profiles into Terraform state
import {
  to = aws_iam_role.ec2_codedeploy_role
  id = "${var.project_name}_ec2_codedeploy_role"
}

import {
  to = aws_iam_role.codedeploy_service_role
  id = "${var.project_name}_codedeploy_service_role"
}

import {
  to = aws_iam_role.cloudwatch_agent_role
  id = "${var.project_name}_cloudwatch_agent_role"
}

import {
  to = aws_iam_role.codebuild_role
  id = "CodeBuildRole"
}

import {
  to = aws_iam_role.codepipeline_role
  id = "CodePipelineRole"
}

import {
  to = aws_iam_instance_profile.ec2_codedeploy_instance_profile
  id = "${var.project_name}_ec2_codedeploy_instance_profile"
}

import {
  to = aws_iam_instance_profile.cloudwatch_agent_instance_profile
  id = "${var.project_name}_cloudwatch_agent_instance_profile"
}

# Variable for project name
variable "project_name" {
  description = "Prefix for resource names"
  type        = string
  default     = "Cv-React-App"
}

# Data sources for static provider metadata
data "aws_caller_identity" "current" {}

# Random suffix for S3 bucket name and KMS alias
resource "random_id" "suffix" {
  byte_length = 4
}

# Local values
locals {
  account_id = data.aws_caller_identity.current.account_id
  bucket_name = "${lower(replace(var.project_name, "/[^a-z0-9-]/", ""))}-codepipeline-artifacts-${random_id.suffix.hex}"
}

# ------------------------------------------------------------------------------
# KMS Customer Managed Key for S3 Encryption
# ------------------------------------------------------------------------------
resource "aws_kms_key" "s3" {
  description             = "KMS key for CodePipeline artifacts bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_alias" "s3" {
  name          = "alias/${var.project_name}-codepipeline-artifacts-${random_id.suffix.hex}"
  target_key_id = aws_kms_key.s3.id
}

# ------------------------------------------------------------------------------
# S3 Bucket for CodePipeline Artifacts
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "codepipeline_artifacts" {
  bucket = local.bucket_name
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "codepipeline_artifacts" {
  bucket                  = aws_s3_bucket.codepipeline_artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "codepipeline_artifacts" {
  bucket = aws_s3_bucket.codepipeline_artifacts.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "codepipeline_artifacts" {
  bucket = aws_s3_bucket.codepipeline_artifacts.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ------------------------------------------------------------------------------
# EC2 CodeDeploy Role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "ec2_codedeploy_role" {
  name = "${var.project_name}_ec2_codedeploy_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_AmazonEC2RoleforAWSCodeDeploy" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2RoleforAWSCodeDeploy"
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_AmazonEC2FullAccess" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2FullAccess"
}

resource "aws_iam_role_policy" "ec2_codedeploy_s3_policy" {
  name = "EC2CodeDeployS3Access"
  role = aws_iam_role.ec2_codedeploy_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "s3:GetObject",
        "s3:PutObject",
        "s3:ListBucket"
      ]
      Resource = [
        aws_s3_bucket.codepipeline_artifacts.arn,
        "${aws_s3_bucket.codepipeline_artifacts.arn}/*"
      ]
    }]
  })
}

resource "aws_iam_instance_profile" "ec2_codedeploy_instance_profile" {
  name = "${var.project_name}_ec2_codedeploy_instance_profile"
  role = aws_iam_role.ec2_codedeploy_role.name
}

# ------------------------------------------------------------------------------
# CodeDeploy Service Role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "codedeploy_service_role" {
  name = "${var.project_name}_codedeploy_service_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "codedeploy.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_AWSCodeDeployRole" {
  role       = aws_iam_role.codedeploy_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRole"
}

resource "aws_iam_role_policy" "codedeploy_service_s3_policy" {
  name = "CodeDeployServiceS3Access"
  role = aws_iam_role.codedeploy_service_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "s3:GetObject",
        "s3:ListBucket"
      ]
      Resource = [
        aws_s3_bucket.codepipeline_artifacts.arn,
        "${aws_s3_bucket.codepipeline_artifacts.arn}/*"
      ]
    }]
  })
}

# ------------------------------------------------------------------------------
# EC2 CloudWatch Agent Role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "cloudwatch_agent_role" {
  name = "${var.project_name}_cloudwatch_agent_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "cloudwatch_agent_CloudWatchAgentServerPolicy" {
  role       = aws_iam_role.cloudwatch_agent_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_instance_profile" "cloudwatch_agent_instance_profile" {
  name = "${var.project_name}_cloudwatch_agent_instance_profile"
  role = aws_iam_role.cloudwatch_agent_role.name
}

# ------------------------------------------------------------------------------
# CodeBuild Role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "codebuild_role" {
  name = "CodeBuildRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "codebuild.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy" "codebuild_inline_policy" {
  name = "CodeBuildInlinePolicy"
  role = aws_iam_role.codebuild_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:GetBucketPolicy",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.codepipeline_artifacts.arn,
          "${aws_s3_bucket.codepipeline_artifacts.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "codebuild:CreateReportGroup",
          "codebuild:CreateReport",
          "codebuild:UpdateReport",
          "codebuild:BatchPutTestCases",
          "codebuild:BatchPutCodeCoverages"
        ]
        Resource = "*"
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# CodePipeline Role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "codepipeline_role" {
  name = "CodePipelineRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "codepipeline.amazonaws.com",
            "codebuild.amazonaws.com",
            "codedeploy.amazonaws.com",
            "cloudformation.amazonaws.com",
            "ec2.amazonaws.com",
            "lambda.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      },
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "codepipeline_inline_policy" {
  name = "CodePipelineInlinePolicy"
  role = aws_iam_role.codepipeline_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "codestar-connections:*"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:GetBucketPolicy",
          "s3:PutObjectAcl"
        ]
        Resource = [
          aws_s3_bucket.codepipeline_artifacts.arn,
          "${aws_s3_bucket.codepipeline_artifacts.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = "codecommit:*"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "codedeploy:*"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "lambda:*"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "codebuild:*"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "cloudformation:*"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:*",
          "autoscaling:*",
          "elasticloadbalancing:*",
          "cloudwatch:*",
          "iam:PassRole"
        ]
        Resource = "*"
      }
    ]
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.90.0"
    }
  }
}

variable "environment" {
  description = "Environment name for tagging"
  type        = string
  default     = "dev"
}

locals {
  common_tags = {
    Name        = "dynamodb-tables"
    Environment = var.environment
  }
}

# Table 1: near-app-actions-mapping
resource "aws_dynamodb_table" "near_app_actions_mapping" {
  name           = "near-app-actions-mapping"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "appId"

  attribute {
    name = "appId"
    type = "S"
  }

  tags = merge(local.common_tags, { Name = "near-app-actions-mapping" })

  lifecycle {
    prevent_destroy = true
  }
}

