  global_secondary_index {
    name            = "OwnerIdIndex"
    hash_key        = "ownerId"
    projection_type = "ALL"
  }

  tags = merge(local.common_tags, { Name = "near-nft-collections" })

  lifecycle {
    prevent_destroy = true
  }
}

