terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.75.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "ecs_optimized" {
  owners      = ["amazon"]
  most_recent = true
  filter {
    name   = "name"
    values = ["amzn2-ami-ecs-hvm-*-x86_64-ebs"]
  }
  filter {
    name   = "state"
    values = ["available"]
  }
}

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------
locals {
  common_tags = {
    Environment = "chaos-engineering"
    Project     = "fis-demo"
    ManagedBy   = "Terraform"
  }
  name_prefix = "fis-chaos"
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "admin_cidr" {
  description = "CIDR block allowed to SSH into instances"
  type        = string
  default     = "10.0.0.0/24"
}

variable "instance_type" {
  description = "EC2 instance type for Auto Scaling group"
  type        = string
  default     = "t3.micro"
}

variable "desired_capacity" {
  description = "Desired capacity for Auto Scaling group"
  type        = number
  default     = 1
}

variable "s3_bucket_name" {
  description = "Globally unique name for the FIS experiment log bucket"
  type        = string
  default     = "fis-experiment-logs-20250331"
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

# ---------------------------------------------------------------------------
# Internet Gateway
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

# ---------------------------------------------------------------------------
# Public subnet
# ---------------------------------------------------------------------------
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false
  tags = merge(local.common_tags, {
    Name        = "${local.name_prefix}-public-subnet"
    ChaosTarget = "true"
  })
}

# ---------------------------------------------------------------------------
# Route table & association
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# SSH key pair (auto-generated)
# ---------------------------------------------------------------------------
resource "tls_private_key" "admin" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "aws_key_pair" "admin" {
  key_name   = "${local.name_prefix}-admin-key"
  public_key = tls_private_key.admin.public_key_openssh
  tags       = local.common_tags
}

# ---------------------------------------------------------------------------
# Security group for SSH
# ---------------------------------------------------------------------------
resource "aws_security_group" "ssh" {
  name        = "${local.name_prefix}-ssh-sg"
  description = "Allow SSH from admin CIDR"
  vpc_id      = aws_vpc.main.id
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }
  egress {
    from_port   = 1024
    to_port     = 65535
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ssh-sg"
  })
}

# ---------------------------------------------------------------------------
# VPC Endpoints for required AWS services
# ---------------------------------------------------------------------------
resource "aws_vpc_endpoint" "ssm" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ssm"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.public.id]
  security_group_ids  = [aws_security_group.ssh.id]
  private_dns_enabled = true
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ssm-endpoint"
  })
}

resource "aws_vpc_endpoint" "ec2messages" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ec2messages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.public.id]
  security_group_ids  = [aws_security_group.ssh.id]
  private_dns_enabled = true
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ec2messages-endpoint"
  })
}

resource "aws_vpc_endpoint" "ssmmessages" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ssmmessages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.public.id]
  security_group_ids  = [aws_security_group.ssh.id]
  private_dns_enabled = true
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ssmmessages-endpoint"
  })
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.public.id]
  security_group_ids  = [aws_security_group.ssh.id]
  private_dns_enabled = true
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ecr-dkr-endpoint"
  })
}

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ecr.api"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.public.id]
  security_group_ids  = [aws_security_group.ssh.id]
  private_dns_enabled = true
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ecr-api-endpoint"
  })
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.public.id]
  security_group_ids  = [aws_security_group.ssh.id]
  private_dns_enabled = true
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-logs-endpoint"
  })
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id          = aws_vpc.main.id
  service_name    = "com.amazonaws.us-east-1.s3"
  route_table_ids = [aws_route_table.public.id]
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-s3-endpoint"
  })
}

# ---------------------------------------------------------------------------
# IAM roles & instance profile for EC2 instances
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs" {
  name = "${local.name_prefix}-ecs-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "ecs_service" {
  role       = aws_iam_role.ecs.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

resource "aws_iam_role_policy_attachment" "ssm" {
  role       = aws_iam_role.ecs.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ecs" {
  name = "${local.name_prefix}-ecs-instance-profile"
  role = aws_iam_role.ecs.name
  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# Launch template
# ---------------------------------------------------------------------------
resource "aws_launch_template" "ecs" {
  name_prefix   = "${local.name_prefix}-lt-"
  image_id      = data.aws_ami.ecs_optimized.id
  instance_type = var.instance_type
  key_name      = aws_key_pair.admin.key_name

  metadata_options {
    http_tokens               = "required"
    http_put_response_hop_limit = 1
  }

  network_interfaces {
    associate_public_ip_address = true
    delete_on_termination       = true
    security_groups             = [aws_security_group.ssh.id]
  }

  iam_instance_profile {
    name = aws_iam_instance_profile.ecs.name
  }

  block_device_mappings {
    device_name = "/dev/xvda"
    ebs {
      volume_size           = 30
      volume_type           = "gp3"
      delete_on_termination = true
      encrypted             = true
    }
  }

  tag_specifications {
    resource_type = "volume"
    tags = merge(local.common_tags, {
      ChaosTarget = "true"
    })
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-lt"
  })
}

# ---------------------------------------------------------------------------
# Auto Scaling Group
# ---------------------------------------------------------------------------
resource "aws_autoscaling_group" "ecs" {
  name                = "${local.name_prefix}-asg"
  vpc_zone_identifier = [aws_subnet.public.id]
  desired_capacity    = var.desired_capacity
  min_size            = 1
  max_size            = 1
  health_check_type   = "EC2"

  launch_template {
    id      = aws_launch_template.ecs.id
    version = "$Latest"
  }

  tag {
    key                 = "ChaosTarget"
    value               = "true"
    propagate_at_launch = true
  }

  tag {
    key                 = "Name"
    value               = "${local.name_prefix}-instance"
    propagate_at_launch = true
  }
}

# ---------------------------------------------------------------------------
# KMS key for S3 bucket encryption
# ---------------------------------------------------------------------------
resource "aws_kms_key" "fis_logs" {
  description             = "KMS key for FIS experiment log bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAdmin"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowFISService"
        Effect = "Allow"
        Principal = {
          Service = "fis.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      }
    ]
  })
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-kms"
  })
  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# S3 bucket for FIS experiment logs
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "fis_logs" {
  bucket = var.s3_bucket_name
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-logs"
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "fis_logs" {
  bucket                  = aws_s3_bucket.fis_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.fis_logs.arn
    }
  }
}

resource "aws_s3_bucket_policy" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowFISLogDelivery"
        Effect = "Allow"
        Principal = {
          Service = "fis.amazonaws.com"
        }
        Action = [
          "s3:PutObject"
        ]
        Resource = "${aws_s3_bucket.fis_logs.arn}/*"
      },
      {
        Sid    = "AllowRootAccount"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "s3:*"
        Resource = [
          aws_s3_bucket.fis_logs.arn,
          "${aws_s3_bucket.fis_logs.arn}/*"
        ]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# IAM role & policy for AWS FIS
# ---------------------------------------------------------------------------
resource "aws_iam_role" "fis" {
  name = "${local.name_prefix}-fis-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "fis.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.common_tags
}

data "aws_iam_policy_document" "fis" {
  statement {
    sid = "DescribeImagesAPI"
    effect = "Allow"
    actions = [
      "ec2:DescribeImages"
    ]
    resources = ["*"]
  }
  statement {
    sid = "EBSVolumeIO"
    effect = "Allow"
    actions = [
      "ec2:DescribeVolumes",
      "ec2:AttachVolume",
      "ec2:DetachVolume",
      "ec2:ModifyVolume"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/ChaosTarget"
      values   = ["true"]
    }
  }
  statement {
    sid = "EC2InstanceTermination"
    effect = "Allow"
    actions = [
      "ec2:TerminateInstances"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/ChaosTarget"
      values   = ["true"]
    }
  }
  statement {
    sid = "SSMCommands"
    effect = "Allow"
    actions = [
      "ssm:SendCommand",
      "ssm:ListCommands",
      "ssm:ListCommandInvocations"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/ChaosTarget"
      values   = ["true"]
    }
  }
  statement {
    sid = "NetworkDisruption"
    effect = "Allow"
    actions = [
      "ec2:CreateNetworkAcl",
      "ec2:DeleteNetworkAcl",
      "ec2:CreateNetworkAclEntry",
      "ec2:DeleteNetworkAclEntry",
      "ec2:DescribeNetworkAcls"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/ChaosTarget"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "fis" {
  name   = "${local.name_prefix}-fis-policy"
  policy = data.aws_iam_policy_document.fis.json
  tags   = local.common_tags
}

resource "aws_iam_role_policy_attachment" "fis" {
  role       = aws_iam_role.fis.name
  policy_arn = aws_iam_policy.fis.arn
}

# ---------------------------------------------------------------------------
# FIS Experiment Templates
# ---------------------------------------------------------------------------

# 1. API internal-error on ec2:DescribeImages
resource "aws_fis_experiment_template" "api_internal_error" {
  description = "FIS experiment: inject internal-error on DescribeImages API"
  role_arn    = aws_iam_role.fis.arn

  target {
    name           = "TargetInstances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"
    resource_tags {
      tag {
        key   = "ChaosTarget"
        value = "true"
      }
    }
  }

  action {
    name      = "fault"
    action_id = "aws:ec2:api-internal-error"
    target {
      key   = "Targets"
      value = "TargetInstances"
    }
    parameter {
      key   = "apiName"
      value = "DescribeImages"
    }
    parameter {
      key   = "errorCode"
      value = "InternalError"
    }
  }

  log_configuration {
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.bucket
      prefix      = "experiments/api-internal-error/"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-api-internal-error"
  })
}

# 2. EBS volume I/O pause
resource "aws_fis_experiment_template" "ebs_pause_io" {
  description = "FIS experiment: pause EBS volume I/O"
  role_arn    = aws_iam_role.fis.arn

  target {
    name           = "TargetVolumes"
    resource_type  = "aws:ec2:volume"
    selection_mode = "ALL"
    resource_tags {
      tag {
        key   = "ChaosTarget"
        value = "true"
      }
    }
  }

  action {
    name      = "fault"
    action_id = "aws:ebs:pause-volume-io"
    target {
      key   = "Volumes"
      value = "TargetVolumes"
    }
    parameter {
      key   = "duration"
      value = "PT60S"
    }
  }

  log_configuration {
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.bucket
      prefix      = "experiments/ebs-pause-io/"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ebs-pause-io"
  })
}

# 3. EC2 CPU stress via SSM
resource "aws_fis_experiment_template" "ec2_cpu_stress" {
  description = "FIS experiment: CPU stress on EC2 instances"
  role_arn    = aws_iam_role.fis.arn

  target {
    name           = "TargetInstances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"
    resource_tags {
      tag {
        key   = "ChaosTarget"
        value = "true"
      }
    }
  }

  action {
    name      = "fault"
    action_id = "aws:ec2:send-command"
    target {
      key   = "Instances"
      value = "TargetInstances"
    }
    parameter {
      key   = "documentArn"
      value = "arn:aws:ssm:${data.aws_region.current.name}::document/AWSFIS-Run-CPU-Stress"
    }
    parameter {
      key   = "duration"
      value = "PT60S"
    }
  }

  log_configuration {
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.bucket
      prefix      = "experiments/ec2-cpu-stress/"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ec2-cpu-stress"
  })
}

# Helper for current region
data "aws_region" "current" {}

# 4. EC2 instance termination
resource "aws_fis_experiment_template" "ec2_terminate_instances" {
  description = "FIS experiment: terminate EC2 instances"
  role_arn    = aws_iam_role.fis.arn

  target {
    name           = "TargetInstances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"
    resource_tags {
      tag {
        key   = "ChaosTarget"
        value = "true"
      }
    }
  }

  action {
    name      = "fault"
    action_id = "aws:ec2:terminate-instances"
    target {
      key   = "Instances"
      value = "TargetInstances"
    }
  }

  log_configuration {
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.bucket
      prefix      = "experiments/ec2-terminate-instances/"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ec2-terminate-instances"
  })
}

# 5. Network connectivity disruption on subnet
resource "aws_fis_experiment_template" "network_disruption" {
  description = "FIS experiment: disrupt network connectivity on subnet"
  role_arn    = aws_iam_role.fis.arn

  target {
    name           = "TargetSubnets"
    resource_type  = "aws:ec2:subnet"
    selection_mode = "ALL"
    resource_tags {
      tag {
        key   = "ChaosTarget"
        value = "true"
      }
    }
  }

  action {
    name      = "fault"
    action_id = "aws:ec2:network-connectivity-disruption"
    target {
      key   = "Subnets"
      value = "TargetSubnets"
    }
    parameter {
      key   = "duration"
      value = "PT60S"
    }
  }

  log_configuration {
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.bucket
      prefix      = "experiments/network-disruption/"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-network-disruption"
  })
}

# ----------------------------------------------------------------------
# TERRAFORM & PROVIDER REQUIREMENTS
# ----------------------------------------------------------------------
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ----------------------------------------------------------------------
# VARIABLES
# ----------------------------------------------------------------------
variable "create_vpc" {
  description = "Controls whether to create the VPC"
  type        = bool
  default     = true
}

variable "cidr" {
  description = "IPv4 CIDR block for the VPC (used if ipv4_ipam_pool_id is not provided)"
  type        = string
  default     = "10.0.0.0/16"
}

variable "ipv4_ipam_pool_id" {
  description = "IPv4 IPAM pool ID for VPC CIDR allocation"
  type        = string
  default     = null
}

variable "ipv4_netmask_length" {
  description = "Netmask length for VPC CIDR when using IPAM pool"
  type        = number
  default     = null
}

variable "secondary_cidr_blocks" {
  description = "Map of secondary IPv4 CIDR blocks or IPAM pools to associate with the VPC"
  type = map(object({
    cidr_block        = optional(string)
    ipam_pool_id      = optional(string)
    netmask_length    = optional(number)
  }))
  default = {}
}

variable "public_subnets" {
  description = "Map of public subnet configurations. Each key is a subnet name."
  type = map(object({
    cidr_block              = string
    availability_zone       = string
    map_public_ip_on_launch = optional(bool, true)
    ipv6_cidr_block         = optional(string)
    tags                    = optional(map(string), {})
  }))
  default = {}
}

variable "private_subnets" {
  description = "Map of private subnet configurations. Each key is a subnet name."
  type = map(object({
    cidr_block              = string
    availability_zone       = string
    map_public_ip_on_launch = optional(bool, false)
    ipv6_cidr_block         = optional(string)
    tags                    = optional(map(string), {})
  }))
  default = {}
}

variable "create_igw" {
  description = "Controls whether to create an Internet Gateway"
  type        = bool
  default     = true
}

variable "create_nat_gateway" {
  description = "Controls whether to create NAT Gateways (one per AZ)"
  type        = bool
  default     = true
}

variable "create_egress_only_igw" {
  description = "Controls whether to create an egress-only Internet Gateway"
  type        = bool
  default     = false
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "dhcp_options" {
  description = "DHCP options configuration. Set to null to skip."
  type = object({
    domain_name          = string
    domain_name_servers  = list(string)
    ntp_servers          = optional(list(string))
    netbios_name_servers = optional(list(string))
    netbios_node_type    = optional(string)
  })
  default = null
}

variable "manage_default_security_group" {
  description = "Manage the default security group"
  type        = bool
  default     = false
}

variable "default_security_group_ingress" {
  description = "Ingress rules for default security group (if managed)"
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  default = []
}

variable "default_security_group_egress" {
  description = "Egress rules for default security group (if managed)"
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  default = []
}

variable "manage_default_network_acl" {
  description = "Manage the default network ACL"
  type        = bool
  default     = false
}

variable "manage_default_route_table" {
  description = "Manage the default route table"
  type        = bool
  default     = false
}

variable "flow_logs" {
  description = "VPC Flow Logs configuration. Set to null to skip."
  type = object({
    log_destination_type = string          # "s3" or "cloud-watch-logs"
    log_destination      = optional(string) # ARN of S3 bucket or CloudWatch log group (if not created by module)
    traffic_type         = optional(string, "ALL")
    aggregation_interval = optional(number, 600)
    log_format           = optional(string, "$${version} $${account-id} $${vpc-id} $${subnet-id} $${instance-id} $${srcaddr} $${dstaddr} $${srcport} $${dstport} $${protocol} $${packets} $${bytes} $${start} $${end} $${action} $${log-status}")
    kms_key_id           = optional(string)
    tags                 = optional(map(string), {})
    # For S3
    s3_bucket_name_prefix = optional(string, "vpc-flow-logs")
    # For CloudWatch
    cloudwatch_log_group_name = optional(string, "/aws/vpc-flow-logs")
    iam_role_name             = optional(string, "vpc-flow-log-role")
  })
  default = null
}

# ----------------------------------------------------------------------
# DATA SOURCES (only static provider metadata)
# ----------------------------------------------------------------------
data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

# ----------------------------------------------------------------------
# LOCALS
# ----------------------------------------------------------------------
locals {
  vpc_id = var.create_vpc ? aws_vpc.this[0].id : null

  # Group public subnets by AZ to determine NAT Gateway placement
  public_subnets_by_az = {
    for az_key, subnet_list in {
      for k, v in var.public_subnets : v.availability_zone => k...
    } : az_key => [for name in subnet_list : aws_subnet.public[name].id]
  }

  # For each AZ that has a public subnet, create a NAT Gateway
  nat_azs = keys(local.public_subnets_by_az)

  # Private subnets by AZ for route table associations
  private_subnets_by_az = {
    for az_key, subnet_list in {
      for k, v in var.private_subnets : v.availability_zone => k...
    } : az_key => [for name in subnet_list : aws_subnet.private[name].id]
  }
}

# ----------------------------------------------------------------------
# VPC
# ----------------------------------------------------------------------
resource "aws_vpc" "this" {
  count = var.create_vpc ? 1 : 0

  cidr_block            = var.ipv4_ipam_pool_id != null ? null : var.cidr
  ipv4_ipam_pool_id     = var.ipv4_ipam_pool_id
  ipv4_netmask_length   = var.ipv4_netmask_length

  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = {
    Name = "main-vpc"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Secondary CIDR blocks
resource "aws_vpc_ipv4_cidr_block_association" "secondary" {
  for_each = var.secondary_cidr_blocks

  vpc_id = local.vpc_id

  cidr_block        = each.value.cidr_block
  ipv4_ipam_pool_id = each.value.ipam_pool_id
  ipv4_netmask_length = each.value.netmask_length

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# PUBLIC SUBNETS
# ----------------------------------------------------------------------
resource "aws_subnet" "public" {
  for_each = var.public_subnets

  vpc_id                  = local.vpc_id
  cidr_block              = each.value.cidr_block
  availability_zone       = each.value.availability_zone
  map_public_ip_on_launch = each.value.map_public_ip_on_launch
  ipv6_cidr_block         = each.value.ipv6_cidr_block

  tags = merge(each.value.tags, { Name = "public-${each.key}" })

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# PRIVATE SUBNETS
# ----------------------------------------------------------------------
resource "aws_subnet" "private" {
  for_each = var.private_subnets

  vpc_id                  = local.vpc_id
  cidr_block              = each.value.cidr_block
  availability_zone       = each.value.availability_zone
  map_public_ip_on_launch = each.value.map_public_ip_on_launch
  ipv6_cidr_block         = each.value.ipv6_cidr_block

  tags = merge(each.value.tags, { Name = "private-${each.key}" })

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# INTERNET GATEWAY
# ----------------------------------------------------------------------
resource "aws_internet_gateway" "this" {
  count = var.create_igw && var.create_vpc ? 1 : 0

  vpc_id = local.vpc_id

  tags = {
    Name = "main-igw"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# ELASTIC IPs & NAT GATEWAYS (one per AZ with public subnet)
# ----------------------------------------------------------------------
resource "aws_eip" "nat" {
  for_each = toset(local.nat_azs)

  domain = "vpc"

  tags = {
    Name = "nat-eip-${each.key}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_nat_gateway" "this" {
  for_each = toset(local.nat_azs)

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = local.public_subnets_by_az[each.key][0]  # use first public subnet in this AZ

  tags = {
    Name = "nat-gw-${each.key}"
  }

  depends_on = [aws_internet_gateway.this]

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# PUBLIC ROUTE TABLE
# ----------------------------------------------------------------------
resource "aws_route_table" "public" {
  count = var.create_vpc && length(var.public_subnets) > 0 ? 1 : 0

  vpc_id = local.vpc_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = var.create_igw ? aws_internet_gateway.this[0].id : null
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  for_each = var.public_subnets

  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public[0].id
}

# ----------------------------------------------------------------------
# PRIVATE ROUTE TABLES (one per AZ)
# ----------------------------------------------------------------------
resource "aws_route_table" "private" {
  for_each = local.private_subnets_by_az

  vpc_id = local.vpc_id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = var.create_nat_gateway ? aws_nat_gateway.this[each.key].id : null
  }

  dynamic "route" {
    for_each = var.create_egress_only_igw ? [1] : []
    content {
      ipv6_cidr_block        = "::/0"
      egress_only_gateway_id = aws_egress_only_internet_gateway.this[0].id
    }
  }

  tags = {
    Name = "private-route-table-${each.key}"
  }
}

resource "aws_route_table_association" "private" {
  for_each = merge([
    for az, subnet_ids in local.private_subnets_by_az : {
      for subnet_id in subnet_ids : "${az}-${subnet_id}" => {
        az        = az
        subnet_id = subnet_id
      }
    }
  ]...)

  subnet_id      = each.value.subnet_id
  route_table_id = aws_route_table.private[each.value.az].id
}

# ----------------------------------------------------------------------
# EGRESS-ONLY INTERNET GATEWAY
# ----------------------------------------------------------------------
resource "aws_egress_only_internet_gateway" "this" {
  count = var.create_egress_only_igw && var.create_vpc ? 1 : 0

  vpc_id = local.vpc_id

  tags = {
    Name = "main-eigw"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# NETWORK ACLs
# ----------------------------------------------------------------------
resource "aws_network_acl" "public" {
  count = var.create_vpc && length(var.public_subnets) > 0 ? 1 : 0

  vpc_id = local.vpc_id

  tags = {
    Name = "public-nacl"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_network_acl" "private" {
  count = var.create_vpc && length(var.private_subnets) > 0 ? 1 : 0

  vpc_id = local.vpc_id

  # Default allow-all inbound (rule number 100)
  ingress {
    protocol   = -1
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  # Default allow-all outbound (rule number 200)
  egress {
    protocol   = -1
    rule_no    = 200
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "private-nacl"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# DHCP OPTIONS
# ----------------------------------------------------------------------
resource "aws_vpc_dhcp_options" "this" {
  count = var.dhcp_options != null && var.create_vpc ? 1 : 0

  domain_name          = var.dhcp_options.domain_name
  domain_name_servers  = var.dhcp_options.domain_name_servers
  ntp_servers          = var.dhcp_options.ntp_servers
  netbios_name_servers = var.dhcp_options.netbios_name_servers
  netbios_node_type    = var.dhcp_options.netbios_node_type

  tags = {
    Name = "main-dhcp-options"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_vpc_dhcp_options_association" "this" {
  count = var.dhcp_options != null && var.create_vpc ? 1 : 0

  vpc_id          = local.vpc_id
  dhcp_options_id = aws_vpc_dhcp_options.this[0].id
}

# ----------------------------------------------------------------------
# VPC FLOW LOGS
# ----------------------------------------------------------------------
# IAM role for CloudWatch Logs
resource "aws_iam_role" "flow_logs" {
  count = var.flow_logs != null && var.flow_logs.log_destination_type == "cloud-watch-logs" && var.create_vpc ? 1 : 0

  name = var.flow_logs.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "flow_logs" {
  count = var.flow_logs != null && var.flow_logs.log_destination_type == "cloud-watch-logs" && var.create_vpc ? 1 : 0

  name = "vpc-flow-log-policy"
  role = aws_iam_role.flow_logs[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      }
    ]
  })
}

# S3 bucket for flow logs (if S3 destination)
resource "aws_s3_bucket" "flow_logs" {
  count = var.flow_logs != null && var.flow_logs.log_destination_type == "s3" && var.create_vpc ? 1 : 0

  bucket = "${var.flow_logs.s3_bucket_name_prefix}-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"

  tags = merge(var.flow_logs.tags, { Name = "vpc-flow-logs" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "flow_logs" {
  count = var.flow_logs != null && var.flow_logs.log_destination_type == "s3" && var.create_vpc ? 1 : 0

  bucket = aws_s3_bucket.flow_logs[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "flow_logs" {
  count = var.flow_logs != null && var.flow_logs.log_destination_type == "s3" && var.create_vpc ? 1 : 0

  bucket = aws_s3_bucket.flow_logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "flow_logs" {
  count = var.flow_logs != null && var.flow_logs.log_destination_type == "s3" && var.create_vpc ? 1 : 0

  bucket = aws_s3_bucket.flow_logs[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

# CloudWatch Log Group for flow logs (if CloudWatch destination)
resource "aws_cloudwatch_log_group" "flow_logs" {
  count = var.flow_logs != null && var.flow_logs.log_destination_type == "cloud-watch-logs" && var.create_vpc ? 1 : 0

  name              = var.flow_logs.cloudwatch_log_group_name
  retention_in_days = 365

  tags = var.flow_logs.tags
}

# Flow Log resource
resource "aws_flow_log" "this" {
  count = var.flow_logs != null && var.create_vpc ? 1 : 0

  log_destination_type     = var.flow_logs.log_destination_type
  log_destination          = var.flow_logs.log_destination_type == "s3" ? aws_s3_bucket.flow_logs[0].arn : aws_cloudwatch_log_group.flow_logs[0].arn
  traffic_type             = var.flow_logs.traffic_type
  vpc_id                   = local.vpc_id
  max_aggregation_interval = var.flow_logs.aggregation_interval
  log_format               = var.flow_logs.log_format

  iam_role_arn = var.flow_logs.log_destination_type == "cloud-watch-logs" ? aws_iam_role.flow_logs[0].arn : null

  tags = var.flow_logs.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# DEFAULT SECURITY GROUP
# ----------------------------------------------------------------------
resource "aws_default_security_group" "this" {
  count = var.manage_default_security_group && var.create_vpc ? 1 : 0

  vpc_id = local.vpc_id

  dynamic "ingress" {
    for_each = var.default_security_group_ingress
    content {
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
    }
  }

  dynamic "egress" {
    for_each = var.default_security_group_egress
    content {
      from_port   = egress.value.from_port
      to_port     = egress.value.to_port
      protocol    = egress.value.protocol
      cidr_blocks = egress.value.cidr_blocks
    }
  }

  tags = {
    Name = "default"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# DEFAULT NETWORK ACL
# ----------------------------------------------------------------------
resource "aws_default_network_acl" "this" {
  count = var.manage_default_network_acl && var.create_vpc ? 1 : 0

  default_network_acl_id = aws_vpc.this[0].default_network_acl_id

  # Allow all IPv4 inbound
  ingress {
    protocol   = -1
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  # Allow all IPv4 outbound
  egress {
    protocol   = -1
    rule_no    = 200
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  # Allow all IPv6 inbound
  ingress {
    protocol        = -1
    rule_no         = 110
    action          = "allow"
    ipv6_cidr_block = "::/0"
    from_port       = 0
    to_port         = 0
  }

  # Allow all IPv6 outbound
  egress {
    protocol        = -1
    rule_no         = 210
    action          = "allow"
    ipv6_cidr_block = "::/0"
    from_port       = 0
    to_port         = 0
  }

  tags = {
    Name = "default"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# DEFAULT ROUTE TABLE
# ----------------------------------------------------------------------
resource "aws_default_route_table" "this" {
  count = var.manage_default_route_table && var.create_vpc ? 1 : 0

  default_route_table_id = aws_vpc.this[0].default_route_table_id

  tags = {
    Name = "default"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# OUTPUTS (optional, but helpful)
# ----------------------------------------------------------------------
output "vpc_id" {
  value = local.vpc_id
}

output "public_subnet_ids" {
  value = { for k, v in aws_subnet.public : k => v.id }
}

output "private_subnet_ids" {
  value = { for k, v in aws_subnet.private : k => v.id }
}

output "nat_gateway_ids" {
  value = { for k, v in aws_nat_gateway.this : k => v.id }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.75.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Data sources for dynamic lookups
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# Random pet name for server name fallback
resource "random_pet" "server_name_fallback" {
  length    = 2
  separator = "-"
}

# Variables
variable "server_name" {
  type    = string
  default = ""
}

variable "logging_role_arn" {
  type    = string
  default = null
}

variable "api_gateway_auth_enabled" {
  type    = bool
  default = false
}

variable "endpoint_type" {
  type    = string
  default = "PUBLIC"
}

variable "protocols" {
  type    = list(string)
  default = ["SFTP"]
}

variable "custom_security_policy" {
  type    = string
  default = "TransferSecurityPolicy-2023-05"
}

variable "acm_certificate_arn" {
  type    = string
  default = null
}

variable "custom_login_banner" {
  type    = string
  default = null
}

variable "host_key" {
  type      = string
  default   = null
  sensitive = true
}

variable "protocol_details" {
  type = object({
    as2_transports  = optional(list(string))
    passive_ip      = optional(string)
    set_stat_option = optional(string)
  })
  default = {}
}

variable "vpc_id" {
  type    = string
  default = null
}

variable "subnet_ids" {
  type    = list(string)
  default = []
}

variable "security_group_ids" {
  type    = list(string)
  default = []
}

variable "elastic_ip_allocation_ids" {
  type    = list(string)
  default = []
}

variable "route53_zone_id" {
  type    = string
  default = null
}

variable "route53_subdomain" {
  type    = string
  default = "sftp"
}

variable "sftp_users" {
  type = map(object({
    home_directory  = string
    ssh_public_key = optional(string)
  }))
  default = {}
}

# Local values
locals {
  server_name = coalesce(var.server_name, random_pet.server_name_fallback.id)

  # Determine if we need to create VPC infrastructure for VPC or VPC_ENDPOINT
  create_vpc_infra = (var.endpoint_type == "VPC" || var.endpoint_type == "VPC_ENDPOINT") && (
    var.vpc_id == null && length(var.subnet_ids) == 0 && length(var.security_group_ids) == 0
  )

  # Extract unique bucket names from user home directories
  bucket_names = distinct([for u in var.sftp_users : split("/", u.home_directory)[0]])
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "transfer" {
  name              = "/aws/transfer/${local.server_name}"
  retention_in_days = 30
  lifecycle {
    prevent_destroy = true
  }
}

# IAM Role for Transfer logging (if no ARN provided)
resource "aws_iam_role" "transfer_logging" {
  count = var.logging_role_arn == null ? 1 : 0
  name_prefix = "aws_transfer_logging_role-"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "transfer.amazonaws.com"
      }
    }]
  })
  lifecycle {
    prevent_destroy = true
  }
}

# Inline IAM policy for Transfer logging (replaces managed policy attachment)
resource "aws_iam_role_policy" "transfer_logging" {
  count = var.logging_role_arn == null ? 1 : 0
  name  = "transfer-logging-policy"
  role  = aws_iam_role.transfer_logging[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:PutRetentionPolicy"
        ]
        Resource = "arn:aws:logs:*:*:log-group:/aws/transfer/*"
      }
    ]
  })
}

# IAM Role for API Gateway authentication (if enabled)
resource "aws_iam_role" "api_gateway_auth" {
  count = var.api_gateway_auth_enabled ? 1 : 0
  name_prefix = "transfer-api-gateway-auth-role-"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "apigateway.amazonaws.com"
      }
    }]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_policy" "api_gateway_logging" {
  count = var.api_gateway_auth_enabled ? 1 : 0
  name  = "transfer-api-gateway-logging-policy"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ]
      Resource = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/transfer/api-gateway-*"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "api_gateway_logging" {
  count      = var.api_gateway_auth_enabled ? 1 : 0
  role       = aws_iam_role.api_gateway_auth[0].name
  policy_arn = aws_iam_policy.api_gateway_logging[0].arn
}

# VPC infrastructure (if creating from scratch)
resource "aws_vpc" "transfer" {
  count                = local.create_vpc_infra ? 1 : 0
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "transfer-vpc"
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "transfer" {
  count                   = local.create_vpc_infra ? length(data.aws_availability_zones.available.names) : 0
  vpc_id                  = aws_vpc.transfer[0].id
  cidr_block              = cidrsubnet(aws_vpc.transfer[0].cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true
  tags = {
    Name = "transfer-subnet-${count.index}"
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_security_group" "transfer" {
  count       = local.create_vpc_infra ? 1 : 0
  name        = "transfer-sg"
  description = "Security group for Transfer Family SFTP server"
  vpc_id      = aws_vpc.transfer[0].id
  ingress {
    description = "SFTP from anywhere"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_eip" "transfer" {
  count    = local.create_vpc_infra ? length(aws_subnet.transfer) : 0
  domain   = "vpc"
  tags = {
    Name = "transfer-eip-${count.index}"
  }
  lifecycle {
    prevent_destroy = true
  }
}

# Transfer Server
resource "aws_transfer_server" "main" {
  identity_provider_type = var.api_gateway_auth_enabled ? "API_GATEWAY" : "SERVICE_MANAGED"
  logging_role          = var.logging_role_arn != null ? var.logging_role_arn : aws_iam_role.transfer_logging[0].arn
  endpoint_type         = var.endpoint_type
  protocols             = var.protocols
  security_policy_name  = var.custom_security_policy
  certificate           = var.acm_certificate_arn
  pre_authentication_login_banner = var.custom_login_banner
  host_key              = var.host_key

  dynamic "endpoint_details" {
    for_each = local.create_vpc_infra ? [1] : []
    content {
      vpc_id          = aws_vpc.transfer[0].id
      subnet_ids      = aws_subnet.transfer[*].id
      security_group_ids = [aws_security_group.transfer[0].id]
      address_allocation_ids = var.endpoint_type == "VPC" ? aws_eip.transfer[*].allocation_id : null
    }
  }

  dynamic "endpoint_details" {
    for_each = !local.create_vpc_infra && (var.endpoint_type == "VPC" || var.endpoint_type == "VPC_ENDPOINT") ? [1] : []
    content {
      vpc_id          = var.vpc_id
      subnet_ids      = var.subnet_ids
      security_group_ids = var.security_group_ids
      address_allocation_ids = var.endpoint_type == "VPC" ? var.elastic_ip_allocation_ids : null
    }
  }

  dynamic "protocol_details" {
    for_each = length(keys(var.protocol_details)) > 0 ? [1] : []
    content {
      as2_transports  = var.protocol_details.as2_transports
      passive_ip      = var.protocol_details.passive_ip
      set_stat_option = var.protocol_details.set_stat_option
    }
  }

  lifecycle {
    create_before_destroy = true
  }
}

# Route 53 record (if zone provided)
resource "aws_route53_record" "sftp" {
  count   = var.route53_zone_id != null ? 1 : 0
  zone_id = var.route53_zone_id
  name    = var.route53_subdomain
  type    = "CNAME"
  ttl     = 300
  records = [aws_transfer_server.main.endpoint]
}

# S3 Buckets for user home directories
resource "aws_s3_bucket" "user_home" {
  for_each = toset(local.bucket_names)
  bucket   = each.key
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "user_home" {
  for_each = aws_s3_bucket.user_home
  bucket   = each.value.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "user_home" {
  for_each = aws_s3_bucket.user_home
  bucket   = each.value.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "user_home" {
  for_each = aws_s3_bucket.user_home
  bucket   = each.value.id
  versioning_configuration {
    status = "Enabled"
  }
}

# IAM Role and Policy for each SFTP user
resource "aws_iam_role" "sftp_user" {
  for_each = var.sftp_users
  name     = "transfer-sftp-user-${each.key}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "transfer.amazonaws.com"
      }
    }]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_policy" "sftp_user" {
  for_each = var.sftp_users
  name     = "transfer-sftp-user-policy-${each.key}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket"
        ]
        Resource = "arn:aws:s3:::${split("/", each.value.home_directory)[0]}"
        Condition = {
          StringLike = {
            "s3:prefix": ["${element(split("/", each.value.home_directory), length(split("/", each.value.home_directory)) - 1)}/*"]
          }
        }
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = "arn:aws:s3:::${each.value.home_directory}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sftp_user" {
  for_each   = var.sftp_users
  role       = aws_iam_role.sftp_user[each.key].name
  policy_arn = aws_iam_policy.sftp_user[each.key].arn
}

# AWS Transfer User
resource "aws_transfer_user" "sftp" {
  for_each       = var.sftp_users
  server_id      = aws_transfer_server.main.id
  user_name      = each.key
  role           = aws_iam_role.sftp_user[each.key].arn
  home_directory = "/${each.value.home_directory}"
}

# SSH Public Keys (if provided)
resource "aws_transfer_ssh_key" "sftp" {
  for_each = { for k, v in var.sftp_users : k => v if v.ssh_public_key != null }
  server_id = aws_transfer_server.main.id
  user_name = each.key
  body      = each.value.ssh_public_key
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.0.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = data.aws_availability_zones.available.names
  vpc_cidr = "192.168.0.0/16"
  public_subnet_cidrs  = ["192.168.0.0/19", "192.168.32.0/19", "192.168.64.0/19"]
  private_subnet_cidrs = ["192.168.96.0/19", "192.168.128.0/19", "192.168.160.0/19"]
  cluster_name = "md-k8s"
}

# VPC
resource "aws_vpc" "eks_vpc" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true

  tags = {
    Name = "md-k8s-vpc"
  }
}

# Public subnets
resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.eks_vpc.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name                              = "md-k8s-public-${local.azs[count.index]}"
    "kubernetes.io/cluster/md-k8s"    = "shared"
    "kubernetes.io/role/elb"          = "1"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.eks_vpc.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name                              = "md-k8s-private-${local.azs[count.index]}"
    "kubernetes.io/cluster/md-k8s"    = "shared"
    "kubernetes.io/role/internal-elb" = "1"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.eks_vpc.id

  tags = {
    Name = "md-k8s-igw"
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat_eip" {
  domain = "vpc"

  tags = {
    Name = "md-k8s-nat-eip"
  }
}

# NAT Gateway in first public subnet
resource "aws_nat_gateway" "nat_gw" {
  allocation_id = aws_eip.nat_eip.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "md-k8s-nat"
  }
}

# Public route table
resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.eks_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "md-k8s-public-rt"
  }
}

# Associate public subnets with public route table
resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public_rt.id
}

# Private route table
resource "aws_route_table" "private_rt" {
  vpc_id = aws_vpc.eks_vpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_gw.id
  }

  tags = {
    Name = "md-k8s-private-rt"
  }
}

# Associate private subnets with private route table
resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_rt.id
}

# DB subnet group
resource "aws_db_subnet_group" "md_k8s_private" {
  name       = "md-k8s-private-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "md-k8s-private-subnet-group"
  }
}

# IAM role for EKS cluster
resource "aws_iam_role" "eks_cluster_role" {
  name = "eks-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach AWS managed policies
resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  role       = aws_iam_role.eks_cluster_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
}

# Custom IAM policy for EC2 networking and CloudWatch metrics
resource "aws_iam_policy" "eks_custom_ec2_cloudwatch" {
  name        = "eks-custom-ec2-cloudwatch"
  description = "Allow EKS to describe EC2 networking and publish CloudWatch metrics"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeInstances",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVpcs"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "cloudwatch:PutMetricData"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_custom_ec2_cloudwatch" {
  role       = aws_iam_role.eks_cluster_role.name
  policy_arn = aws_iam_policy.eks_custom_ec2_cloudwatch.arn
}

# KMS key for envelope encryption of Kubernetes secrets
resource "aws_kms_key" "eks_kms_key" {
  description             = "EKS secrets encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow EKS cluster role to use key"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.eks_cluster_role.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Security group for EKS cluster control plane
resource "aws_security_group" "eks_cluster_sg" {
  name        = "md-k8s-cluster-sg"
  description = "Security group for EKS cluster control plane"
  vpc_id      = aws_vpc.eks_vpc.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "md-k8s-cluster-sg"
  }
}

# Security group for EKS worker nodes
resource "aws_security_group" "eks_node_sg" {
  name        = "md-k8s-node-sg"
  description = "Security group for EKS worker nodes"
  vpc_id      = aws_vpc.eks_vpc.id

  ingress {
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    self            = true
    description     = "Allow all traffic between nodes"
  }

  ingress {
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    security_groups = [aws_security_group.eks_cluster_sg.id]
    description     = "Allow all traffic from cluster security group"
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
    description = "Allow all outbound traffic within VPC CIDR"
  }

  tags = {
    Name = "md-k8s-node-sg"
  }
}

# EKS cluster
resource "aws_eks_cluster" "md_k8s" {
  name     = local.cluster_name
  role_arn = aws_iam_role.eks_cluster_role.arn

  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    endpoint_private_access = true
    endpoint_public_access  = false
    security_group_ids      = [aws_security_group.eks_cluster_sg.id]
  }

  encryption_config {
    provider {
      key_arn = aws_kms_key.eks_kms_key.arn
    }
    resources = ["secrets"]
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller,
    aws_iam_role_policy_attachment.eks_custom_ec2_cloudwatch
  ]
}

# Data source for current account ID (used in KMS key policy)
data "aws_caller_identity" "current" {}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# INPUT VARIABLES
# ---------------------------------------------------------------------------------------------------------------------
variable "namespace" {
  description = "Namespace for the label module (e.g., company or project abbreviation)"
  type        = string
  default     = null
}

variable "stage" {
  description = "Stage/environment (e.g., dev, staging, prod)"
  type        = string
  default     = null
}

variable "name" {
  description = "Name component for the bucket label"
  type        = string
  default     = "s3-bucket"
}

variable "delimiter" {
  description = "Delimiter used to join label parts"
  type        = string
  default     = "-"
}

variable "attributes" {
  description = "Additional attributes for the label (e.g., list of strings)"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags (map of strings) applied to all resources"
  type        = map(string)
  default     = {}
}

variable "enable_kms" {
  description = "Enable KMS server‑side encryption (false uses AES256)"
  type        = bool
  default     = true
}

variable "kms_key_id" {
  description = "Existing KMS key ARN; if null and enable_kms is true, a new key is created"
  type        = string
  default     = null
}

variable "acl" {
  description = "Canned ACL to apply to the bucket (e.g., private, public-read); null means no canned ACL"
  type        = string
  default     = null
}

variable "grants" {
  description = "List of fine‑grained ACL grants (used only when acl is null)"
  type = list(object({
    permission = string
    grantee = object({
      type          = string
      email_address = optional(string)
      id            = optional(string)
      uri           = optional(string)
    })
  }))
  default = []
}

variable "website" {
  description = "Static website hosting configuration"
  type = object({
    index_document = string
    error_document = optional(string)
    routing_rules  = optional(string) # JSON string of routing rules
  })
  default = null
}

variable "acceleration_status" {
  description = "Bucket acceleration status (Enabled or Suspended); null means no acceleration"
  type        = string
  default     = null
}

variable "requester_pays" {
  description = "Enable requester pays (true = Requester, false = BucketOwner)"
  type        = bool
  default     = false
}

variable "logging" {
  description = "Logging configuration (target_prefix); if set, a separate logging bucket is created"
  type = object({
    target_prefix = string
  })
  default = null
}

variable "object_lock_configuration" {
  description = "Object lock configuration with default retention"
  type = object({
    default_retention = object({
      mode  = string
      days  = optional(number)
      years = optional(number)
    })
  })
  default = null
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules for transitions and expirations"
  type = list(object({
    id     = string
    enabled = bool
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    expiration = optional(object({
      days                         = optional(number)
      expired_object_delete_marker = optional(bool)
    }))
    transitions = list(object({
      days          = number
      storage_class = string
    }))
    noncurrent_version_expiration = optional(object({
      days = number
    }))
    noncurrent_version_transitions = list(object({
      days          = number
      storage_class = string
    }))
  }))
  default = []
}

variable "cors_rules" {
  description = "List of CORS rules for the bucket"
  type = list(object({
    allowed_headers = list(string)
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "bucket_policy" {
  description = "Bucket policy configuration with statements"
  type = object({
    statements = list(object({
      effect    = string
      actions   = list(string)
      principals = list(object({
        type        = string
        identifiers = list(string)
      }))
      conditions = list(object({
        test     = string
        variable = string
        values   = list(string)
      }))
    }))
  })
  default = null
}

# ---------------------------------------------------------------------------------------------------------------------
# RANDOM SUFFIX FOR GLOBAL UNIQUENESS
# ---------------------------------------------------------------------------------------------------------------------
resource "random_pet" "this" {
  length    = 2
  separator = "-"
}

# ---------------------------------------------------------------------------------------------------------------------
# LABEL MODULE
# Generates consistent naming and tags for all resources.
# ---------------------------------------------------------------------------------------------------------------------
module "this" {
  source  = "cloudposse/label/null"
  version = "~> 0.25.0"

  namespace   = var.namespace
  stage       = var.stage
  name        = var.name
  delimiter   = var.delimiter
  attributes  = var.attributes
  tags        = var.tags
}

# ---------------------------------------------------------------------------------------------------------------------
# MAIN S3 BUCKET
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket" "this" {
  bucket = "${module.this.id}-${random_pet.this.id}"
  acl    = var.acl != null ? var.acl : null

  dynamic "website" {
    for_each = var.website != null ? [var.website] : []
    content {
      index_document = website.value.index_document
      error_document = website.value.error_document
      routing_rules  = website.value.routing_rules
    }
  }

  acceleration_status = var.acceleration_status
  request_payer       = var.requester_pays ? "Requester" : null

  dynamic "logging" {
    for_each = var.logging != null ? [var.logging] : []
    content {
      target_bucket = aws_s3_bucket.logging[0].id
      target_prefix = logging.value.target_prefix
    }
  }

  dynamic "object_lock_configuration" {
    for_each = var.object_lock_configuration != null ? [var.object_lock_configuration] : []
    content {
      object_lock_enabled = "Enabled"
      dynamic "rule" {
        for_each = object_lock_configuration.value.default_retention != null ? [object_lock_configuration.value.default_retention] : []
        content {
          default_retention {
            mode  = rule.value.mode
            days  = rule.value.days
            years = rule.value.years
          }
        }
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = module.this.tags
}

# ---------------------------------------------------------------------------------------------------------------------
# PUBLIC ACCESS BLOCK (always enforced)
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------------------------------------------------
# VERSIONING (main bucket)
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration {
    status = "Enabled"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# SERVER-SIDE ENCRYPTION
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.enable_kms ? "aws:kms" : "AES256"
      kms_master_key_id = var.enable_kms ? (var.kms_key_id != null ? var.kms_key_id : aws_kms_key.this[0].arn) : null
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# KMS KEY (if enabled and no key ID provided)
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_kms_key" "this" {
  count = var.enable_kms && var.kms_key_id == null ? 1 : 0

  description             = "KMS key for S3 bucket ${module.this.id}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  tags                    = module.this.tags
}

resource "aws_kms_alias" "this" {
  count = var.enable_kms && var.kms_key_id == null ? 1 : 0

  name          = "alias/${module.this.id}"
  target_key_id = aws_kms_key.this[0].key_id
}

# ---------------------------------------------------------------------------------------------------------------------
# LOGGING BUCKET (optional)
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket" "logging" {
  count = var.logging != null ? 1 : 0

  bucket = "${module.this.id}-logs-${random_pet.this.id}"

  lifecycle {
    prevent_destroy = true
  }

  tags = module.this.tags
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count = var.logging != null ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "logging" {
  count = var.logging != null ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count = var.logging != null ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# LIFECYCLE RULES (optional)
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = filter.value.prefix
          dynamic "and" {
            for_each = filter.value.tags != null ? [filter.value.tags] : []
            content {
              tags = and.value
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          days                         = expiration.value.days
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions
        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions
        content {
          noncurrent_days = noncurrent_version_transition.value.days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# CORS CONFIGURATION (optional)
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# BUCKET POLICY (optional)
# ---------------------------------------------------------------------------------------------------------------------
data "aws_iam_policy_document" "this" {
  count = var.bucket_policy != null ? 1 : 0

  dynamic "statement" {
    for_each = var.bucket_policy.statements
    content {
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = [aws_s3_bucket.this.arn, "${aws_s3_bucket.this.arn}/*"]

      dynamic "principals" {
        for_each = statement.value.principals
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count = var.bucket_policy != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.this[0].json
}

# ---------------------------------------------------------------------------------------------------------------------
# ACL GRANTS (fine‑grained, optional – only if no canned ACL is used)
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket_acl" "this" {
  count = var.acl == null && length(var.grants) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "access_control_policy" {
    for_each = [1]
    content {
      dynamic "grant" {
        for_each = var.grants
        content {
          permission = grant.value.permission
          grantee {
            type          = grant.value.grantee.type
            email_address = grant.value.grantee.email_address
            id            = grant.value.grantee.id
            uri           = grant.value.grantee.uri
          }
        }
      }
      owner {
        id = data.aws_caller_identity.current.account_id
      }
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCE FOR CURRENT ACCOUNT ID (used in ACL owner and elsewhere)
# ---------------------------------------------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------
output "bucket_id" {
  description = "The name of the bucket"
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the bucket"
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "The bucket domain name (bucket name + regional suffix)"
  value       = aws_s3_bucket.this.bucket_domain_name
}

output "tags" {
  description = "The tags applied to the bucket"
  value       = module.this.tags
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.0.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/18"
}

variable "az_count" {
  description = "Number of Availability Zones to use (0 = all available)"
  type        = number
  default     = 0
}

variable "create_public_subnets" {
  description = "Whether to create public subnets, IGW, public route table, and public NACL"
  type        = bool
  default     = true
}

variable "create_private_subnets" {
  description = "Whether to create private subnets, private route table, and private NACL"
  type        = bool
  default     = true
}

variable "create_nat_gateway" {
  description = "Whether to create a NAT Gateway for private subnets"
  type        = bool
  default     = true
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = {
    Environment = "benchmark"
    ManagedBy   = "terraform"
    Region      = var.aws_region
  }
  az_names = var.az_count == 0 ? data.aws_availability_zones.available.names : slice(data.aws_availability_zones.available.names, 0, var.az_count)
  az_count = length(local.az_names)

  # Subnet CIDR calculation: newbits=4 gives /22 subnets (16 total)
  # Public subnets: netnum from 0 to az_count-1
  # Private subnets: netnum from az_count to 2*az_count-1
  public_subnet_cidrs  = [for i in range(local.az_count) : cidrsubnet(var.vpc_cidr, 4, i)]
  private_subnet_cidrs = [for i in range(local.az_count) : cidrsubnet(var.vpc_cidr, 4, i + local.az_count)]
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = var.vpc_name
  })
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  count  = var.create_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-igw"
  })
}

# Public Subnets
resource "aws_subnet" "public" {
  count = var.create_public_subnets ? local.az_count : 0
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.az_names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-${local.az_names[count.index]}"
  })
}

# Private Subnets
resource "aws_subnet" "private" {
  count = var.create_private_subnets ? local.az_count : 0
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.az_names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-${local.az_names[count.index]}"
  })
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  count  = var.create_nat_gateway && var.create_public_subnets ? 1 : 0
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat-eip"
  })
}

# NAT Gateway
resource "aws_nat_gateway" "nat" {
  count         = var.create_nat_gateway && var.create_public_subnets ? 1 : 0
  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id
  depends_on    = [aws_internet_gateway.igw]

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat"
  })
}

# Public Route Table
resource "aws_route_table" "public" {
  count  = var.create_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw[0].id
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = var.create_public_subnets ? local.az_count : 0
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# Private Route Table
resource "aws_route_table" "private" {
  count  = var.create_private_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  dynamic "route" {
    for_each = var.create_nat_gateway && var.create_public_subnets ? [1] : []
    content {
      cidr_block     = "0.0.0.0/0"
      nat_gateway_id = aws_nat_gateway.nat[0].id
    }
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count          = var.create_private_subnets ? local.az_count : 0
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# Public Network ACL
resource "aws_network_acl" "public" {
  count  = var.create_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-nacl"
  })
}

resource "aws_network_acl_rule" "public_ingress_ssh" {
  count          = var.create_public_subnets ? 1 : 0
  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 100
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 22
  to_port        = 22
}

resource "aws_network_acl_rule" "public_ingress_http" {
  count          = var.create_public_subnets ? 1 : 0
  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 110
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_ingress_https" {
  count          = var.create_public_subnets ? 1 : 0
  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 120
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "public_egress" {
  count          = var.create_public_subnets ? 1 : 0
  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_association" "public" {
  count          = var.create_public_subnets ? local.az_count : 0
  subnet_id      = aws_subnet.public[count.index].id
  network_acl_id = aws_network_acl.public[0].id
}

# Private Network ACL
resource "aws_network_acl" "private" {
  count  = var.create_private_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-nacl"
  })
}

resource "aws_network_acl_rule" "private_ingress" {
  count          = var.create_private_subnets ? 1 : 0
  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 100
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = var.vpc_cidr
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_rule" "private_egress" {
  count          = var.create_private_subnets ? 1 : 0
  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_association" "private" {
  count          = var.create_private_subnets ? local.az_count : 0
  subnet_id      = aws_subnet.private[count.index].id
  network_acl_id = aws_network_acl.private[0].id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100.0"
    }
  }
}

variable "is_ipv6_enabled" {
  type    = bool
  default = true
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block                       = "10.16.0.0/16"
  assign_generated_ipv6_cidr_block = var.is_ipv6_enabled
  instance_tenancy                 = "default"
  enable_dns_hostnames             = true
  enable_dns_support               = true

  tags = {
    Name = "main-vpc"
  }
}

locals {
  azs = data.aws_availability_zones.available.names

  # Define 12 subnets across 3 AZs: web (public), app (private), database (private), reserved (private)
  sn_details = [
    # Web (public)
    { name = "web-az1", az = local.azs[0], public = true },
    { name = "web-az2", az = local.azs[1], public = true },
    { name = "web-az3", az = local.azs[2], public = true },
    # App (private)
    { name = "app-az1", az = local.azs[0], public = false },
    { name = "app-az2", az = local.azs[1], public = false },
    { name = "app-az3", az = local.azs[2], public = false },
    # Database (private)
    { name = "db-az1", az = local.azs[0], public = false },
    { name = "db-az2", az = local.azs[1], public = false },
    { name = "db-az3", az = local.azs[2], public = false },
    # Reserved (private)
    { name = "reserved-az1", az = local.azs[0], public = false },
    { name = "reserved-az2", az = local.azs[1], public = false },
    { name = "reserved-az3", az = local.azs[2], public = false },
  ]
}

module "subnet_calculator" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = aws_vpc.main.cidr_block

  networks = [
    for s in local.sn_details : {
      name              = s.name
      new_bits          = 4   # /20 subnets for IPv4
      availability_zone = s.az
    }
  ]
}

resource "aws_subnet" "this" {
  count = length(local.sn_details)

  vpc_id = aws_vpc.main.id

  cidr_block        = module.subnet_calculator.networks[count.index].cidr_block
  ipv6_cidr_block   = var.is_ipv6_enabled ? cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index) : null
  availability_zone = local.sn_details[count.index].az

  map_public_ip_on_launch = false

  tags = {
    Name = local.sn_details[count.index].name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw-vpc-${aws_vpc.main.id}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "public-rt-web"
  }
}

resource "aws_route" "public_ipv4" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6" {
  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = length([for s in local.sn_details : s if s.public])

  subnet_id      = aws_subnet.this[tonumber(keys({for idx, s in local.sn_details : idx => s if s.public})[count.index])].id
  route_table_id = aws_route_table.public.id
}

# Security groups
resource "aws_security_group" "web_sg" {
  name        = "web-sg"
  description = "Security group for web tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "web-sg"
  }
}

resource "aws_security_group" "app_sg" {
  name        = "app-sg"
  description = "Security group for app tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "app-sg"
  }
}

resource "aws_security_group" "db_sg" {
  name        = "db-sg"
  description = "Security group for database tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "db-sg"
  }
}

# Ingress rules for web_sg
resource "aws_security_group_rule" "web_ingress_https" {
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.web_sg.id
}

resource "aws_security_group_rule" "web_ingress_ssh" {
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.web_sg.id
}

# Egress rule from web_sg to app_sg (port 443)
resource "aws_security_group_rule" "web_egress_to_app" {
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.app_sg.id
  security_group_id        = aws_security_group.web_sg.id
}

# Ingress rule for app_sg from web_sg (port 443)
resource "aws_security_group_rule" "app_ingress_from_web" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.web_sg.id
  security_group_id        = aws_security_group.app_sg.id
}

# Egress rule from app_sg to db_sg (port 443)
resource "aws_security_group_rule" "app_egress_to_db" {
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.db_sg.id
  security_group_id        = aws_security_group.app_sg.id
}

# Ingress rule for db_sg from app_sg (port 443)
resource "aws_security_group_rule" "db_ingress_from_app" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.app_sg.id
  security_group_id        = aws_security_group.db_sg.id
}

terraform {
  required_version = "~> 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.99.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Random pet name for IAM role prefix
resource "random_pet" "role_prefix" {
  length = 2
}

# IAM role for Lambda execution
resource "aws_iam_role" "canary_execution" {
  name = "${random_pet.role_prefix.id}-lambda-exec"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM policy for canary execution
resource "aws_iam_policy" "canary_execution" {
  name        = "${random_pet.role_prefix.id}-canary-policy"
  description = "Policy for CloudWatch Synthetics canary execution"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.canary_bucket.arn,
          "${aws_s3_bucket.canary_bucket.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "cloudwatch:PutMetricData"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "canary_execution" {
  role       = aws_iam_role.canary_execution.name
  policy_arn = aws_iam_policy.canary_execution.arn
}

# KMS key for S3 and SNS encryption (optional toggle)
variable "enable_kms_key" {
  description = "Toggle to create a custom KMS key for encryption"
  type        = bool
  default     = true
}

resource "aws_kms_key" "canary_key" {
  count                   = var.enable_kms_key ? 1 : 0
  description             = "KMS key for CloudWatch Synthetics canary artifacts and SNS"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable root account permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Synthetics to use the key"
        Effect = "Allow"
        Principal = {
          Service = "synthetics.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "canary_key" {
  count         = var.enable_kms_key ? 1 : 0
  name          = "alias/benchmark-canary-key"
  target_key_id = aws_kms_key.canary_key[0].key_id
}

# S3 bucket for canary artifacts
resource "aws_s3_bucket" "canary_bucket" {
  bucket        = "benchmark-canary-bucket-${random_pet.role_prefix.id}"
  force_destroy = true
}

variable "bucket_versioning_enabled" {
  description = "Enable S3 bucket versioning"
  type        = bool
  default     = false
}

resource "aws_s3_bucket_versioning" "canary_bucket" {
  bucket = aws_s3_bucket.canary_bucket.id
  versioning_configuration {
    status = var.bucket_versioning_enabled ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_public_access_block" "canary_bucket" {
  bucket                  = aws_s3_bucket.canary_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_cors_configuration" "canary_bucket" {
  bucket = aws_s3_bucket.canary_bucket.id
  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "PUT", "POST", "DELETE", "HEAD"]
    allowed_origins = ["*"]
    expose_headers  = []
    max_age_seconds = 3600
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "canary_bucket" {
  bucket = aws_s3_bucket.canary_bucket.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = try(aws_kms_key.canary_key[0].arn, null)
      sse_algorithm     = var.enable_kms_key ? "aws:kms" : "AES256"
    }
  }
}

# SNS topic for alarms
resource "aws_sns_topic" "canary_alarms" {
  name              = "benchmark-canary-topic"
  kms_master_key_id = try(aws_kms_key.canary_key[0].arn, null)
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sns_topic_policy" "canary_alarms" {
  arn = aws_sns_topic.canary_alarms.arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.canary_alarms.arn
      }
    ]
  })
}

variable "alarm_email" {
  description = "Email address for SNS subscription"
  type        = string
  default     = "nobody@example.com"
}

resource "aws_sns_topic_subscription" "email_subscription" {
  topic_arn = aws_sns_topic.canary_alarms.arn
  protocol  = "email"
  endpoint  = var.alarm_email
}

# Data sources
data "aws_caller_identity" "current" {}

# Canary configurations variable
variable "canary_configs" {
  description = "Map of canary configurations"
  type = map(object({
    subnet_ids         = list(string)
    security_group_ids = list(string)
    source_type        = string # "inline" or "s3"
    inline_zip         = optional(string) # base64 encoded zip
    s3_bucket          = optional(string)
    s3_key             = optional(string)
    schedule_expression = string
  }))
  default = {}
}

# CloudWatch Synthetics canaries
resource "aws_synthetics_canary" "this" {
  for_each = var.canary_configs

  name                 = each.key
  execution_role_arn   = aws_iam_role.canary_execution.arn
  artifact_s3_location = "s3://${aws_s3_bucket.canary_bucket.id}/"
  runtime_version      = "syn-nodejs-puppeteer-7.0"
  handler              = "index.handler"

  schedule {
    expression = each.value.schedule_expression
  }

  run_config {
    timeout_in_seconds = 120
  }

  vpc_config {
    subnet_ids         = each.value.subnet_ids
    security_group_ids = each.value.security_group_ids
  }

  # Conditional source configuration
  zip_file   = each.value.source_type == "inline" ? each.value.inline_zip : null
  s3_bucket  = each.value.source_type == "s3" ? each.value.s3_bucket : null
  s3_key     = each.value.source_type == "s3" ? each.value.s3_key : null
}

# CloudWatch metric alarm for Failure (>=1 in 60s)
resource "aws_cloudwatch_metric_alarm" "failure_alarm" {
  for_each = var.canary_configs

  alarm_name          = "${each.key}-failure-alarm"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = "1"
  metric_name         = "Failure"
  namespace           = "CloudWatchSynthetics"
  period              = "60"
  statistic           = "Sum"
  threshold           = "1"
  alarm_description   = "Alarm when canary ${each.key} fails 1 or more times in 60 seconds"
  alarm_actions       = [aws_sns_topic.canary_alarms.arn]

  dimensions = {
    CanaryName = each.key
  }
}

# Conditional success percent alarm
variable "enable_success_percent_alarm" {
  description = "Enable success percent alarm with OK notification"
  type        = bool
  default     = false
}

resource "aws_cloudwatch_metric_alarm" "success_percent_alarm" {
  for_each = var.enable_success_percent_alarm ? var.canary_configs : {}

  alarm_name          = "${each.key}-success-percent-alarm"
  comparison_operator = "LessThanThreshold"
  evaluation_periods  = "1"
  metric_name         = "SuccessPercent"
  namespace           = "CloudWatchSynthetics"
  period              = "60"
  statistic           = "Average"
  threshold           = "90"
  alarm_description   = "Alarm when canary ${each.key} success percent falls below 90%"
  ok_actions          = [aws_sns_topic.canary_alarms.arn]
  alarm_actions       = []

  dimensions = {
    CanaryName = each.key
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  create = var.create_vpc

  # Resolve availability zones: use variable if provided, otherwise fall back to data source
  azs = var.azs != null ? var.azs : data.aws_availability_zones.available.names

  # Subnet name generation
  public_subnet_names = var.public_subnet_names != null ? var.public_subnet_names : [
    for idx, az in local.azs : "${var.vpc_cidr}-${var.public_subnet_suffix}-${az}"
  ]
  private_subnet_names = var.private_subnet_names != null ? var.private_subnet_names : [
    for idx, az in local.azs : "${var.vpc_cidr}-${var.private_subnet_suffix}-${az}"
  ]
  intra_subnet_names = var.intra_subnet_names != null ? var.intra_subnet_names : [
    for idx, az in local.azs : "${var.vpc_cidr}-${var.intra_subnet_suffix}-${az}"
  ]

  # Number of NAT gateways = min(public_subnets, private_subnets) when both exist
  nat_gateway_count = local.create && var.enable_nat_gateway && length(var.public_subnets) > 0 && length(var.private_subnets) > 0 ? min(length(var.public_subnets), length(var.private_subnets)) : 0
}

# VPC
resource "aws_vpc" "this" {
  count = local.create ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = merge(var.tags, {
    Name = "${var.vpc_cidr}-vpc"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Public subnets
resource "aws_subnet" "public" {
  count = local.create ? length(var.public_subnets) : 0

  vpc_id                  = aws_vpc.this[0].id
  cidr_block              = var.public_subnets[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(var.tags, {
    Name = local.public_subnet_names[count.index]
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count = local.create ? length(var.private_subnets) : 0

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = var.private_subnets[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(var.tags, {
    Name = local.private_subnet_names[count.index]
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Intra subnets
resource "aws_subnet" "intra" {
  count = local.create ? length(var.intra_subnets) : 0

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = var.intra_subnets[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(var.tags, {
    Name = local.intra_subnet_names[count.index]
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Internet Gateway
resource "aws_internet_gateway" "this" {
  count = local.create && var.create_igw && length(var.public_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, {
    Name = "${var.vpc_cidr}-igw"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Public route table
resource "aws_route_table" "public" {
  count = local.create && length(var.public_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, {
    Name = "${var.vpc_cidr}-public"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Route to IGW in public route table
resource "aws_route" "public_internet_gateway" {
  count = local.create && var.create_igw && length(var.public_subnets) > 0 ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

# Public subnet associations
resource "aws_route_table_association" "public" {
  count = local.create ? length(var.public_subnets) : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# Elastic IPs for NAT Gateways
resource "aws_eip" "nat" {
  count = local.nat_gateway_count

  domain = "vpc"

  tags = merge(var.tags, {
    Name = "${var.vpc_cidr}-nat-${count.index + 1}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# NAT Gateways (one per private subnet, placed in the corresponding public subnet)
resource "aws_nat_gateway" "this" {
  count = local.nat_gateway_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(var.tags, {
    Name = "${var.vpc_cidr}-nat-${count.index + 1}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Private route tables (one per private subnet)
resource "aws_route_table" "private" {
  count = local.create ? length(var.private_subnets) : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, {
    Name = "${var.vpc_cidr}-private-${local.azs[count.index]}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Routes to NAT in private route tables
resource "aws_route" "private_nat_gateway" {
  count = local.create && var.enable_nat_gateway && local.nat_gateway_count > 0 ? length(var.private_subnets) : 0

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[count.index].id
}

# Private subnet associations
resource "aws_route_table_association" "private" {
  count = local.create ? length(var.private_subnets) : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# Intra route tables (one per intra subnet, no default route)
resource "aws_route_table" "intra" {
  count = local.create ? length(var.intra_subnets) : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, {
    Name = "${var.vpc_cidr}-intra-${local.azs[count.index]}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Intra subnet associations
resource "aws_route_table_association" "intra" {
  count = local.create ? length(var.intra_subnets) : 0

  subnet_id      = aws_subnet.intra[count.index].id
  route_table_id = aws_route_table.intra[count.index].id
}

# Variables
variable "create_vpc" {
  description = "Toggle to create all VPC resources"
  type        = bool
  default     = true
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "azs" {
  description = "List of availability zone names or IDs (defaults to all available AZs)"
  type        = list(string)
  default     = null
}

variable "public_subnets" {
  description = "List of CIDR blocks for public subnets"
  type        = list(string)
  default     = []
}

variable "private_subnets" {
  description = "List of CIDR blocks for private subnets"
  type        = list(string)
  default     = []
}

variable "intra_subnets" {
  description = "List of CIDR blocks for intra subnets"
  type        = list(string)
  default     = []
}

variable "public_subnet_names" {
  description = "Explicit names for public subnets (overrides auto-generation)"
  type        = list(string)
  default     = null
}

variable "private_subnet_names" {
  description = "Explicit names for private subnets (overrides auto-generation)"
  type        = list(string)
  default     = null
}

variable "intra_subnet_names" {
  description = "Explicit names for intra subnets (overrides auto-generation)"
  type        = list(string)
  default     = null
}

variable "public_subnet_suffix" {
  description = "Suffix for auto-generated public subnet names"
  type        = string
  default     = "public"
}

variable "private_subnet_suffix" {
  description = "Suffix for auto-generated private subnet names"
  type        = string
  default     = "private"
}

variable "intra_subnet_suffix" {
  description = "Suffix for auto-generated intra subnet names"
  type        = string
  default     = "intra"
}

variable "map_public_ip_on_launch" {
  description = "Assign public IP to instances launched in public subnets"
  type        = bool
  default     = false
}

variable "create_igw" {
  description = "Toggle to create an Internet Gateway"
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Toggle to create NAT Gateways and associated routes"
  type        = bool
  default     = false
}

variable "tags" {
  description = "Additional tags for all resources"
  type        = map(string)
  default     = {}
}

# Outputs
output "vpc_id" {
  description = "ID of the VPC"
  value       = try(aws_vpc.this[0].id, null)
}

output "public_subnet_ids" {
  description = "IDs of public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of private subnets"
  value       = aws_subnet.private[*].id
}

output "intra_subnet_ids" {
  description = "IDs of intra subnets"
  value       = aws_subnet.intra[*].id
}

output "public_route_table_ids" {
  description = "IDs of public route tables"
  value       = aws_route_table.public[*].id
}

output "private_route_table_ids" {
  description = "IDs of private route tables"
  value       = aws_route_table.private[*].id
}

output "intra_route_table_ids" {
  description = "IDs of intra route tables"
  value       = aws_route_table.intra[*].id
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway (if created)"
  value       = try(aws_internet_gateway.this[0].id, null)
}

output "nat_gateway_ids" {
  description = "IDs of NAT Gateways (if created)"
  value       = aws_nat_gateway.this[*].id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.0.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# Variables
variable "api_type" {
  description = "Type of API Gateway: 'http' or 'rest'"
  type        = string
  default     = "http"
}

variable "api_name" {
  description = "Name of the API"
  type        = string
  default     = "benchmark-api"
}

variable "environment_name" {
  description = "Environment name used for stage names"
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets (at least 2)"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "custom_domain_name" {
  description = "Custom domain name for the API (optional)"
  type        = string
  default     = ""
}

variable "route53_zone_id" {
  description = "Route53 hosted zone ID for custom domain (optional)"
  type        = string
  default     = ""
}

variable "enable_http_vpc_link" {
  description = "Enable VPC link for HTTP API"
  type        = bool
  default     = false
}

variable "enable_rest_vpc_link" {
  description = "Enable VPC link for REST API"
  type        = bool
  default     = false
}

variable "target_alb_private_ip" {
  description = "Private IP of the ALB for REST VPC link target"
  type        = string
  default     = "10.0.1.100"
}

variable "http_routes" {
  description = "Map of HTTP API routes: key = route identifier, value = object with route_key, target, integration_type, etc."
  type = map(object({
    route_key        = string
    target           = string
    integration_type = string
  }))
  default = {}
}

variable "rest_paths" {
  description = "List of REST API paths with methods"
  type = list(object({
    path       = string
    http_method = string
  }))
  default = []
}

variable "allowed_ip_cidrs" {
  description = "List of allowed IP CIDRs for REST API resource policy"
  type        = list(string)
  default     = []
}

# Local values
locals {
  stage_name = "${var.environment_name}-stage"
  is_http    = var.api_type == "http"
  is_rest    = var.api_type == "rest"
}

# VPC and Subnets
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "${var.api_name}-vpc"
  }
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = {
    Name = "${var.api_name}-private-${count.index}"
  }
}

# ========== HTTP API (v2) ==========
resource "aws_apigatewayv2_api" "http" {
  count          = local.is_http ? 1 : 0
  name           = var.api_name
  protocol_type  = "HTTP"
}

resource "aws_apigatewayv2_integration" "http" {
  for_each       = local.is_http ? var.http_routes : {}
  api_id         = aws_apigatewayv2_api.http[0].id
  integration_type = each.value.integration_type
  integration_uri   = each.value.target
}

resource "aws_apigatewayv2_route" "http" {
  for_each   = local.is_http ? var.http_routes : {}
  api_id     = aws_apigatewayv2_api.http[0].id
  route_key  = each.value.route_key
  target     = "integrations/${aws_apigatewayv2_integration.http[each.key].id}"
}

resource "aws_apigatewayv2_stage" "http" {
  count       = local.is_http ? 1 : 0
  api_id      = aws_apigatewayv2_api.http[0].id
  name        = local.stage_name
  auto_deploy = true
}

# Security group for HTTP VPC link
resource "aws_security_group" "http_vpc_link" {
  count       = local.is_http && var.enable_http_vpc_link ? 1 : 0
  name        = "${var.api_name}-vpc-link-sg"
  description = "Security group for HTTP API VPC link"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.api_name}-vpc-link-sg"
  }
}

# HTTP VPC Link
resource "aws_apigatewayv2_vpc_link" "http" {
  count              = local.is_http && var.enable_http_vpc_link ? 1 : 0
  name               = "${var.api_name}-vpc-link"
  subnet_ids         = aws_subnet.private[*].id
  security_group_ids = [aws_security_group.http_vpc_link[0].id]
}

# Custom Domain for HTTP
resource "aws_acm_certificate" "http" {
  count                     = local.is_http && var.custom_domain_name != "" ? 1 : 0
  domain_name               = var.custom_domain_name
  validation_method         = "DNS"
  subject_alternative_names = []
  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_route53_record" "http_cert_validation" {
  for_each = local.is_http && var.custom_domain_name != "" && var.route53_zone_id != "" ? {
    for dvo in aws_acm_certificate.http[0].domain_validation_options : dvo.domain_name => {
      name   = dvo.resource_record_name
      record = dvo.resource_record_value
      type   = dvo.resource_record_type
    }
  } : {}
  zone_id = var.route53_zone_id
  name    = each.value.name
  type    = each.value.type
  records = [each.value.record]
  ttl     = 60
}

resource "aws_acm_certificate_validation" "http" {
  count                   = local.is_http && var.custom_domain_name != "" ? 1 : 0
  certificate_arn         = aws_acm_certificate.http[0].arn
  validation_record_fqdns = [for record in aws_route53_record.http_cert_validation : record.fqdn]
}

resource "aws_apigatewayv2_domain_name" "http" {
  count       = local.is_http && var.custom_domain_name != "" ? 1 : 0
  domain_name = var.custom_domain_name
  domain_name_configuration {
    certificate_arn = aws_acm_certificate.http[0].arn
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }
}

resource "aws_apigatewayv2_api_mapping" "http" {
  count       = local.is_http && var.custom_domain_name != "" ? 1 : 0
  api_id      = aws_apigatewayv2_api.http[0].id
  domain_name = aws_apigatewayv2_domain_name.http[0].id
  stage       = aws_apigatewayv2_stage.http[0].id
}

resource "aws_route53_record" "http_alias" {
  count   = local.is_http && var.custom_domain_name != "" && var.route53_zone_id != "" ? 1 : 0
  zone_id = var.route53_zone_id
  name    = var.custom_domain_name
  type    = "A"
  alias {
    name                   = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].target_domain_name
    zone_id                = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].hosted_zone_id
    evaluate_target_health = false
  }
}

# ========== REST API (v1) ==========
resource "aws_api_gateway_rest_api" "rest" {
  count       = local.is_rest ? 1 : 0
  name        = var.api_name
  description = "REST API managed by Terraform"
}

# Dynamic resource paths
resource "aws_api_gateway_resource" "rest" {
  for_each = local.is_rest ? { for idx, path in var.rest_paths : idx => path } : {}
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  parent_id   = aws_api_gateway_rest_api.rest[0].root_resource_id
  path_part   = each.value.path
}

resource "aws_api_gateway_method" "rest" {
  for_each    = local.is_rest ? { for idx, path in var.rest_paths : idx => path } : {}
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  resource_id = aws_api_gateway_resource.rest[each.key].id
  http_method = each.value.http_method
  authorization = "NONE"
  request_parameters = {}
}

# IP source restriction resource policy
resource "aws_api_gateway_rest_api_policy" "rest" {
  count       = local.is_rest && length(var.allowed_ip_cidrs) > 0 ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = "*"
        Action    = "execute-api:Invoke"
        Resource  = "${aws_api_gateway_rest_api.rest[0].arn}/*"
        Condition = {
          IpAddress = {
            "aws:SourceIp" = var.allowed_ip_cidrs
          }
        }
      }
    ]
  })
}

# Deployment with trigger based on resources hash
locals {
  rest_resources_hash = sha256(jsonencode(var.rest_paths))
}

resource "aws_api_gateway_deployment" "rest" {
  count       = local.is_rest ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  triggers = {
    redeployment = local.rest_resources_hash
  }
  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_stage" "rest" {
  count         = local.is_rest ? 1 : 0
  stage_name    = local.stage_name
  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  deployment_id = aws_api_gateway_deployment.rest[0].id
}

# Usage Plan and API Key
resource "aws_api_gateway_usage_plan" "rest" {
  count       = local.is_rest ? 1 : 0
  name        = "${var.api_name}-usage-plan"
  description = "Usage plan for ${var.api_name}"
  api_stages {
    api_id = aws_api_gateway_rest_api.rest[0].id
    stage  = aws_api_gateway_stage.rest[0].stage_name
  }
}

resource "aws_api_gateway_api_key" "rest" {
  count       = local.is_rest ? 1 : 0
  name        = "${var.api_name}-api-key"
  description = "API Key for ${var.api_name}"
  enabled     = true
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_api_gateway_usage_plan_key" "rest" {
  count         = local.is_rest ? 1 : 0
  key_id        = aws_api_gateway_api_key.rest[0].id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.rest[0].id
}

resource "aws_ssm_parameter" "rest_api_key" {
  count       = local.is_rest ? 1 : 0
  name        = "/${var.api_name}/api-key"
  description = "API Key for ${var.api_name} (SecureString)"
  type        = "SecureString"
  value       = aws_api_gateway_api_key.rest[0].value
  lifecycle {
    prevent_destroy = true
  }
}

# Lambda Authorizer
data "archive_file" "authorizer_zip" {
  count       = local.is_rest ? 1 : 0
  type        = "zip"
  output_path = "${path.module}/authorizer.zip"
  source {
    content  = <<-EOF
exports.handler = async (event) => {
    return {
        principalId: 'user',
        policyDocument: {
            Version: '2012-10-17',
            Statement: [{
                Action: 'execute-api:Invoke',
                Effect: 'Allow',
                Resource: event.methodArn
            }]
        }
    };
};
EOF
    filename = "index.js"
  }
}

resource "aws_iam_role" "lambda_exec" {
  count = local.is_rest ? 1 : 0
  name  = "${var.api_name}-lambda-exec-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_exec" {
  count      = local.is_rest ? 1 : 0
  role       = aws_iam_role.lambda_exec[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "authorizer" {
  count         = local.is_rest ? 1 : 0
  filename      = data.archive_file.authorizer_zip[0].output_path
  function_name = "${var.api_name}-authorizer"
  role          = aws_iam_role.lambda_exec[0].arn
  handler       = "index.handler"
  runtime       = "nodejs16.x"
  source_code_hash = data.archive_file.authorizer_zip[0].output_base64sha256
}

# IAM role for API Gateway to invoke authorizer
resource "aws_iam_role" "api_gateway_invoke" {
  count = local.is_rest ? 1 : 0
  name  = "${var.api_name}-apigw-invoke-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "apigw_invoke_lambda" {
  count = local.is_rest ? 1 : 0
  name  = "${var.api_name}-apigw-invoke-policy"
  role  = aws_iam_role.api_gateway_invoke[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "lambda:InvokeFunction"
        Resource = aws_lambda_function.authorizer[0].arn
      }
    ]
  })
}

resource "aws_api_gateway_authorizer" "rest" {
  count                   = local.is_rest ? 1 : 0
  name                    = "${var.api_name}-authorizer"
  rest_api_id             = aws_api_gateway_rest_api.rest[0].id
  authorizer_uri          = aws_lambda_function.authorizer[0].invoke_arn
  authorizer_credentials  = aws_iam_role.api_gateway_invoke[0].arn
  authorizer_result_ttl_in_seconds = 300
  type                    = "TOKEN"
  identity_source         = "method.request.header.Authorization"
}

# REST VPC Link
resource "aws_lb" "nlb" {
  count              = local.is_rest && var.enable_rest_vpc_link ? 1 : 0
  name               = "${var.api_name}-nlb"
  internal           = true
  load_balancer_type = "network"
  subnets            = aws_subnet.private[*].id
}

resource "aws_lb_target_group" "nlb" {
  count       = local.is_rest && var.enable_rest_vpc_link ? 1 : 0
  name        = "${var.api_name}-tg"
  port        = 443
  protocol    = "TCP"
  target_type = "ip"
  vpc_id      = aws_vpc.main.id
  health_check {
    protocol = "HTTPS"
    port     = "443"
    path     = "/"
  }
}

resource "aws_lb_target_group_attachment" "nlb" {
  count            = local.is_rest && var.enable_rest_vpc_link ? 1 : 0
  target_group_arn = aws_lb_target_group.nlb[0].arn
  target_id        = var.target_alb_private_ip
  port             = 443
}

resource "aws_lb_listener" "nlb" {
  count             = local.is_rest && var.enable_rest_vpc_link ? 1 : 0
  load_balancer_arn = aws_lb.nlb[0].arn
  port              = 443
  protocol          = "TCP"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.nlb[0].arn
  }
}

resource "aws_api_gateway_vpc_link" "rest" {
  count       = local.is_rest && var.enable_rest_vpc_link ? 1 : 0
  name        = "${var.api_name}-vpc-link"
  target_arns = [aws_lb.nlb[0].arn]
}

terraform {
  required_version = "~> 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.0.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "bucket_name" {
  description = "Override the auto-generated S3 bucket name. If empty, a name is generated."
  type        = string
  default     = ""
}

variable "force_destroy_bucket" {
  description = "Allow the S3 bucket to be destroyed even if it contains objects."
  type        = bool
  default     = true
}

variable "bucket_versioning_enabled" {
  description = "Enable versioning on the S3 bucket."
  type        = bool
  default     = false
}

variable "cloudwatch_logs_retention" {
  description = "Number of days to retain CloudWatch logs."
  type        = number
  default     = 90
}

variable "kms_alias_prefix" {
  description = "Prefix for the KMS key alias."
  type        = string
  default     = "alias/cloudtrail-"
}

variable "kms_key_deletion_window" {
  description = "Deletion window in days for the KMS key."
  type        = number
  default     = 30
}

variable "kms_key_decryption_role_arn" {
  description = "ARN of an IAM role that is allowed to decrypt CloudTrail logs (optional)."
  type        = string
  default     = ""
}

variable "create_sns_topic" {
  description = "Create an SNS topic for CloudTrail alerts."
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "ARN of an existing SNS topic for CloudTrail alerts (used only if create_sns_topic is false)."
  type        = string
  default     = ""
}

variable "enable_log_file_validation" {
  description = "Enable log file validation for the CloudTrail trail."
  type        = bool
  default     = true
}

variable "include_global_service_events" {
  description = "Include global service events in the trail."
  type        = bool
  default     = true
}

variable "is_multi_region_trail" {
  description = "Create a multi-region trail."
  type        = bool
  default     = true
}

variable "enable_logging" {
  description = "Enable logging for the trail."
  type        = bool
  default     = true
}

variable "is_organization_trail" {
  description = "Create an organization trail (requires AWS Organizations)."
  type        = bool
  default     = false
}

variable "read_write_type" {
  description = "Type of read/write events to log: 'All', 'ReadOnly', 'WriteOnly'."
  type        = string
  default     = "All"
}

variable "include_management_events" {
  description = "Include management events in the event selector."
  type        = bool
  default     = true
}

variable "tags" {
  description = "Tags to apply to resources."
  type        = map(string)
  default     = {}
}

# ------------------------------------------------------------------------------
# Data sources
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# Random suffix
# ------------------------------------------------------------------------------
resource "random_string" "cloudtrail_suffix" {
  length  = 8
  special = false
  lower   = true
  upper   = false
}

# ------------------------------------------------------------------------------
# Local values
# ------------------------------------------------------------------------------
locals {
  bucket_name = var.bucket_name != "" ? var.bucket_name : "cloudtrail-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}-${lower(random_string.cloudtrail_suffix.result)}"

  sns_topic_name = var.create_sns_topic ? aws_sns_topic.cloudtrail[0].name : (
    var.sns_topic_arn != "" ? split(":", var.sns_topic_arn)[5] : ""
  )

  # Conditionally include sns_topic_name in CloudTrail only if one is available
  has_sns = var.create_sns_topic || var.sns_topic_arn != ""
}

# ------------------------------------------------------------------------------
# S3 Bucket
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "cloudtrail" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy_bucket

  tags = merge(var.tags, {
    Name = local.bucket_name
  })
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cloudtrail.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  versioning_configuration {
    status = var.bucket_versioning_enabled ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  policy = data.aws_iam_policy_document.s3_bucket_policy.json
}

data "aws_iam_policy_document" "s3_bucket_policy" {
  statement {
    sid    = "AllowCloudTrailAclCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail.arn]
  }

  statement {
    sid    = "AllowCloudTrailPutObject"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail.arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowCloudTrailPutObjectOrganization"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail.arn}/AWSLogs/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

# ------------------------------------------------------------------------------
# KMS Key
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "kms_key_policy" {
  # Allow root account full access
  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  # Allow CloudTrail to use the key
  statement {
    sid    = "AllowCloudTrailToUseKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey"
    ]

    resources = ["*"]

    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:cloudtrail:arn"
      values   = ["arn:aws:cloudtrail:*:${data.aws_caller_identity.current.account_id}:trail/*"]
    }
  }

  # Allow CloudWatch Logs to use the key
  statement {
    sid    = "AllowCloudWatchLogsToUseKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]

    resources = ["*"]
  }

  # Allow S3 to use the key for SSE-KMS
  statement {
    sid    = "AllowS3ToUseKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:EncryptionContext:aws:s3:arn"
      values   = [aws_s3_bucket.cloudtrail.arn]
    }
  }

  # Allow optional decryption role
  dynamic "statement" {
    for_each = var.kms_key_decryption_role_arn != "" ? [1] : []
    content {
      sid    = "AllowDecryptionRole"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = [var.kms_key_decryption_role_arn]
      }

      actions = [
        "kms:Decrypt",
        "kms:DescribeKey"
      ]

      resources = ["*"]
    }
  }
}

resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key for CloudTrail log encryption"
  deletion_window_in_days = var.kms_key_deletion_window
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = var.tags
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "${var.kms_alias_prefix}${random_string.cloudtrail_suffix.result}"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

# ------------------------------------------------------------------------------
# CloudWatch Logs
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = "/aws/cloudtrail/${local.bucket_name}"
  retention_in_days = var.cloudwatch_logs_retention

  tags = var.tags
}

# IAM role for CloudTrail to write logs to CloudWatch
resource "aws_iam_role" "cloudtrail_cloudwatch_logs" {
  name               = "CloudTrailCloudWatchLogsRole"
  assume_role_policy = data.aws_iam_policy_document.cloudtrail_assume_role.json

  tags = var.tags
}

data "aws_iam_policy_document" "cloudtrail_assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_policy" "cloudtrail_cloudwatch_logs" {
  name   = "CloudTrailCloudWatchLogsPolicy"
  policy = data.aws_iam_policy_document.cloudtrail_cloudwatch_logs_policy.json

  tags = var.tags
}

data "aws_iam_policy_document" "cloudtrail_cloudwatch_logs_policy" {
  statement {
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]

    resources = ["${aws_cloudwatch_log_group.cloudtrail.arn}:*"]
  }
}

resource "aws_iam_role_policy_attachment" "cloudtrail_cloudwatch_logs" {
  role       = aws_iam_role.cloudtrail_cloudwatch_logs.name
  policy_arn = aws_iam_policy.cloudtrail_cloudwatch_logs.arn
}

# ------------------------------------------------------------------------------
# CloudTrail Trail
# ------------------------------------------------------------------------------
resource "aws_cloudtrail" "cloudtrail" {
  name                          = "cloudtrail-${local.bucket_name}"
  s3_bucket_name                = aws_s3_bucket.cloudtrail.id
  s3_key_prefix                 = ""
  include_global_service_events = var.include_global_service_events
  is_multi_region_trail         = var.is_multi_region_trail
  enable_log_file_validation    = var.enable_log_file_validation
  enable_logging                = var.enable_logging
  is_organization_trail         = var.is_organization_trail
  kms_key_id                    = aws_kms_key.cloudtrail.arn
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch_logs.arn

  dynamic "event_selector" {
    for_each = [1] # Always one event selector block
    content {
      read_write_type           = var.read_write_type
      include_management_events = var.include_management_events

      dynamic "data_resource" {
        for_each = [] # User can add data resources via variable if needed; currently empty
        content {
          type   = data_resource.value.type
          values = data_resource.value.values
        }
      }
    }
  }

  dynamic "insight_selector" {
    for_each = [] # User can add insight selectors via variable if needed; currently empty
    content {
      insight_type = insight_selector.value.insight_type
    }
  }

  sns_topic_name = local.has_sns ? local.sns_topic_name : null

  tags = var.tags
}

# ------------------------------------------------------------------------------
# SNS Topic (optional)
# ------------------------------------------------------------------------------
resource "aws_sns_topic" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0

  name = "cloudtrail-alerts"

  tags = var.tags
}

resource "aws_sns_topic_policy" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0

  arn = aws_sns_topic.cloudtrail[0].arn
  policy = data.aws_iam_policy_document.sns_topic_policy[0].json
}

data "aws_iam_policy_document" "sns_topic_policy" {
  count = var.create_sns_topic ? 1 : 0

  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = ["SNS:Publish"]

    condition {
      test     = "ArnEquals"
      variable = "aws:SourceArn"
      values   = [aws_cloudtrail.cloudtrail.arn]
    }

    resources = [aws_sns_topic.cloudtrail[0].arn]
  }
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "region" {
  description = "AWS region for EBS security settings. Defaults to us-east-1."
  type        = string
  default     = "us-east-1"
}

variable "global_enabled" {
  description = "Master switch to enable or disable all EBS security controls."
  type        = bool
  default     = true
}

variable "enable_default_encryption" {
  description = "Enable default EBS encryption for the region."
  type        = bool
  default     = true
}

variable "block_public_access" {
  description = "Block public access to EBS snapshots."
  type        = bool
  default     = true
}

variable "block_public_access_state" {
  description = "State for blocking public access to EBS snapshots (e.g., block-all-sharing, block-new-sharing)."
  type        = string
  default     = "block-all-sharing"
}

data "aws_region" "current" {}

locals {
  effective_region = coalesce(var.region, data.aws_region.current.name)
}

resource "aws_ebs_encryption_by_default" "this" {
  count   = var.global_enabled && var.enable_default_encryption ? 1 : 0
  enabled = true
}

resource "aws_ebs_snapshot_block_public_access" "this" {
  count = var.global_enabled && var.block_public_access ? 1 : 0
  state = var.block_public_access_state
}

output "default_ebs_encryption_id" {
  description = "ID of the default EBS encryption resource (if created)."
  value       = try(aws_ebs_encryption_by_default.this[0].id, null)
}

output "snapshot_block_public_access_id" {
  description = "ID of the snapshot block public access resource (if created)."
  value       = try(aws_ebs_snapshot_block_public_access.this[0].id, null)
}

output "effective_region" {
  description = "The region being used for EBS settings (explicit override or provider region)."
  value       = local.effective_region
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "username" {
  description = "IAM user name for CI/CD deployment"
  type        = string
  default     = "DeploymentUser"
}

variable "tags" {
  description = "Optional tags to apply to the IAM user"
  type        = map(string)
  default     = {}
}

variable "s3_bucket_arns" {
  description = "List of S3 bucket ARNs for CI/CD artifact management"
  type        = list(string)
  default     = []
}

variable "s3_bucket_sub_paths" {
  description = "List of sub-paths per bucket ARN (must match length of s3_bucket_arns). Defaults to '*' per bucket."
  type        = list(string)
  default     = ["*"]
}

variable "lambda_function_arns" {
  description = "List of Lambda function ARNs for code updates"
  type        = list(string)
  default     = []
}

locals {
  # Normalize sub-paths: ensure we have one sub-path per bucket ARN
  s3_sub_paths = length(var.s3_bucket_arns) > 0 ? (
    length(var.s3_bucket_sub_paths) >= length(var.s3_bucket_arns) ? var.s3_bucket_sub_paths : [for i in range(length(var.s3_bucket_arns)) : var.s3_bucket_sub_paths[i % length(var.s3_bucket_sub_paths)]]
  ) : []
}

# IAM user
resource "aws_iam_user" "deployment" {
  name = var.username
  tags = var.tags
}

# S3 policy and attachment (conditional)
data "aws_iam_policy_document" "s3" {
  count = length(var.s3_bucket_arns) > 0 ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "s3:ListBucket"
    ]
    resources = var.s3_bucket_arns
  }

  dynamic "statement" {
    for_each = zipmap(var.s3_bucket_arns, local.s3_sub_paths)
    content {
      effect = "Allow"
      actions = [
        "s3:GetObject",
        "s3:PutObject",
        "s3:DeleteObject",
        "s3:PutObjectAcl",
        "s3:GetObjectAcl"
      ]
      resources = ["${statement.key}/${statement.value}"]
    }
  }
}

resource "aws_iam_policy" "s3" {
  count       = length(var.s3_bucket_arns) > 0 ? 1 : 0
  name        = "deployment-s3-policy"
  description = "Policy for S3 artifact management"
  policy      = data.aws_iam_policy_document.s3[0].json
  tags        = var.tags
}

resource "aws_iam_user_policy_attachment" "s3" {
  count      = length(var.s3_bucket_arns) > 0 ? 1 : 0
  user       = aws_iam_user.deployment.name
  policy_arn = aws_iam_policy.s3[0].arn
}

# Lambda policy and attachment (conditional)
data "aws_iam_policy_document" "lambda" {
  count = length(var.lambda_function_arns) > 0 ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "lambda:UpdateFunctionCode"
    ]
    resources = var.lambda_function_arns
  }
}

resource "aws_iam_policy" "lambda" {
  count       = length(var.lambda_function_arns) > 0 ? 1 : 0
  name        = "deployment-lambda-policy"
  description = "Policy for Lambda code updates"
  policy      = data.aws_iam_policy_document.lambda[0].json
  tags        = var.tags
}

resource "aws_iam_user_policy_attachment" "lambda" {
  count      = length(var.lambda_function_arns) > 0 ? 1 : 0
  user       = aws_iam_user.deployment.name
  policy_arn = aws_iam_policy.lambda[0].arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.0.1"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Variables
variable "bucket_name" {
  description = "Custom name for the S3 bucket. Falls back to domain_name if empty, then to a generated name."
  type        = string
  default     = ""
}

variable "domain_name" {
  description = "Domain name for the static website. If set, hosted_zone_id must also be set."
  type        = string
  default     = ""
}

variable "hosted_zone_id" {
  description = "Route53 hosted zone ID for the domain. Required if domain_name is set."
  type        = string
  default     = ""
  validation {
    condition     = var.domain_name == "" || (var.domain_name != "" && var.hosted_zone_id != "")
    error_message = "hosted_zone_id must be provided when domain_name is set."
  }
}

variable "create_www_alias" {
  description = "Whether to create a www subdomain alias for the CloudFront distribution."
  type        = bool
  default     = false
}

variable "enable_bucket_versioning" {
  description = "Enable versioning on the S3 bucket."
  type        = bool
  default     = false
}

# Random ID for fallback bucket name
resource "random_id" "bucket_suffix" {
  byte_length = 8
}

# Local values
locals {
  effective_bucket_name = var.bucket_name != "" ? var.bucket_name : (
    var.domain_name != "" ? var.domain_name : "webapp-template-${random_id.bucket_suffix.hex}"
  )
  create_domain = var.domain_name != "" ? true : false
}

# S3 Bucket
resource "aws_s3_bucket" "this" {
  bucket        = local.effective_bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "this" {
  count  = var.enable_bucket_versioning ? 1 : 0
  bucket = aws_s3_bucket.this.id
  versioning_configuration {
    status = "Enabled"
  }
}

# KMS Key for S3 encryption
data "aws_caller_identity" "current" {}

resource "aws_kms_key" "s3" {
  description             = "KMS key for S3 bucket encryption (static website)"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudFront to Decrypt"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action   = "kms:Decrypt"
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = aws_cloudfront_distribution.main.arn
          }
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
  }
}

# S3 Bucket Policy for CloudFront OAC
resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudFrontServicePrincipal"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.this.arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = aws_cloudfront_distribution.main.arn
          }
        }
      }
    ]
  })
}

# CloudFront Origin Access Control
resource "aws_cloudfront_origin_access_control" "this" {
  name                              = "${local.effective_bucket_name}-oac"
  description                       = "OAC for S3 bucket ${local.effective_bucket_name}"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

# WAFv2 Web ACL (CloudFront scope)
resource "aws_wafv2_web_acl" "this" {
  name        = "cloudfront-waf-acl"
  description = "WAF ACL for CloudFront distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "cloudfront-waf-metrics"
    sampled_requests_enabled   = true
  }
}

# Data sources for managed cache policies
data "aws_cloudfront_cache_policy" "caching_optimized" {
  name = "Managed-CachingOptimized"
}

data "aws_cloudfront_cache_policy" "caching_disabled" {
  name = "Managed-CachingDisabled"
}

# CloudFront Distribution
resource "aws_cloudfront_distribution" "main" {
  enabled             = true
  is_ipv6_enabled     = true
  price_class         = "PriceClass_100"
  default_root_object = "index.html"
  aliases             = local.create_domain ? concat([var.domain_name], var.create_www_alias ? ["www.${var.domain_name}"] : []) : []

  origin {
    domain_name              = aws_s3_bucket.this.bucket_regional_domain_name
    origin_id                = "s3-origin"
    origin_access_control_id = aws_cloudfront_origin_access_control.this.id
  }

  default_cache_behavior {
    target_origin_id       = "s3-origin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["DELETE", "GET", "HEAD", "OPTIONS", "PATCH", "POST", "PUT"]
    cached_methods         = ["GET", "HEAD"]
    compress               = true
    cache_policy_id        = data.aws_cloudfront_cache_policy.caching_optimized.id
  }

  ordered_cache_behavior {
    path_pattern           = "/index.html"
    target_origin_id       = "s3-origin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["DELETE", "GET", "HEAD", "OPTIONS", "PATCH", "POST", "PUT"]
    cached_methods         = ["GET", "HEAD"]
    compress               = true
    cache_policy_id        = data.aws_cloudfront_cache_policy.caching_disabled.id
  }

  custom_error_response {
    error_code            = 403
    response_code         = 404
    response_page_path    = "/index.html"
    error_caching_min_ttl = 10
  }

  custom_error_response {
    error_code            = 404
    response_code         = 404
    response_page_path    = "/index.html"
    error_caching_min_ttl = 10
  }

  viewer_certificate {
    cloudfront_default_certificate = local.create_domain ? false : true
    acm_certificate_arn            = local.create_domain ? aws_acm_certificate.this[0].arn : null
    ssl_support_method             = local.create_domain ? "sni-only" : null
    minimum_protocol_version       = local.create_domain ? "TLSv1.2_2021" : null
  }

  web_acl_id = aws_wafv2_web_acl.this.arn

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  retain_on_delete = false
}

# ACM Certificate (us-east-1) - only if domain_name is set
resource "aws_acm_certificate" "this" {
  count = local.create_domain ? 1 : 0

  domain_name       = var.domain_name
  subject_alternative_names = var.create_www_alias ? ["*.${var.domain_name}"] : []
  validation_method = "DNS"
}

# Route53 DNS validation records
resource "aws_route53_record" "validation" {
  for_each = local.create_domain ? {
    for dvo in aws_acm_certificate.this[0].domain_validation_options : dvo.domain_name => dvo
  } : {}

  zone_id = var.hosted_zone_id
  name    = each.value.resource_record_name
  type    = each.value.resource_record_type
  records = [each.value.resource_record_value]
  ttl     = 60
}

# Certificate validation
resource "aws_acm_certificate_validation" "this" {
  count = local.create_domain ? 1 : 0

  certificate_arn         = aws_acm_certificate.this[0].arn
  validation_record_fqdns = [for record in aws_route53_record.validation : record.fqdn]
}

# Route53 Alias A records for CloudFront
resource "aws_route53_record" "main_alias" {
  count = local.create_domain ? 1 : 0

  zone_id = var.hosted_zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.main.domain_name
    zone_id                = aws_cloudfront_distribution.main.hosted_zone_id
    evaluate_target_health = false
  }
}

resource "aws_route53_record" "www_alias" {
  count = local.create_domain && var.create_www_alias ? 1 : 0

  zone_id = var.hosted_zone_id
  name    = "www.${var.domain_name}"
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.main.domain_name
    zone_id                = aws_cloudfront_distribution.main.hosted_zone_id
    evaluate_target_health = false
  }
}

# Outputs (for reference)
output "s3_bucket_name" {
  value = aws_s3_bucket.this.id
}

output "cloudfront_distribution_domain" {
  value = aws_cloudfront_distribution.main.domain_name
}

output "cloudfront_distribution_arn" {
  value = aws_cloudfront_distribution.main.arn
}

terraform {
  required_version = ">= 1.3, < 2.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.75.0"
    }
  }
}

# Variables
variable "availability_zones" {
  description = "List of availability zone names to deploy subnets into"
  type        = list(string)
  default     = ["us-east-1a", "us-east-1b", "us-east-1c"]
}

variable "enable_s3_vpc_endpoint" {
  description = "Whether to provision a Gateway VPC Endpoint for S3"
  type        = bool
  default     = true
}

variable "multi_az_nat_gateway" {
  description = "Whether to deploy a NAT Gateway in each AZ"
  type        = bool
  default     = true
}

variable "single_nat_gateway" {
  description = "Whether to deploy a single NAT Gateway for all AZs (ignored if multi_az_nat_gateway is true)"
  type        = bool
  default     = false
}

variable "tags" {
  description = "Global tags applied to all resources"
  type        = map(string)
  default = {
    Author     = "Fairwinds"
    Managed_By = "Terraform"
  }
}

# Data sources
data "aws_region" "current" {}

# Local values
locals {
  base_cidr = "10.20.0.0/16"
  newbits   = 5

  # Subnet CIDRs per tier per AZ (netnum offsets: admin 0-2, public 4-6, private_prod 8-10, private_work 12-14)
  admin_cidrs       = [for i in range(length(var.availability_zones)) : cidrsubnet(local.base_cidr, local.newbits, 0 + i)]
  public_cidrs      = [for i in range(length(var.availability_zones)) : cidrsubnet(local.base_cidr, local.newbits, 4 + i)]
  private_prod_cidrs = [for i in range(length(var.availability_zones)) : cidrsubnet(local.base_cidr, local.newbits, 8 + i)]
  private_work_cidrs = [for i in range(length(var.availability_zones)) : cidrsubnet(local.base_cidr, local.newbits, 12 + i)]
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = local.base_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(var.tags, {
    Name = "vpc"
  })
}

# Internet Gateway
resource "aws_internet_gateway" "vpc" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "vpc"
  })
}

# Subnets
resource "aws_subnet" "admin" {
  count             = length(var.availability_zones)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.admin_cidrs[count.index]
  availability_zone = var.availability_zones[count.index]

  tags = merge(var.tags, {
    Name = "admin-${var.availability_zones[count.index]}"
    Tier = "admin"
  })
}

resource "aws_subnet" "public" {
  count             = length(var.availability_zones)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_cidrs[count.index]
  availability_zone = var.availability_zones[count.index]

  tags = merge(var.tags, {
    Name = "public-${var.availability_zones[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private_prod" {
  count             = length(var.availability_zones)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_prod_cidrs[count.index]
  availability_zone = var.availability_zones[count.index]

  tags = merge(var.tags, {
    Name = "private-prod-${var.availability_zones[count.index]}"
    Tier = "private-prod"
  })
}

resource "aws_subnet" "private_work" {
  count             = length(var.availability_zones)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_work_cidrs[count.index]
  availability_zone = var.availability_zones[count.index]

  tags = merge(var.tags, {
    Name = "private-work-${var.availability_zones[count.index]}"
    Tier = "private-work"
  })
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "public"
  })
}

resource "aws_route" "public_igw" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.vpc.id
}

resource "aws_route_table_association" "public" {
  count          = length(var.availability_zones)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private route tables (one per AZ)
resource "aws_route_table" "private" {
  count  = length(var.availability_zones)
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "private_az${count.index + 1}"
  })
}

# Associate private subnets to corresponding private route tables
resource "aws_route_table_association" "admin" {
  count          = length(var.availability_zones)
  subnet_id      = aws_subnet.admin[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_route_table_association" "private_prod" {
  count          = length(var.availability_zones)
  subnet_id      = aws_subnet.private_prod[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_route_table_association" "private_work" {
  count          = length(var.availability_zones)
  subnet_id      = aws_subnet.private_work[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# Elastic IPs for NAT Gateways
resource "aws_eip" "nat" {
  count  = var.multi_az_nat_gateway ? length(var.availability_zones) : (var.single_nat_gateway ? 1 : 0)
  domain = "vpc"

  tags = merge(var.tags, {
    Name = "nat-eip-${count.index}"
  })
}

# NAT Gateways (one per AZ)
resource "aws_nat_gateway" "main" {
  count         = length(var.availability_zones)
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(var.tags, {
    Name = "nat-${var.availability_zones[count.index]}"
  })
}

# Private routes to NAT Gateways
resource "aws_route" "private_nat" {
  count                  = length(var.availability_zones)
  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

# S3 Gateway VPC Endpoint (conditional)
data "aws_iam_policy_document" "s3_endpoint" {
  count = var.enable_s3_vpc_endpoint ? 1 : 0

  statement {
    sid    = "FullAccess"
    effect = "Allow"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions   = ["s3:*"]
    resources = ["*"]
  }
}

resource "aws_vpc_endpoint" "s3" {
  count             = var.enable_s3_vpc_endpoint ? 1 : 0
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  policy            = data.aws_iam_policy_document.s3_endpoint[0].json

  tags = merge(var.tags, {
    Name = "s3-gateway-endpoint"
  })
}

resource "aws_vpc_endpoint_route_table_association" "private" {
  count           = var.enable_s3_vpc_endpoint ? length(var.availability_zones) : 0
  vpc_endpoint_id = aws_vpc_endpoint.s3[0].id
  route_table_id  = aws_route_table.private[count.index].id
}

# ------------------------------------------------------------------------------
# Terraform and Provider Requirements
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.50, < 5.100"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Random suffix for unique resource names
# ------------------------------------------------------------------------------
resource "random_id" "suffix" {
  byte_length = 4
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "health_check_path" {
  description = "Health check path for the ALB target group"
  type        = string
  default     = "/"
}

variable "app_port" {
  description = "Port exposed by the application container"
  type        = number
  default     = 80
}

variable "github_org" {
  description = "GitHub organization or account name for CI/CD role trust"
  type        = string
  default     = "my-org"
}

# ------------------------------------------------------------------------------
# Data Sources
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# VPC
# ------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "fargate-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "fargate-igw"
  }
}

# ------------------------------------------------------------------------------
# Subnets
# ------------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "fargate-public-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 3)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "fargate-private-${count.index}"
  }
}

# ------------------------------------------------------------------------------
# Route Tables
# ------------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "fargate-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "fargate-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ------------------------------------------------------------------------------
# Security Groups
# ------------------------------------------------------------------------------
resource "aws_security_group" "alb" {
  name        = "fargate-alb-sg"
  description = "Security group for the internal ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "fargate-alb-sg"
  }
}

resource "aws_security_group" "ecs_tasks" {
  name        = "fargate-ecs-tasks-sg"
  description = "Security group for ECS Fargate tasks"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port       = var.app_port
    to_port         = var.app_port
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "fargate-ecs-tasks-sg"
  }
}

resource "aws_security_group" "rds" {
  name        = "fargate-rds-sg"
  description = "Security group for RDS PostgreSQL"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs_tasks.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "fargate-rds-sg"
  }
}

# ------------------------------------------------------------------------------
# Self-Signed Certificate (via TLS provider)
# ------------------------------------------------------------------------------
resource "tls_private_key" "self_signed" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  private_key_pem = tls_private_key.self_signed.private_key_pem

  subject {
    common_name  = "internal-fargate.local"
    organization = "Example Corp"
  }

  validity_period_hours = 87600

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "self_signed" {
  private_key       = tls_private_key.self_signed.private_key_pem
  certificate_body  = tls_self_signed_cert.self_signed.cert_pem
  certificate_chain = tls_self_signed_cert.self_signed.cert_pem
}

# ------------------------------------------------------------------------------
# Application Load Balancer
# ------------------------------------------------------------------------------
resource "aws_lb" "internal" {
  name               = "fargate-alb"
  internal           = true
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = aws_subnet.public[*].id

  drop_invalid_header_fields = true

  tags = {
    Name = "fargate-alb"
  }
}

resource "aws_lb_target_group" "app" {
  name        = "fargate-tg-${random_id.suffix.hex}"
  port        = var.app_port
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "ip"

  health_check {
    path                = var.health_check_path
    port                = "traffic-port"
    protocol            = "HTTP"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    interval            = 30
    matcher             = "200-399"
  }

  tags = {
    Name = "fargate-tg"
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.internal.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS-1-2-2017-01"
  certificate_arn   = aws_acm_certificate.self_signed.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app.arn
  }
}

resource "aws_lb_listener" "http_redirect" {
  load_balancer_arn = aws_lb.internal.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

# ------------------------------------------------------------------------------
# ECS Cluster
# ------------------------------------------------------------------------------
resource "aws_ecs_cluster" "main" {
  name = "fargate-cluster"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = {
    Name = "fargate-cluster"
  }
}

# ------------------------------------------------------------------------------
# ECR Repository
# ------------------------------------------------------------------------------
resource "aws_ecr_repository" "app" {
  name                 = "fargate-app"
  image_tag_mutability = "IMMUTABLE"
  image_scanning_configuration {
    scan_on_push = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecr_lifecycle_policy" "untagged_expire" {
  repository = aws_ecr_repository.app.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images after 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# CloudWatch Log Group for ECS
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "ecs" {
  name              = "/ecs/fargate-app"
  retention_in_days = 30

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Secrets Manager - Database Password
# ------------------------------------------------------------------------------
resource "aws_secretsmanager_secret" "db_password" {
  name = "rds-postgres-password"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_password" {
  secret_id     = aws_secretsmanager_secret.db_password.id
  secret_string = "postgres"
}

# ------------------------------------------------------------------------------
# RDS PostgreSQL
# ------------------------------------------------------------------------------
resource "aws_db_subnet_group" "main" {
  name       = "fargate-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "fargate-db-subnet-group"
  }
}

resource "aws_db_instance" "postgres" {
  identifier             = "fargate-db"
  engine                 = "postgres"
  engine_version         = "15"
  instance_class         = "db.t3.micro"
  allocated_storage      = 20
  storage_encrypted      = true
  db_name                = "mydb"
  username               = "postgres"
  password               = aws_secretsmanager_secret_version.db_password.secret_string
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  skip_final_snapshot    = false
  final_snapshot_identifier = "fargate-db-final-snapshot-${formatdate("YYYYMMDDhhmmss", timestamp())}"
  publicly_accessible    = false
  multi_az               = false
  backup_retention_period = 7
  backup_window          = "03:00-04:00"
  maintenance_window     = "sun:04:00-sun:05:00"
  auto_minor_version_upgrade = true

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "fargate-db"
  }
}

# ------------------------------------------------------------------------------
# IAM Roles for ECS
# ------------------------------------------------------------------------------
resource "aws_iam_role" "ecs_execution" {
  name = "fargate-ecs-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_execution_managed" {
  role       = aws_iam_role.ecs_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role" "ecs_task" {
  name = "fargate-ecs-task-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# ECS Task Definition
# ------------------------------------------------------------------------------
resource "aws_ecs_task_definition" "app" {
  family                   = "fargate-app"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name      = "app"
      image     = "public.ecr.aws/nginx/nginx:latest"
      essential = true
      portMappings = [
        {
          containerPort = var.app_port
          protocol      = "tcp"
        }
      ]
      environment = [
        { name = "PGHOST", value = aws_db_instance.postgres.address },
        { name = "PGPORT", value = tostring(aws_db_instance.postgres.port) },
        { name = "PGDATABASE", value = "mydb" },
        { name = "PGUSER", value = "postgres" }
      ]
      secrets = [
        { name = "PGPASSWORD", valueFrom = aws_secretsmanager_secret.db_password.arn }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.ecs.name
          "awslogs-region"        = data.aws_region.current.name
          "awslogs-stream-prefix" = "ecs"
        }
      }
    }
  ])

  tags = {
    Name = "fargate-app-task-def"
  }
}

# ------------------------------------------------------------------------------
# ECS Service
# ------------------------------------------------------------------------------
resource "aws_ecs_service" "app" {
  name            = "fargate-app-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = 2

  network_configuration {
    subnets         = aws_subnet.private[*].id
    security_groups = [aws_security_group.ecs_tasks.id]
    assign_public_ip = false
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.app.arn
    container_name   = "app"
    container_port   = var.app_port
  }

  deployment_circuit_breaker {
    enable   = true
    rollback = true
  }

  capacity_provider_strategy {
    capacity_provider = "FARGATE"
    weight            = 20
    base              = 1
  }

  capacity_provider_strategy {
    capacity_provider = "FARGATE_SPOT"
    weight            = 80
  }

  depends_on = [aws_lb_listener.https]

  tags = {
    Name = "fargate-app-service"
  }
}

# ------------------------------------------------------------------------------
# Auto Scaling for ECS Service
# ------------------------------------------------------------------------------
resource "aws_appautoscaling_target" "ecs" {
  max_capacity       = 4
  min_capacity       = 2
  resource_id        = "service/${aws_ecs_cluster.main.name}/${aws_ecs_service.app.name}"
  scalable_dimension = "ecs:service:DesiredCount"
  service_namespace  = "ecs"
}

resource "aws_appautoscaling_policy" "cpu" {
  name               = "fargate-cpu-autoscaling"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.ecs.resource_id
  scalable_dimension = aws_appautoscaling_target.ecs.scalable_dimension
  service_namespace  = aws_appautoscaling_target.ecs.service_namespace

  target_tracking_scaling_policy_configuration {
    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageCPUUtilization"
    }
    target_value = 50.0
    scale_in_cooldown  = 60
    scale_out_cooldown = 60
  }
}

resource "aws_appautoscaling_policy" "memory" {
  name               = "fargate-memory-autoscaling"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.ecs.resource_id
  scalable_dimension = aws_appautoscaling_target.ecs.scalable_dimension
  service_namespace  = aws_appautoscaling_target.ecs.service_namespace

  target_tracking_scaling_policy_configuration {
    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageMemoryUtilization"
    }
    target_value = 50.0
    scale_in_cooldown  = 60
    scale_out_cooldown = 60
  }
}

# ------------------------------------------------------------------------------
# IAM OpenID Connect Provider for GitHub Actions
# ------------------------------------------------------------------------------
resource "aws_iam_openid_connect_provider" "github" {
  url = "https://token.actions.githubusercontent.com"
  client_id_list = ["sts.amazonaws.com"]
  thumbprint_list = ["6938fd4d98bab03faadb97b34396831e3780aea1"]
}

# ------------------------------------------------------------------------------
# CI/CD IAM Role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "github_actions" {
  name = "fargate-github-actions-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRoleWithWebIdentity"
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.github.arn
        }
        Condition = {
          StringLike = {
            "token.actions.githubusercontent.com:sub" : "repo:${var.github_org}/*"
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "github_actions" {
  name        = "fargate-github-actions-policy"
  description = "Policy for GitHub Actions CI/CD"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:InitiateLayerUpload",
          "ecr:UploadLayerPart",
          "ecr:CompleteLayerUpload",
          "ecr:PutImage",
          "ecr:BatchGetImage",
          "ecr:DescribeRepositories",
          "ecr:ListImages",
          "ecr:DeleteLifecyclePolicy",
          "ecr:SetRepositoryPolicy"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ecs:RegisterTaskDefinition",
          "ecs:DeregisterTaskDefinition",
          "ecs:ListTaskDefinitions",
          "ecs:DescribeTaskDefinition",
          "ecs:UpdateService",
          "ecs:DescribeServices"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "iam:PassRole"
        ]
        Resource = aws_iam_role.ecs_task.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "github_actions" {
  role       = aws_iam_role.github_actions.name
  policy_arn = aws_iam_policy.github_actions.arn
}

# ------------------------------------------------------------------------------
# Import Blocks for Already-Existing Resources (state adoption)
# ------------------------------------------------------------------------------
import {
  id = "fargate-app"
  to = aws_ecr_repository.app
}

import {
  id = "/ecs/fargate-app"
  to = aws_cloudwatch_log_group.ecs
}

import {
  id = "rds-postgres-password"
  to = aws_secretsmanager_secret.db_password
}

import {
  id = "fargate-ecs-execution-role"
  to = aws_iam_role.ecs_execution
}

import {
  id = "fargate-ecs-task-role"
  to = aws_iam_role.ecs_task
}

import {
  id = "arn:aws:iam::000000000000:oidc-provider/token.actions.githubusercontent.com"
  to = aws_iam_openid_connect_provider.github
}

import {
  id = "fargate-github-actions-role"
  to = aws_iam_role.github_actions
}

import {
  id = "arn:aws:iam::000000000000:policy/fargate-github-actions-policy"
  to = aws_iam_policy.github_actions
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

data "aws_region" "current" {}

variable "cluster_tag" {
  type    = string
  default = "default"
}

variable "enable_key_rotation" {
  type    = bool
  default = false
}

variable "machine_roles" {
  type    = map(set(string))
  default = {}
}

# KMS Key for Vault unsealing
resource "aws_kms_key" "vault_unseal" {
  description         = "resinstack:vault:seal:${var.cluster_tag}"
  enable_key_rotation = var.enable_key_rotation
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

# Secrets Manager secrets for tokens and keys
resource "aws_secretsmanager_secret" "consul_agent_token" {
  name                    = "resinstack-consul-agent-token-${var.cluster_tag}"
  recovery_window_in_days = 0
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  depends_on = [null_resource.cleanup_secrets]
}

resource "aws_secretsmanager_secret" "consul_gossip_key" {
  name                    = "resinstack-consul-gossip-key-${var.cluster_tag}"
  recovery_window_in_days = 0
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  depends_on = [null_resource.cleanup_secrets]
}

resource "aws_secretsmanager_secret" "nomad_client_consul_token" {
  name                    = "resinstack-nomad-client-consul-token-${var.cluster_tag}"
  recovery_window_in_days = 0
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  depends_on = [null_resource.cleanup_secrets]
}

resource "aws_secretsmanager_secret" "nomad_gossip_key" {
  name                    = "resinstack-nomad-gossip-key-${var.cluster_tag}"
  recovery_window_in_days = 0
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  depends_on = [null_resource.cleanup_secrets]
}

resource "aws_secretsmanager_secret" "nomad_server_consul_token" {
  name                    = "resinstack-nomad-server-consul-token-${var.cluster_tag}"
  recovery_window_in_days = 0
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  depends_on = [null_resource.cleanup_secrets]
}

resource "aws_secretsmanager_secret" "nomad_vault_token" {
  name                    = "resinstack-nomad-vault-token-${var.cluster_tag}"
  recovery_window_in_days = 0
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  depends_on = [null_resource.cleanup_secrets]
}

resource "aws_secretsmanager_secret" "vault_consul_token" {
  name                    = "resinstack-vault-consul-token-${var.cluster_tag}"
  recovery_window_in_days = 0
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  depends_on = [null_resource.cleanup_secrets]
}

# IAM policy for Vault KMS unseal
data "aws_iam_policy_document" "vault_kms_unseal" {
  statement {
    effect    = "Allow"
    actions   = ["kms:Encrypt", "kms:Decrypt", "kms:DescribeKey"]
    resources = [aws_kms_key.vault_unseal.arn]
  }
}

resource "aws_iam_policy" "vault_kms_unseal" {
  name        = "ResinStackVaultKMSUnseal-${var.cluster_tag}"
  description = "Policy for Vault unseal via KMS"
  policy      = data.aws_iam_policy_document.vault_kms_unseal.json
}

# IAM policy for reading EC2 tags
data "aws_iam_policy_document" "read_tags" {
  statement {
    effect    = "Allow"
    actions   = ["ec2:DescribeInstances"]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "resinstack_read_tags" {
  name        = "ResinStackReadTags-${var.cluster_tag}"
  description = "Policy for reading EC2 instance tags"
  policy      = data.aws_iam_policy_document.read_tags.json
}

# IAM policy for client secrets
data "aws_iam_policy_document" "client_keys" {
  statement {
    effect    = "Allow"
    actions   = ["secretsmanager:GetSecretValue"]
    resources = [
      aws_secretsmanager_secret.consul_agent_token.arn,
      aws_secretsmanager_secret.consul_gossip_key.arn,
      aws_secretsmanager_secret.nomad_client_consul_token.arn
    ]
  }
}

resource "aws_iam_policy" "client_keys" {
  name        = "ResinStackClientKeys-${var.cluster_tag}"
  description = "Policy for retrieving client secrets"
  policy      = data.aws_iam_policy_document.client_keys.json
}

# IAM policy for Nomad server secrets
data "aws_iam_policy_document" "nomad_keys" {
  statement {
    effect    = "Allow"
    actions   = ["secretsmanager:GetSecretValue"]
    resources = [
      aws_secretsmanager_secret.consul_agent_token.arn,
      aws_secretsmanager_secret.consul_gossip_key.arn,
      aws_secretsmanager_secret.nomad_gossip_key.arn,
      aws_secretsmanager_secret.nomad_server_consul_token.arn,
      aws_secretsmanager_secret.nomad_vault_token.arn
    ]
  }
}

resource "aws_iam_policy" "nomad_keys" {
  name        = "ResinStackNomadKeys-${var.cluster_tag}"
  description = "Policy for retrieving Nomad server secrets"
  policy      = data.aws_iam_policy_document.nomad_keys.json
}

# IAM policy for Consul server secrets
data "aws_iam_policy_document" "consul_keys" {
  statement {
    effect    = "Allow"
    actions   = ["secretsmanager:GetSecretValue"]
    resources = [aws_secretsmanager_secret.consul_gossip_key.arn]
  }
}

resource "aws_iam_policy" "consul_keys" {
  name        = "ResinStackConsulKeys-${var.cluster_tag}"
  description = "Policy for retrieving Consul server secrets"
  policy      = data.aws_iam_policy_document.consul_keys.json
}

# IAM policy for Vault server secrets
data "aws_iam_policy_document" "vault_keys" {
  statement {
    effect    = "Allow"
    actions   = ["secretsmanager:GetSecretValue"]
    resources = [
      aws_secretsmanager_secret.consul_gossip_key.arn,
      aws_secretsmanager_secret.vault_consul_token.arn
    ]
  }
}

resource "aws_iam_policy" "vault_keys" {
  name        = "ResinStackVaultKeys-${var.cluster_tag}"
  description = "Policy for retrieving Vault server secrets"
  policy      = data.aws_iam_policy_document.vault_keys.json
}

# Assume role policy for EC2
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# IAM roles for each machine role
resource "aws_iam_role" "this" {
  for_each = var.machine_roles

  name                = "resinstack-${each.key}-${var.cluster_tag}"
  assume_role_policy  = data.aws_iam_policy_document.ec2_assume_role.json
  max_session_duration = 43200
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

# Instance profiles for each machine role
resource "aws_iam_instance_profile" "this" {
  for_each = var.machine_roles

  name = "resinstack-${each.key}-${var.cluster_tag}"
  role = aws_iam_role.this[each.key].name
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

# Local map from policy identifier to IAM policy ARN
locals {
  policy_arn_map = {
    "read-tags"   = aws_iam_policy.resinstack_read_tags.arn
    "vault-kms"   = aws_iam_policy.vault_kms_unseal.arn
    "client-keys" = aws_iam_policy.client_keys.arn
    "nomad-keys"  = aws_iam_policy.nomad_keys.arn
    "consul-keys" = aws_iam_policy.consul_keys.arn
    "vault-keys"  = aws_iam_policy.vault_keys.arn
  }

  # Flatten list of role-policy pairs for attachment
  role_policy_attachments = flatten([
    for role_key, policies in var.machine_roles : [
      for policy_id in policies : {
        role_key  = role_key
        policy_id = policy_id
      }
    ]
  ])
}

# Attach policies to roles based on identifiers
resource "aws_iam_role_policy_attachment" "this" {
  for_each = {
    for att in local.role_policy_attachments :
    "${att.role_key}-${att.policy_id}" => att
  }

  role       = aws_iam_role.this[each.value.role_key].name
  policy_arn = local.policy_arn_map[each.value.policy_id]
}

# Null resource to force-delete stale secrets before creation
resource "null_resource" "cleanup_secrets" {
  provisioner "local-exec" {
    command = <<EOT
      for secret in \
        "resinstack-consul-agent-token-${var.cluster_tag}" \
        "resinstack-consul-gossip-key-${var.cluster_tag}" \
        "resinstack-nomad-client-consul-token-${var.cluster_tag}" \
        "resinstack-nomad-gossip-key-${var.cluster_tag}" \
        "resinstack-nomad-server-consul-token-${var.cluster_tag}" \
        "resinstack-nomad-vault-token-${var.cluster_tag}" \
        "resinstack-vault-consul-token-${var.cluster_tag}"; do
        aws secretsmanager delete-secret \
          --secret-id "$secret" \
          --force-delete-without-recovery \
          --region "${data.aws_region.current.name}" 2>/dev/null || true
      done
    EOT
  }
}

# Outputs
output "vault_kms_key_id" {
  value = aws_kms_key.vault_unseal.key_id
}

output "secret_names" {
  value = {
    consul_agent_token       = aws_secretsmanager_secret.consul_agent_token.name
    consul_gossip_key        = aws_secretsmanager_secret.consul_gossip_key.name
    nomad_client_consul_token = aws_secretsmanager_secret.nomad_client_consul_token.name
    nomad_gossip_key         = aws_secretsmanager_secret.nomad_gossip_key.name
    nomad_server_consul_token = aws_secretsmanager_secret.nomad_server_consul_token.name
    nomad_vault_token        = aws_secretsmanager_secret.nomad_vault_token.name
    vault_consul_token       = aws_secretsmanager_secret.vault_consul_token.name
  }
}

output "machine_role_names" {
  value = { for k, r in aws_iam_role.this : k => r.name }
}

output "instance_profile_names" {
  value = { for k, p in aws_iam_instance_profile.this : k => p.name }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.90.0"
    }
  }
}

variable "env_prefix" {
  description = "Environment prefix used for resource naming and tagging"
  type        = string
  default     = "elluis_codes_limited_network"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  # Map subnet offset values (11, 22, 33) to the first three availability zone names
  az_offset_map = {
    for i, offset in [11, 22, 33] :
    offset => element(data.aws_availability_zones.available.names, i)
  }
  common_tags = {
    Environment = var.env_prefix
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "64.0.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.env_prefix}-vpc"
  })
}

# Public subnets
resource "aws_subnet" "public" {
  for_each = local.az_offset_map

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, each.key)
  availability_zone       = each.value
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.env_prefix}-public-subnet-${each.key}"
  })
}

# Private subnets (offset + 100)
resource "aws_subnet" "private" {
  for_each = local.az_offset_map

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, each.key + 100)
  availability_zone       = each.value
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.env_prefix}-private-subnet-${each.key}"
  })
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.env_prefix}-igw"
  })
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.env_prefix}-public-rt"
  })

  lifecycle {
    ignore_changes = [route]
  }
}

# Public route table associations
resource "aws_route_table_association" "public" {
  for_each = aws_subnet.public

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public.id

  lifecycle {
    ignore_changes = [route_table_id]
  }
}

# Elastic IPs (one per AZ)
resource "aws_eip" "nat" {
  for_each = local.az_offset_map

  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.env_prefix}-eip-${each.key}"
  })
}

# NAT Gateways (one per AZ, in the corresponding public subnet)
resource "aws_nat_gateway" "main" {
  for_each = local.az_offset_map

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[each.key].id

  tags = merge(local.common_tags, {
    Name = "${var.env_prefix}-nat-${each.key}"
  })

  # To avoid unnecessary changes, ignore the attachment (Terraform will recreate if needed)
  lifecycle {
    ignore_changes = [subnet_id]
  }
}

# Private route tables (one per AZ)
resource "aws_route_table" "private" {
  for_each = local.az_offset_map

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[each.key].id
  }

  tags = merge(local.common_tags, {
    Name = "${var.env_prefix}-private-rt-${each.key}"
  })

  lifecycle {
    ignore_changes = [route]
  }
}

# Private route table associations (one per AZ)
resource "aws_route_table_association" "private" {
  for_each = aws_subnet.private

  subnet_id      = each.value.id
  route_table_id = aws_route_table.private[each.key].id

  lifecycle {
    ignore_changes = [route_table_id]
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Variables
variable "creation_token" {
  description = "Creation token for the EFS file system"
  type        = string
  default     = "test-efs"
}

variable "performance_mode" {
  description = "Performance mode for the EFS file system"
  type        = string
  default     = "generalPurpose"
}

variable "throughput_mode" {
  description = "Throughput mode for the EFS file system"
  type        = string
  default     = "bursting"
}

variable "transition_to_ia" {
  description = "Lifecycle policy transition to Infrequent Access"
  type        = string
  default     = "AFTER_30_DAYS"
}

# KMS key for EFS encryption
resource "aws_kms_key" "efs" {
  description             = "KMS key for EFS encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "efs" {
  name          = "alias/efs-kms-key"
  target_key_id = aws_kms_key.efs.key_id
}

# EFS file system
resource "aws_efs_file_system" "main" {
  creation_token   = var.creation_token
  performance_mode = var.performance_mode
  throughput_mode  = var.throughput_mode
  encrypted        = true
  kms_key_id       = aws_kms_key.efs.arn

  lifecycle_policy {
    transition_to_ia = var.transition_to_ia
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "shared-efs"
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "efs-vpc"
  }
}

# Public subnets in different AZs
resource "aws_subnet" "public" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  map_public_ip_on_launch = false

  tags = {
    Name = "efs-subnet-${count.index + 1}"
  }
}

# Security group allowing NFS from VPC CIDR
resource "aws_security_group" "efs" {
  name        = "efs-mount-sg"
  description = "Allow NFS inbound from VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from VPC"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "efs-mount-sg"
  }
}

# Mount targets for each subnet
resource "aws_efs_mount_target" "main" {
  count = length(aws_subnet.public)

  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.public[count.index].id
  security_groups = [aws_security_group.efs.id]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "hosted_zone_id" {
  description = "Route 53 hosted zone ID for policy scoping"
  type        = string
  default     = "*"
}

variable "iam_user_name" {
  description = "Name for the IAM user"
  type        = string
  default     = "cert-manager"
}

resource "aws_iam_user" "cert_manager" {
  name = var.iam_user_name
}

resource "aws_iam_access_key" "cert_manager" {
  user = aws_iam_user.cert_manager.name
}

resource "aws_ssm_parameter" "access_key_id" {
  name  = "/cert-manager/access-key"
  type  = "SecureString"
  value = aws_iam_access_key.cert_manager.id
}

resource "aws_ssm_parameter" "secret_access_key" {
  name  = "/cert-manager/secret-key"
  type  = "SecureString"
  value = aws_iam_access_key.cert_manager.secret
}

data "aws_iam_policy_document" "cert_manager_route53" {
  statement {
    sid    = "GetChange"
    effect = "Allow"
    actions = [
      "route53:GetChange"
    ]
    resources = [
      "arn:aws:route53:::change/*"
    ]
  }

  statement {
    sid    = "ManageHostedZone"
    effect = "Allow"
    actions = [
      "route53:ChangeResourceRecordSets",
      "route53:ListResourceRecordSets"
    ]
    resources = [
      "arn:aws:route53:::hostedzone/${var.hosted_zone_id}"
    ]
  }

  statement {
    sid    = "ListHostedZonesByName"
    effect = "Allow"
    actions = [
      "route53:ListHostedZonesByName"
    ]
    resources = [
      "*"
    ]
  }
}

resource "aws_iam_policy" "cert_manager_route53" {
  name        = "cert-manager-route53-policy"
  description = "Policy for cert-manager to manage Route 53 DNS records"
  policy      = data.aws_iam_policy_document.cert_manager_route53.json
}

# ---------------------------------------------------------------------------
# REQUIRED PROVIDERS AND TERRAFORM VERSION
# ---------------------------------------------------------------------------
terraform {
  required_version = "~> 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.81.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "3.2.1"
    }
  }
}

# ---------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------
variable "finding_filters" {
  description = "List of finding filter configurations"
  type = list(object({
    name   = string
    action = string
    rank   = number
    finding_criteria = list(object({
      field      = string
      equals     = optional(list(string))
      not_equals = optional(list(string))
      greater_than = optional(number)
      less_than    = optional(number)
    }))
  }))
  default = []
}

variable "ip_sets" {
  description = "List of IP set configurations"
  type = list(object({
    name     = string
    format   = string
    location = string
  }))
  default = []
}

variable "threat_intel_sets" {
  description = "List of threat intelligence set configurations"
  type = list(object({
    name     = string
    format   = string
    location = string
  }))
  default = []
}

variable "replica_region" {
  description = "AWS region for the replica bucket"
  type        = string
  default     = "us-west-2"
}

variable "environment" {
  description = "Environment name for tagging"
  type        = string
  default     = "production"
}

# ---------------------------------------------------------------------------
# LOCALS
# ---------------------------------------------------------------------------
locals {
  name_prefix = "guardduty"
  common_tags = {
    Name        = local.name_prefix
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# DATA SOURCES (static provider metadata and existing resources)
# ---------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

data "aws_guardduty_detector" "main" {}

data "aws_iam_role" "s3_replication" {
  name = "guardduty-s3-replication-role"
}

# ---------------------------------------------------------------------------
# PROVIDER ALIAS (replica region)
# ---------------------------------------------------------------------------
provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

# ---------------------------------------------------------------------------
# FINDING FILTERS (dynamic count)
# ---------------------------------------------------------------------------
resource "aws_guardduty_filter" "finding_filter" {
  count = length(var.finding_filters)

  detector_id = data.aws_guardduty_detector.main.id
  name        = var.finding_filters[count.index].name
  action      = var.finding_filters[count.index].action
  rank        = var.finding_filters[count.index].rank

  finding_criteria {
    dynamic "criterion" {
      for_each = var.finding_filters[count.index].finding_criteria
      content {
        field       = criterion.value.field
        equals      = criterion.value.equals
        not_equals  = criterion.value.not_equals
        greater_than = criterion.value.greater_than
        less_than    = criterion.value.less_than
      }
    }
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-filter-${var.finding_filters[count.index].name}" })
}

# ---------------------------------------------------------------------------
# IP SETS
# ---------------------------------------------------------------------------
resource "aws_guardduty_ipset" "ip_set" {
  count = length(var.ip_sets)

  detector_id = data.aws_guardduty_detector.main.id
  name        = var.ip_sets[count.index].name
  format      = var.ip_sets[count.index].format
  location    = var.ip_sets[count.index].location
  activate    = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-ipset-${var.ip_sets[count.index].name}" })
}

# ---------------------------------------------------------------------------
# THREAT INTELLIGENCE SETS
# ---------------------------------------------------------------------------
resource "aws_guardduty_threatintelset" "threat_intel_set" {
  count = length(var.threat_intel_sets)

  detector_id = data.aws_guardduty_detector.main.id
  name        = var.threat_intel_sets[count.index].name
  format      = var.threat_intel_sets[count.index].format
  location    = var.threat_intel_sets[count.index].location
  activate    = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-threatintel-${var.threat_intel_sets[count.index].name}" })
}

# ---------------------------------------------------------------------------
# KMS KEY (multi-region) FOR SOURCE BUCKET
# ---------------------------------------------------------------------------
resource "aws_kms_key" "multi_region_guardduty" {
  description             = "Multi-region KMS key for GuardDuty findings encryption"
  multi_region            = true
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow GuardDuty to use the key"
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use the key for replication"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt",
          "kms:ReEncryptTo",
          "kms:ReEncryptFrom"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-kms-multi-region" })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# SOURCE S3 BUCKET (findings)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "guardduty_findings" {
  bucket_prefix = "${local.name_prefix}-findings-"
  force_destroy = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-findings" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "findings_versioning" {
  bucket = aws_s3_bucket.guardduty_findings.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "findings_encryption" {
  bucket = aws_s3_bucket.guardduty_findings.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.multi_region_guardduty.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "findings_block" {
  bucket                  = aws_s3_bucket.guardduty_findings.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# S3 BUCKET POLICY FOR GUARDDUTY PUBLISHING
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_policy" "findings_policy" {
  bucket = aws_s3_bucket.guardduty_findings.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Allow GuardDuty to publish findings"
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action = [
          "s3:PutObject",
          "s3:GetBucketLocation"
        ]
        Resource = [
          aws_s3_bucket.guardduty_findings.arn,
          "${aws_s3_bucket.guardduty_findings.arn}/*"
        ]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# ACCESS LOG BUCKET (source region)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "guardduty_logs" {
  bucket_prefix = "${local.name_prefix}-logs-"
  force_destroy = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-logs" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "logs_versioning" {
  bucket = aws_s3_bucket.guardduty_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs_encryption" {
  bucket = aws_s3_bucket.guardduty_logs.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.multi_region_guardduty.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "logs_block" {
  bucket                  = aws_s3_bucket.guardduty_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "findings_logging" {
  bucket        = aws_s3_bucket.guardduty_findings.id
  target_bucket = aws_s3_bucket.guardduty_logs.id
  target_prefix = "access-logs/"
}

# ---------------------------------------------------------------------------
# IAM REPLICATION ROLE POLICY
# ---------------------------------------------------------------------------
resource "aws_iam_role_policy" "s3_replication_policy" {
  name = "${local.name_prefix}-s3-replication-policy"
  role = data.aws_iam_role.s3_replication.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl"
        ]
        Resource = "${aws_s3_bucket.guardduty_findings.arn}/*"
      },
      {
        Effect = "Allow"
        Action = "s3:ReplicateObject"
        Resource = "${aws_s3_bucket.guardduty_findings_replica.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.multi_region_guardduty.arn
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.replica_region_key.arn
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# REPLICA REGION RESOURCES (using provider alias)
# ---------------------------------------------------------------------------
resource "aws_kms_key" "replica_region_key" {
  provider = aws.replica

  description             = "Replica region KMS key for GuardDuty findings replication"
  multi_region            = true
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 replication to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:ReEncryptTo",
          "kms:ReEncryptFrom"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-kms-replica" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "guardduty_findings_replica" {
  provider = aws.replica

  bucket_prefix = "${local.name_prefix}-findings-replica-"
  force_destroy = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-findings-replica" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica_versioning" {
  provider = aws.replica

  bucket = aws_s3_bucket.guardduty_findings_replica.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica_encryption" {
  provider = aws.replica

  bucket = aws_s3_bucket.guardduty_findings_replica.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica_region_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "replica_block" {
  provider = aws.replica

  bucket                  = aws_s3_bucket.guardduty_findings_replica.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Replica region log bucket
resource "aws_s3_bucket" "guardduty_logs_replica" {
  provider = aws.replica

  bucket_prefix = "${local.name_prefix}-logs-replica-"
  force_destroy = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-logs-replica" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "logs_replica_versioning" {
  provider = aws.replica

  bucket = aws_s3_bucket.guardduty_logs_replica.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs_replica_encryption" {
  provider = aws.replica

  bucket = aws_s3_bucket.guardduty_logs_replica.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica_region_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "logs_replica_block" {
  provider = aws.replica

  bucket                  = aws_s3_bucket.guardduty_logs_replica.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "replica_logging" {
  provider = aws.replica

  bucket        = aws_s3_bucket.guardduty_findings_replica.id
  target_bucket = aws_s3_bucket.guardduty_logs_replica.id
  target_prefix = "access-logs/"
}

# ---------------------------------------------------------------------------
# S3 REPLICATION CONFIGURATION (attached to source bucket)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_replication_configuration" "findings_replication" {
  depends_on = [aws_iam_role_policy.s3_replication_policy]

  bucket = aws_s3_bucket.guardduty_findings.id
  role   = data.aws_iam_role.s3_replication.arn

  rule {
    id       = "GuardDutyFindingsReplication"
    status   = "Enabled"
    priority = 1

    filter {
      prefix = ""
    }

    delete_marker_replication {
      status = "Disabled"
    }

    destination {
      bucket        = aws_s3_bucket.guardduty_findings_replica.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica_region_key.arn
      }

      replication_time {
        status = "Enabled"
        time {
          minutes = 15
        }
      }

      metrics {
        status = "Enabled"
        event_threshold {
          minutes = 15
        }
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name_prefix" {
  description = "Prefix for all IAM resource names"
  type        = string
  default     = "imputation-example"
}

variable "tags" {
  description = "Map of tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# Data sources for AWS managed policies (excluding EMR service role)
data "aws_iam_policy" "emr_ec2" {
  name = "AmazonElasticMapReduceforEC2Role"
}

data "aws_iam_policy" "cloudwatch_agent" {
  name = "CloudWatchAgentServerPolicy"
}

data "aws_iam_policy" "ssm_managed_instance" {
  name = "AmazonSSMManagedInstanceCore"
}

data "aws_iam_policy" "emr_autoscaling" {
  name = "AmazonElasticMapReduceforAutoScalingRole"
}

# EMR Service Role with inline policy
resource "aws_iam_role" "emr_service" {
  name = "${var.name_prefix}-emr-service-role"
  tags = var.tags

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "elasticmapreduce.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  inline_policy {
    name = "${var.name_prefix}-emr-service-inline-policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect   = "Allow"
          Action   = [
            "ec2:AuthorizeSecurityGroupEgress",
            "ec2:AuthorizeSecurityGroupIngress",
            "ec2:CancelSpotInstanceRequests",
            "ec2:CreateNetworkInterface",
            "ec2:CreateSecurityGroup",
            "ec2:CreateTags",
            "ec2:DeleteNetworkInterface",
            "ec2:DeleteSecurityGroup",
            "ec2:DeleteTags",
            "ec2:DescribeAvailabilityZones",
            "ec2:DescribeAccountAttributes",
            "ec2:DescribeDhcpOptions",
            "ec2:DescribeInstances",
            "ec2:DescribeKeyPairs",
            "ec2:DescribeNetworkAcls",
            "ec2:DescribeNetworkInterfaces",
            "ec2:DescribePlacementGroups",
            "ec2:DescribeRouteTables",
            "ec2:DescribeSecurityGroups",
            "ec2:DescribeSpotInstanceRequests",
            "ec2:DescribeSpotPriceHistory",
            "ec2:DescribeSubnets",
            "ec2:DescribeTags",
            "ec2:DescribeVpcAttribute",
            "ec2:DescribeVpcEndpoints",
            "ec2:DescribeVpcEndpointServices",
            "ec2:DescribeVpcs",
            "ec2:DetachNetworkInterface",
            "ec2:ModifyImageAttribute",
            "ec2:ModifyInstanceAttribute",
            "ec2:RequestSpotInstances",
            "ec2:RunInstances",
            "ec2:TerminateInstances",
            "ec2:DescribeInstanceStatus",
            "ec2:DescribeVolumes",
            "ec2:DescribeSnapshots",
            "ec2:DescribeImages",
            "iam:GetRole",
            "iam:GetRolePolicy",
            "iam:ListInstanceProfiles",
            "iam:ListRoles",
            "iam:PassRole",
            "s3:GetBucketLocation",
            "s3:GetObject",
            "s3:ListBucket",
            "s3:ListBucketMultipartUploads",
            "s3:ListMultipartUploadParts",
            "s3:AbortMultipartUpload",
            "s3:CreateBucket",
            "s3:PutObject",
            "s3:DeleteObject",
            "s3:GetBucketAcl",
            "s3:PutBucketAcl",
            "s3:PutBucketVersioning",
            "s3:GetBucketVersioning",
            "s3:GetBucketLogging",
            "s3:PutBucketLogging",
            "s3:GetBucketNotification",
            "s3:PutBucketNotification",
            "cloudwatch:PutMetricData",
            "cloudwatch:GetMetricStatistics",
            "cloudwatch:ListMetrics",
            "elasticmapreduce:*",
            "ecs:DescribeClusters",
            "ecs:DescribeTaskDefinition",
            "ecs:RunTask",
            "ecs:StopTask",
            "ecs:RegisterTaskDefinition",
            "ecs:DeregisterTaskDefinition",
            "ecs:DescribeTasks",
            "ecs:ListTaskDefinitions",
            "ecs:ListTasks"
          ]
          Resource = "*"
        }
      ]
    })
  }
}

# EC2 Instance Profile Role (for EMR EC2 instances)
resource "aws_iam_role" "ec2_instance_profile" {
  name = "${var.name_prefix}-emr-ec2-instance-profile-role"
  tags = var.tags

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_instance_profile_emr" {
  role       = aws_iam_role.ec2_instance_profile.name
  policy_arn = data.aws_iam_policy.emr_ec2.arn
}

resource "aws_iam_role_policy_attachment" "ec2_instance_profile_cloudwatch" {
  role       = aws_iam_role.ec2_instance_profile.name
  policy_arn = data.aws_iam_policy.cloudwatch_agent.arn
}

resource "aws_iam_role_policy_attachment" "ec2_instance_profile_ssm" {
  role       = aws_iam_role.ec2_instance_profile.name
  policy_arn = data.aws_iam_policy.ssm_managed_instance.arn
}

# EMR Auto Scaling Role
resource "aws_iam_role" "emr_autoscaling" {
  name = "${var.name_prefix}-emr-autoscaling-role"
  tags = var.tags

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "application-autoscaling.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "emr_autoscaling" {
  role       = aws_iam_role.emr_autoscaling.name
  policy_arn = data.aws_iam_policy.emr_autoscaling.arn
}

# EC2 Instance Profile
resource "aws_iam_instance_profile" "emr_ec2" {
  name = "${var.name_prefix}-emr-ec2-instance-profile"
  role = aws_iam_role.ec2_instance_profile.name
  tags = var.tags
}

# Outputs
output "emr_service_role_arn" {
