terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ---------------------------------------------------------------
# Variables
# ---------------------------------------------------------------
variable "cognito_user_pool_arn" {
  description = "Optional ARN of a Cognito user pool. If provided, an additional policy granting cognito-idp:AdminInitiateAuth is attached to the IAM user."
  type        = string
  default     = ""
}

# ---------------------------------------------------------------
# IAM User and Access Key
# ---------------------------------------------------------------
resource "aws_iam_user" "postman_user" {
  name = "postman-user"
  path = "/"
}

resource "aws_iam_access_key" "postman_user_key" {
  user = aws_iam_user.postman_user.name
}

# ---------------------------------------------------------------
# IAM Policy Documents
# ---------------------------------------------------------------
data "aws_iam_policy_document" "api_gateway_read_only" {
  statement {
    effect = "Allow"
    actions = [
      "apigateway:GET"
    ]
    resources = [
      "arn:aws:apigateway:*::/*"
    ]
  }
}

data "aws_iam_policy_document" "cloudwatch_metrics_read_only" {
  statement {
    effect = "Allow"
    actions = [
      "cloudwatch:GetMetricData",
      "cloudwatch:ListMetrics"
    ]
    resources = [
      "*"
    ]
  }
}

data "aws_iam_policy_document" "cognito_admin_auth" {
  count = var.cognito_user_pool_arn != "" ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "cognito-idp:AdminInitiateAuth"
    ]
    resources = [
      var.cognito_user_pool_arn
    ]
  }
}

# ---------------------------------------------------------------
# IAM Policies
# ---------------------------------------------------------------
resource "aws_iam_policy" "api_gateway_read_only" {
  name        = "apigateway-read-only"
  description = "Grant global read-only access to API Gateway (apigateway:GET)"
  policy      = data.aws_iam_policy_document.api_gateway_read_only.json
}

resource "aws_iam_policy" "cloudwatch_metrics_read_only" {
  name        = "cloudwatch-metrics-read-only"
  description = "Grant read-only access to CloudWatch metrics (GetMetricData, ListMetrics)"
  policy      = data.aws_iam_policy_document.cloudwatch_metrics_read_only.json
}

resource "aws_iam_policy" "cognito_admin_auth" {
  count       = var.cognito_user_pool_arn != "" ? 1 : 0
  name        = "cognito-admin-init-auth"
  description = "Grant cognito-idp:AdminInitiateAuth on the specified Cognito user pool"
  policy      = data.aws_iam_policy_document.cognito_admin_auth[0].json
}

# ---------------------------------------------------------------
# Policy Attachments to the IAM User
# ---------------------------------------------------------------
resource "aws_iam_user_policy_attachment" "api_gateway_read_only" {
  user       = aws_iam_user.postman_user.name
  policy_arn = aws_iam_policy.api_gateway_read_only.arn
}

resource "aws_iam_user_policy_attachment" "cloudwatch_metrics_read_only" {
  user       = aws_iam_user.postman_user.name
  policy_arn = aws_iam_policy.cloudwatch_metrics_read_only.arn
}

resource "aws_iam_user_policy_attachment" "cognito_admin_auth_attachment" {
  count      = var.cognito_user_pool_arn != "" ? 1 : 0
  user       = aws_iam_user.postman_user.name
  policy_arn = aws_iam_policy.cognito_admin_auth[0].arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = "legion"
}

data "aws_iam_policy_document" "eks_master_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "eks_node_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "eks_autoscaling" {
  statement {
    effect = "Allow"
    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "autoscaling:DescribeLaunchTemplateVersions"
    ]
    resources = ["*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup",
      "autoscaling:UpdateAutoScalingGroup"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "autoscaling:ResourceTag/kubernetes.io/cluster/${var.cluster_name}"
      values   = ["owned"]
    }
    condition {
      test     = "StringEquals"
      variable = "autoscaling:ResourceTag/k8s.io/cluster-autoscaler/enabled"
      values   = ["true"]
    }
  }
}

# Master IAM Role
resource "aws_iam_role" "eks_master" {
  name               = "tf-${var.cluster_name}"
  assume_role_policy = data.aws_iam_policy_document.eks_master_assume_role.json
}

resource "aws_iam_role_policy_attachment" "eks_master_cluster_policy" {
  role       = aws_iam_role.eks_master.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_master_service_policy" {
  role       = aws_iam_role.eks_master.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
}

# Worker Node IAM Role
resource "aws_iam_role" "eks_node" {
  name               = "tf-${var.cluster_name}-node"
  assume_role_policy = data.aws_iam_policy_document.eks_node_assume_role.json
}

resource "aws_iam_role_policy_attachment" "eks_node_worker_policy" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "eks_node_cni_policy" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "eks_node_ecr_readonly" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

# Instance Profile for Worker Nodes
resource "aws_iam_instance_profile" "eks_node" {
  name = "tf-${var.cluster_name}-node"
  role = aws_iam_role.eks_node.name
}

# Custom Autoscaling Policy
resource "aws_iam_policy" "eks_autoscaling" {
  name        = "eks-worker-autoscaling-${var.cluster_name}"
  description = "Policy for EKS Cluster Autoscaler to manage Auto Scaling groups"
  policy      = data.aws_iam_policy_document.eks_autoscaling.json
}

resource "aws_iam_role_policy_attachment" "eks_node_autoscaling" {
  role       = aws_iam_role.eks_node.name
  policy_arn = aws_iam_policy.eks_autoscaling.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 6.0, < 6.70.0"
    }
  }
}

# Variables
variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "172.69.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "172.69.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  type        = string
  default     = "172.69.2.0/24"
}

variable "web_server_ingress_rules" {
  description = "Ingress rules for the web server security group"
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  default = [
    {
      from_port   = 80
      to_port     = 80
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    },
    {
      from_port   = 22
      to_port     = 22
      protocol    = "tcp"
      cidr_blocks = ["172.69.0.0/16"] # Will be overridden by var.vpc_cidr
    }
  ]
}

# Local to resolve VPC CIDR for port 22 rule
locals {
  web_server_ingress_rules_resolved = [
    for rule in var.web_server_ingress_rules : {
      from_port   = rule.from_port
      to_port     = rule.to_port
      protocol    = rule.protocol
      cidr_blocks = rule.from_port == 22 ? [var.vpc_cidr] : rule.cidr_blocks
    }
  ]
}

# VPC
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "vpc_name"
  }
}

# Public subnet
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  map_public_ip_on_launch = false

  tags = {
    Name = "public_subnet"
  }
}

# Private subnet
resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidr
  map_public_ip_on_launch = false

  tags = {
    Name = "private_subnet"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "igw_tag"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "rtb_tag"
  }
}

# Route table association
resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Web server security group
resource "aws_security_group" "web_server" {
  name        = "webserver-sg_${aws_vpc.main.id}"
  description = "Security group for web servers"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = local.web_server_ingress_rules_resolved
    content {
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
    }
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "web-server_security_group"
  }
}

# Database security group
resource "aws_security_group" "database" {
  name        = "database-sg_${aws_vpc.main.id}"
  description = "Security group for databases"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.web_server.id]
  }

  # No egress rules specified; default allows all outbound traffic
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "tags" {
  description = "Common tags for all resources"
  type        = map(string)
  default     = {}
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "controlplane_policy" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:CreateNetworkInterface",
      "ec2:DeleteNetworkInterface",
      "ec2:AttachNetworkInterface",
      "ec2:DetachNetworkInterface",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DescribeInstances",
      "ec2:DescribeSubnets",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeVpcs",
      "ec2:DescribeAvailabilityZones",
      "ec2:DescribeRouteTables",
      "ec2:DescribeInternetGateways",
      "ec2:DescribeNatGateways",
      "ec2:ModifyNetworkInterfaceAttribute",
      "ec2:AssignPrivateIpAddresses",
      "ec2:UnassignPrivateIpAddresses"
    ]
    resources = ["*"]
  }
  statement {
    effect = "Allow"
    actions = [
      "autoscaling:DescribeAutoScalingGroups"
    ]
    resources = ["*"]
  }
  statement {
    effect = "Allow"
    actions = [
      "elasticloadbalancing:DescribeLoadBalancers",
      "elasticloadbalancing:DescribeTargetGroups",
      "elasticloadbalancing:DescribeListeners",
      "elasticloadbalancing:DescribeRules",
      "elasticloadbalancing:CreateLoadBalancer",
      "elasticloadbalancing:DeleteLoadBalancer",
      "elasticloadbalancing:ModifyLoadBalancerAttributes",
      "elasticloadbalancing:CreateTargetGroup",
      "elasticloadbalancing:DeleteTargetGroup",
      "elasticloadbalancing:ModifyTargetGroupAttributes",
      "elasticloadbalancing:RegisterTargets",
      "elasticloadbalancing:DeregisterTargets",
      "elasticloadbalancing:CreateListener",
      "elasticloadbalancing:DeleteListener",
      "elasticloadbalancing:ModifyListener",
      "elasticloadbalancing:CreateRule",
      "elasticloadbalancing:DeleteRule",
      "elasticloadbalancing:ModifyRule",
      "elasticloadbalancing:SetSecurityGroups",
      "elasticloadbalancing:SetSubnets"
    ]
    resources = ["*"]
  }
  statement {
    effect = "Allow"
    actions = [
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }
  statement {
    effect = "Allow"
    actions = [
      "iam:CreateServiceLinkedRole"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "iam:AWSServiceName"
      values   = ["elasticloadbalancing.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "worker_policy" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeRegions"
    ]
    resources = ["*"]
  }
  statement {
    effect = "Allow"
    actions = [
      "ecr:GetAuthorizationToken"
    ]
    resources = ["*"]
  }
  statement {
    effect = "Allow"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:GetDownloadUrlForLayer",
      "ecr:GetRepositoryPolicy",
      "ecr:DescribeRepositories",
      "ecr:ListImages"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role" "controlplane" {
  name               = "aws_ccm_k8s_controlplane"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = var.tags
}

resource "aws_iam_instance_profile" "controlplane" {
  name = "aws_ccm_k8s_controlplane"
  role = aws_iam_role.controlplane.name
  tags = var.tags
}

resource "aws_iam_policy" "controlplane" {
  name        = "aws_ccm_k8s_controlplane"
  description = "IAM policy for Kubernetes control plane nodes"
  policy      = data.aws_iam_policy_document.controlplane_policy.json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "controlplane" {
  role       = aws_iam_role.controlplane.name
  policy_arn = aws_iam_policy.controlplane.arn
}

resource "aws_iam_role" "worker" {
  name               = "aws_ccm_k8s_worker"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = var.tags
}

resource "aws_iam_instance_profile" "worker" {
  name = "aws_ccm_k8s_worker"
  role = aws_iam_role.worker.name
  tags = var.tags
}

resource "aws_iam_policy" "worker" {
  name        = "aws_ccm_k8s_worker"
  description = "IAM policy for Kubernetes worker nodes"
  policy      = data.aws_iam_policy_document.worker_policy.json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "worker" {
  role       = aws_iam_role.worker.name
  policy_arn = aws_iam_policy.worker.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100"
    }
  }
}

data "aws_caller_identity" "current" {}

variable "name_prefix" {
  type        = string
  default     = "awscademo-"
  description = "Prefix for resource naming"
}

variable "default_tags" {
  type = map(string)
  default = {
    contact    = "devops@example.com"
    deployment = "terraform"
    ttl        = "infinite"
  }
}

locals {
  admin_role_name = substr("${var.name_prefix}admin-role", 0, 31)
  default_tags    = merge(var.default_tags, { deployment_date = timestamp() })
}

# IAM Groups
resource "aws_iam_group" "demo_users" {
  name = "${var.name_prefix}demo-users"
}

resource "aws_iam_group" "read_only_users" {
  name = "${var.name_prefix}read-only-users"
}

resource "aws_iam_group" "mfa_superadmin" {
  name = "${var.name_prefix}mfa-superadmin"
}

# Attach ReadOnlyAccess managed policy to read-only group
resource "aws_iam_group_policy_attachment" "read_only_attach" {
  group      = aws_iam_group.read_only_users.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

# Custom self-management policy for demo users
data "aws_iam_policy_document" "demo_self_management" {
  statement {
    sid = "AllowUserSelfManagement"
    actions = [
      "iam:ChangePassword",
      "iam:CreateAccessKey",
      "iam:UpdateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
      "iam:UploadSSHPublicKey",
      "iam:GetSSHPublicKey",
      "iam:DeleteSSHPublicKey",
      "iam:ListSSHPublicKeys",
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice",
      "iam:CreateVirtualMFADevice"
    ]
    resources = [
      "arn:aws:iam::*:user/&{aws:username}",
      "arn:aws:iam::*:mfa/&{aws:username}"
    ]
  }

  statement {
    sid = "DeactivateMFAWithMFA"
    actions = [
      "iam:DeactivateMFADevice"
    ]
    resources = [
      "arn:aws:iam::*:mfa/&{aws:username}"
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "demo_self_management" {
  name        = "${var.name_prefix}self-management"
  description = "Self-management policy for demo users"
  policy      = data.aws_iam_policy_document.demo_self_management.json
}

resource "aws_iam_group_policy_attachment" "demo_self_management_attach" {
  group      = aws_iam_group.demo_users.name
  policy_arn = aws_iam_policy.demo_self_management.arn
}

# Admin role
data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name               = local.admin_role_name
  assume_role_policy = data.aws_iam_policy_document.admin_assume_role.json
  max_session_duration = 43200
  tags = merge(local.default_tags, {
    Name = local.admin_role_name
  })
}

# Admin policy attached to role (full admin with MFA condition)
data "aws_iam_policy_document" "admin_policy" {
  statement {
    sid = "FullAdminAccessWithMFA"
    actions = ["*"]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin_policy" {
  name        = "${var.name_prefix}admin-policy"
  description = "Admin policy requiring MFA"
  policy      = data.aws_iam_policy_document.admin_policy.json
}

resource "aws_iam_role_policy_attachment" "admin_policy_attach" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin_policy.arn
}

# Group policy for MFA superadmin to assume the admin role
data "aws_iam_policy_document" "mfa_superadmin_group_policy" {
  statement {
    actions = ["sts:AssumeRole"]
    resources = [aws_iam_role.admin.arn]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "mfa_superadmin_group_policy" {
  name        = "${var.name_prefix}mfa-superadmin-assume"
  description = "Allow MFA superadmin group to assume admin role with MFA"
  policy      = data.aws_iam_policy_document.mfa_superadmin_group_policy.json
}

resource "aws_iam_group_policy_attachment" "mfa_superadmin_attach" {
  group      = aws_iam_group.mfa_superadmin.name
  policy_arn = aws_iam_policy.mfa_superadmin_group_policy.arn
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "6.69.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# IAM Groups
# ------------------------------------------------------------------------------
resource "aws_iam_group" "admin" {
  name = "admin"
  path = "/admin/"
}

resource "aws_iam_group" "admin_terraform_cloud" {
  name = "admin-terraform-cloud"
  path = "/admin_terraform_cloud/"
}

resource "aws_iam_group" "github" {
  name = "github"
  path = "/github/"
}

resource "aws_iam_group" "serverless" {
  name = "serverless"
  path = "/serverless/"
}

# ------------------------------------------------------------------------------
# Inline Group Policies (using data.aws_iam_policy_document)
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "admin" {
  statement {
    effect    = "Allow"
    actions   = ["*"]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "admin_terraform_cloud" {
  statement {
    effect    = "Allow"
    actions   = ["*"]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "github" {
  statement {
    effect = "Allow"
    actions = [
      "acm:DescribeCertificate",
      "acm:GetCertificate",
      "acm:ListCertificates",
      "acm:RequestCertificate",
      "cloudfront:CreateDistribution",
      "cloudfront:GetDistribution",
      "cloudfront:ListDistributions",
      "cloudfront:UpdateDistribution",
      "iam:CreateRole",
      "iam:DeleteRole",
      "iam:GetRole",
      "iam:ListRoles",
      "iam:PassRole",
      "iam:PutRolePolicy",
      "lambda:CreateFunction",
      "lambda:GetFunction",
      "lambda:ListFunctions",
      "lambda:UpdateFunctionCode",
      "route53:ChangeResourceRecordSets",
      "route53:GetHostedZone",
      "route53:ListHostedZones",
      "s3:DeleteObject",
      "s3:GetObject",
      "s3:ListBucket",
      "s3:PutObject",
      "sqs:DeleteMessage",
      "sqs:ReceiveMessage",
      "sqs:SendMessage"
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "serverless_group" {
  statement {
    effect = "Allow"
    actions = [
      "acm:DescribeCertificate",
      "acm:GetCertificate",
      "acm:ListCertificates",
      "cloudfront:CreateDistribution",
      "cloudfront:GetDistribution",
      "cloudfront:ListDistributions",
      "cloudfront:UpdateDistribution",
      "iam:CreateRole",
      "iam:DeleteRole",
      "iam:GetRole",
      "iam:ListRoles",
      "iam:PassRole",
      "iam:PutRolePolicy",
      "lambda:CreateFunction",
      "lambda:GetFunction",
      "lambda:ListFunctions",
      "lambda:UpdateFunctionCode",
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "route53:ChangeResourceRecordSets",
      "route53:GetHostedZone",
      "route53:ListHostedZones",
      "s3:DeleteObject",
      "s3:GetObject",
      "s3:ListBucket",
      "s3:PutObject",
      "sqs:DeleteMessage",
      "sqs:ReceiveMessage",
      "sqs:SendMessage"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_group_policy" "admin" {
  name   = "admin-policy"
  group  = aws_iam_group.admin.name
  policy = data.aws_iam_policy_document.admin.json
}

resource "aws_iam_group_policy" "admin_terraform_cloud" {
  name   = "admin-terraform-cloud-policy"
  group  = aws_iam_group.admin_terraform_cloud.name
  policy = data.aws_iam_policy_document.admin_terraform_cloud.json
}

resource "aws_iam_group_policy" "github" {
  name   = "github-policy"
  group  = aws_iam_group.github.name
  policy = data.aws_iam_policy_document.github.json
}

resource "aws_iam_group_policy" "serverless" {
  name   = "serverless-policy"
  group  = aws_iam_group.serverless.name
  policy = data.aws_iam_policy_document.serverless_group.json
}

# ------------------------------------------------------------------------------
# IAM Users
# ------------------------------------------------------------------------------
resource "aws_iam_user" "admin" {
  name = "admin"
  path = "/admin/"
}

resource "aws_iam_user" "admin_macbook_pro" {
  name = "admin-macbook-pro"
  path = "/admin/"
}

resource "aws_iam_user" "admin_terraform_cloud_user" {
  name = "admin-terraform-cloud"
  path = "/admin_terraform_cloud/"
}

resource "aws_iam_user" "github" {
  name = "github"
  path = "/github/"
}

resource "aws_iam_user" "serverless" {
  name = "serverless"
  path = "/serverless/"
}

# ------------------------------------------------------------------------------
# User Group Memberships
# ------------------------------------------------------------------------------
resource "aws_iam_user_group_membership" "admin" {
  user   = aws_iam_user.admin.name
  groups = [aws_iam_group.admin.name]
}

resource "aws_iam_user_group_membership" "admin_macbook_pro" {
  user   = aws_iam_user.admin_macbook_pro.name
  groups = [aws_iam_group.admin.name]
}

resource "aws_iam_user_group_membership" "admin_terraform_cloud" {
  user   = aws_iam_user.admin_terraform_cloud_user.name
  groups = [aws_iam_group.admin_terraform_cloud.name]
}

resource "aws_iam_user_group_membership" "github" {
  user   = aws_iam_user.github.name
  groups = [aws_iam_group.github.name]
}

resource "aws_iam_user_group_membership" "serverless" {
  user   = aws_iam_user.serverless.name
  groups = [aws_iam_group.serverless.name]
}

# ------------------------------------------------------------------------------
# Access Keys (stored in AWS Secrets Manager for security)
# ------------------------------------------------------------------------------
resource "aws_iam_access_key" "admin_macbook_pro" {
