}

resource "aws_secretsmanager_secret" "admin_macbook_pro" {
  name = "admin-macbook-pro-access-key"
}

resource "aws_secretsmanager_secret_version" "admin_macbook_pro" {
  secret_id     = aws_secretsmanager_secret.admin_macbook_pro.id
