}

resource "aws_secretsmanager_secret" "admin_terraform_cloud" {
  name = "admin-terraform-cloud-access-key"
}

resource "aws_secretsmanager_secret_version" "admin_terraform_cloud" {
  secret_id     = aws_secretsmanager_secret.admin_terraform_cloud.id
  secret_string = jsonencode({
    access_key_id     = aws_iam_access_key.admin_terraform_cloud.id
    secret_access_key = aws_iam_access_key.admin_terraform_cloud.secret
  })
}

# ------------------------------------------------------------------------------
# Serverless Role and Policy
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "serverless_role_trust" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com", "edgelambda.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "serverless" {
  name               = "serverless"
  path               = "/serverless/"
  assume_role_policy = data.aws_iam_policy_document.serverless_role_trust.json
}

data "aws_iam_policy_document" "serverless_policy" {
  statement {
    effect = "Allow"
    actions = [
      "acm:DescribeCertificate",
      "acm:GetCertificate",
      "acm:ListCertificates",
      "cloudfront:CreateDistribution",
      "cloudfront:GetDistribution",
      "cloudfront:ListDistributions",
      "cloudfront:UpdateDistribution",
      "iam:CreateRole",
      "iam:DeleteRole",
      "iam:GetRole",
      "iam:ListRoles",
      "iam:PassRole",
      "iam:PutRolePolicy",
      "lambda:CreateFunction",
      "lambda:GetFunction",
      "lambda:ListFunctions",
      "lambda:UpdateFunctionCode",
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "route53:ChangeResourceRecordSets",
      "route53:GetHostedZone",
      "route53:ListHostedZones",
      "s3:DeleteObject",
      "s3:GetObject",
      "s3:ListBucket",
      "s3:PutObject",
      "sqs:DeleteMessage",
      "sqs:ReceiveMessage",
      "sqs:SendMessage"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "serverless" {
  name        = "serverless"
  path        = "/serverless/"
  description = "Policy for serverless role"
  policy      = data.aws_iam_policy_document.serverless_policy.json
}

resource "aws_iam_role_policy_attachment" "serverless" {
  role       = aws_iam_role.serverless.name
  policy_arn = aws_iam_policy.serverless.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
  }
}

# Data sources
data "aws_caller_identity" "current" {}

# CloudPosse label for admin group
module "label_admin" {
  source     = "cloudposse/label/null"
  version    = "0.25.0"
  namespace  = var.namespace
  environment = var.environment
  name       = var.name
  attributes = var.attributes
  tags       = var.tags
}

# CloudPosse label for non-admin group
module "label_non_admin" {
  source     = "cloudposse/label/null"
  version    = "0.25.0"
  namespace  = var.namespace
  environment = var.environment
  name       = var.name
  attributes = concat(var.attributes, ["non-admin"])
  tags       = var.tags
}

# CloudPosse label for admin role
module "label_admin_role" {
  source     = "cloudposse/label/null"
  version    = "0.25.0"
  namespace  = var.namespace
  environment = var.environment
  name       = var.name
  attributes = concat(var.attributes, ["admin"])
  tags       = var.tags
}

# IAM groups
resource "aws_iam_group" "admin" {
  name = module.label_admin.id
  path = "/"
}

resource "aws_iam_group" "non_admin" {
  name = module.label_non_admin.id
  path = "/"
}

# Self-management policy document
data "aws_iam_policy_document" "self_management" {
  statement {
    sid    = "SelfManagePassword"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:GetAccountPasswordPolicy"
    ]
    resources = ["arn:aws:iam::*:user/&{aws:username}"]
  }

  statement {
    sid    = "SelfManageAccessKeys"
    effect = "Allow"
    actions = [
      "iam:CreateAccessKey",
      "iam:UpdateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys"
    ]
    resources = ["arn:aws:iam::*:user/&{aws:username}"]
  }

  statement {
    sid    = "SelfManageVirtualMFADevice"
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ListVirtualMFADevices",
      "iam:ResyncMFADevice"
    ]
    resources = [
      "arn:aws:iam::*:user/&{aws:username}",
      "arn:aws:iam::*:mfa/&{aws:username}"
    ]
  }

  statement {
    sid    = "DeactivateMFADeviceWithMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice"
    ]
    resources = [
      "arn:aws:iam::*:user/&{aws:username}",
      "arn:aws:iam::*:mfa/&{aws:username}"
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid    = "ListAccountMFADevicesAndPolicy"
    effect = "Allow"
    actions = [
      "iam:ListAccountAliases",
      "iam:GetAccountSummary"
    ]
    resources = ["*"]
  }
}

# Self-management policy
resource "aws_iam_policy" "self_management" {
  name        = "${module.label_admin.id}-self-management"
  description = "Policy for self-management of IAM credentials and MFA"
  policy      = data.aws_iam_policy_document.self_management.json
}

# Attach self-management policy to both groups
resource "aws_iam_group_policy_attachment" "self_management_admin" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "self_management_non_admin" {
  group      = aws_iam_group.non_admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

# Admin group additional policy: assume role with MFA
data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    sid    = "AllowAssumeAdminRoleWithMFA"
    effect = "Allow"
    actions = [
      "sts:AssumeRole"
    ]
    resources = [aws_iam_role.admin.arn]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin_assume_role" {
  name        = "${module.label_admin.id}-assume-admin-role"
  description = "Policy for admin group to assume admin role"
  policy      = data.aws_iam_policy_document.admin_assume_role.json
}

resource "aws_iam_group_policy_attachment" "admin_assume_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_assume_role.arn
}

# Admin role
data "aws_iam_policy_document" "admin_role_trust" {
  statement {
    sid    = "AllowRootAssumeRoleWithMFA"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions = ["sts:AssumeRole"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name               = module.label_admin_role.id
  description        = "Administrator role with full access, requiring MFA"
  assume_role_policy = data.aws_iam_policy_document.admin_role_trust.json
}

resource "aws_iam_role_policy_attachment" "admin" {
  role       = aws_iam_role.admin.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

# IAM users
resource "aws_iam_user" "admin" {
  for_each = toset(var.admin_users)
  name     = each.value
  path     = "/"
}

resource "aws_iam_user" "non_admin" {
  for_each = toset(var.non_admin_users)
  name     = each.value
  path     = "/"
}

# Add users to groups
resource "aws_iam_user_group_membership" "admin" {
  for_each = toset(var.admin_users)
  user     = each.value
  groups   = [aws_iam_group.admin.name]
}

resource "aws_iam_user_group_membership" "non_admin" {
  for_each = toset(var.non_admin_users)
  user     = each.value
  groups   = [aws_iam_group.non_admin.name]
}

# Variables
variable "namespace" {
  description = "Namespace (e.g., 'eg' or 'cp')"
  type        = string
  default     = "eg"
}

variable "environment" {
  description = "Environment (e.g., 'prod', 'dev')"
  type        = string
  default     = "prod"
}

variable "name" {
  description = "Name (e.g., 'iam' or 'app')"
  type        = string
  default     = "iam"
}

variable "attributes" {
  description = "Additional attributes (e.g., ['admin', 'readonly'])"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags (e.g., map('Owner', 'DevOps'))"
  type        = map(string)
  default     = {}
}

variable "admin_users" {
  description = "List of admin usernames"
  type        = list(string)
  default     = []
}

variable "non_admin_users" {
  description = "List of non-admin usernames"
  type        = list(string)
  default     = []
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0, < 5.0"
    }
  }
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default = {
    Environment = "dev"
    Project     = "test"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr = "10.0.0.0/16"
  # Public subnets: /24, one per AZ, starting at 10.0.1.0
  public_subnet_newbits  = 8
  # Private subnets: /24, two per AZ, starting at 10.0.11.0
  private_subnet_newbits = 8
  public_subnet_count    = 2
  private_subnet_count   = 4
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, { Name = "dev-test-vpc" })
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, { Name = "dev-test-igw" })
}

# Public Subnets (one per AZ)
resource "aws_subnet" "public" {
  count = local.public_subnet_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(local.vpc_cidr, local.public_subnet_newbits, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.tags, { Name = "dev-test-public-subnet-${count.index + 1}" })
}

# Private Subnets (two per AZ)
resource "aws_subnet" "private" {
  count = local.private_subnet_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, local.private_subnet_newbits, 11 + (count.index % 2) + (floor(count.index / 2) * 10))
  availability_zone = data.aws_availability_zones.available.names[count.index % 2]

  tags = merge(var.tags, { Name = "dev-test-private-subnet-${count.index + 1}" })
}

# Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.tags, { Name = "dev-test-public-rt" })
}

# Private Route Table (no explicit routes)
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, { Name = "dev-test-private-rt" })
}

# Route Table Associations
resource "aws_route_table_association" "public" {
  count = local.public_subnet_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count = local.private_subnet_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Public Security Group
resource "aws_security_group" "public" {
  name        = "public-sg"
  description = "Public security group for dev/test"
  vpc_id      = aws_vpc.main.id

  tags = merge(var.tags, { Name = "dev-test-public-sg" })
}

# Ingress rules for public SG
resource "aws_security_group_rule" "public_ingress_all_vpc" {
  type              = "ingress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.public.id
}

resource "aws_security_group_rule" "public_ingress_ssh_vpc" {
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.public.id
}

resource "aws_security_group_rule" "public_ingress_http_all" {
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.public.id
}

# Egress rule for public SG
resource "aws_security_group_rule" "public_egress_vpc" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.public.id
}

# Private Security Group
resource "aws_security_group" "private" {
  name        = "private-sg"
  description = "Private security group for dev/test"
  vpc_id      = aws_vpc.main.id

  tags = merge(var.tags, { Name = "dev-test-private-sg" })
}

# Ingress rule for private SG
resource "aws_security_group_rule" "private_ingress_all_vpc" {
  type              = "ingress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.private.id
}

# Egress rule for private SG
resource "aws_security_group_rule" "private_egress_vpc" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.private.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name_suffix" {
  type    = string
  default = ""
}

locals {
  role_name        = "prod-ci-${var.name_suffix}"
  policy_name      = "prod-ci-assume-${var.name_suffix}"
  group_name       = "prod-ci-${var.name_suffix}"
  user_name        = "prod-ci-${var.name_suffix}"
  membership_name  = "prod-ci-membership-${var.name_suffix}"
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
  }
}

resource "aws_iam_role" "this" {
  name               = local.role_name
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
}

data "aws_iam_policy_document" "assume_policy" {
  statement {
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.this.arn]
  }
}

resource "aws_iam_policy" "assume_role_policy" {
  name        = local.policy_name
  policy      = data.aws_iam_policy_document.assume_policy.json
}

resource "aws_iam_group" "this" {
  name = local.group_name
}

resource "aws_iam_group_policy_attachment" "this" {
  group      = aws_iam_group.this.name
  policy_arn = aws_iam_policy.assume_role_policy.arn
}

resource "aws_iam_user" "this" {
  name = local.user_name
}

resource "aws_iam_group_membership" "this" {
  name  = local.membership_name
  users = [aws_iam_user.this.name]
  group = aws_iam_group.this.name
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

resource "aws_config_configuration_aggregator" "default" {
  name = "default"

  account_aggregation_source {
    account_ids = [data.aws_caller_identity.current.account_id]
    all_regions = true
  }

  tags = {
    Terraform = "true"
    ManagedBy = "Terraform"
  }
}

# Terraform configuration
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.99.0"
    }
  }
}

# Variables
variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "tags" {
  description = "Additional tags to apply to all resources"
  type        = map(string)
  default     = {}
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "ssh_inbound" {
  description = "List of CIDR blocks allowed for SSH access to public instances"
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Locals
locals {
  az_names  = data.aws_availability_zones.available.names
  az_count  = length(local.az_names)
  newbits   = ceil(log(local.az_count * 2, 2))

  # Tags
  default_tags = {
    Name = var.vpc_name
  }
  merged_tags = merge(local.default_tags, var.tags)
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = local.merged_tags
}

# Public subnets
resource "aws_subnet" "public" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, local.newbits, count.index)
  availability_zone       = local.az_names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.default_tags, {
    Name = "${var.vpc_name}-public-${count.index + 1}"
  }, var.tags)
}

# Private subnets
resource "aws_subnet" "private" {
  count             = local.az_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, local.newbits, count.index + local.az_count)
  availability_zone = local.az_names[count.index]

  tags = merge(local.default_tags, {
    Name = "${var.vpc_name}-private-${count.index + 1}"
  }, var.tags)
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.default_tags, {
    Name = "${var.vpc_name}-igw"
  }, var.tags)
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.default_tags, {
    Name = "${var.vpc_name}-nat-eip"
  }, var.tags)
}

# NAT Gateway in first public subnet
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.default_tags, {
    Name = "${var.vpc_name}-nat-gw"
  }, var.tags)

  depends_on = [aws_internet_gateway.main]
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.default_tags, {
    Name = "${var.vpc_name}-public-rt"
  }, var.tags)
}

resource "aws_route" "public_internet_gateway" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private route table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.default_tags, {
    Name = "${var.vpc_name}-private-rt"
  }, var.tags)
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main.id
}

resource "aws_route_table_association" "private" {
  count          = local.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Default Network ACL (manage existing)
resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.main.default_network_acl_id

  tags = merge(local.default_tags, {
    Name = "${var.vpc_name}-Default"
  }, var.tags)
}

# Default Security Group (manage existing)
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.default_tags, {
    Name = "${var.vpc_name}-Default"
  }, var.tags)
}

# Public Security Group
resource "aws_security_group" "public" {
  name        = "${var.vpc_name}-public-sg"
  description = "Security group for public tier"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.default_tags, {
    Name = "${var.vpc_name}-public-sg"
  }, var.tags)
}

resource "aws_security_group_rule" "public_ingress_http" {
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.public.id
}

resource "aws_security_group_rule" "public_ingress_https" {
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.public.id
}

resource "aws_security_group_rule" "public_ingress_ssh" {
  count             = length(var.ssh_inbound)
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [var.ssh_inbound[count.index]]
  security_group_id = aws_security_group.public.id
}

resource "aws_security_group_rule" "public_egress_http" {
  type              = "egress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = [var.vpc_cidr]
  security_group_id = aws_security_group.public.id
}

resource "aws_security_group_rule" "public_egress_https" {
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = [var.vpc_cidr]
  security_group_id = aws_security_group.public.id
}

# Private Security Group
resource "aws_security_group" "private" {
  name        = "${var.vpc_name}-private-sg"
  description = "Security group for private tier"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.default_tags, {
    Name = "${var.vpc_name}-private-sg"
  }, var.tags)
}

resource "aws_security_group_rule" "private_ingress_http" {
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = aws_subnet.public[*].cidr_block
  security_group_id = aws_security_group.private.id
}

resource "aws_security_group_rule" "private_ingress_https" {
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = aws_subnet.public[*].cidr_block
  security_group_id = aws_security_group.private.id
}

resource "aws_security_group_rule" "private_egress_https" {
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = [var.vpc_cidr]
  security_group_id = aws_security_group.private.id
}

# Public Network ACL
resource "aws_network_acl" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.default_tags, {
    Name = "${var.vpc_name}-public-nacl"
  }, var.tags)
}

# Public NACL Ingress Rules
resource "aws_network_acl_rule" "public_ingress_http" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 200
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_ingress_https" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 210
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "public_ingress_ephemeral" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 220
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

# Public NACL Ingress SSH rules (starting rule 100 + index for each SSH CIDR)
resource "aws_network_acl_rule" "public_ingress_ssh" {
  count          = length(var.ssh_inbound)
  network_acl_id = aws_network_acl.public.id
  rule_number    = 100 + count.index
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = var.ssh_inbound[count.index]
  from_port      = 22
  to_port        = 22
}

# Public NACL Egress Rules
resource "aws_network_acl_rule" "public_egress_http" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_egress_https" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 110
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "public_egress_ephemeral" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 120
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

# Public NACL Associations
resource "aws_network_acl_association" "public" {
  count          = local.az_count
  network_acl_id = aws_network_acl.public.id
  subnet_id      = aws_subnet.public[count.index].id
}

# Private Network ACL
resource "aws_network_acl" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.default_tags, {
    Name = "${var.vpc_name}-private-nacl"
  }, var.tags)
}

# Private NACL Ingress Rules
resource "aws_network_acl_rule" "private_ingress_http" {
  count          = local.az_count
  network_acl_id = aws_network_acl.private.id
  rule_number    = 100 + count.index
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = aws_subnet.public[count.index].cidr_block
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "private_ingress_https" {
  count          = local.az_count
  network_acl_id = aws_network_acl.private.id
  rule_number    = 200 + count.index
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = aws_subnet.public[count.index].cidr_block
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "private_ingress_ephemeral" {
  network_acl_id = aws_network_acl.private.id
  rule_number    = 300
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

# Private NACL Egress Rules
resource "aws_network_acl_rule" "private_egress_https" {
  network_acl_id = aws_network_acl.private.id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

# Ephemeral return traffic to private subnets
resource "aws_network_acl_rule" "private_egress_ephemeral_private" {
  count          = local.az_count
  network_acl_id = aws_network_acl.private.id
  rule_number    = 200 + count.index
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = aws_subnet.private[count.index].cidr_block
  from_port      = 1024
  to_port        = 65535
}

# Ephemeral traffic to public subnets
resource "aws_network_acl_rule" "private_egress_ephemeral_public" {
  count          = local.az_count
  network_acl_id = aws_network_acl.private.id
  rule_number    = 300 + count.index
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = aws_subnet.public[count.index].cidr_block
  from_port      = 1024
  to_port        = 65535
}

# Private NACL Associations
resource "aws_network_acl_association" "private" {
  count          = local.az_count
  network_acl_id = aws_network_acl.private.id
  subnet_id      = aws_subnet.private[count.index].id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_iam_policy" "imagebuilder_full_access" {
  name = "AWSImageBuilderFullAccess"
}

resource "aws_iam_role" "imagebuilder" {
  name = "imagebuilder_role"
  path = "/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "imagebuilder" {
  role       = aws_iam_role.imagebuilder.name
  policy_arn = data.aws_iam_policy.imagebuilder_full_access.arn
}

resource "aws_iam_instance_profile" "imagebuilder" {
  name = "imagebuilder_instance_profile"
  role = aws_iam_role.imagebuilder.name
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "role_name" {
  type    = string
  default = "tamr-instance-role"
}

variable "instance_profile_name" {
  type    = string
  default = "tamr-instance-profile"
}

variable "tags" {
  type    = map(string)
  default = {}
}

variable "permissions_boundary_arn" {
  type    = string
  default = ""
}

data "aws_iam_policy_document" "tamr_trust_policy" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "tamr_instance_role" {
  name               = var.role_name
  assume_role_policy = data.aws_iam_policy_document.tamr_trust_policy.json
  tags               = var.tags
  permissions_boundary = var.permissions_boundary_arn != "" ? var.permissions_boundary_arn : null
}

resource "aws_iam_instance_profile" "tamr_instance_profile" {
  name = var.instance_profile_name
  role = aws_iam_role.tamr_instance_role.name
  tags = var.tags
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "rds_custom_sql_server_role" {
  name = "AWSRDSCustomSQLServerInstanceRole"
  path = "/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
