  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "rds_custom_policy_attachment" {
  role       = aws_iam_role.rds_custom_sql_server_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSCustomInstanceProfileRolePolicy"
}

resource "aws_iam_instance_profile" "rds_custom_sql_server_profile" {
  name = "AWSRDSCustomSQLServerInstanceProfile"
  role = aws_iam_role.rds_custom_sql_server_role.name

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "env_prefix" {
  type        = string
  default     = "dev"
  description = "Environment-specific resource name prefix"
}

variable "target_account_id" {
  type        = string
  default     = "123456789012"
  description = "AWS account ID of the target account hosting the S3 read role"
}

variable "target_role_name" {
  type        = string
  default     = "CrossAccountS3ReadRole"
  description = "Name of the IAM role to assume in the target account"
}

data "aws_iam_policy_document" "packer_assume_role_trust" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "packer_builder_role" {
  name               = "${var.env_prefix}-packer-builder-role"
  assume_role_policy = data.aws_iam_policy_document.packer_assume_role_trust.json
}

data "aws_iam_policy_document" "packer_sts_assume_role_permissions" {
  statement {
    effect = "Allow"
    actions = [
      "sts:AssumeRole"
    ]
    resources = [
      "arn:aws:iam::${var.target_account_id}:role/${var.target_role_name}"
    ]
  }
}

resource "aws_iam_policy" "packer_sts_assume_role_policy" {
  name   = "${var.env_prefix}-packer-sts-assume-role-policy"
  policy = data.aws_iam_policy_document.packer_sts_assume_role_permissions.json
}

resource "aws_iam_role_policy_attachment" "packer_sts_assume_role_attachment" {
  role       = aws_iam_role.packer_builder_role.name
  policy_arn = aws_iam_policy.packer_sts_assume_role_policy.arn
}

resource "aws_iam_instance_profile" "packer_builder_instance_profile" {
  name = "${var.env_prefix}-packer-builder-instance-profile"
  role = aws_iam_role.packer_builder_role.name
}

