locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# IAM role for Service Catalog
resource "aws_iam_role" "test_role" {
  name               = "test_role"
  assume_role_policy = data.aws_iam_policy_document.test_role_assume.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "test_role_assume" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["servicecatalog.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

# Launch constraint policy
resource "aws_iam_policy" "launch_constraint" {
  name        = "test_role_launch_constraint_policy"
  description = "Minimum permissions for Service Catalog product provisioning"
  policy      = data.aws_iam_policy_document.launch_constraint.json
  tags        = local.common_tags
}

data "aws_iam_policy_document" "launch_constraint" {
  statement {
    effect = "Allow"
    actions = [
      "servicecatalog:ProvisionProduct",
      "servicecatalog:ListLaunchPaths",
      "servicecatalog:DescribeProduct"
    ]
    resources = ["arn:aws:servicecatalog:*:*:product/*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "cloudformation:CreateStack",
      "cloudformation:DescribeStacks",
      "cloudformation:DeleteStack",
      "cloudformation:UpdateStack"
    ]
    resources = ["arn:aws:cloudformation:*:*:stack/SC-*"]
  }
}

# Attach policy to role
resource "aws_iam_role_policy_attachment" "launch_constraint_attach" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.launch_constraint.arn
}

# IAM group
resource "aws_iam_group" "test_group" {
  name = "test_group"
  path = "/"
}

# IAM user
resource "aws_iam_user" "test_user" {
  name          = "test_user"
  path          = "/"
  force_destroy = true
  tags          = local.common_tags
}

# Console login profile (password auto-generated by AWS)
resource "aws_iam_user_login_profile" "test_user" {
  user            = aws_iam_user.test_user.name
  password_length = 20
  password_reset_required = false
}

# Secrets Manager secret for the auto-generated password
resource "aws_secretsmanager_secret" "console_password" {
  name        = "test_user_console_password"
  description = "Console password for test_user"
  tags        = local.common_tags
}

resource "aws_secretsmanager_secret_version" "console_password" {
  secret_id     = aws_secretsmanager_secret.console_password.id
  secret_string = jsonencode({
    password = aws_iam_user_login_profile.test_user.password
  })
}

# Add user to group
resource "aws_iam_user_group_membership" "test_user_group" {
  user = aws_iam_user.test_user.name
  groups = [
    aws_iam_group.test_group.name
  ]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.0.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

variable "ssm_endpoints_enabled" {
  type    = bool
  default = false
}

locals {
  az_count = min(3, length(data.aws_availability_zones.available.names))
  common_tags = {
    Datadog               = "true"
    DatadogAgentlessScanner = "true"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "DatatogAgentlessScanner"
  })
}

resource "aws_subnet" "public" {
  count             = local.az_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "public-${count.index}"
  })
}

resource "aws_subnet" "private" {
  count             = local.az_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 3)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "private-${count.index}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "DatatogAgentlessScanner-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "public"
  })
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "nat"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "DatatogAgentlessScanner-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "private"
  })
}

resource "aws_route_table_association" "private" {
  count          = local.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"

  tags = merge(local.common_tags, {
    Name = "s3-gateway-endpoint"
  })
}

resource "aws_vpc_endpoint_route_table_association" "public_s3" {
  vpc_endpoint_id = aws_vpc_endpoint.s3.id
  route_table_id  = aws_route_table.public.id
}

resource "aws_vpc_endpoint_route_table_association" "private_s3" {
  vpc_endpoint_id = aws_vpc_endpoint.s3.id
  route_table_id  = aws_route_table.private.id
}

resource "aws_security_group" "vpc_endpoints" {
  name        = "vpc-endpoints-sg"
  description = "Security group for VPC interface endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "vpc-endpoints-sg"
  })
}

resource "aws_vpc_endpoint" "interface" {
  count = 2

  vpc_id            = aws_vpc.main.id
  service_name      = element(
    [
      "com.amazonaws.${data.aws_region.current.name}.lambda",
      "com.amazonaws.${data.aws_region.current.name}.ebs"
    ],
    count.index
  )
  vpc_endpoint_type = "Interface"
  subnet_ids        = aws_subnet.private[*].id
  security_group_ids = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = element(
      [
        "lambda-interface-endpoint",
        "ebs-interface-endpoint"
      ],
      count.index
    )
  })
}

resource "aws_vpc_endpoint" "ssm" {
  count = var.ssm_endpoints_enabled ? 3 : 0

  vpc_id            = aws_vpc.main.id
  service_name      = element(
    [
      "com.amazonaws.${data.aws_region.current.name}.ec2messages",
      "com.amazonaws.${data.aws_region.current.name}.ssmmessages",
      "com.amazonaws.${data.aws_region.current.name}.ssm"
    ],
    count.index
  )
  vpc_endpoint_type = "Interface"
  subnet_ids        = aws_subnet.private[*].id
  security_group_ids = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = element(
      [
        "ec2messages-endpoint",
        "ssmmessages-endpoint",
        "ssm-endpoint"
      ],
      count.index
    )
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 4.0.0"
    }
  }
}

variable "role_name" {
  description = "Name of the IAM role for CloudForecast"
  type        = string
  default     = "CloudForecast-ZeroWaste"
}

variable "external_id" {
  description = "External ID for cross-account role assumption"
  type        = string
  default     = "benchmark-external-id"
}

resource "aws_iam_role" "this" {
  name = var.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::656227328603:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = var.external_id
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudwatch_get_metric_statistics" {
  name   = "cloudwatch-get-metric-statistics"
