terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  type    = string
  default = "dev"
}

variable "enable_db_dr_user" {
  type    = bool
  default = false
}

variable "enable_data_exports_user" {
  type    = bool
  default = false
}

variable "enable_packer_user" {
  type    = bool
  default = false
}

variable "data_export_bucket_arn" {
  type    = string
  default = ""
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# Mandatory cost report user
resource "aws_iam_user" "cost_report" {
  name = "mattermost-cost-report-${var.environment}"
}

data "aws_iam_policy_document" "cost_report" {
  statement {
    actions   = ["ce:*"]
    resources = ["*"]
    effect    = "Allow"
  }
}

resource "aws_iam_user_policy" "cost_report" {
  name   = "cost-report-policy"
  user   = aws_iam_user.cost_report.name
  policy = data.aws_iam_policy_document.cost_report.json
}

# Database DR user (conditional)
resource "aws_iam_user" "db_dr" {
  count = var.enable_db_dr_user ? 1 : 0
  name  = "mattermost-db-dr-${var.environment}"
}

data "aws_iam_policy_document" "db_dr" {
  count = var.enable_db_dr_user ? 1 : 0
  statement {
    actions   = ["rds:*"]
    resources = ["*"]
    effect    = "Allow"
  }
  statement {
    actions   = ["kms:*"]
    resources = ["*"]
    effect    = "Allow"
  }
  statement {
    actions   = ["secretsmanager:GetSecretValue"]
    resources = ["arn:aws:secretsmanager:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:secret:rds-cluster-multitenant-*"]
    effect    = "Allow"
  }
}

resource "aws_iam_user_policy" "db_dr" {
  count  = var.enable_db_dr_user ? 1 : 0
  name   = "db-dr-policy"
  user   = aws_iam_user.db_dr[0].name
  policy = data.aws_iam_policy_document.db_dr[0].json
}

# Data exports user (conditional)
resource "aws_iam_user" "data_exports" {
  count = var.enable_data_exports_user ? 1 : 0
  name  = "mattermost-data-exports-${var.environment}"
}

data "aws_iam_policy_document" "data_exports" {
  count = var.enable_data_exports_user && var.data_export_bucket_arn != "" ? 1 : 0
  statement {
    actions   = ["s3:ListBucket"]
    resources = [var.data_export_bucket_arn]
    effect    = "Allow"
  }
  statement {
    actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
    resources = ["${var.data_export_bucket_arn}/*"]
    effect    = "Allow"
  }
}

resource "aws_iam_user_policy" "data_exports" {
  count  = var.enable_data_exports_user && var.data_export_bucket_arn != "" ? 1 : 0
  name   = "data-exports-policy"
  user   = aws_iam_user.data_exports[0].name
  policy = data.aws_iam_policy_document.data_exports[0].json
}

# Packer user (conditional)
resource "aws_iam_user" "packer" {
  count = var.enable_packer_user ? 1 : 0
  name  = "mattermost-packer-${var.environment}"
}

# Packer monitoring state S3 bucket (conditional)
resource "aws_s3_bucket" "packer_monitoring_state" {
  count = var.enable_packer_user ? 1 : 0
  bucket = "mattermost-packer-monitoring-state-${data.aws_caller_identity.current.account_id}-${var.environment}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "packer_monitoring_state" {
  count  = var.enable_packer_user ? 1 : 0
  bucket = aws_s3_bucket.packer_monitoring_state[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "packer_monitoring_state" {
  count  = var.enable_packer_user ? 1 : 0
  bucket = aws_s3_bucket.packer_monitoring_state[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "packer_monitoring_state" {
  count  = var.enable_packer_user ? 1 : 0
  bucket = aws_s3_bucket.packer_monitoring_state[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

# Packer server IAM role (conditional)
resource "aws_iam_role" "packer_server_role" {
  count = var.enable_packer_user ? 1 : 0
  name  = "mattermost-packer-server-role-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Packer user inline policy (conditional)
data "aws_iam_policy_document" "packer" {
  count = var.enable_packer_user ? 1 : 0

  # EC2 permissions for Packer
  statement {
    actions = [
      "ec2:AttachVolume",
      "ec2:AuthorizeSecurityGroupEgress",
      "ec2:AuthorizeSecurityGroupIngress",
      "ec2:CopyImage",
      "ec2:CreateImage",
      "ec2:CreateKeyPair",
      "ec2:CreateSecurityGroup",
      "ec2:CreateSnapshot",
      "ec2:CreateTags",
      "ec2:CreateVolume",
      "ec2:DeleteKeyPair",
      "ec2:DeleteSecurityGroup",
      "ec2:DeleteSnapshot",
      "ec2:DeleteVolume",
      "ec2:DeregisterImage",
      "ec2:Describe*",
      "ec2:DetachVolume",
      "ec2:GetConsoleOutput",
      "ec2:GetPasswordData",
      "ec2:ModifyImageAttribute",
      "ec2:ModifyInstanceAttribute",
      "ec2:ModifySnapshotAttribute",
      "ec2:RegisterImage",
      "ec2:RunInstances",
      "ec2:StopInstances",
      "ec2:TerminateInstances"
    ]
    resources = ["*"]
    effect    = "Allow"
  }

  # Auto Scaling permissions
  statement {
    actions   = ["autoscaling:Describe*"]
    resources = ["*"]
    effect    = "Allow"
  }

  # CloudWatch Events permissions
  statement {
    actions = [
      "events:PutRule",
      "events:PutTargets",
      "events:DeleteRule",
      "events:RemoveTargets",
      "events:DescribeRule",
      "events:ListRules",
      "events:ListTargetsByRule"
    ]
    resources = ["*"]
    effect    = "Allow"
  }

  # SSM Parameter permissions
  statement {
    actions = [
      "ssm:GetParameter",
      "ssm:GetParameters",
      "ssm:DescribeParameters"
    ]
    resources = ["*"]
    effect    = "Allow"
  }

  # IAM profile/role inspection
  statement {
    actions = [
      "iam:GetInstanceProfile",
      "iam:ListInstanceProfiles",
      "iam:GetRole",
      "iam:ListRoles"
    ]
    resources = ["*"]
    effect    = "Allow"
  }

  # S3 monitoring state bucket access
  statement {
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.packer_monitoring_state[0].arn,
      "${aws_s3_bucket.packer_monitoring_state[0].arn}/*"
    ]
    effect = "Allow"
  }

  # Lambda function configuration for bind-server-network-attachment
  statement {
    actions = [
      "lambda:GetFunctionConfiguration",
      "lambda:UpdateFunctionConfiguration"
    ]
    resources = [
      "arn:aws:lambda:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:function:bind-server-network-attachment"
    ]
    effect = "Allow"
  }

  # PassRole for packer server role
  statement {
    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.packer_server_role[0].arn]
    effect    = "Allow"
  }
}

resource "aws_iam_user_policy" "packer" {
  count  = var.enable_packer_user ? 1 : 0
  name   = "packer-policy"
  user   = aws_iam_user.packer[0].name
  policy = data.aws_iam_policy_document.packer[0].json
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.75.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Variables
variable "ecr_repository_names" {
  description = "List of ECR repository names to create"
  type        = list(string)
  default     = []
}

variable "external_account_ids" {
  description = "List of external AWS account IDs to grant cross-account ECR pull access"
  type        = list(string)
  default     = []
}

# Data sources
data "aws_caller_identity" "current" {}

# Random suffixes for globally unique names
resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "random_id" "role_suffix" {
  byte_length = 4
}

resource "random_id" "user_suffix" {
  byte_length = 4
}

resource "random_id" "secret_suffix" {
  byte_length = 4
}

resource "random_id" "alias_suffix" {
  byte_length = 4
}

resource "random_id" "service_policy_suffix" {
  byte_length = 4
}

resource "random_id" "user_policy_suffix" {
  byte_length = 4
}

# KMS Key for S3 SSE-KMS
data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type = "AWS"
      identifiers = [
        "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
      ]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "Allow HealthOmicsRole and User to use the key"
    effect = "Allow"
    principals {
      type = "AWS"
      identifiers = [
        aws_iam_role.healthomics_role.arn,
        aws_iam_user.workbench_user.arn
      ]
    }
    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt",
      "kms:Encrypt"
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "omics_key" {
  description             = "KMS key for HealthOmics output bucket encryption"
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "omics_key_alias" {
  name          = "alias/omics-output-key-${random_id.alias_suffix.hex}"
  target_key_id = aws_kms_key.omics_key.key_id
}

# S3 Output Bucket with unique suffix
resource "aws_s3_bucket" "output_bucket" {
  bucket = "tf-benchmark-omics-output-bucket-${random_id.bucket_suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "output_bucket_block" {
  bucket                  = aws_s3_bucket.output_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "output_bucket_encryption" {
  bucket = aws_s3_bucket.output_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.omics_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "output_bucket_versioning" {
  bucket = aws_s3_bucket.output_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

# IAM Role for HealthOmics Service
data "aws_iam_policy_document" "healthomics_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["omics.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "healthomics_role" {
  name               = "HealthOmicsRole-${random_id.role_suffix.hex}"
  assume_role_policy = data.aws_iam_policy_document.healthomics_assume_role.json
}

# IAM Policy for HealthOmics Service Role
data "aws_iam_policy_document" "healthomics_service_policy" {
  statement {
    effect = "Allow"
    actions = [
      "omics:*"
    ]
    resources = ["*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.output_bucket.arn,
      "${aws_s3_bucket.output_bucket.arn}/*"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt",
      "kms:Encrypt"
    ]
    resources = [aws_kms_key.omics_key.arn]
  }
}

resource "aws_iam_policy" "healthomics_service_policy" {
  name        = "HealthOmicsServicePolicy-${random_id.service_policy_suffix.hex}"
  description = "Policy for HealthOmics service role"
  policy      = data.aws_iam_policy_document.healthomics_service_policy.json
}

resource "aws_iam_role_policy_attachment" "healthomics_service_attach" {
  role       = aws_iam_role.healthomics_role.name
  policy_arn = aws_iam_policy.healthomics_service_policy.arn
}

# IAM User for Programmatic Access
resource "aws_iam_user" "workbench_user" {
  name = "workbench-health-omics-${random_id.user_suffix.hex}"
}

resource "aws_iam_access_key" "workbench_user_key" {
  user = aws_iam_user.workbench_user.name
}

# Store access key in Secrets Manager
resource "aws_secretsmanager_secret" "workbench_user_secret" {
  name = "workbench-health-omics-access-key-${random_id.secret_suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "workbench_user_secret_version" {
  secret_id = aws_secretsmanager_secret.workbench_user_secret.id
  secret_string = jsonencode({
    access_key_id     = aws_iam_access_key.workbench_user_key.id
    secret_access_key = aws_iam_access_key.workbench_user_key.secret
  })
}

# IAM Policy for User
data "aws_iam_policy_document" "healthomics_user_policy" {
  statement {
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = [aws_iam_role.healthomics_role.arn]
  }

  statement {
    effect = "Allow"
    actions = [
      "omics:*"
    ]
    resources = ["*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.output_bucket.arn,
      "${aws_s3_bucket.output_bucket.arn}/*"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt",
      "kms:Encrypt"
    ]
    resources = [aws_kms_key.omics_key.arn]
  }
}

resource "aws_iam_policy" "healthomics_user_policy" {
  name        = "HealthOmicsUserPolicy-${random_id.user_policy_suffix.hex}"
  description = "Policy for HealthOmics user"
  policy      = data.aws_iam_policy_document.healthomics_user_policy.json
}

resource "aws_iam_user_policy_attachment" "healthomics_user_attach" {
  user       = aws_iam_user.workbench_user.name
  policy_arn = aws_iam_policy.healthomics_user_policy.arn
}

# ECR Repositories
resource "aws_ecr_repository" "repos" {
  for_each = toset(var.ecr_repository_names)

  name                 = each.value
  image_tag_mutability = "MUTABLE"
  force_delete         = false

  image_scanning_configuration {
    scan_on_push = true
  }
}

# ECR Repository Policy (allow HealthOmicsRole and external accounts to pull)
data "aws_iam_policy_document" "ecr_repo_policy" {
  for_each = toset(var.ecr_repository_names)

  statement {
    sid    = "HealthOmicsPull"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = concat(
        [aws_iam_role.healthomics_role.arn],
        [for account_id in var.external_account_ids : "arn:aws:iam::${account_id}:root"]
      )
    }
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:GetDownloadUrlForLayer"
    ]
  }
}

resource "aws_ecr_repository_policy" "repo_policy" {
  for_each = toset(var.ecr_repository_names)

  repository = aws_ecr_repository.repos[each.key].name
  policy     = data.aws_iam_policy_document.ecr_repo_policy[each.key].json
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.90.0"
    }
  }
  required_version = ">= 1.0"
}

variable "cluster_name" {
  description = "Name of the cluster"
  type        = string
  default     = "benchmark"
}

variable "vpc_cidr_network_octets" {
  description = "First two octets of VPC CIDR"
  type        = string
  default     = "10.0"
}

variable "default_tags" {
  description = "Default tags applied to all resources"
  type        = map(string)
  default     = {}
}

locals {
  az_names = slice(data.aws_availability_zones.available.names, 0, 3)
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "${var.vpc_cidr_network_octets}.0.0/16"
  enable_dns_hostnames = false

  tags = merge(var.default_tags, {
    Name = "dit-paas-${var.cluster_name}-vpc"
  })
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = "${var.vpc_cidr_network_octets}.${12 + count.index * 4}.0/22"
  availability_zone       = local.az_names[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.default_tags, {
    Name = "dit-paas-${var.cluster_name}-public-${count.index}"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = "${var.vpc_cidr_network_octets}.${0 + count.index * 4}.0/22"
  availability_zone       = local.az_names[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.default_tags, {
    Name = "dit-paas-${var.cluster_name}-private-${count.index}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-ig"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.default_tags, {
    Name = "dit-paas-${var.cluster_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count = 3

  domain = "vpc"

  tags = merge(var.default_tags, {
    Name = "dit-paas-${var.cluster_name}-nat-eip-${count.index}"
  })
}

resource "aws_nat_gateway" "main" {
  count = 3

  allocation_id     = aws_eip.nat[count.index].id
  subnet_id         = aws_subnet.public[count.index].id
  connectivity_type = "public"

  tags = merge(var.default_tags, {
    Name = "dit-paas-${var.cluster_name}-nat-${count.index}"
  })
}

resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = merge(var.default_tags, {
    Name = "dit-paas-${var.cluster_name}-private-rt-${count.index}"
  })
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_ecs_cluster" "main" {
  name = "dit-paas-${var.cluster_name}-cluster"

  tags = merge(var.default_tags, {
    Name = "dit-paas-${var.cluster_name}-cluster"
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.0.0"
    }
  }
}

variable "vpc_name" {
  type    = string
  default = "benchmark-vpc"
}

variable "vpc_cidr_block" {
  type    = string
  default = "172.16.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 3)
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_hostnames = true
  enable_dns_support   = true
  assign_generated_ipv6_cidr_block = false

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-default-sg"
  }
}

resource "aws_subnet" "public" {
  count = length(local.azs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr_block, 4, count.index)
  availability_zone       = local.azs[count.index]

  tags = {
    Name = "${var.vpc_name}-public-${local.azs[count.index]}"
  }
}

resource "aws_subnet" "private" {
  count = length(local.azs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr_block, 4, count.index + length(local.azs))
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.vpc_name}-private-${local.azs[count.index]}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

resource "aws_eip" "nat" {
  count = length(local.azs)
  domain = "vpc"

  tags = {
    Name = "${var.vpc_name}-nat-eip-${count.index}"
  }
}

resource "aws_nat_gateway" "nat" {
  count = length(local.azs)

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${var.vpc_name}-nat-${count.index}"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "${var.vpc_name}-public-rt"
  }
}

resource "aws_route_table" "private" {
  count = length(local.azs)

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[count.index].id
  }

  tags = {
    Name = "${var.vpc_name}-private-rt-${local.azs[count.index]}"
  }
}

resource "aws_route_table_association" "public" {
  count = length(local.azs)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count = length(local.azs)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_default_route_table" "main" {
  default_route_table_id = aws_vpc.main.default_route_table_id

  tags = {
    Name = "${var.vpc_name}-default-rt"
  }
}

resource "aws_security_group" "vpc_endpoint_sg" {
  name        = "vpc_endpoint_sg"
  description = "Security group for VPC interface endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    self        = true
  }

  egress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    self        = true
  }

  tags = {
    Name = "vpc_endpoint_sg"
  }
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"

  route_table_ids = concat(
    [aws_route_table.public.id],
    aws_route_table.private[*].id,
    [aws_default_route_table.main.id]
  )

  tags = {
    Name = "${var.vpc_name}-s3-endpoint"
  }
}

locals {
  interface_services = [
    "ecr.dkr",
    "ecr.api",
    "logs",
    "ssm",
    "kms"
  ]
}

resource "aws_vpc_endpoint" "interface" {
  for_each = toset(local.interface_services)

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  private_dns_enabled = true
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]

  tags = {
    Name = "${var.vpc_name}-${each.value}-endpoint"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

variable "vpc_name" {
  type    = string
  default = "benchmark-vpc"
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "endpoint_services" {
  type    = set(string)
  default = ["logs"]
}

variable "endpoint_source_security_group_ids" {
  type    = list(string)
  default = []
}

variable "custom_endpoint_services" {
  type = map(object({
    service_name = string
    port         = number
    source_sg_id = string
  }))
  default = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

locals {
  region = data.aws_region.current.name

  # Only the variable-provided IDs (known at plan time)
  endpoint_sg_ids = toset(var.endpoint_source_security_group_ids)
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_hostnames = true
  tags = {
    Name = var.vpc_name
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.vpc_name}-private-${count.index + 1}"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-private"
  }
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# VPC Flow Logs
resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = "/aws/vpc-flow-logs/${var.vpc_name}"
  retention_in_days = 180
}

resource "aws_iam_role" "flow_logs" {
  name = "vpc_flow_logs_${var.vpc_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "flow_logs" {
  name        = "vpc_flow_logs_policy_${var.vpc_name}"
  description = "Policy for VPC Flow Logs to CloudWatch"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.flow_logs.arn,
          "${aws_cloudwatch_log_group.flow_logs.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "flow_logs" {
  role       = aws_iam_role.flow_logs.name
  policy_arn = aws_iam_policy.flow_logs.arn
}

resource "aws_flow_log" "main" {
  iam_role_arn    = aws_iam_role.flow_logs.arn
  log_destination = aws_cloudwatch_log_group.flow_logs.arn
  traffic_type    = "ALL"
  vpc_id          = aws_vpc.main.id
}

# Default security group
resource "aws_default_security_group" "this" {
  vpc_id = aws_vpc.main.id

  ingress = []
  egress = [
    {
      from_port        = 0
      to_port          = 0
      protocol         = "-1"
      cidr_blocks      = ["0.0.0.0/0"]
      description      = ""
      ipv6_cidr_blocks = []
      prefix_list_ids  = []
      security_groups  = []
      self             = false
    }
  ]

  tags = {
    Name = "${var.vpc_name}-default"
  }
}

# VPC Endpoints Security Group
resource "aws_security_group" "vpc_endpoints" {
  name        = "vpc-endpoints-${var.vpc_name}"
  description = "Security group for VPC endpoints"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "vpc-endpoints-${var.vpc_name}"
  }
}

# Ingress and egress rules for VPC endpoints security group (from variable IDs)
resource "aws_security_group_rule" "vpc_endpoints_ingress" {
  for_each = local.endpoint_sg_ids

  type      = "ingress"
  from_port = 443
  to_port   = 443
  protocol  = "tcp"

  security_group_id        = aws_security_group.vpc_endpoints.id
  source_security_group_id = each.value
}

resource "aws_security_group_rule" "vpc_endpoints_egress" {
  for_each = local.endpoint_sg_ids

  type      = "egress"
  from_port = 443
  to_port   = 443
  protocol  = "tcp"

  security_group_id        = aws_security_group.vpc_endpoints.id
  source_security_group_id = each.value
}

# Fallback rules using the default security group when no variable IDs provided
resource "aws_security_group_rule" "vpc_endpoints_ingress_default" {
  count = length(var.endpoint_source_security_group_ids) == 0 ? 1 : 0

  type      = "ingress"
  from_port = 443
  to_port   = 443
  protocol  = "tcp"

  security_group_id        = aws_security_group.vpc_endpoints.id
  source_security_group_id = aws_default_security_group.this.id
}

resource "aws_security_group_rule" "vpc_endpoints_egress_default" {
  count = length(var.endpoint_source_security_group_ids) == 0 ? 1 : 0

  type      = "egress"
  from_port = 443
  to_port   = 443
  protocol  = "tcp"

  security_group_id        = aws_security_group.vpc_endpoints.id
  source_security_group_id = aws_default_security_group.this.id
}

# Custom Endpoints Security Group
resource "aws_security_group" "custom_endpoints" {
  name        = "custom-endpoints-${var.vpc_name}"
  description = "Security group for custom endpoint services"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "custom-endpoints-${var.vpc_name}"
  }
}

# Ingress and egress rules for custom endpoints security group
resource "aws_security_group_rule" "custom_endpoints_ingress" {
  for_each = var.custom_endpoint_services

  type      = "ingress"
  from_port = each.value.port
  to_port   = each.value.port
  protocol  = "tcp"

  security_group_id        = aws_security_group.custom_endpoints.id
  source_security_group_id = each.value.source_sg_id
}

resource "aws_security_group_rule" "custom_endpoints_egress" {
  for_each = var.custom_endpoint_services

  type      = "egress"
  from_port = each.value.port
  to_port   = each.value.port
  protocol  = "tcp"

  security_group_id        = aws_security_group.custom_endpoints.id
  source_security_group_id = each.value.source_sg_id
}

# Gateway endpoints for S3 and DynamoDB
resource "aws_vpc_endpoint" "s3" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.${local.region}.s3"
  route_table_ids = [aws_route_table.private.id]
}

resource "aws_vpc_endpoint" "dynamodb" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.${local.region}.dynamodb"
  route_table_ids = [aws_route_table.private.id]
}

# Interface endpoints for standard AWS services
resource "aws_vpc_endpoint" "standard" {
  for_each = var.endpoint_services

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${local.region}.${each.key}"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
}

# Interface endpoints for custom endpoint services (no private DNS)
resource "aws_vpc_endpoint" "custom" {
  for_each = var.custom_endpoint_services

  vpc_id              = aws_vpc.main.id
  service_name        = each.value.service_name
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = false
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.custom_endpoints.id]
}

# Conditional SSM role and instance profile
resource "aws_iam_role" "ssm" {
  count = contains(var.endpoint_services, "ssm") ? 1 : 0

  name = "ssm_${var.vpc_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ssm" {
  count = contains(var.endpoint_services, "ssm") ? 1 : 0

  role       = aws_iam_role.ssm[0].name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ssm" {
  count = contains(var.endpoint_services, "ssm") ? 1 : 0

  name = "ssm_${var.vpc_name}"
  role = aws_iam_role.ssm[0].name
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

variable "project_name" {
  description = "Project name used for KMS key aliases"
  type        = string
  default     = "my-project"
}

variable "rotation_period_days" {
  description = "Desired key rotation period in days (AWS KMS fixed at 365 days, used for documentation)"
  type        = number
  default     = 90
}

variable "external_ebs_kms_key_arn" {
  description = "Optional external KMS key ARN for account-level EBS encryption; if empty, uses compute key"
  type        = string
  default     = ""
}

variable "hop_limit" {
  description = "EC2 instance metadata HTTP PUT response hop limit (for IMDSv2)"
  type        = number
  default     = 1
}

variable "enable_imdsv2_defaults" {
  description = "Enable account-level EC2 instance metadata defaults (IMDSv2 required)"
  type        = bool
  default     = true
}

variable "disable_serial_console" {
  description = "Disable EC2 Serial Console access at the account level"
  type        = bool
  default     = true
}

variable "enable_emr_block_public_access" {
  description = "Enable EMR block public access configuration"
  type        = bool
  default     = true
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition
}

# ------------------------------------------------------------------------------
# KMS Keys and Policies
# ------------------------------------------------------------------------------

# Compute KMS Key Policy
data "aws_iam_policy_document" "compute_key_policy" {
  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowEC2Service"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AllowAutoScalingService"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["autoscaling.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
      "kms:ListGrants",
      "kms:RetireGrant"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_kms_key" "compute" {
  description              = "KMS key for compute layer (EBS and EC2 encryption) — intended rotation period: ${var.rotation_period_days} days"
  deletion_window_in_days  = 30
  enable_key_rotation      = true
  policy                   = data.aws_iam_policy_document.compute_key_policy.json
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "compute" {
  name          = "alias/${var.project_name}-compute"
  target_key_id = aws_kms_key.compute.key_id
}

import {
  to = aws_kms_alias.compute
  id = "alias/${var.project_name}-compute"
}

# Observability KMS Key Policy
data "aws_iam_policy_document" "observability_key_policy" {
  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogs"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logs.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:*"]
    }
  }

  statement {
    sid    = "AllowCloudTrail"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AllowCloudWatchAlarms"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AllowSNS"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AllowSQS"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["sqs.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AllowEventBridge"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_kms_key" "observability" {
  description              = "KMS key for observability layer (CloudWatch, CloudTrail, SNS, SQS, EventBridge) — intended rotation period: ${var.rotation_period_days} days"
  deletion_window_in_days  = 30
  enable_key_rotation      = true
  policy                   = data.aws_iam_policy_document.observability_key_policy.json
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "observability" {
  name          = "alias/${var.project_name}-observability"
  target_key_id = aws_kms_key.observability.key_id
}

import {
  to = aws_kms_alias.observability
  id = "alias/${var.project_name}-observability"
}

# Storage KMS Key Policy
data "aws_iam_policy_document" "storage_key_policy" {
  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3Service"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AllowAWSConfig"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AllowCloudTrailForStorage"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_kms_key" "storage" {
  description              = "KMS key for storage layer (S3, Config, CloudTrail) — intended rotation period: ${var.rotation_period_days} days"
  deletion_window_in_days  = 30
  enable_key_rotation      = true
  policy                   = data.aws_iam_policy_document.storage_key_policy.json
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "storage" {
  name          = "alias/${var.project_name}-storage"
  target_key_id = aws_kms_key.storage.key_id
}

import {
  to = aws_kms_alias.storage
  id = "alias/${var.project_name}-storage"
}

# ------------------------------------------------------------------------------
# Account-Level EBS Encryption
# ------------------------------------------------------------------------------

resource "aws_ebs_encryption_by_default" "this" {
  enabled = true
}

resource "aws_ebs_default_kms_key" "this" {
  key_arn = var.external_ebs_kms_key_arn != "" ? var.external_ebs_kms_key_arn : aws_kms_key.compute.arn
}

# ------------------------------------------------------------------------------
# Public Access Restrictions
# ------------------------------------------------------------------------------

resource "aws_ec2_image_block_public_access" "this" {
  state = "block-new-sharing"
}

resource "aws_ebs_snapshot_block_public_access" "this" {
  state = "block-all-sharing"
}

# ------------------------------------------------------------------------------
# Conditional Account-Level EC2 Settings
# ------------------------------------------------------------------------------

resource "aws_ec2_instance_metadata_defaults" "this" {
  count = var.enable_imdsv2_defaults ? 1 : 0

  http_tokens                 = "required"
  http_put_response_hop_limit = var.hop_limit
}

resource "aws_ec2_serial_console_access" "this" {
  count   = var.disable_serial_console ? 1 : 0
  enabled = false
}

resource "aws_emr_block_public_access_configuration" "this" {
  count = var.enable_emr_block_public_access ? 1 : 0

  block_public_security_group_rules = true
}

# main.tf

# ------------------------------------------------------------------------------
# Terraform required providers and version
# ------------------------------------------------------------------------------

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      # Use a version lower than 5.100.0 to avoid a locked provider binary in the cache.
      # If the error persists, manually clear /tmp/iac-god-tf-plugin-cache-tianyi/ and re-run init.
      version = ">= 5.0, < 5.100.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "cluster_prefix" {
  description = "Prefix for all resource names, must be 5-8 characters."
  type        = string
  default     = "bench"

  validation {
    condition     = length(var.cluster_prefix) >= 5 && length(var.cluster_prefix) <= 8
    error_message = "cluster_prefix must be between 5 and 8 characters."
  }
}

variable "public_subnet_count" {
  description = "Number of public subnets to create."
  type        = number
  default     = 2
}

variable "private_subnet_count" {
  description = "Number of private subnets to create."
  type        = number
  default     = 2
}

variable "dynamic_ingress_rules" {
  description = "List of additional ingress rules to apply to the default security group."
  type = list(object({
    port        = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  default = []
}

variable "inventory_nodes" {
  description = "List of EC2 instance configurations."
  type = list(object({
    subnet_type      = string          # "public" or "private"
    subnet_index     = number          # index into the respective subnet list
    instance_type    = string          # e.g., "t3.micro"
    root_volume_size = number          # in GiB
    secondary_volumes = list(object({
      size        = number
      device_name = string
      mount_point = string
    }))
    associate_eip    = bool
  }))
  default = [
    {
      subnet_type      = "public"
      subnet_index     = 0
      instance_type    = "t3.micro"
      root_volume_size = 8
      secondary_volumes = []
      associate_eip    = false
    }
  ]
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  name_prefix = var.cluster_prefix

  # VPC and Internet Gateway (always created)
  vpc_id   = aws_vpc.main.id
  vpc_cidr = aws_vpc.main.cidr_block
  igw_id   = aws_internet_gateway.main.id

  # Total subnets per type
  public_subnet_count  = var.public_subnet_count
  private_subnet_count = var.private_subnet_count

  # Subnet CIDR calculation
  newbits = 8

  public_subnet_netnums  = range(local.public_subnet_count)
  private_subnet_netnums = range(local.public_subnet_count, local.public_subnet_count + local.private_subnet_count)

  # Availability zones
  azs = data.aws_availability_zones.available.names

  # Subnet ID lists
  public_subnet_ids  = aws_subnet.public[*].id
  private_subnet_ids = aws_subnet.private[*].id
}

# ------------------------------------------------------------------------------
# Data Sources
# ------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

# ------------------------------------------------------------------------------
# SSH Key Pair (generated via TLS)
# ------------------------------------------------------------------------------

resource "tls_private_key" "deployer" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "deployer" {
  key_name   = "${local.name_prefix}-keypair"
  public_key = tls_private_key.deployer.public_key_openssh
}

# ------------------------------------------------------------------------------
# VPC and Internet Gateway
# ------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "172.16.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

# ------------------------------------------------------------------------------
# Subnets
# ------------------------------------------------------------------------------

resource "aws_subnet" "public" {
  count = local.public_subnet_count

  vpc_id                  = local.vpc_id
  cidr_block              = cidrsubnet(local.vpc_cidr, local.newbits, local.public_subnet_netnums[count.index])
  availability_zone       = element(local.azs, count.index % length(local.azs))
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-public-${count.index}"
    Type = "public"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "private" {
  count = local.private_subnet_count

  vpc_id                  = local.vpc_id
  cidr_block              = cidrsubnet(local.vpc_cidr, local.newbits, local.private_subnet_netnums[count.index])
  availability_zone       = element(local.azs, (count.index + local.public_subnet_count) % length(local.azs))
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-private-${count.index}"
    Type = "private"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Public Route Table
# ------------------------------------------------------------------------------

resource "aws_route_table" "public" {
  vpc_id = local.vpc_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = local.igw_id
  }

  tags = {
    Name = "${local.name_prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = local.public_subnet_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ------------------------------------------------------------------------------
# Elastic IPs and NAT Gateways (one per public subnet)
# ------------------------------------------------------------------------------

resource "aws_eip" "nat" {
  count = local.public_subnet_count

  domain = "vpc"

  tags = {
    Name = "${local.name_prefix}-nat-eip-${count.index}"
  }
}

resource "aws_nat_gateway" "main" {
  count = local.public_subnet_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${local.name_prefix}-nat-${count.index}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Private Route Tables (one per private subnet)
# ------------------------------------------------------------------------------

resource "aws_route_table" "private" {
  count = local.private_subnet_count

  vpc_id = local.vpc_id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[0].id
  }

  tags = {
    Name = "${local.name_prefix}-private-rt-${count.index}"
  }
}

resource "aws_route_table_association" "private" {
  count = local.private_subnet_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ------------------------------------------------------------------------------
# Default Security Group
# ------------------------------------------------------------------------------

resource "aws_security_group" "default" {
  name        = "${local.name_prefix}-default"
  description = "Default security group for ${local.name_prefix} cluster"
  vpc_id      = local.vpc_id

  # Self-referencing ingress
  ingress {
    from_port = 0
    to_port   = 0
    protocol  = "-1"
    self      = true
  }

  # Dynamic ingress rules
  dynamic "ingress" {
    for_each = var.dynamic_ingress_rules
    content {
      from_port   = ingress.value.port
      to_port     = ingress.value.port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
    }
  }

  # Outbound only within VPC CIDR
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${local.name_prefix}-default"
  }
}

# ------------------------------------------------------------------------------
# EC2 Instances from Inventory
# ------------------------------------------------------------------------------

resource "aws_instance" "node" {
  count = length(var.inventory_nodes)

  ami           = data.aws_ami.amazon_linux_2.id
  instance_type = var.inventory_nodes[count.index].instance_type
  key_name      = aws_key_pair.deployer.key_name

  # Single-line conditional for subnet_id
  subnet_id = var.inventory_nodes[count.index].subnet_type == "public" ? local.public_subnet_ids[var.inventory_nodes[count.index].subnet_index] : local.private_subnet_ids[var.inventory_nodes[count.index].subnet_index]

  vpc_security_group_ids = [aws_security_group.default.id]

  ebs_optimized = true

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    volume_size           = var.inventory_nodes[count.index].root_volume_size
    delete_on_termination = true
    encrypted             = true
  }

  tags = {
    Name = "${local.name_prefix}-node-${count.index}"
  }
}

# ------------------------------------------------------------------------------
# Elastic IPs for instances (when associate_eip = true)
# ------------------------------------------------------------------------------

resource "aws_eip" "instance" {
  for_each = {
    for idx, node in var.inventory_nodes :
    idx => node if node.associate_eip
  }

  domain = "vpc"

  tags = {
    Name = "${local.name_prefix}-eip-instance-${each.key}"
  }
}

resource "aws_eip_association" "instance" {
  for_each = aws_eip.instance

  instance_id   = aws_instance.node[tonumber(each.key)].id
  allocation_id = each.value.id
}

# ------------------------------------------------------------------------------
# Secondary EBS Volumes and Attachments
# ------------------------------------------------------------------------------

resource "aws_ebs_volume" "secondary" {
  for_each = {
    for pair in flatten([
      for node_idx, node in var.inventory_nodes : [
        for vol_idx, vol in node.secondary_volumes : {
          key      = "${node_idx}-${vol_idx}"
          node_idx = node_idx
          vol      = vol
        }
      ]
    ]) : pair.key => pair
  }

  availability_zone = aws_instance.node[tonumber(each.value.node_idx)].availability_zone
  size              = each.value.vol.size
  encrypted         = true

  tags = {
    Name       = "${local.name_prefix}-vol-${each.key}"
    DeviceName = each.value.vol.device_name
    MountPoint = each.value.vol.mount_point
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_volume_attachment" "secondary" {
  for_each = aws_ebs_volume.secondary

  device_name = each.value.tags["DeviceName"]
  volume_id   = each.value.id
  instance_id = aws_instance.node[tonumber(split("-", each.key)[0])].id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.0.0"
    }
  }
}

provider "aws" {
  region = "us-west-2"
}

# --------------------------------------------------------------------------
# Variables
# --------------------------------------------------------------------------
variable "enable_private_subnets" {
  type        = bool
  default     = true
  description = "When true, creates 2 public and 2 private subnets; when false, creates 4 public subnets."
}

variable "enable_nat_gateways" {
  type        = bool
  default     = false
  description = "Deploy NAT Gateways in each public subnet with associated Elastic IPs."
}

variable "enable_nat_instances" {
  type        = bool
  default     = false
  description = "Deploy NAT EC2 instances in each public subnet using Amazon Linux NAT AMI."
}

variable "enable_egress_only_igw" {
  type        = bool
  default     = false
  description = "Create an Egress-Only Internet Gateway for IPv6 egress."
}

variable "vpc_cidr" {
  type        = string
  default     = "10.0.0.0/16"
  description = "CIDR block for the VPC."
}

variable "public_subnet_cidrs" {
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
  description = "CIDR blocks for public subnets."
}

variable "private_subnet_cidrs" {
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
  description = "CIDR blocks for private subnets (used only when enable_private_subnets = true)."
}

variable "nat_instance_instance_type" {
  type        = string
  default     = "t2.micro"
  description = "Instance type for NAT EC2 instances (must be HVM-compatible)."
}

# --------------------------------------------------------------------------
# Validation – mutually exclusive egress strategies
# --------------------------------------------------------------------------
resource "terraform_data" "egress_validation" {
  lifecycle {
    precondition {
      condition     = (var.enable_nat_gateways ? 1 : 0) + (var.enable_nat_instances ? 1 : 0) + (var.enable_egress_only_igw ? 1 : 0) <= 1
      error_message = "At most one of enable_nat_gateways, enable_nat_instances, enable_egress_only_igw can be true."
    }
  }
}

# --------------------------------------------------------------------------
# Data sources
# --------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ssm_parameter" "nat_ami" {
  name = "/aws/service/ami-amazon-linux-latest/amzn2-ami-hvm-x86_64-gp2"
}

# --------------------------------------------------------------------------
# Local values
# --------------------------------------------------------------------------
locals {
  has_private_subnets  = var.enable_private_subnets
  public_subnet_count  = local.has_private_subnets ? 2 : 4
  private_subnet_count = local.has_private_subnets ? 2 : 0
  az_names             = data.aws_availability_zones.available.names
}

# --------------------------------------------------------------------------
# VPC
# --------------------------------------------------------------------------
resource "aws_vpc" "benchmark_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "benchmark-vpc"
  }
}

# --------------------------------------------------------------------------
# Internet Gateway
# --------------------------------------------------------------------------
resource "aws_internet_gateway" "benchmark_igw" {
  vpc_id = aws_vpc.benchmark_vpc.id

  tags = {
    Name = "benchmark-igw"
  }
}

# --------------------------------------------------------------------------
# Default Security Group (self-referencing)
# --------------------------------------------------------------------------
resource "aws_default_security_group" "benchmark_default_sg" {
  vpc_id = aws_vpc.benchmark_vpc.id

  ingress {
    description = "Self-referencing ingress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  egress {
    description = "Self-referencing egress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  tags = {
    Name = "benchmark-default-sg"
  }
}

# --------------------------------------------------------------------------
# TLS Security Group (port 443)
# --------------------------------------------------------------------------
resource "aws_security_group" "benchmark_tls_sg" {
  name        = "benchmark-tls-sg"
  description = "Security group allowing inbound HTTPS traffic"
  vpc_id      = aws_vpc.benchmark_vpc.id

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound traffic to VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "benchmark-tls-sg"
  }
}

# --------------------------------------------------------------------------
# Public Subnets
# --------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = local.public_subnet_count

  vpc_id                  = aws_vpc.benchmark_vpc.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.az_names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "benchmark-public-${count.index + 1}"
  }
}

# --------------------------------------------------------------------------
# Private Subnets (only when enabled)
# --------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count = local.private_subnet_count

  vpc_id            = aws_vpc.benchmark_vpc.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = local.az_names[count.index]

  tags = {
    Name = "benchmark-private-${count.index + 1}"
  }
}

# --------------------------------------------------------------------------
# Public Route Table and Associations
# --------------------------------------------------------------------------
resource "aws_route_table" "benchmark_public_rt" {
  vpc_id = aws_vpc.benchmark_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.benchmark_igw.id
  }

  tags = {
    Name = "benchmark-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = local.public_subnet_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.benchmark_public_rt.id
}

# --------------------------------------------------------------------------
# Private Route Table (only when private subnets exist)
# --------------------------------------------------------------------------
resource "aws_route_table" "benchmark_private_rt" {
  count = local.has_private_subnets ? 1 : 0

  vpc_id = aws_vpc.benchmark_vpc.id

  tags = {
    Name = "benchmark-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count = local.private_subnet_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.benchmark_private_rt[0].id
}

# --------------------------------------------------------------------------
# Egress Strategy: NAT Gateways
# --------------------------------------------------------------------------
resource "aws_eip" "nat" {
  count = local.has_private_subnets && var.enable_nat_gateways ? local.public_subnet_count : 0

  domain = "vpc"

  tags = {
    Name = "benchmark-nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "benchmark" {
  count = local.has_private_subnets && var.enable_nat_gateways ? local.public_subnet_count : 0

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "benchmark-nat-gw-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.benchmark_igw]
}

resource "aws_route" "private_nat_gateway" {
  count = local.has_private_subnets && var.enable_nat_gateways ? local.private_subnet_count : 0

  route_table_id         = aws_route_table.benchmark_private_rt[0].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.benchmark[count.index].id
}

# --------------------------------------------------------------------------
# Egress Strategy: NAT Instances
# --------------------------------------------------------------------------
resource "aws_security_group" "nat_instance_sg" {
  count = local.has_private_subnets && var.enable_nat_instances ? 1 : 0

  name        = "benchmark-nat-instance-sg"
  description = "Security group for NAT instances"
  vpc_id      = aws_vpc.benchmark_vpc.id

  ingress {
    description = "Allow all traffic from VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Outbound traffic to VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "benchmark-nat-instance-sg"
  }
}

resource "aws_instance" "nat" {
  count = local.has_private_subnets && var.enable_nat_instances ? local.public_subnet_count : 0

  ami                    = data.aws_ssm_parameter.nat_ami.value
  instance_type          = var.nat_instance_instance_type
  subnet_id              = aws_subnet.public[count.index].id
  vpc_security_group_ids = [aws_security_group.nat_instance_sg[0].id]
  source_dest_check      = false

  user_data = <<-EOF
    #!/bin/bash
    echo "net.ipv4.ip_forward = 1" >> /etc/sysctl.conf
    sysctl -p /etc/sysctl.conf
    iptables -t nat -A POSTROUTING -o eth0 -j MASQUERADE
    /sbin/iptables-save > /etc/sysconfig/iptables
  EOF

  tags = {
    Name = "benchmark-nat-instance-${count.index + 1}"
  }
}

resource "aws_route" "private_nat_instance" {
  count = local.has_private_subnets && var.enable_nat_instances ? local.private_subnet_count : 0

  route_table_id         = aws_route_table.benchmark_private_rt[0].id
  destination_cidr_block = "0.0.0.0/0"
  network_interface_id   = aws_instance.nat[count.index].primary_network_interface_id
}

# --------------------------------------------------------------------------
# Egress Strategy: Egress-Only Internet Gateway
# --------------------------------------------------------------------------
resource "aws_egress_only_internet_gateway" "benchmark" {
  count = local.has_private_subnets && var.enable_egress_only_igw ? 1 : 0

  vpc_id = aws_vpc.benchmark_vpc.id

  tags = {
    Name = "benchmark-egress-only-igw"
  }
}

resource "aws_route" "private_egress_only" {
  count = local.has_private_subnets && var.enable_egress_only_igw ? 1 : 0

  route_table_id              = aws_route_table.benchmark_private_rt[0].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.benchmark[0].id
}

# --------------------------------------------------------------------------
# Outputs
# --------------------------------------------------------------------------
output "vpc_id" {
  value = aws_vpc.benchmark_vpc.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "default_security_group_id" {
  value = aws_default_security_group.benchmark_default_sg.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "secondary"
  region = var.secondary_region
}

# Variables
variable "environment" {
  description = "Environment name used for resource naming"
  type        = string
  default     = "benchmark"
}

variable "glacier_transition_days" {
  description = "Number of days after which objects are transitioned to Glacier"
  type        = number
  default     = 7
}

variable "expiration_days" {
  description = "Number of days after which objects are expired"
  type        = number
  default     = 30
}

variable "secondary_region" {
  description = "Secondary AWS region for replication targets"
  type        = string
  default     = "us-west-2"
}

# Data sources
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# Random suffix for globally unique names
resource "random_id" "suffix" {
  byte_length = 4
}

# Primary region KMS key for state bucket
resource "aws_kms_key" "state" {
  description             = "KMS key for Terraform state bucket encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 10
}

resource "aws_kms_alias" "state" {
  name          = "alias/${var.environment}-terraform-state-key-${random_id.suffix.hex}"
  target_key_id = aws_kms_key.state.key_id
}

# Secondary region KMS key for replica state bucket
resource "aws_kms_key" "state_replica" {
  provider                = aws.secondary
  description             = "KMS key for replica Terraform state bucket encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 10
}

resource "aws_kms_alias" "state_replica" {
  provider      = aws.secondary
  name          = "alias/${var.environment}-terraform-state-replica-key-${random_id.suffix.hex}"
  target_key_id = aws_kms_key.state_replica.key_id
}

# Primary access logs bucket (must exist before state bucket logging)
resource "aws_s3_bucket" "access_logs" {
  bucket = "${var.environment}-${data.aws_caller_identity.current.account_id}-access-logs-${random_id.suffix.hex}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  rule {
    id     = "glacier_transition_and_expiration"
    status = "Enabled"

    transition {
      days          = var.glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = var.expiration_days
    }
  }
}

resource "aws_s3_bucket_ownership_controls" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id
  acl    = "log-delivery-write"

  depends_on = [aws_s3_bucket_ownership_controls.access_logs]
}

resource "aws_s3_bucket_public_access_block" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Primary state bucket
resource "aws_s3_bucket" "state" {
  bucket = "${var.environment}-${data.aws_caller_identity.current.account_id}-terraform-state-${random_id.suffix.hex}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_logging" "state" {
  bucket = aws_s3_bucket.state.id

  target_bucket = aws_s3_bucket.access_logs.id
  target_prefix = "log/"
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnforceSameAccountAndACL"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.state.arn,
          "${aws_s3_bucket.state.arn}/*"
        ]
        Condition = {
          StringNotEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          StringNotEqualsIfExists = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
          ArnNotEquals = {
            "aws:PrincipalArn" = data.aws_caller_identity.current.arn
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Replica buckets in secondary region
resource "aws_s3_bucket" "state_replica" {
  provider = aws.secondary
  bucket   = "${var.environment}-${data.aws_caller_identity.current.account_id}-terraform-state-replica-${random_id.suffix.hex}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.state_replica.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.state_replica.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state_replica.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_policy" "state_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.state_replica.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnforceSameAccountAndACL"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.state_replica.arn,
          "${aws_s3_bucket.state_replica.arn}/*"
        ]
        Condition = {
          StringNotEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          StringNotEqualsIfExists = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
          ArnNotEquals = {
            "aws:PrincipalArn" = data.aws_caller_identity.current.arn
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_public_access_block" "state_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.state_replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket" "access_logs_replica" {
  provider = aws.secondary
  bucket   = "${var.environment}-${data.aws_caller_identity.current.account_id}-access-logs-replica-${random_id.suffix.hex}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "access_logs_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.access_logs_replica.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "access_logs_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.access_logs_replica.id

  rule {
    id     = "glacier_transition_and_expiration"
    status = "Enabled"

    transition {
      days          = var.glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = var.expiration_days
    }
  }
}

resource "aws_s3_bucket_ownership_controls" "access_logs_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.access_logs_replica.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "access_logs_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.access_logs_replica.id
  acl      = "log-delivery-write"

  depends_on = [aws_s3_bucket_ownership_controls.access_logs_replica]
}

resource "aws_s3_bucket_public_access_block" "access_logs_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.access_logs_replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# IAM role and policy for replication
resource "aws_iam_role" "replication" {
  name = "${var.environment}-s3-replication-role-${random_id.suffix.hex}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "replication" {
  name_prefix = "${var.environment}-s3-replication-policy-${random_id.suffix.hex}-"
  description = "Policy for S3 cross-region replication"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketActions"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = [
          aws_s3_bucket.state.arn,
          "${aws_s3_bucket.state.arn}/*",
          aws_s3_bucket.access_logs.arn,
          "${aws_s3_bucket.access_logs.arn}/*"
        ]
      },
      {
        Sid    = "SourceReplicationActions"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = [
          "${aws_s3_bucket.state.arn}/*",
          "${aws_s3_bucket.access_logs.arn}/*"
        ]
      },
      {
        Sid    = "DestinationReplicationActions"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ObjectOwnerOverrideToBucketOwner"
        ]
        Resource = [
          "${aws_s3_bucket.state_replica.arn}/*",
          "${aws_s3_bucket.access_logs_replica.arn}/*"
        ]
      },
      {
        Sid    = "KMSDecryptForStateSource"
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = [
          aws_kms_key.state.arn
        ]
        Condition = {
          StringLike = {
            "kms:ViaService" = "s3.${data.aws_region.current.name}.amazonaws.com"
          }
        }
      },
      {
        Sid    = "KMSEncryptForStateDestination"
        Effect = "Allow"
        Action = [
          "kms:Encrypt"
        ]
        Resource = [
          aws_kms_key.state_replica.arn
        ]
        Condition = {
          StringLike = {
            "kms:ViaService" = "s3.${var.secondary_region}.amazonaws.com"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

# Replication configuration for state bucket (no delete marker replication)
resource "aws_s3_bucket_replication_configuration" "state" {
  bucket = aws_s3_bucket.state.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "ReplicateToSecondary"
    status = "Enabled"

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.state_replica.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.state_replica.arn
      }
    }
  }
}

# Replication configuration for access logs bucket (no delete marker replication)
resource "aws_s3_bucket_replication_configuration" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "ReplicateToSecondary"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.access_logs_replica.arn
      storage_class = "STANDARD"
    }
  }
}

# Terraform configuration
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.80.0"
    }
  }
}

# Variables
variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "existing_vpc_id" {
  description = "ID of an existing VPC; if provided, VPC creation is skipped"
  type        = string
  default     = ""
}

variable "existing_private_subnet_ids" {
  description = "Map of availability zone to existing private subnet IDs"
  type        = map(string)
  default     = {}
}

variable "existing_security_group_id" {
  description = "ID of an existing security group for VPC endpoints; if provided, security group creation is skipped"
  type        = string
  default     = ""
}

variable "endpoint_services" {
  description = "List of AWS services for which to create interface VPC endpoints"
  type        = list(string)
  default = [
    "ec2",
    "ecr.api",
    "ecr.dkr",
    "s3",
    "logs",
    "sts",
    "elasticloadbalancing",
    "autoscaling",
  ]
}

# Data sources
data "aws_region" "current" {}

data "aws_vpcs" "all" {}

data "aws_subnets" "default" {
  filter {
    name   = "vpc-id"
    values = [local.vpc_id]
  }
}

# Locals
locals {
  # VPC ID: use existing if provided, otherwise use the first existing VPC
  vpc_id = var.existing_vpc_id != "" ? var.existing_vpc_id : data.aws_vpcs.all.ids[0]

  # Endpoint security group ID
  endpoint_sg_id = var.existing_security_group_id != "" ? var.existing_security_group_id : aws_security_group.endpoint[0].id

  # Subnet IDs for endpoints: use provided private subnet IDs if available,
  # otherwise use all subnets in the chosen VPC
  endpoint_subnet_ids = length(var.existing_private_subnet_ids) > 0 ? values(var.existing_private_subnet_ids) : data.aws_subnets.default.ids
}

# Endpoint security group
resource "aws_security_group" "endpoint" {
  count       = var.existing_security_group_id == "" ? 1 : 0
  name        = "${var.vpc_name}-vpc-endpoints"
  description = "Security group for VPC endpoints"
  vpc_id      = local.vpc_id

  ingress {
    description = "HTTPS from VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "All traffic within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.vpc_name}-vpc-endpoints"
  }
}

# Interface VPC endpoints
resource "aws_vpc_endpoint" "interface" {
  for_each          = toset(var.endpoint_services)
  vpc_id            = local.vpc_id
  service_name      = "com.amazonaws.${data.aws_region.current.id}.${each.value}"
  vpc_endpoint_type = "Interface"
  subnet_ids        = local.endpoint_subnet_ids
  security_group_ids = [local.endpoint_sg_id]

  tags = {
    Name = "${var.vpc_name}-${each.value}"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0.0"
    }
  }
}

variable "app_shortcode" {
  type        = string
  default     = "bmk"
  description = "Shortcode used as prefix for IAM role and instance profile names"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-2.0.*-x86_64-ebs"]
  }
}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.8.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "bmk-test-vpc"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.8.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "bmk-private-subnet"
  }
}

resource "aws_security_group" "endpoint_sg" {
  name        = "bmk-endpoint-sg"
  description = "Security group for VPC endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow HTTPS from VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress = []

  tags = {
    Name = "bmk-endpoint-sg"
  }
}

resource "aws_vpc_endpoint" "ssm" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ssm"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoint_sg.id]
  private_dns_enabled = true
  auto_accept         = true

  tags = {
    Name = "bmk-ssm-endpoint"
  }
}

resource "aws_vpc_endpoint" "ec2messages" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ec2messages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoint_sg.id]
  private_dns_enabled = true
  auto_accept         = true

  tags = {
    Name = "bmk-ec2messages-endpoint"
  }
}

resource "aws_vpc_endpoint" "ssmmessages" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ssmmessages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoint_sg.id]
  private_dns_enabled = true
  auto_accept         = true

  tags = {
    Name = "bmk-ssmmessages-endpoint"
  }
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoint_sg.id]
  private_dns_enabled = true
  auto_accept         = true

  tags = {
    Name = "bmk-logs-endpoint"
  }
}

resource "aws_security_group" "instance_sg" {
  name        = "bmk-instance-sg"
  description = "Security group for test EC2 instance"
  vpc_id      = aws_vpc.main.id

  ingress = []

  egress {
    description = "Allow HTTPS to VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "bmk-instance-sg"
  }
}

resource "aws_iam_role" "ssm_role" {
  name = "${var.app_shortcode}-ssm-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  inline_policy {
    name = "${var.app_shortcode}-ssm-policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect   = "Allow"
          Action   = [
            "ssm:*",
            "ssmmessages:*",
            "ec2messages:*"
          ]
          Resource = "*"
        },
        {
          Effect   = "Allow"
          Action   = [
            "logs:PutLogEvents",
            "logs:CreateLogStream",
            "logs:DescribeLogGroups"
          ]
          Resource = "arn:aws:logs:*:*:*"
        },
        {
          Effect   = "Allow"
          Action   = [
            "s3:GetObject",
            "s3:PutObject",
            "s3:ListBucket"
          ]
          Resource = [
            "arn:aws:s3:::*",
            "arn:aws:s3:::*/*"
          ]
        }
      ]
    })
  }

  tags = {
    Name = "${var.app_shortcode}-ssm-role"
  }
}

resource "aws_iam_instance_profile" "ssm_profile" {
  name = "${var.app_shortcode}-ssm-instance-profile"
  role = aws_iam_role.ssm_role.name

  tags = {
    Name = "${var.app_shortcode}-ssm-instance-profile"
  }
}

resource "aws_iam_policy" "kms" {
  name        = "${var.app_shortcode}-kms-policy"
  description = "Permissions to use the EBS encryption key"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["kms:GenerateDataKey", "kms:Decrypt"]
        Resource = aws_kms_key.ebs.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "kms" {
  role       = aws_iam_role.ssm_role.name
  policy_arn = aws_iam_policy.kms.arn
}

resource "aws_kms_key" "ebs" {
  description             = "EBS encryption key"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  is_enabled              = true
  multi_region            = false

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/${var.app_shortcode}-ssm-role"
        }
        Action   = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })

  depends_on = [aws_iam_role.ssm_role]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "ebs" {
  name          = "alias/ebs-encryption-key"
  target_key_id = aws_kms_key.ebs.key_id
}

resource "aws_instance" "test_instance" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = "t3.small"
  subnet_id                   = aws_subnet.private.id
  iam_instance_profile        = aws_iam_instance_profile.ssm_profile.name
  vpc_security_group_ids      = [aws_security_group.instance_sg.id]
  associate_public_ip_address = false
  source_dest_check           = false

  metadata_options {
    http_tokens   = "required"
    http_endpoint = "enabled"
  }

  root_block_device {
    encrypted  = true
    kms_key_id = aws_kms_key.ebs.arn
  }

  tags = {
    Name = "bmk-test-instance"
  }
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

resource "random_pet" "suffix" {
  length = 1
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-ebs"]
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "main"
  }
}

# Public subnets
resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "public-${count.index}"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 3)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "private-${count.index}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main"
  }
}

# Elastic IPs for NAT Gateways
resource "aws_eip" "nat" {
  count  = 3
  domain = "vpc"

  tags = {
    Name = "nat-${count.index}"
  }
}

# NAT Gateways
resource "aws_nat_gateway" "main" {
  count = 3

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "nat-${count.index}"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public"
  }
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private route tables (one per AZ)
resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = {
    Name = "private-${count.index}"
  }
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# Gateway VPC Endpoint for S3
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"

  route_table_ids = aws_route_table.private[*].id

  tags = {
    Name = "s3-endpoint"
  }
}

# Security Group for Interface Endpoints
resource "aws_security_group" "vpc_endpoints" {
  name        = "vpc_endpoints_sg"
  description = "Allow HTTPS from VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "vpc_endpoints_sg"
  }
}

# Interface VPC Endpoints
locals {
  interface_endpoint_services = [
    "com.amazonaws.us-east-1.ecr.dkr",
    "com.amazonaws.us-east-1.ecr.api",
    "com.amazonaws.us-east-1.logs",
    "com.amazonaws.us-east-1.secretsmanager",
    "com.amazonaws.us-east-1.ssm",
    "com.amazonaws.us-east-1.kms"
  ]
}

resource "aws_vpc_endpoint" "interface" {
  for_each = toset(local.interface_endpoint_services)

  vpc_id              = aws_vpc.main.id
  service_name        = each.key
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = each.key
  }
}

# Cloud Map Private DNS Namespace
resource "aws_service_discovery_private_dns_namespace" "main" {
  name        = "private-fargate-crowdnews.hands-on.cloud.local"
  description = "Private namespace for Fargate services"
  vpc         = aws_vpc.main.id
}

# ECR Repository
resource "aws_ecr_repository" "nginx" {
  name                 = "nginx-repo-${random_pet.suffix.id}"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "nginx-repo-${random_pet.suffix.id}"
  }
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "nginx" {
  name              = "/ecs/nginx-fargate-${random_pet.suffix.id}"
  retention_in_days = 30

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "/ecs/nginx-fargate-${random_pet.suffix.id}"
  }
}

# ECS Cluster
resource "aws_ecs_cluster" "main" {
  name = "nginx-cluster"

  tags = {
    Name = "nginx-cluster"
  }
}

# IAM Role for ECS Task Execution
resource "aws_iam_role" "ecs_task_execution" {
  name = "ecs_task_execution_role_${random_pet.suffix.id}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "ecs_task_execution_role_${random_pet.suffix.id}"
  }
}

# Inline policy for ECS Task Execution: ECR and Logs
resource "aws_iam_role_policy" "ecs_task_execution" {
  name = "ecs_task_execution_policy"
  role = aws_iam_role.ecs_task_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

# IAM Role for ECS Task
resource "aws_iam_role" "ecs_task" {
  name = "ecs_task_role_${random_pet.suffix.id}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "ecs_task_role_${random_pet.suffix.id}"
  }
}

# Inline policy for ECS Task: Service Discovery
resource "aws_iam_role_policy" "ecs_task_service_discovery" {
  name = "ecs_task_service_discovery"
  role = aws_iam_role.ecs_task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "servicediscovery:RegisterInstance",
          "servicediscovery:DeregisterInstance",
          "servicediscovery:UpdateInstanceCustomHealthStatus"
        ]
        Resource = aws_service_discovery_private_dns_namespace.main.arn
      }
    ]
  })
}

# Security Group for ECS Tasks
resource "aws_security_group" "ecs_task" {
  name        = "ecs_task_sg"
  description = "Allow port 80 from VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "ecs_task_sg"
  }
}

# Cloud Map Service
resource "aws_service_discovery_service" "main" {
  name = "nginx-service"

  dns_config {
    namespace_id = aws_service_discovery_private_dns_namespace.main.id

    dns_records {
      ttl  = 10
      type = "A"
    }

    dns_records {
      ttl  = 10
      type = "SRV"
    }

    routing_policy = "MULTIVALUE"
  }
}

# ECS Task Definition
resource "aws_ecs_task_definition" "nginx" {
  family                   = "nginx"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = 512
  memory                   = 1024
  execution_role_arn       = aws_iam_role.ecs_task_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name  = "nginx"
      image = "nginx:latest"
      portMappings = [
        {
          containerPort = 80
          protocol      = "tcp"
        }
      ]
      environment = [
        {
          name  = "SERVICE_DISCOVERY_NAMESPACE"
          value = aws_service_discovery_private_dns_namespace.main.id
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.nginx.name
          "awslogs-region"        = "us-east-1"
          "awslogs-stream-prefix" = "nginx"
        }
      }
    }
  ])

  tags = {
    Name = "nginx-task"
  }
}

# ECS Service
resource "aws_ecs_service" "nginx" {
  name            = "nginx-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.nginx.arn
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs_task.id]
    assign_public_ip = false
  }

  service_registries {
    registry_arn   = aws_service_discovery_service.main.arn
    container_name = "nginx"
    container_port = 80
  }

  tags = {
    Name = "nginx-service"
  }
}

# Network Interface for Jumphost
resource "aws_network_interface" "jumphost" {
  subnet_id   = aws_subnet.public[0].id
  private_ips = ["10.0.0.10"]
  security_groups = [aws_security_group.jumphost.id]

  tags = {
    Name = "jumphost-eni"
  }
}

# IAM Role for Jumphost
resource "aws_iam_role" "jumphost_ssm" {
  name = "jumphost_ssm_role_${random_pet.suffix.id}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "jumphost_ssm_role_${random_pet.suffix.id}"
  }
}

resource "aws_iam_role_policy_attachment" "jumphost_ssm" {
  role       = aws_iam_role.jumphost_ssm.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "jumphost" {
  name = "jumphost_instance_profile_${random_pet.suffix.id}"
  role = aws_iam_role.jumphost_ssm.name
}

# Security Group for Jumphost
resource "aws_security_group" "jumphost" {
  name        = "jumphost_sg"
  description = "Allow all inbound from VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "jumphost_sg"
  }
}

# EC2 Instance (Jumphost)
resource "aws_instance" "jumphost" {
  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = "t3.micro"
  iam_instance_profile   = aws_iam_instance_profile.jumphost.name

  network_interface {
    device_index          = 0
    network_interface_id  = aws_network_interface.jumphost.id
  }

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted = true
  }

  tags = {
    Name = "jumphost"
  }
}

# Output
output "curl_nginx_command" {
  value = "curl http://${aws_service_discovery_service.main.name}.${aws_service_discovery_private_dns_namespace.main.name}"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 3.0"
    }
  }
}

variable "project" {
  description = "Project name for tagging"
  type        = string
  default     = "my-project"
}

variable "application" {
  description = "Application name for tagging"
  type        = string
  default     = "my-app"
}

variable "environment" {
  description = "Environment name (e.g., dev, prod)"
  type        = string
  default     = "dev"
}

variable "availability_zone_prefix" {
  description = "Availability Zone suffix (e.g., us-east-1a)"
  type        = string
  default     = "us-east-1a"
}

variable "custom_routes" {
  description = "List of additional route definitions for the public route table"
  type = list(object({
    cidr_block      = string
    gateway_id      = optional(string)
    nat_gateway_id  = optional(string)
    transit_gateway_id = optional(string)
    vpc_peering_connection_id = optional(string)
  }))
  default = []
}

variable "assign_eip" {
  description = "Whether to allocate and associate an Elastic IP to the ENI"
  type        = bool
  default     = false
}

variable "generate_ssh_key" {
  description = "Whether to generate an SSH key pair"
  type        = bool
  default     = false
}

variable "attach_ssm_managed_policy" {
  description = "Whether to attach the AmazonSSMManagedInstanceCore managed policy to the IAM role"
  type        = bool
  default     = false
}

locals {
  # Standardized name prefix
  name_prefix = "${var.project}-${var.application}-${var.environment}-${var.availability_zone_prefix}"

  # Common tags
  common_tags = {
    Project     = var.project
    Application = var.application
    Environment = var.environment
    Az          = var.availability_zone_prefix
  }

  # IAM policy document for SSM Session Manager permissions
  ssm_session_manager_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ssm:StartSession",
          "ssm:TerminateSession",
          "ssm:ResumeSession",
          "ssmmessages:CreateControlChannel",
          "ssmmessages:CreateDataChannel",
          "ssmmessages:OpenControlChannel",
          "ssmmessages:OpenDataChannel"
        ]
        Resource = "*"
      }
    ]
  })
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    { Name = "${local.name_prefix}-vpc" }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    { Name = "${local.name_prefix}-igw" }
  )
}

# Public Subnet
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    { Name = "${local.name_prefix}-subnet" }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  dynamic "route" {
    for_each = var.custom_routes
    content {
      cidr_block                = route.value.cidr_block
      gateway_id                = route.value.gateway_id
      nat_gateway_id            = route.value.nat_gateway_id
      transit_gateway_id        = route.value.transit_gateway_id
      vpc_peering_connection_id = route.value.vpc_peering_connection_id
    }
  }

  tags = merge(
    local.common_tags,
    { Name = "${local.name_prefix}-rtb" }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Route Table Association
resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Elastic Network Interface (ENI)
resource "aws_network_interface" "main" {
  subnet_id   = aws_subnet.public.id
  private_ips = []

  tags = merge(
    local.common_tags,
    { Name = "${local.name_prefix}-eni" }
  )
}

# Elastic IP (conditional)
resource "aws_eip" "main" {
  count = var.assign_eip ? 1 : 0

  domain = "vpc"

  tags = merge(
    local.common_tags,
    { Name = "${local.name_prefix}-eip" }
  )
}

resource "aws_eip_association" "main" {
  count = var.assign_eip ? 1 : 0

  allocation_id        = aws_eip.main[0].id
  network_interface_id = aws_network_interface.main.id
}

# SSH Key Pair (conditional)
resource "tls_private_key" "generated" {
  count = var.generate_ssh_key ? 1 : 0

  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "generated" {
  count = var.generate_ssh_key ? 1 : 0

  key_name   = "${local.name_prefix}-key"
  public_key = tls_private_key.generated[0].public_key_openssh

  lifecycle {
    ignore_changes = [public_key]
  }

  tags = merge(
    local.common_tags,
    { Name = "${local.name_prefix}-key" }
  )
}

# IAM Role
resource "aws_iam_role" "ec2_ssm" {
  name = "${local.name_prefix}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "ec2.amazonaws.com",
            "ssm.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(
    local.common_tags,
    { Name = "${local.name_prefix}-role" }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Dedicated SSM Session Manager Policy
resource "aws_iam_policy" "ssm_session_manager" {
  name        = "${local.name_prefix}-ssm-session-manager-policy"
  description = "Policy granting SSM Session Manager permissions"
  policy      = local.ssm_session_manager_policy

  tags = merge(
    local.common_tags,
    { Name = "${local.name_prefix}-ssm-session-manager-policy" }
  )
}

resource "aws_iam_role_policy_attachment" "ssm_session_manager" {
  role       = aws_iam_role.ec2_ssm.name
  policy_arn = aws_iam_policy.ssm_session_manager.arn
}

# Conditional attachment of AmazonSSMManagedInstanceCore
resource "aws_iam_role_policy_attachment" "ssm_managed_instance" {
  count = var.attach_ssm_managed_policy ? 1 : 0

  role       = aws_iam_role.ec2_ssm.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# Instance Profile
resource "aws_iam_instance_profile" "ec2_ssm" {
  name = "${local.name_prefix}-instance-profile"
  role = aws_iam_role.ec2_ssm.name

  tags = merge(
    local.common_tags,
    { Name = "${local.name_prefix}-instance-profile" }
  )
}

# EC2 Instance
resource "aws_instance" "main" {
  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = "t3.micro"
  key_name               = var.generate_ssh_key ? aws_key_pair.generated[0].key_name : null
  iam_instance_profile   = aws_iam_instance_profile.ec2_ssm.name
  user_data_base64       = ""
  user_data_replace_on_change = false

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
    instance_metadata_tags      = "enabled"
  }

  root_block_device {
    volume_size = 20
    encrypted   = true
    tags = merge(
      local.common_tags,
      { Name = "${local.name_prefix}-root-volume" }
    )
  }

  network_interface {
    network_interface_id = aws_network_interface.main.id
    device_index         = 0
  }

  tags = merge(
    local.common_tags,
    { Name = "${local.name_prefix}-instance" }
  )
}

# Outputs
output "instance_id" {
  description = "EC2 instance ID"
  value       = aws_instance.main.id
}

output "instance_arn" {
  description = "EC2 instance ARN"
  value       = aws_instance.main.arn
}

output "iam_role_name" {
  description = "IAM role name"
  value       = aws_iam_role.ec2_ssm.name
}

output "iam_role_arn" {
  description = "IAM role ARN"
  value       = aws_iam_role.ec2_ssm.arn
}

output "instance_profile_name" {
  description = "Instance profile name"
  value       = aws_iam_instance_profile.ec2_ssm.name
}

output "instance_profile_arn" {
  description = "Instance profile ARN"
  value       = aws_iam_instance_profile.ec2_ssm.arn
}

output "route_table_id" {
  description = "Route table ID"
  value       = aws_route_table.public.id
}

output "subnet_id" {
  description = "Public subnet ID"
  value       = aws_subnet.public.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.0.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.9"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
  }
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "eks_ami" {
  most_recent = true
  owners      = ["602401143452"]

  filter {
    name   = "name"
    values = ["amazon-eks-node-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

# VPC and networking
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name                                 = "demo-eks-vpc"
    "kubernetes.io/cluster/demo-eks"     = "owned"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "demo-eks-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]

  tags = {
    Name                                 = "demo-eks-public-subnet"
    "kubernetes.io/cluster/demo-eks"     = "owned"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "demo-eks-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "demo-eks-nat"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "demo-eks-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet("10.0.0.0/16", 8, count.index + 10)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name                                 = "demo-eks-private-subnet-${count.index + 1}"
    "kubernetes.io/role/internal-elb"    = "1"
    "kubernetes.io/cluster/demo-eks"     = "owned"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "demo-eks-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# TLS key pair
resource "tls_private_key" "eks" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "local_file" "eks_key" {
  filename        = pathexpand("~/.ssh/eks-aws.pem")
  content         = tls_private_key.eks.private_key_pem
  file_permission = "0600"
}

resource "aws_key_pair" "eks" {
  key_name   = "eks_kp"
  public_key = tls_private_key.eks.public_key_openssh
}

# IAM roles and policies
resource "aws_iam_role" "eks_cluster" {
  name = "eksClusterRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
}

# KMS key for EKS secrets encryption
resource "aws_kms_key" "eks" {
  description             = "EKS secrets encryption key"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow EKS Cluster Role to use key"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.eks_cluster.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:Encrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "eks" {
  name          = "alias/eks-demo"
  target_key_id = aws_kms_key.eks.key_id
}

# Custom policy for cluster role to use KMS key
resource "aws_iam_policy" "eks_kms_policy" {
  name        = "eksClusterKmsPolicy"
  description = "Allow EKS cluster to use KMS key for secrets encryption"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:Encrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.eks.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_kms" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = aws_iam_policy.eks_kms_policy.arn
}

# Data source for account ID (needed for KMS key policy)
data "aws_caller_identity" "current" {}

# EKS cluster
resource "aws_eks_cluster" "main" {
  name     = "demo-eks"
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  encryption_config {
    provider {
      key_arn = aws_kms_key.eks.arn
    }
    resources = ["secrets"]
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller,
    aws_iam_role_policy_attachment.eks_kms
  ]
}

# Security group for worker nodes
resource "aws_security_group" "node" {
  name        = "eks-demo-node-sg"
  description = "Security group for EKS worker nodes"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name                             = "eks-demo-node-sg"
    "kubernetes.io/cluster/demo-eks" = "owned"
  }
}

# Ingress from self (all internal communication)
resource "aws_security_group_rule" "node_ingress_self" {
  type              = "ingress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  self              = true
  security_group_id = aws_security_group.node.id
}

# Ingress from control plane on port 443
resource "aws_security_group_rule" "node_ingress_cp_443" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.main.vpc_config[0].cluster_security_group_id
  security_group_id        = aws_security_group.node.id
}

# Ingress from control plane on ports 1025-65535
resource "aws_security_group_rule" "node_ingress_cp_wide" {
  type                     = "ingress"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.main.vpc_config[0].cluster_security_group_id
  security_group_id        = aws_security_group.node.id
}

# Egress to VPC CIDR (all traffic)
resource "aws_security_group_rule" "node_egress_vpc" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.node.id
}

# Egress to control plane on port 443
resource "aws_security_group_rule" "node_egress_cp_443" {
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.main.vpc_config[0].cluster_security_group_id
  security_group_id        = aws_security_group.node.id
}

# Egress to control plane on ports 1025-65535
resource "aws_security_group_rule" "node_egress_cp_wide" {
  type                     = "egress"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.main.vpc_config[0].cluster_security_group_id
  security_group_id        = aws_security_group.node.id
}

# Node IAM role
resource "aws_iam_role" "node" {
  name = "eks-demo-node"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "node_worker" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "node_cni" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "node_ecr" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "node_ssm" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "node" {
  name = "eks-demo-node-profile"
  role = aws_iam_role.node.name
}

# Launch template
locals {
  user_data = <<-EOF
#!/bin/bash
set -ex
/etc/eks/bootstrap.sh demo-eks
# Signal CloudFormation stack
aws cloudformation signal-resource \
  --stack-name eks-cluster-stack \
  --logical-resource-id AutoScalingGroup \
  --status SUCCESS \
  --unique-id $(curl -s http://169.254.169.254/latest/meta-data/instance-id) \
  --region us-east-1
EOF
}

resource "aws_launch_template" "node" {
  name          = "eks-demo-node-lt"
  image_id      = data.aws_ami.eks_ami.image_id
  instance_type = "t3.medium"
  key_name      = aws_key_pair.eks.key_name

  iam_instance_profile {
    arn = aws_iam_instance_profile.node.arn
  }

  block_device_mappings {
    device_name = "/dev/xvda"
    ebs {
      volume_size = 30
      volume_type = "gp2"
    }
  }

  metadata_options {
    http_tokens               = "required"
    http_put_response_hop_limit = 2
  }

  user_data = base64encode(local.user_data)

  tag_specifications {
    resource_type = "instance"
    tags = {
      Name                             = "eks-demo-node"
      "kubernetes.io/cluster/demo-eks" = "owned"
    }
  }
}

# Wait for launch template to settle
resource "time_sleep" "wait_for_lt" {
  depends_on      = [aws_launch_template.node]
  create_duration = "30s"
}

# CloudFormation stack for Auto Scaling Group
resource "aws_cloudformation_stack" "node" {
  name = "eks-cluster-stack"

  template_body = <<TEMPLATE
{
  "AWSTemplateFormatVersion": "2010-09-09",
  "Resources": {
    "AutoScalingGroup": {
      "Type": "AWS::AutoScaling::AutoScalingGroup",
      "Properties": {
        "MinSize": "1",
        "MaxSize": "4",
        "DesiredCapacity": "3",
        "VPCZoneIdentifier": [
          "${aws_subnet.private[0].id}",
          "${aws_subnet.private[1].id}",
          "${aws_subnet.private[2].id}"
        ],
        "LaunchTemplate": {
          "LaunchTemplateId": "${aws_launch_template.node.id}",
          "Version": "${aws_launch_template.node.latest_version}"
        }
      },
      "UpdatePolicy": {
        "AutoScalingRollingUpdate": {
          "MaxBatchSize": "1",
          "MinInstancesInService": "3",
          "PauseTime": "PT5M"
        }
      }
    }
  },
  "Outputs": {
    "AutoScalingGroupName": {
      "Value": { "Ref": "AutoScalingGroup" }
    }
  }
}
TEMPLATE

  depends_on = [
    time_sleep.wait_for_lt,
    aws_eks_cluster.main,
    aws_security_group.node,
    aws_iam_role_policy_attachment.node_worker,
    aws_iam_role_policy_attachment.node_cni,
    aws_iam_role_policy_attachment.node_ecr,
    aws_iam_role_policy_attachment.node_ssm
  ]
}

# Outputs
output "node_instance_role_arn" {
  value = aws_iam_role.node.arn
}

output "node_security_group_id" {
  value = aws_security_group.node.id
}

output "autoscaling_group_id" {
  value = aws_cloudformation_stack.node.outputs["AutoScalingGroupName"]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

# Provider for replica region (explicit alias)
provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

# Data sources for dynamic account ID and region
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# Variable for replica region
variable "replica_region" {
  description = "AWS region for the replica S3 bucket"
  type        = string
  default     = "us-west-2"
}

# Variable for EKS stacks
variable "eks_stacks" {
  description = "Map of stack names to regions (DynamoDB tables will be created in the primary region)"
  type        = map(string)
  default     = {}
}

# Common tags
locals {
  common_tags = {
    Environment = "Production"
    Terraform   = "true"
    Purpose     = "StateManagement"
  }
}

# Random suffix for unique resource names
resource "random_id" "suffix" {
  byte_length = 4
}

# ----------------------------------------------------------------------
# Primary Region Resources (provider "aws" default)
# ----------------------------------------------------------------------

# Primary KMS Key
resource "aws_kms_key" "primary" {
  description             = "Primary state KMS key"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
  tags = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "primary" {
  name          = "alias/primary-state-key-${random_id.suffix.hex}"
  target_key_id = aws_kms_key.primary.key_id
}

# Primary S3 Bucket
resource "aws_s3_bucket" "primary" {
  bucket = "eks-state-${data.aws_caller_identity.current.account_id}-${random_id.suffix.hex}"
  tags   = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket                  = aws_s3_bucket.primary.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_policy" "primary" {
  bucket = aws_s3_bucket.primary.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyNonSSL"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# Replication IAM Role
resource "aws_iam_role" "replication" {
  name = "s3-replication-role-${random_id.suffix.hex}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3ReplicationService"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy" "replication" {
  name = "s3-replication-policy-${random_id.suffix.hex}"
  role = aws_iam_role.replication.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadSourceBucket"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion"
        ]
        Resource = "${aws_s3_bucket.primary.arn}/*"
      },
      {
        Sid    = "DecryptSourceKMS"
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = aws_kms_key.primary.arn
      },
      {
        Sid    = "ReplicateToDestination"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete"
        ]
        Resource = "${aws_s3_bucket.replica.arn}/*"
      },
      {
        Sid    = "EncryptDestinationKMS"
        Effect = "Allow"
        Action = [
          "kms:Encrypt"
        ]
        Resource = aws_kms_key.replica.arn
      }
    ]
  })
}

# Cross-region replication configuration
resource "aws_s3_bucket_replication_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "ReplicateAllObjects"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.replica.arn
      storage_class = "STANDARD"
      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }
}

# ----------------------------------------------------------------------
# Replica Region Resources (provider "aws.replica")
# ----------------------------------------------------------------------

# Replica KMS Key
resource "aws_kms_key" "replica" {
  provider                = aws.replica
  description             = "Replica state KMS key"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
  tags = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "replica" {
  provider      = aws.replica
  name          = "alias/replica-state-key-${random_id.suffix.hex}"
  target_key_id = aws_kms_key.replica.key_id
}

# Replica S3 Bucket
resource "aws_s3_bucket" "replica" {
  provider = aws.replica
  bucket   = "eks-state-replica-${data.aws_caller_identity.current.account_id}-${random_id.suffix.hex}"
  tags     = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider                = aws.replica
  bucket                  = aws_s3_bucket.replica.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_policy" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyNonSSL"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.replica.arn,
          "${aws_s3_bucket.replica.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# ----------------------------------------------------------------------
# DynamoDB Tables per EKS Stack (primary region)
# ----------------------------------------------------------------------

resource "aws_dynamodb_table" "state_lock" {
  for_each = var.eks_stacks

  name         = "terraform-state-lock-${each.key}"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  tags = merge(local.common_tags, { StackName = each.key })
  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# IAM Policies per Stack
# ----------------------------------------------------------------------

resource "aws_iam_policy" "stack_policy" {
  for_each = var.eks_stacks

  name        = "eks-stack-${each.key}-state-policy"
  description = "Policy for stack ${each.key} to access state management resources"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DynamoDBLock"
        Effect = "Allow"
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem"
        ]
        Resource = aws_dynamodb_table.state_lock[each.key].arn
      },
      {
        Sid    = "S3StateAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/eks-stacks/${each.key}/*"
        ]
      },
      {
        Sid    = "KMSEncryptDecrypt"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.primary.arn
      }
    ]
  })
  tags = merge(local.common_tags, { StackName = each.key })
}

# ----------------------------------------------------------------------
# Generate backend.tf files for each stack
# ----------------------------------------------------------------------

resource "local_file" "backend_tf" {
  for_each = var.eks_stacks

  filename = "${path.module}/eks-stacks/${each.key}/backend.tf"
  content  = <<-EOT
terraform {
  backend "s3" {
    bucket         = "${aws_s3_bucket.primary.id}"
    key            = "eks-stacks/${each.key}/terraform.tfstate"
    region         = "${data.aws_region.current.region}"
    dynamodb_table = "${aws_dynamodb_table.state_lock[each.key].name}"
    encrypt        = true
    kms_key_id     = "${aws_kms_key.primary.arn}"
  }
}
EOT
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

resource "aws_cognito_user_pool" "box_things" {
  name = "box_things"

  alias_attributes           = ["email"]
  auto_verified_attributes   = ["email"]
  mfa_configuration          = "OFF"
  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  password_policy {
    minimum_length    = 8
    require_lowercase = true
    require_numbers   = true
    require_symbols   = true
    require_uppercase = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cognito_user_pool_client" "box_things_client" {
  name         = "box_things_client"
  user_pool_id = aws_cognito_user_pool.box_things.id

  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH"
  ]

  access_token_validity = 60
  id_token_validity     = 60

  token_validity_units {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }

  callback_urls = ["https://example.com/callback"]
  logout_urls   = ["https://example.com/logout"]

  supported_identity_providers = ["COGNITO"]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "user_owner_map" {
  type        = map(string)
  description = "Map of IAM usernames to their Owner tag value"
  default = {
    dev1  = "Devel"
    dev2  = "Devel"
    guest = "Guest"
  }
}

resource "aws_iam_group" "ersia_devel" {
  name = "Ersia_Devel_Group"
}

resource "aws_iam_group" "ersia_guest" {
  name = "Ersia_Guest_Group"
}

resource "aws_iam_group_policy_attachment" "devel_readonly" {
  group      = aws_iam_group.ersia_devel.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "guest_iamreadonly" {
  group      = aws_iam_group.ersia_guest.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_user" "user" {
  for_each = var.user_owner_map
  name     = each.key
  tags = {
    Owner = each.value
  }
}

resource "aws_iam_user_group_membership" "membership" {
  for_each = var.user_owner_map
  user     = aws_iam_user.user[each.key].name
  groups = [
    each.value == "Devel" ? aws_iam_group.ersia_devel.name : aws_iam_group.ersia_guest.name
  ]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

resource "random_pet" "main" {
  length = 2
}

# KMS key for SQS encryption
resource "aws_kms_key" "main" {
  description             = "KMS key for SQS queue encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_alias" "main" {
  name          = "alias/websocket-sqs-key-${random_pet.main.id}"
  target_key_id = aws_kms_key.main.key_id
}

# SQS queue
resource "aws_sqs_queue" "main" {
  name                              = random_pet.main.id
  kms_master_key_id                 = aws_kms_key.main.arn
  kms_data_key_reuse_period_seconds = 300
  delay_seconds                     = 0

  lifecycle {
    prevent_destroy = true
  }
}

# IAM role for API Gateway
resource "aws_iam_role" "main" {
  name = "api-gateway-sqs-role-${random_pet.main.id}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })
}

# IAM policy for SQS and CloudWatch Logs
resource "aws_iam_policy" "main" {
  name = "api-gateway-sqs-logs-policy-${random_pet.main.id}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "sqs:SendMessage"
        ]
        Resource = [
          aws_sqs_queue.main.arn
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/apigateway/*",
          "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/apigateway/*:log-stream:*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "main" {
  role       = aws_iam_role.main.name
  policy_arn = aws_iam_policy.main.arn
}

# CloudWatch Log Group for API Gateway access logs
resource "aws_cloudwatch_log_group" "main" {
  name              = "/aws/apigateway/websocket-${random_pet.main.id}"
  retention_in_days = 1
}

# WebSocket API
resource "aws_apigatewayv2_api" "main" {
  name                       = random_pet.main.id
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"
}

# Integration for $connect (mock)
resource "aws_apigatewayv2_integration" "connect" {
  api_id           = aws_apigatewayv2_api.main.id
  integration_type = "MOCK"

  request_templates = {
    "application/json" = jsonencode({ statusCode = 200 })
  }
  passthrough_behavior = "WHEN_NO_TEMPLATES"
}

# Integration for $default (send raw message to SQS)
resource "aws_apigatewayv2_integration" "default" {
  api_id           = aws_apigatewayv2_api.main.id
  integration_type = "AWS"
  integration_uri  = "arn:aws:apigateway:${data.aws_region.current.name}:sqs:path/${data.aws_caller_identity.current.account_id}/${aws_sqs_queue.main.name}"
  integration_method = "POST"
  credentials_arn  = aws_iam_role.main.arn

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }
  request_templates = {
    "application/json" = "Action=SendMessage&MessageBody=$input.json('$')"
  }
  passthrough_behavior = "WHEN_NO_TEMPLATES"
}

# Integration for $disconnect (send fixed message to SQS)
resource "aws_apigatewayv2_integration" "disconnect" {
  api_id           = aws_apigatewayv2_api.main.id
  integration_type = "AWS"
  integration_uri  = "arn:aws:apigateway:${data.aws_region.current.name}:sqs:path/${data.aws_caller_identity.current.account_id}/${aws_sqs_queue.main.name}"
  integration_method = "POST"
  credentials_arn  = aws_iam_role.main.arn

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }
  request_templates = {
    "application/json" = "Action=SendMessage&MessageBody=Client disconnected"
  }
  passthrough_behavior = "WHEN_NO_TEMPLATES"
}

# Routes
resource "aws_apigatewayv2_route" "connect" {
  api_id    = aws_apigatewayv2_api.main.id
  route_key = "$connect"
  target    = "integrations/${aws_apigatewayv2_integration.connect.id}"
}

resource "aws_apigatewayv2_route" "default" {
  api_id    = aws_apigatewayv2_api.main.id
  route_key = "$default"
  target    = "integrations/${aws_apigatewayv2_integration.default.id}"
}

resource "aws_apigatewayv2_route" "disconnect" {
  api_id    = aws_apigatewayv2_api.main.id
  route_key = "$disconnect"
  target    = "integrations/${aws_apigatewayv2_integration.disconnect.id}"
}

# Deployment
resource "aws_apigatewayv2_deployment" "main" {
  api_id      = aws_apigatewayv2_api.main.id
  description = "Deployment for WebSocket API"

  triggers = {
    redeployment = sha1(join(",", [
      aws_apigatewayv2_route.connect.id,
      aws_apigatewayv2_route.default.id,
      aws_apigatewayv2_route.disconnect.id,
      aws_apigatewayv2_integration.connect.id,
      aws_apigatewayv2_integration.default.id,
      aws_apigatewayv2_integration.disconnect.id
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }
}

# Stage
resource "aws_apigatewayv2_stage" "main" {
  api_id      = aws_apigatewayv2_api.main.id
  name        = "dev"
  auto_deploy = true
  deployment_id = aws_apigatewayv2_deployment.main.id

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.main.arn
    format = jsonencode({
      requestId               = "$context.requestId"
      ip                      = "$context.identity.sourceIp"
      caller                  = "$context.identity.caller"
      user                    = "$context.identity.user"
      requestTime             = "$context.requestTime"
      httpMethod              = "$context.httpMethod"
      routeKey                = "$context.routeKey"
      protocol                = "$context.protocol"
      status                  = "$context.status"
      responseLength          = "$context.responseLength"
    })
  }
}

# Output
output "websocket_endpoint" {
  value = "wss://${aws_apigatewayv2_api.main.id}.execute-api.${data.aws_region.current.name}.amazonaws.com/${aws_apigatewayv2_stage.main.name}"
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_configs" {
  description = "Map of VPC configurations"
  type = map(object({
    cidr_block           = string
    name_tag             = string
    enable_dns_support   = bool
    enable_dns_hostnames = bool
    extra_tags           = map(string)
  }))
  default = {
    vpc1 = {
      cidr_block           = "10.0.0.0/16"
      name_tag             = "XXXX-vpc-test"
      enable_dns_support   = true
      enable_dns_hostnames = false
      extra_tags           = {}
    }
    vpc2 = {
      cidr_block           = "172.31.0.0/16"
      name_tag             = "Default"
      enable_dns_support   = true
      enable_dns_hostnames = true
      extra_tags           = {}
    }
    vpc3 = {
      cidr_block           = "192.168.0.0/16"
      name_tag             = "eksctl-eks-cluster-px-cluster/VPC"
      enable_dns_support   = true
      enable_dns_hostnames = true
      extra_tags = {
        "eksctl.cluster.k8s.io/v1alpha1/cluster-name" = "eks-cluster-px"
        "eksctl.io/version"                           = "0.94.0"
      }
    }
    vpc4 = {
      cidr_block           = "10.0.0.0/24"
      name_tag             = ""
      enable_dns_support   = true
      enable_dns_hostnames = false
      extra_tags           = {}
    }
    vpc5 = {
      cidr_block           = "10.0.0.0/16"
      name_tag             = ""
      enable_dns_support   = true
      enable_dns_hostnames = false
      extra_tags           = {}
    }
  }
}

locals {
  # Build final tags for each VPC:
  # - Always include Name tag (even if empty string)
  # - Merge with extra_tags
  vpc_tags = {
    for k, config in var.vpc_configs :
    k => merge(
      { Name = config.name_tag },
      config.extra_tags
    )
  }
}

resource "aws_vpc" "this" {
  for_each = var.vpc_configs

  cidr_block           = each.value.cidr_block
  enable_dns_support   = each.value.enable_dns_support
  enable_dns_hostnames = each.value.enable_dns_hostnames
  instance_tenancy     = "default"

  tags = local.vpc_tags[each.key]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100.0"
    }
  }
}

data "aws_default_tags" "current" {}

data "aws_iam_policy_document" "ecs_role_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "ecs_tasks_role_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "events_role_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "ecs_policy" {
  statement {
    effect = "Allow"
    actions = [
      "ecs:RunTask"
    ]
    resources = ["*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = [aws_iam_role.ecs_tasks_role.arn]
  }
}

resource "aws_iam_role" "ecs_role" {
  name               = "ecs-role"
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.ecs_role_assume.json
  force_detach_policies = true
  tags = merge(data.aws_default_tags.current.tags, var.tags)
}

resource "aws_iam_role_policy_attachment" "ecs_role_attachment" {
  role       = aws_iam_role.ecs_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

resource "aws_iam_role" "ecs_tasks_role" {
  name               = "ecs-tasks-role"
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_role_assume.json
  force_detach_policies = true
  tags = merge(data.aws_default_tags.current.tags, var.tags)
}

resource "aws_iam_role_policy_attachment" "ecs_tasks_role_attachment" {
  role       = aws_iam_role.ecs_tasks_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_policy" "ecs_policy" {
  name        = "ecs-policy"
  path        = "/"
  description = "Policy to allow ECS RunTask and PassRole for ECS task execution role"
  policy      = data.aws_iam_policy_document.ecs_policy.json
}

resource "aws_iam_role" "events_role" {
  name               = "events-role"
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.events_role_assume.json
  force_detach_policies = true
  tags = merge(data.aws_default_tags.current.tags, var.tags)
}

resource "aws_iam_role_policy_attachment" "events_role_ecs_policy" {
  role       = aws_iam_role.events_role.name
  policy_arn = aws_iam_policy.ecs_policy.arn
}

resource "aws_iam_role_policy_attachment" "events_role_cloudwatch_logs" {
  role       = aws_iam_role.events_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchLogsFullAccess"
}

variable "tags" {
  description = "Optional tags to merge with provider default tags"
  type        = map(string)
  default     = {}
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.80.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "secondary"
  region = "us-west-2"
}

variable "bucket_name_primary" {
  description = "Name for the primary S3 bucket (without account ID suffix)"
  type        = string
  default     = "example1"
}

variable "bucket_name_secondary" {
  description = "Name for the secondary S3 bucket (without account ID suffix)"
  type        = string
  default     = "example2"
}

variable "mrap_name" {
  description = "Name for the Multi-Region Access Point"
  type        = string
  default     = "example-mrap"
}

data "aws_caller_identity" "current" {}

locals {
  account_id            = data.aws_caller_identity.current.account_id
  primary_bucket_name   = "${var.bucket_name_primary}-${local.account_id}"
  secondary_bucket_name = "${var.bucket_name_secondary}-${local.account_id}"
}

# KMS Keys
resource "aws_kms_key" "primary" {
  description             = "KMS key for primary S3 bucket SSE-KMS"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "primary" {
  name          = "alias/s3-primary-key"
  target_key_id = aws_kms_key.primary.key_id
}

resource "aws_kms_key" "secondary" {
  provider = aws.secondary
  description             = "KMS key for secondary S3 bucket SSE-KMS"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "secondary" {
  provider      = aws.secondary
  name          = "alias/s3-secondary-key"
  target_key_id = aws_kms_key.secondary.key_id
}

# Primary S3 Bucket
resource "aws_s3_bucket" "primary" {
  bucket = local.primary_bucket_name
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket = aws_s3_bucket.primary.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "primary" {
  bucket = aws_s3_bucket.primary.id
  acl    = "private"
  depends_on = [aws_s3_bucket_ownership_controls.primary]
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket                  = aws_s3_bucket.primary.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary.arn
    }
  }
}

# Secondary S3 Bucket
resource "aws_s3_bucket" "secondary" {
  provider = aws.secondary
  bucket   = local.secondary_bucket_name
}

resource "aws_s3_bucket_versioning" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "secondary" {
  provider   = aws.secondary
  bucket     = aws_s3_bucket.secondary.id
  acl        = "private"
  depends_on = [aws_s3_bucket_ownership_controls.secondary]
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  provider                = aws.secondary
  bucket                  = aws_s3_bucket.secondary.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.secondary.arn
    }
  }
}

# IAM Role for Replication
resource "aws_iam_role" "replication" {
  name = "s3-replication-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

data "aws_iam_policy_document" "replication" {
  statement {
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.primary.arn,
      "${aws_s3_bucket.primary.arn}/*"
    ]
  }

  statement {
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:GetReplicationConfiguration"
    ]
    resources = [
      aws_s3_bucket.secondary.arn,
      "${aws_s3_bucket.secondary.arn}/*"
    ]
  }

  statement {
    actions = [
      "kms:Decrypt"
    ]
    resources = [
      aws_kms_key.primary.arn
    ]
    condition {
      test     = "StringLike"
      variable = "kms:ViaService"
      values   = ["s3.${aws_s3_bucket.primary.region}.amazonaws.com"]
    }
  }

  statement {
    actions = [
      "kms:Encrypt"
    ]
    resources = [
      aws_kms_key.secondary.arn
    ]
    condition {
      test     = "StringLike"
      variable = "kms:ViaService"
      values   = ["s3.${aws_s3_bucket.secondary.region}.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy" "replication" {
  name   = "s3-replication-policy"
  role   = aws_iam_role.replication.id
  policy = data.aws_iam_policy_document.replication.json
}

# Replication Configuration on Primary Bucket
resource "aws_s3_bucket_replication_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.replication.arn
  depends_on = [aws_iam_role_policy.replication]

  rule {
    id     = "ReplicateAll"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Disabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }
    }
  }
}

# Multi-Region Access Point
resource "aws_s3control_multi_region_access_point" "mrap" {
  provider = aws.secondary
  details {
    name = var.mrap_name
    region {
      bucket = aws_s3_bucket.primary.bucket
    }
    region {
      bucket = aws_s3_bucket.secondary.bucket
    }
  }
}

# Access Point Policy
data "aws_iam_policy_document" "mrap" {
  statement {
    actions = [
      "s3:GetObject",
      "s3:PutObject"
    ]
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${local.account_id}:root"]
    }
    resources = [
      "arn:aws:s3::${local.account_id}:accesspoint/${var.mrap_name}/object/*"
    ]
  }
}

resource "aws_s3control_multi_region_access_point_policy" "mrap" {
  provider = aws.secondary
  details {
    name = var.mrap_name
    policy = data.aws_iam_policy_document.mrap.json
  }
  depends_on = [aws_s3control_multi_region_access_point.mrap]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.34, < 5.100"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "name" {
  description = "Name for the null-label module"
  type        = string
  default     = "patch-manager"
}

variable "environment" {
  description = "Environment for the null-label module"
  type        = string
  default     = "dev"
}

variable "aws_region" {
  description = "AWS region for deployment"
  type        = string
  default     = "eu-west-2"
}

variable "scan_patch_group" {
  description = "Tag value for patch group targeted by scan maintenance window"
  type        = string
  default     = "TOSCAN"
}

variable "install_patch_group" {
  description = "Tag value for patch group targeted by install maintenance window"
  type        = string
  default     = "TOPATCH"
}

variable "sns_notifications_enabled" {
  description = "Enable SNS notifications for maintenance window tasks"
  type        = bool
  default     = false
}

variable "cloudwatch_logs_enabled" {
  description = "Enable CloudWatch Logs output for maintenance window tasks"
  type        = bool
  default     = false
}

variable "scan_schedule" {
  description = "Cron schedule for scan maintenance window"
  type        = string
  default     = "cron(0 0 18 ? * WED *)"
}

variable "install_schedule" {
  description = "Cron schedule for install maintenance window"
  type        = string
  default     = "cron(0 0 21 ? * WED *)"
}

variable "max_concurrency" {
  description = "Maximum concurrency for Run Command tasks"
  type        = string
  default     = "20"
}

variable "max_errors" {
  description = "Maximum errors for Run Command tasks"
  type        = string
  default     = "50"
}

variable "approval_delay_days" {
  description = "Number of days before auto-approving patches"
  type        = number
  default     = 7
}

variable "output_s3_key_prefix" {
  description = "S3 key prefix for command output"
  type        = string
  default     = "scanning"
}

locals {
  scan_window_name   = module.label.id
  install_window_name = "${module.label.id}-install"
  log_bucket_name    = "${module.label.id}-logs-${random_id.bucket_suffix.hex}"
}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

module "label" {
  source      = "cloudposse/label/null"
  version     = "0.25.0"
  name        = var.name
  environment = var.environment
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# KMS Key for S3 log bucket encryption
resource "aws_kms_key" "maintenance_window" {
  description             = "KMS key for SSM Patch Manager log bucket encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  tags                    = module.label.tags
}

# Patch Baseline
resource "aws_ssm_patch_baseline" "amazon_linux_2" {
  name             = "${module.label.id}-amazon-linux-2"
  operating_system = "AMAZON_LINUX_2"
  approved_patches_compliance_level = "HIGH"
  tags             = module.label.tags

  approval_rule {
    approve_after_days = var.approval_delay_days
    enable_non_security = true

    patch_filter {
      key    = "SEVERITY"
      values = ["Critical", "Important", "Medium"]
    }

    patch_filter {
      key    = "CLASSIFICATION"
      values = ["Security", "Bugfix", "Recommended"]
    }
  }
}

resource "aws_ssm_patch_group" "scan" {
  baseline_id = aws_ssm_patch_baseline.amazon_linux_2.id
  patch_group = var.scan_patch_group
}

resource "aws_ssm_patch_group" "install" {
  baseline_id = aws_ssm_patch_baseline.amazon_linux_2.id
  patch_group = var.install_patch_group
}

# S3 Log Bucket
resource "aws_s3_bucket" "logs" {
  bucket        = local.log_bucket_name
  force_destroy = false
  tags          = module.label.tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.maintenance_window.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket                  = aws_s3_bucket.logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "logs" {
  bucket = aws_s3_bucket.logs.id
  policy = data.aws_iam_policy_document.log_bucket.json
}

data "aws_iam_policy_document" "log_bucket" {
  statement {
    sid    = "AllowAccountAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.logs.arn,
      "${aws_s3_bucket.logs.arn}/*"
    ]
  }
}

# IAM Role for Maintenance Window Tasks
resource "aws_iam_role" "maintenance_window" {
  name               = "${module.label.id}-mw-role"
  assume_role_policy = data.aws_iam_policy_document.maintenance_window_trust.json
  tags               = module.label.tags
}

data "aws_iam_policy_document" "maintenance_window_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ssm.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy_attachment" "maintenance_window" {
  role       = aws_iam_role.maintenance_window.name
  policy_arn = aws_iam_policy.maintenance_window.arn
}

resource "aws_iam_policy" "maintenance_window" {
  name        = "${module.label.id}-mw-policy"
  description = "Least privilege policy for maintenance window tasks"
  tags        = module.label.tags
  policy      = data.aws_iam_policy_document.maintenance_window_permissions.json
}

data "aws_iam_policy_document" "maintenance_window_permissions" {
  statement {
    sid    = "SSM"
    effect = "Allow"
    actions = [
      "ssm:SendCommand",
      "ssm:DescribeInstanceInformation",
      "ssm:GetCommandInvocation"
    ]
    resources = ["*"]
  }
  statement {
    sid    = "S3Logs"
    effect = "Allow"
    actions = [
      "s3:PutObject"
    ]
    resources = [
      "${aws_s3_bucket.logs.arn}/*"
    ]
  }
  statement {
    sid    = "KMSDecrypt"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey"
    ]
    resources = [aws_kms_key.maintenance_window.arn]
  }
}

# Scan Maintenance Window
resource "aws_ssm_maintenance_window" "scan" {
  name                          = local.scan_window_name
  schedule                      = var.scan_schedule
  duration                      = 3
  cutoff                        = 1
  allow_unassociated_targets    = false
  tags                          = module.label.tags
}

resource "aws_ssm_maintenance_window_target" "scan" {
  window_id     = aws_ssm_maintenance_window.scan.id
  resource_type = "INSTANCE"
  name          = "${module.label.id}-scan-target"
  targets {
    key    = "tag:PatchGroup"
    values = [var.scan_patch_group]
  }
}

resource "aws_ssm_maintenance_window_task" "scan" {
  window_id        = aws_ssm_maintenance_window.scan.id
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors
  service_role_arn = aws_iam_role.maintenance_window.arn
  name             = "${module.label.id}-scan-task"

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.scan.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      comment = "Scan"
      parameter {
        name   = "Operation"
        values = ["Scan"]
      }
      parameter {
        name   = "RebootOption"
        values = ["NoReboot"]
      }
      output_s3_bucket     = aws_s3_bucket.logs.id
      output_s3_key_prefix = var.output_s3_key_prefix

      dynamic "notification_config" {
        for_each = var.sns_notifications_enabled ? [1] : []
        content {
          notification_arn    = aws_sns_topic.maintenance_window[0].arn
          notification_events = ["All"]
          notification_type   = "Command"
        }
      }

      dynamic "cloudwatch_config" {
        for_each = var.cloudwatch_logs_enabled ? [1] : []
        content {
          cloudwatch_log_group_name  = aws_cloudwatch_log_group.maintenance_window[0].name
          cloudwatch_output_enabled  = true
        }
      }
    }
  }
}

# Install Maintenance Window
resource "aws_ssm_maintenance_window" "install" {
  name                          = local.install_window_name
  schedule                      = var.install_schedule
  duration                      = 3
  cutoff                        = 1
  allow_unassociated_targets    = false
  tags                          = module.label.tags
}

resource "aws_ssm_maintenance_window_target" "install" {
  window_id     = aws_ssm_maintenance_window.install.id
  resource_type = "INSTANCE"
  name          = "${module.label.id}-install-target"
  targets {
    key    = "tag:PatchGroup"
    values = [var.install_patch_group]
  }
}

resource "aws_ssm_maintenance_window_task" "install" {
  window_id        = aws_ssm_maintenance_window.install.id
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors
  service_role_arn = aws_iam_role.maintenance_window.arn
  name             = "${module.label.id}-install-task"

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.install.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      comment = "Install"
      parameter {
        name   = "Operation"
        values = ["Install"]
      }
      parameter {
        name   = "RebootOption"
        values = ["RebootIfNeeded"]
      }
      output_s3_bucket     = aws_s3_bucket.logs.id
      output_s3_key_prefix = var.output_s3_key_prefix

      dynamic "notification_config" {
        for_each = var.sns_notifications_enabled ? [1] : []
        content {
          notification_arn    = aws_sns_topic.maintenance_window[0].arn
          notification_events = ["All"]
          notification_type   = "Command"
        }
      }

      dynamic "cloudwatch_config" {
        for_each = var.cloudwatch_logs_enabled ? [1] : []
        content {
          cloudwatch_log_group_name  = aws_cloudwatch_log_group.maintenance_window[0].name
          cloudwatch_output_enabled  = true
        }
      }
    }
  }
}

# Optional SNS Topic
resource "aws_sns_topic" "maintenance_window" {
  count = var.sns_notifications_enabled ? 1 : 0
  name  = "${module.label.id}-notifications"
  tags  = module.label.tags
}

# Optional CloudWatch Log Group
resource "aws_cloudwatch_log_group" "maintenance_window" {
  count             = var.cloudwatch_logs_enabled ? 1 : 0
  name              = "/aws/ssm/maintenance-windows/${module.label.id}"
  retention_in_days = 7
  tags              = module.label.tags
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100.0"
    }
  }
}

data "aws_caller_identity" "current" {}

import {
  to = aws_kms_alias.trail_key
  id = "alias/cloudtrail-monitor-key"
}

import {
  to = aws_kms_alias.sns_key
  id = "alias/management-updates-sns-key"
}

import {
  to = aws_s3_bucket.cloudtrail_logs
  id = "cloudtrail-monitor-management-event-logs-${data.aws_caller_identity.current.account_id}"
}

import {
  to = aws_cloudwatch_log_group.trail_logs
  id = "cloudtrail_to_cloudwatch_logs"
}

import {
  to = aws_iam_role.cloudtrail_cloudwatch_role
  id = "CloudTrail_CloudWatchLogs_Role"
}

import {
  to = aws_cloudtrail.monitor_account_activities
  id = "monitor_account_activities"
}

variable "alert_emails" {
  description = "List of email addresses to subscribe to the SNS topic for management alerts"
  type        = list(string)
  default     = ["placeholder@example.com"]
}

locals {
  bucket_name = "cloudtrail-monitor-management-event-logs-${data.aws_caller_identity.current.account_id}"
}

# KMS key for CloudTrail logs encryption
resource "aws_kms_key" "trail_key" {
  description             = "KMS key for CloudTrail log encryption"
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudTrail to use the key"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:DescribeKey",
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "trail_key" {
  name          = "alias/cloudtrail-monitor-key"
  target_key_id = aws_kms_key.trail_key.id
}

# KMS key for SNS topic encryption
resource "aws_kms_key" "sns_key" {
  description             = "KMS key for SNS topic encryption (management alerts)"
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch to publish to encrypted SNS topic"
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "sns_key" {
  name          = "alias/management-updates-sns-key"
  target_key_id = aws_kms_key.sns_key.id
}

# S3 bucket for CloudTrail logs
resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket = local.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.trail_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AWSCloudTrailAclCheck"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.cloudtrail_logs.arn
      },
      {
        Sid    = "AllowCloudTrailWrite"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.cloudtrail_logs.arn}/AWSLogs/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

# CloudWatch Logs group
resource "aws_cloudwatch_log_group" "trail_logs" {
  name              = "cloudtrail_to_cloudwatch_logs"
  retention_in_days = 90
}

# IAM role for CloudTrail to deliver to CloudWatch Logs
resource "aws_iam_role" "cloudtrail_cloudwatch_role" {
  name = "CloudTrail_CloudWatchLogs_Role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch_policy" {
  name = "CloudTrail_CloudWatchLogs_Policy"
  role = aws_iam_role.cloudtrail_cloudwatch_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:PutLogEvents",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.trail_logs.arn}:*"
      }
    ]
  })
}

# CloudTrail trail
resource "aws_cloudtrail" "monitor_account_activities" {
  name                          = "monitor_account_activities"
  s3_bucket_name                = aws_s3_bucket.cloudtrail_logs.id
  s3_key_prefix                 = "AWSLogs"
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  kms_key_id                    = aws_kms_key.trail_key.arn
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.trail_logs.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch_role.arn

  event_selector {
    include_management_events = true
    read_write_type           = "All"

    exclude_management_event_sources = ["kms.amazonaws.com", "rdsdata.amazonaws.com"]
  }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail_logs
  ]
}

# CloudWatch Logs metric filters and alarms

# 1. Security Group Changes
resource "aws_cloudwatch_log_metric_filter" "security_group_changes" {
  name           = "SecurityGroupChanges"
  pattern        = "{ ($.eventName = \"AuthorizeSecurityGroupIngress\") || ($.eventName = \"AuthorizeSecurityGroupEgress\") || ($.eventName = \"RevokeSecurityGroupIngress\") || ($.eventName = \"RevokeSecurityGroupEgress\") || ($.eventName = \"CreateSecurityGroup\") || ($.eventName = \"DeleteSecurityGroup\") }"
  log_group_name = aws_cloudwatch_log_group.trail_logs.name

  metric_transformation {
    name      = "SecurityGroupChanges"
    namespace = "management_activities"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "security_group_changes" {
  alarm_name          = "SecurityGroupChanges"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.security_group_changes.metric_transformation[0].name
  namespace           = "management_activities"
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_actions       = [aws_sns_topic.management_updates.arn]
  alarm_description   = "Alert when security group changes are detected"
}

# 2. IAM User Creation or Deletion
resource "aws_cloudwatch_log_metric_filter" "iam_user_creation_deletion" {
  name           = "IAMUserCreationOrDeletion"
  pattern        = "{ ($.eventName = \"CreateUser\") || ($.eventName = \"DeleteUser\") }"
  log_group_name = aws_cloudwatch_log_group.trail_logs.name

  metric_transformation {
    name      = "IAMUserCreationOrDeletion"
    namespace = "management_activities"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "iam_user_creation_deletion" {
  alarm_name          = "IAMUserCreationOrDeletion"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.iam_user_creation_deletion.metric_transformation[0].name
  namespace           = "management_activities"
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_actions       = [aws_sns_topic.management_updates.arn]
  alarm_description   = "Alert when IAM user creation or deletion is detected"
}

# 3. Failed Console Logins
resource "aws_cloudwatch_log_metric_filter" "failed_console_logins" {
  name           = "FailedConsoleLogins"
  pattern        = "{ ($.eventName = \"ConsoleLogin\") && ($.responseElements.ConsoleLogin = \"Failure\") }"
  log_group_name = aws_cloudwatch_log_group.trail_logs.name

  metric_transformation {
    name      = "FailedConsoleLogins"
    namespace = "management_activities"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "failed_console_logins" {
  alarm_name          = "FailedConsoleLogins"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.failed_console_logins.metric_transformation[0].name
  namespace           = "management_activities"
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_actions       = [aws_sns_topic.management_updates.arn]
  alarm_description   = "Alert when failed console logins are detected"
}

# 4. IAM Group, Role, User Policy Changes
resource "aws_cloudwatch_log_metric_filter" "iam_policy_attachments" {
  name           = "IAMGroupRoleUserPolicyChanges"
  pattern        = "{ ($.eventSource = \"iam.amazonaws.com\") && (($.eventName = \"PutGroupPolicy\") || ($.eventName = \"PutRolePolicy\") || ($.eventName = \"PutUserPolicy\") || ($.eventName = \"DeleteGroupPolicy\") || ($.eventName = \"DeleteRolePolicy\") || ($.eventName = \"DeleteUserPolicy\")) }"
  log_group_name = aws_cloudwatch_log_group.trail_logs.name

  metric_transformation {
    name      = "IAMGroupRoleUserPolicyChanges"
    namespace = "management_activities"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "iam_policy_attachments" {
  alarm_name          = "IAMGroupRoleUserPolicyChanges"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.iam_policy_attachments.metric_transformation[0].name
  namespace           = "management_activities"
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_actions       = [aws_sns_topic.management_updates.arn]
  alarm_description   = "Alert when IAM group, role, or user policy changes are detected"
}

# 5. IAM Policy Changes
resource "aws_cloudwatch_log_metric_filter" "iam_policy_changes" {
  name           = "IAMPolicyChanges"
  pattern        = "{ ($.eventSource = \"iam.amazonaws.com\") && (($.eventName = \"CreatePolicy\") || ($.eventName = \"DeletePolicy\") || ($.eventName = \"AttachRolePolicy\") || ($.eventName = \"DetachRolePolicy\") || ($.eventName = \"AttachUserPolicy\") || ($.eventName = \"DetachUserPolicy\") || ($.eventName = \"AttachGroupPolicy\") || ($.eventName = \"DetachGroupPolicy\")) }"
  log_group_name = aws_cloudwatch_log_group.trail_logs.name

  metric_transformation {
    name      = "IAMPolicyChanges"
    namespace = "management_activities"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "iam_policy_changes" {
  alarm_name          = "IAMPolicyChanges"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.iam_policy_changes.metric_transformation[0].name
  namespace           = "management_activities"
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_actions       = [aws_sns_topic.management_updates.arn]
  alarm_description   = "Alert when IAM policy changes are detected"
}

# 6. Users Added to Groups
resource "aws_cloudwatch_log_metric_filter" "users_added_to_groups" {
  name           = "UsersAddedToGroups"
  pattern        = "{ ($.eventName = \"AddUserToGroup\") }"
  log_group_name = aws_cloudwatch_log_group.trail_logs.name

  metric_transformation {
    name      = "UsersAddedToGroups"
    namespace = "management_activities"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "users_added_to_groups" {
  alarm_name          = "UsersAddedToGroups"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.users_added_to_groups.metric_transformation[0].name
  namespace           = "management_activities"
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_actions       = [aws_sns_topic.management_updates.arn]
  alarm_description   = "Alert when users are added to groups"
}

# 7. IAM Role Creation or Deletion
resource "aws_cloudwatch_log_metric_filter" "iam_role_creation_deletion" {
  name           = "IAMRoleCreationOrDeletion"
  pattern        = "{ ($.eventName = \"CreateRole\") || ($.eventName = \"DeleteRole\") }"
  log_group_name = aws_cloudwatch_log_group.trail_logs.name

  metric_transformation {
    name      = "IAMRoleCreationOrDeletion"
    namespace = "management_activities"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "iam_role_creation_deletion" {
  alarm_name          = "IAMRoleCreationOrDeletion"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.iam_role_creation_deletion.metric_transformation[0].name
  namespace           = "management_activities"
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_actions       = [aws_sns_topic.management_updates.arn]
  alarm_description   = "Alert when IAM role creation or deletion is detected"
}

# SNS topic for alerts
resource "aws_sns_topic" "management_updates" {
  name              = "management-updates"
  kms_master_key_id = aws_kms_key.sns_key.arn
}

resource "aws_sns_topic_policy" "allow_cloudwatch" {
  arn = aws_sns_topic.management_updates.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudWatchAlarms"
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.management_updates.arn
      }
    ]
  })
}

resource "aws_sns_topic_subscription" "email" {
  for_each  = toset(var.alert_emails)
  topic_arn = aws_sns_topic.management_updates.arn
  protocol  = "email"
  endpoint  = each.value
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "name_prefix" {
  description = "Optional prefix for the Config rule name"
  type        = string
  default     = ""
}

variable "days_to_expiration" {
  description = "Number of days before expiration to trigger the rule"
  type        = number
  default     = 14
}

data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

locals {
  rule_name      = "${var.name_prefix}acm-certificate-expiration-check"
  bucket_name    = "config-bucket-${random_id.bucket_suffix.hex}"
  s3_key_prefix  = "config/${data.aws_caller_identity.current.account_id}/${data.aws_region.current.name}"
  account_id     = data.aws_caller_identity.current.account_id
}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "random_id" "role_suffix" {
  byte_length = 4
}

# KMS key for S3 bucket encryption
resource "aws_kms_key" "config_s3" {
  description             = "Customer-managed key for AWS Config delivery bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowConfigService"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "AWS:SourceAccount" = local.account_id
          }
        }
      },
      {
        Sid    = "EnableIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

# S3 bucket for AWS Config delivery
resource "aws_s3_bucket" "config" {
  bucket = local.bucket_name

  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "config" {
  bucket = aws_s3_bucket.config.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config" {
  bucket = aws_s3_bucket.config.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.config_s3.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "config" {
  bucket = aws_s3_bucket.config.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "config" {
  bucket = aws_s3_bucket.config.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AWSConfigWrite"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = [
          "s3:PutObject",
          "s3:GetBucketAcl"
        ]
        Resource = [
          aws_s3_bucket.config.arn,
          "${aws_s3_bucket.config.arn}/*"
        ]
        Condition = {
          StringEquals = {
            "AWS:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })
}

# IAM role for AWS Config
resource "aws_iam_role" "config" {
  name = "aws-config-role-${random_id.role_suffix.hex}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ConfigAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "config" {
  role       = aws_iam_role.config.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWS_ConfigRole"
}

# Configuration recorder
resource "aws_config_configuration_recorder" "main" {
  name     = "default"
  role_arn = aws_iam_role.config.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

# Delivery channel
resource "aws_config_delivery_channel" "main" {
  name           = "default"
  s3_bucket_name = aws_s3_bucket.config.bucket
  s3_key_prefix  = local.s3_key_prefix

  snapshot_delivery_properties {
    delivery_frequency = "TwentyFour_Hours"
  }

  depends_on = [aws_config_configuration_recorder.main]
}

# Config rule: ACM certificate expiration check
resource "aws_config_config_rule" "acm_expiration" {
  name = local.rule_name

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  input_parameters = "{\"daysToExpiration\":\"${var.days_to_expiration}\"}"

  scope {
    compliance_resource_types = ["AWS::ACM::Certificate"]
  }

  maximum_execution_frequency = "TwentyFour_Hours"

  depends_on = [aws_config_configuration_recorder.main]
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "6.69.0"
    }
  }
}

resource "aws_cognito_user_pool" "fiap_hackathon_cognito_pool" {
  name = "fiap-hackathon-cognito-pool"

  username_attributes = ["email"]
  auto_verified_attributes = ["email"]

  mfa_configuration = "OFF"

  password_policy {
    minimum_length    = 8
    require_lowercase = false
    require_uppercase = false
    require_numbers   = false
    require_symbols   = false
  }

  schema {
    name     = "name"
    required = true
    attribute_data_type = "String"
    mutable  = true
    developer_only_attribute = false
    string_attribute_constraints {
      min_length = 1
      max_length = 256
    }
  }
}

resource "aws_cognito_user_pool_client" "cognito_pool_client" {
  name = "cognito-pool-client"

  user_pool_id = aws_cognito_user_pool.fiap_hackathon_cognito_pool.id

  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH"
  ]
}

