}

data "tls_certificate" "azure_ad" {
  url = "https://sts.windows.net/221ca1d3-b3f2-4346-8abc-88f802495c7d/"
}

resource "aws_iam_openid_connect_provider" "azure_ad_sentinel" {
  url            = data.tls_certificate.azure_ad.url
  client_id_list = ["c8b9cf86-e2b4-4428-b356-14313412a4d1"]
  thumbprint_list = [
    data.tls_certificate.azure_ad.certificates[0].sha1_fingerprint
  ]
}

resource "aws_iam_role" "sentinel_oidc_organizations_readonly" {
