          Federated = aws_iam_openid_connect_provider.azure_ad_sentinel.arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${replace(data.tls_certificate.azure_ad.url, "https://", "")}:aud" = "c8b9cf86-e2b4-4428-b356-14313412a4d1"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "organizations_readonly" {
  role       = aws_iam_role.sentinel_oidc_organizations_readonly.name
  policy_arn = "arn:aws:iam::aws:policy/AWSOrganizationsReadOnlyAccess"
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

resource "aws_iam_role" "ec2_test_role" {
  name = "ec2-test-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "rds_add_role_to_db_cluster" {
  name   = "rds-add-role-to-db-cluster"
  role   = aws_iam_role.ec2_test_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "rds:AddRoleToDBCluster"
