terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 6.0.0, != 6.70.0"
    }
  }
}

import {
  to = aws_kms_alias.frontend
  id = "alias/s3-frontend-nft-maker-v2"
}

import {
  to = aws_kms_alias.state
  id = "alias/near-frontend-terraform-state"
}

import {
  to = aws_s3_bucket.frontend
  id = "s3-frontend-nft-maker-v2-${data.aws_caller_identity.current.account_id}"
}

import {
  to = aws_s3_bucket.state
  id = "near-frontend-${var.environment}-terraform-state-${data.aws_caller_identity.current.account_id}"
}

import {
  to = aws_dynamodb_table.state_lock
  id = "near-frontend-terraform-state"
}

provider "aws" {
  region = "us-east-1"
}

# Data source for current account ID
data "aws_caller_identity" "current" {}

# Variable for environment name
variable "environment" {
  description = "Environment name for state bucket naming"
  type        = string
  default     = "dev"
}

# ------------------------------------------------------------------------------
# Frontend KMS Key
# ------------------------------------------------------------------------------
resource "aws_kms_key" "frontend" {
  description             = "KMS key for frontend S3 bucket"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 service to use key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_kms_alias" "frontend" {
  name          = "alias/s3-frontend-nft-maker-v2"
  target_key_id = aws_kms_key.frontend.key_id
}

# ------------------------------------------------------------------------------
# Frontend S3 Bucket
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "frontend" {
  bucket = "s3-frontend-nft-maker-v2-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.frontend.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_website_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  index_document {
    suffix = "index.html"
  }

  error_document {
    key = "index.html"
  }
}

resource "aws_s3_bucket_cors_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "PUT", "POST", "DELETE"]
    allowed_origins = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3000
  }
}

# ------------------------------------------------------------------------------
# CloudFront Origin Access Identity
# ------------------------------------------------------------------------------
resource "aws_cloudfront_origin_access_identity" "frontend" {
  comment = "oai-frontend"
}

# ------------------------------------------------------------------------------
# Frontend Bucket Policy for OAI
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_policy" "frontend" {
  bucket = aws_s3_bucket.frontend.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudFrontOAI"
        Effect = "Allow"
        Principal = {
          AWS = aws_cloudfront_origin_access_identity.frontend.iam_arn
        }
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.frontend.arn,
          "${aws_s3_bucket.frontend.arn}/*"
        ]
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# WAFv2 Web ACL for CloudFront
# ------------------------------------------------------------------------------
resource "aws_wafv2_web_acl" "frontend" {
  name        = "frontend-waf"
  description = "WAF ACL for frontend CloudFront distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AWS-AWSManagedRulesCommonRuleSet"
    priority = 0

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        vendor_name = "AWS"
        name        = "AWSManagedRulesCommonRuleSet"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = false
      metric_name                = "AWSManagedRulesCommonRuleSetMetric"
      sampled_requests_enabled   = false
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = false
    metric_name                = "frontendWAFMetric"
    sampled_requests_enabled   = false
  }
}

# ------------------------------------------------------------------------------
# CloudFront Distribution
# ------------------------------------------------------------------------------
resource "aws_cloudfront_distribution" "frontend" {
  origin {
    domain_name = aws_s3_bucket.frontend.bucket_regional_domain_name
    origin_id   = "S3Origin"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.frontend.cloudfront_access_identity_path
    }
  }

  enabled         = true
  is_ipv6_enabled = true
  comment         = "Frontend distribution"

  default_root_object = "index.html"

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3Origin"

    viewer_protocol_policy = "redirect-to-https"
    compress               = true

    min_ttl     = 0
    default_ttl = 86400
    max_ttl     = 31536000

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
  }

  ordered_cache_behavior {
    path_pattern     = "/content/immutable/*"
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3Origin"

    viewer_protocol_policy = "redirect-to-https"
    compress               = true

    min_ttl     = 0
    default_ttl = 86400
    max_ttl     = 31536000

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
  }

  ordered_cache_behavior {
    path_pattern     = "/content/*"
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3Origin"

    viewer_protocol_policy = "redirect-to-https"
    compress               = true

    min_ttl     = 0
    default_ttl = 3600
    max_ttl     = 86400

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
  }

  price_class = "PriceClass_200"

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  web_acl_id = aws_wafv2_web_acl.frontend.arn
}

# ------------------------------------------------------------------------------
# Terraform State Backend Resources
# ------------------------------------------------------------------------------

# KMS Key for State Bucket
resource "aws_kms_key" "state" {
  description             = "KMS key for Terraform state S3 bucket"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 service to use key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_kms_alias" "state" {
  name          = "alias/near-frontend-terraform-state"
  target_key_id = aws_kms_key.state.key_id
}

# State S3 Bucket
resource "aws_s3_bucket" "state" {
  bucket = "near-frontend-${var.environment}-terraform-state-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# DynamoDB Table for State Locking
resource "aws_dynamodb_table" "state_lock" {
  name         = "near-frontend-terraform-state"
  billing_mode = "PROVISIONED"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  read_capacity  = 5
  write_capacity = 5

  server_side_encryption {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0.0"
    }
  }
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

# Locals
locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  private_subnet_cidrs = [
    "10.1.0.0/18",
    "10.1.64.0/18",
    "10.1.128.0/18"
  ]

  public_subnet_cidrs = [
    "10.1.192.0/22",
    "10.1.196.0/22",
    "10.1.200.0/22"
  ]

  database_subnet_cidrs = [
    "10.1.208.0/20",
    "10.1.224.0/20",
    "10.1.240.0/20"
  ]

  cache_subnet_cidrs = [
    "10.1.244.0/22",
    "10.1.248.0/22",
    "10.1.252.0/22"
  ]

  internal_subnet_cidrs = [
    "10.1.128.0/20",
    "10.1.144.0/20",
    "10.1.160.0/20"
  ]

  common_tags = {
    "kubernetes.io/cluster/stackx" = "owned"
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block                       = "10.1.0.0/16"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = merge(local.common_tags, {
    Name = "stackx-network"
  })
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "stackx-network-igw"
  })
}

# Egress-Only Internet Gateway
resource "aws_egress_only_internet_gateway" "eigw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "stackx-network-eigw"
  })
}

# Private Subnets
resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  ipv6_cidr_block   = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index)
  availability_zone = local.azs[count.index]

  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name                          = "stackx-network-private-${local.azs[count.index]}"
    "kubernetes.io/role/internal-elb" = "1"
    "karpenter.sh/discovery"      = "stackx"
  })
}

# Public Subnets
resource "aws_subnet" "public" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnet_cidrs[count.index]
  ipv6_cidr_block   = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 3)
  availability_zone = local.azs[count.index]

  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name                      = "stackx-network-public-${local.azs[count.index]}"
    "kubernetes.io/role/elb" = "1"
  })
}

# Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.igw.id
  }

  tags = merge(local.common_tags, {
    Name = "stackx-network-public-rt"
  })
}

# Public Route Table Associations
resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Elastic IPs for NAT Gateways
resource "aws_eip" "nat" {
  count  = 3
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "stackx-network-eip-${local.azs[count.index]}"
  })
}

# NAT Gateways
resource "aws_nat_gateway" "nat" {
  count = 3

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(local.common_tags, {
    Name = "stackx-network-nat-${local.azs[count.index]}"
  })

  depends_on = [aws_internet_gateway.igw]
}

# Private Route Tables (one per AZ)
resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[count.index].id
  }

  route {
    ipv6_cidr_block                = "::/0"
    egress_only_gateway_id         = aws_egress_only_internet_gateway.eigw.id
  }

  tags = merge(local.common_tags, {
    Name = "stackx-network-private-rt-${local.azs[count.index]}"
  })
}

# Private Route Table Associations
resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# S3 Gateway VPC Endpoint
resource "aws_vpc_endpoint" "s3" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.${data.aws_region.current.name}.s3"

  route_table_ids = concat(
    aws_route_table.private[*].id,
    var.enable_database_subnets ? aws_route_table.database[*].id : [],
    var.enable_cache_subnets ? aws_route_table.cache[*].id : [],
    var.enable_internal_subnets ? aws_route_table.internal[*].id : []
  )

  tags = merge(local.common_tags, {
    Name = "stackx-network-s3-endpoint"
  })
}

# Variables for optional tiers
variable "enable_database_subnets" {
  description = "Enable optional database subnet tier"
  type        = bool
  default     = false
}

variable "enable_cache_subnets" {
  description = "Enable optional cache subnet tier"
  type        = bool
  default     = false
}

variable "enable_internal_subnets" {
  description = "Enable optional internal (no internet) subnet tier"
  type        = bool
  default     = false
}

# Database subnet tier
resource "aws_subnet" "database" {
  count = var.enable_database_subnets ? 3 : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.database_subnet_cidrs[count.index]
  ipv6_cidr_block   = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 6)
  availability_zone = local.azs[count.index]

  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name                          = "stackx-network-database-${local.azs[count.index]}"
    "kubernetes.io/role/internal-elb" = "1"
    "karpenter.sh/discovery"      = "stackx"
  })
}

resource "aws_route_table" "database" {
  count = var.enable_database_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  # No default routes (internal only)
  tags = merge(local.common_tags, {
    Name = "stackx-network-database-rt"
  })
}

resource "aws_route_table_association" "database" {
  count = var.enable_database_subnets ? 3 : 0

  subnet_id      = aws_subnet.database[count.index].id
  route_table_id = aws_route_table.database[0].id
}

resource "aws_db_subnet_group" "database" {
  count = var.enable_database_subnets ? 1 : 0

  name        = "stackx-network-database"
  subnet_ids  = aws_subnet.database[*].id
  description = "Database subnet group for stackx-network"

  tags = merge(local.common_tags, {
    Name = "stackx-network-database-subnet-group"
  })
}

# Cache subnet tier
resource "aws_subnet" "cache" {
  count = var.enable_cache_subnets ? 3 : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.cache_subnet_cidrs[count.index]
  ipv6_cidr_block   = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 9)
  availability_zone = local.azs[count.index]

  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name                          = "stackx-network-cache-${local.azs[count.index]}"
    "kubernetes.io/role/internal-elb" = "1"
    "karpenter.sh/discovery"      = "stackx"
  })
}

resource "aws_route_table" "cache" {
  count = var.enable_cache_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  # No default routes (internal only)
  tags = merge(local.common_tags, {
    Name = "stackx-network-cache-rt"
  })
}

resource "aws_route_table_association" "cache" {
  count = var.enable_cache_subnets ? 3 : 0

  subnet_id      = aws_subnet.cache[count.index].id
  route_table_id = aws_route_table.cache[0].id
}

resource "aws_elasticache_subnet_group" "cache" {
  count = var.enable_cache_subnets ? 1 : 0

  name        = "stackx-network-cache"
  subnet_ids  = aws_subnet.cache[*].id
  description = "Cache subnet group for stackx-network"

  tags = merge(local.common_tags, {
    Name = "stackx-network-cache-subnet-group"
  })
}

# Internal (no internet) subnet tier
resource "aws_subnet" "internal" {
  count = var.enable_internal_subnets ? 3 : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.internal_subnet_cidrs[count.index]
  ipv6_cidr_block   = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 12)
  availability_zone = local.azs[count.index]

  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name                          = "stackx-network-internal-${local.azs[count.index]}"
    "kubernetes.io/role/internal-elb" = "1"
    "karpenter.sh/discovery"      = "stackx"
  })
}

resource "aws_route_table" "internal" {
  count = var.enable_internal_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  # No default routes (no internet)
  tags = merge(local.common_tags, {
    Name = "stackx-network-internal-rt"
  })
}

resource "aws_route_table_association" "internal" {
  count = var.enable_internal_subnets ? 3 : 0

  subnet_id      = aws_subnet.internal[count.index].id
  route_table_id = aws_route_table.internal[0].id
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.0.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

resource "random_pet" "suffix" {
  length    = 2
  separator = "-"
}

locals {
  account_id = data.aws_caller_identity.current.account_id

  # Bucket names (unique per deployment via random suffix)
  artefacts_bucket = "benchmark-glue-artefacts-${local.account_id}-${random_pet.suffix.id}"
  staging_bucket   = "benchmark-datalake-staging-${local.account_id}-${random_pet.suffix.id}"
  bronze_bucket    = "benchmark-datalake-bronze-${local.account_id}-${random_pet.suffix.id}"
  silver_bucket    = "benchmark-datalake-silver-${local.account_id}-${random_pet.suffix.id}"
  gold_bucket      = "benchmark-datalake-gold-${local.account_id}-${random_pet.suffix.id}"
  logs_bucket      = "benchmark-datalake-logs-${local.account_id}-${random_pet.suffix.id}"

  # Glue job names (unique per deployment)
  extrai_job_name    = "glue-job-extrai-dados-${random_pet.suffix.id}"
  transforma_job_name = "glue-job-transforma-dados-${random_pet.suffix.id}"
}

data "aws_caller_identity" "current" {}

# KMS Key
resource "aws_kms_key" "datalake" {
  description             = "KMS key for weather datalake encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "datalake" {
  name          = "alias/benchmark/datalake-key-${random_pet.suffix.id}"
  target_key_id = aws_kms_key.datalake.id
}

# S3 Buckets
resource "aws_s3_bucket" "artefacts" {
  bucket = local.artefacts_bucket
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "staging" {
  bucket = local.staging_bucket
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "bronze" {
  bucket = local.bronze_bucket
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "silver" {
  bucket = local.silver_bucket
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "gold" {
  bucket = local.gold_bucket
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "logs" {
  bucket = local.logs_bucket
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

# Versioning (artefacts, bronze, silver, gold)
resource "aws_s3_bucket_versioning" "artefacts" {
  bucket = aws_s3_bucket.artefacts.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "bronze" {
  bucket = aws_s3_bucket.bronze.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "silver" {
  bucket = aws_s3_bucket.silver.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "gold" {
  bucket = aws_s3_bucket.gold.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Public Access Block (all buckets)
resource "aws_s3_bucket_public_access_block" "artefacts" {
  bucket = aws_s3_bucket.artefacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "staging" {
  bucket = aws_s3_bucket.staging.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "bronze" {
  bucket = aws_s3_bucket.bronze.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "silver" {
  bucket = aws_s3_bucket.silver.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "gold" {
  bucket = aws_s3_bucket.gold.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# SSE-KMS Encryption (all buckets)
resource "aws_s3_bucket_server_side_encryption_configuration" "artefacts" {
  bucket = aws_s3_bucket.artefacts.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.datalake.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "staging" {
  bucket = aws_s3_bucket.staging.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.datalake.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "bronze" {
  bucket = aws_s3_bucket.bronze.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.datalake.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "silver" {
  bucket = aws_s3_bucket.silver.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.datalake.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "gold" {
  bucket = aws_s3_bucket.gold.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.datalake.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.datalake.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# Upload Glue scripts and library (empty content to avoid file dependency)
resource "aws_s3_object" "extrai_dados_py" {
  bucket = aws_s3_bucket.artefacts.id
  key    = "extraiDados.py"
  content = ""
}

resource "aws_s3_object" "transforma_dados_py" {
  bucket = aws_s3_bucket.artefacts.id
  key    = "transformaDados.py"
  content = ""
}

resource "aws_s3_object" "lib_zip" {
  bucket = aws_s3_bucket.artefacts.id
  key    = "lib.zip"
  content = ""
}

# Athena Database (unique name, underscores only)
resource "aws_athena_database" "silver" {
  name   = "silver_${replace(random_pet.suffix.id, "-", "_")}"
  bucket = aws_s3_bucket.silver.bucket
  encryption_configuration {
    encryption_option = "SSE_KMS"
    kms_key          = aws_kms_key.datalake.arn
  }
}

# IAM Role for Glue
resource "aws_iam_role" "glue" {
  name = "glue-datalake-role-${random_pet.suffix.id}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "glue.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "glue" {
  name        = "glue-datalake-policy-${random_pet.suffix.id}"
  description = "Policy for Glue jobs to access S3, CloudWatch, Secrets Manager"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "glue:StartJobRun",
          "glue:GetJobRun",
          "glue:BatchStopJobRun",
          "glue:GetJobRuns"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:*"
      },
      {
        Effect = "Allow"
        Action = "secretsmanager:GetSecretValue"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = [
          "arn:aws:s3:::${local.artefacts_bucket}/*",
          "arn:aws:s3:::${local.staging_bucket}/*",
          "arn:aws:s3:::${local.bronze_bucket}/*",
          "arn:aws:s3:::${local.silver_bucket}/*",
          "arn:aws:s3:::${local.gold_bucket}/*",
          "arn:aws:s3:::${local.logs_bucket}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = "s3:ListBucket"
        Resource = [
          "arn:aws:s3:::${local.artefacts_bucket}",
          "arn:aws:s3:::${local.staging_bucket}",
          "arn:aws:s3:::${local.bronze_bucket}",
          "arn:aws:s3:::${local.silver_bucket}",
          "arn:aws:s3:::${local.gold_bucket}",
          "arn:aws:s3:::${local.logs_bucket}"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "glue" {
  role       = aws_iam_role.glue.name
  policy_arn = aws_iam_policy.glue.arn
}

# Glue Jobs
resource "aws_glue_job" "extrai_dados" {
  name     = local.extrai_job_name
  role_arn = aws_iam_role.glue.arn
  glue_version = "4.0"
  worker_type = "G.1X"
  number_of_workers = 20
  max_retries = 0
  timeout = 2880
  command {
    script_location = "s3://${aws_s3_bucket.artefacts.bucket}/extraiDados.py"
    python_version = "3"
  }
  default_arguments = {
    "--TempDir" = "s3://${aws_s3_bucket.logs.bucket}/temp/"
  }
}

resource "aws_glue_job" "transforma_dados" {
  name     = local.transforma_job_name
  role_arn = aws_iam_role.glue.arn
  glue_version = "4.0"
  worker_type = "G.1X"
  number_of_workers = 20
  max_retries = 0
  timeout = 2880
  command {
    script_location = "s3://${aws_s3_bucket.artefacts.bucket}/transformaDados.py"
    python_version = "3"
  }
  default_arguments = {
    "--TempDir"                = "s3://${aws_s3_bucket.logs.bucket}/temp/"
    "--additional-python-modules" = "pandas,requests"
    "--extra-py-files"          = "s3://${aws_s3_bucket.artefacts.bucket}/lib.zip"
    "--datalake-formats"        = "iceberg"
  }
}

# IAM Role for Step Functions
resource "aws_iam_role" "step_functions" {
  name = "step-functions-datalake-role-${random_pet.suffix.id}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "states.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "step_functions" {
  name        = "step-functions-datalake-policy-${random_pet.suffix.id}"
  description = "Policy for Step Functions to start and monitor Glue jobs"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "glue:StartJobRun",
          "glue:GetJobRun"
        ]
        Resource = [
          aws_glue_job.extrai_dados.arn,
          aws_glue_job.transforma_dados.arn
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "step_functions" {
  role       = aws_iam_role.step_functions.name
  policy_arn = aws_iam_policy.step_functions.arn
}

# Step Functions State Machine
resource "aws_sfn_state_machine" "weather_pipeline" {
  name     = "weather-datalake-pipeline-${random_pet.suffix.id}"
  role_arn = aws_iam_role.step_functions.arn
  definition = jsonencode({
    StartAt = "ExtractJob"
    States = {
      ExtractJob = {
        Type = "Task"
        Resource = "arn:aws:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.extrai_dados.name
          Arguments = {
            "--city"          = "Sao Paulo"
            "--staging_bucket" = aws_s3_bucket.staging.bucket
            "--api_key"       = "placeholder-api-key"
          }
        }
        Next = "TransformJob"
      }
      TransformJob = {
        Type = "Task"
        Resource = "arn:aws:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.transforma_dados.name
          Arguments = {
            "--staging_bucket"   = aws_s3_bucket.staging.bucket
            "--bronze_bucket"    = aws_s3_bucket.bronze.bucket
            "--silver_bucket"    = aws_s3_bucket.silver.bucket
            "--translation_key"  = "placeholder-translation-key"
          }
        }
        End = true
      }
    }
  })
}

# IAM Role for EventBridge
resource "aws_iam_role" "eventbridge" {
  name = "eventbridge-datalake-role-${random_pet.suffix.id}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "eventbridge" {
  name        = "eventbridge-datalake-policy-${random_pet.suffix.id}"
  description = "Policy for EventBridge to start Step Functions execution"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "states:StartExecution"
        Resource = aws_sfn_state_machine.weather_pipeline.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eventbridge" {
  role       = aws_iam_role.eventbridge.name
  policy_arn = aws_iam_policy.eventbridge.arn
}

# EventBridge Rule
resource "aws_cloudwatch_event_rule" "hourly" {
  name                = "hourly-weather-pipeline-trigger-${random_pet.suffix.id}"
  schedule_expression = "rate(1 hour)"
}

resource "aws_cloudwatch_event_target" "state_machine" {
  rule     = aws_cloudwatch_event_rule.hourly.name
  target_id = "step-functions"
  arn      = aws_sfn_state_machine.weather_pipeline.arn
  role_arn = aws_iam_role.eventbridge.arn
}

# ------------------------------------------------------------------------------
# Terraform Required Providers
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
    github = {
      source  = "hashicorp/github"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "github_repo_owner" {
  description = "GitHub repository owner (organization or user)"
  type        = string
  default     = "my-org"
}

variable "github_repo_name" {
  description = "GitHub repository name"
  type        = string
  default     = "my-repo"
}

variable "github_branch" {
  description = "GitHub branch to trigger the pipeline"
  type        = string
  default     = "master"
}

variable "codestar_connection_arn" {
  description = "ARN of an existing CodeStar connection. If empty, GitHub v1 (OAuth) is used."
  type        = string
  default     = ""
}

variable "enable_pipeline_notifications" {
  description = "Whether to create an SNS topic and EventBridge notification rule"
  type        = bool
  default     = false
}

variable "enable_artifact_bucket_logging" {
  description = "Whether to enable access logging for the artifact bucket"
  type        = bool
  default     = false
}

# ------------------------------------------------------------------------------
# Data Sources
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# KMS Key
# ------------------------------------------------------------------------------
resource "aws_kms_key" "main" {
  description             = "Customer managed key for S3 bucket encryption"
  key_usage               = "ENCRYPT_DECRYPT"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

resource "aws_kms_alias" "main" {
  name          = "alias/benchmark-cicd-key"
  target_key_id = aws_kms_key.main.id
}

# ------------------------------------------------------------------------------
# Target S3 Bucket (Static Website Files)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "site" {
  bucket = "benchmark-cicd-target-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "site" {
  bucket                  = aws_s3_bucket.site.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "site" {
  bucket = aws_s3_bucket.site.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.main.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "site" {
  bucket = aws_s3_bucket.site.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "site" {
  bucket = aws_s3_bucket.site.id
  policy = data.aws_iam_policy_document.cloudfront_oai.json
}

data "aws_iam_policy_document" "cloudfront_oai" {
  statement {
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [aws_cloudfront_origin_access_identity.site.iam_arn]
    }
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.site.arn}/*"]
  }
}

# ------------------------------------------------------------------------------
# Artifact S3 Bucket
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "artifacts" {
  bucket = "benchmark-cicd-artifacts-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket                  = aws_s3_bucket.artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.main.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id
  policy = data.aws_iam_policy_document.artifacts.json
}

data "aws_iam_policy_document" "artifacts" {
  statement {
    effect = "Deny"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions = ["s3:*"]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*",
    ]
  }
}

# Optional access logging for artifact bucket
resource "aws_s3_bucket_logging" "artifacts" {
  count = var.enable_artifact_bucket_logging ? 1 : 0

  bucket = aws_s3_bucket.artifacts.id

  target_bucket = aws_s3_bucket.artifacts.id
  target_prefix = "access-logs/"
}

# ------------------------------------------------------------------------------
# SSM Parameters
# ------------------------------------------------------------------------------
resource "aws_ssm_parameter" "github_oauth" {
  name        = "/benchmark-cicd/github-oauth-token"
  type        = "SecureString"
  value       = "placeholder-oauth-token"
  overwrite   = true
}

resource "aws_ssm_parameter" "github_webhook_secret" {
  name  = "/benchmark-cicd/github-webhook-secret"
  type  = "SecureString"
  value = "placeholder-webhook-secret"
}

# ------------------------------------------------------------------------------
# WAF Web ACL (CloudFront)
# ------------------------------------------------------------------------------
resource "aws_wafv2_web_acl" "main" {
  name        = "benchmark-cicd-waf"
  scope       = "CLOUDFRONT"
  default_action {
    allow {}
  }
  visibility_config {
    cloudwatch_metrics_enabled = false
    metric_name                = "benchmark-cicd-waf"
    sampled_requests_enabled   = false
  }
}

# ------------------------------------------------------------------------------
# CloudFront Distribution
# ------------------------------------------------------------------------------
resource "aws_cloudfront_origin_access_identity" "site" {
  comment = "OAI for benchmark-cicd site bucket"
}

resource "aws_cloudfront_distribution" "site" {
  enabled         = true
  price_class     = "PriceClass_100"
  web_acl_id      = aws_wafv2_web_acl.main.arn

  origin {
    domain_name = aws_s3_bucket.site.bucket_regional_domain_name
    origin_id   = "S3-${aws_s3_bucket.site.id}"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.site.cloudfront_access_identity_path
    }
  }

  default_cache_behavior {
    target_origin_id       = "S3-${aws_s3_bucket.site.id}"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }
}

# ------------------------------------------------------------------------------
# CodeBuild Project
# ------------------------------------------------------------------------------
resource "aws_codebuild_project" "main" {
  name         = "benchmark-cicd-build"
  description  = "Build project for static website"
  service_role = aws_iam_role.codebuild.arn
  build_timeout = 5

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:5.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "TARGET_BUCKET"
      value = aws_s3_bucket.site.bucket
      type  = "PLAINTEXT"
    }

    environment_variable {
      name  = "CLOUDFRONT_DISTRIBUTION_ID"
      value = aws_cloudfront_distribution.site.id
      type  = "PLAINTEXT"
    }

    environment_variable {
      name  = "INVALIDATION_FLAG"
      value = "true"
      type  = "PLAINTEXT"
    }
  }

  source {
    type = "CODEPIPELINE"
    buildspec = <<-BUILDSPEC
version: 0.2
phases:
  build:
    commands:
      - echo "Build commands placeholder"
BUILDSPEC
  }
}

# ------------------------------------------------------------------------------
# CodeBuild IAM Role and Policy
# ------------------------------------------------------------------------------
resource "aws_iam_role" "codebuild" {
  name               = "benchmark-cicd-codebuild-role"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume.json
}

data "aws_iam_policy_document" "codebuild_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy" "codebuild" {
  role   = aws_iam_role.codebuild.id
  policy = data.aws_iam_policy_document.codebuild.json
}

data "aws_iam_policy_document" "codebuild" {
  statement {
    sid    = "Logs"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = ["arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/codebuild/*"]
  }

  statement {
    sid    = "S3"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]
    resources = [
      aws_s3_bucket.site.arn,
      "${aws_s3_bucket.site.arn}/*",
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*",
    ]
  }

  statement {
    sid    = "KMS"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]
    resources = [aws_kms_key.main.arn]
  }

  statement {
    sid    = "CloudFront"
    effect = "Allow"
    actions = [
      "cloudfront:CreateInvalidation",
    ]
    resources = [aws_cloudfront_distribution.site.arn]
  }

  statement {
    sid    = "SSM"
    effect = "Allow"
    actions = [
      "ssm:GetParameter",
    ]
    resources = [
      aws_ssm_parameter.github_oauth.arn,
      aws_ssm_parameter.github_webhook_secret.arn,
    ]
  }
}

# ------------------------------------------------------------------------------
# CodePipeline
# ------------------------------------------------------------------------------
resource "aws_codepipeline" "main" {
  name     = "benchmark-cicd-pipeline"
  role_arn = aws_iam_role.codepipeline.arn

  artifact_store {
    location = aws_s3_bucket.artifacts.id
    type     = "S3"
  }

  stage {
    name = "Source"

    action {
      name             = "Source"
      category         = "Source"
      owner            = var.codestar_connection_arn == "" ? "ThirdParty" : "AWS"
      provider         = var.codestar_connection_arn == "" ? "GitHub" : "CodeStarSourceConnection"
      version          = "1"
      output_artifacts = ["source_output"]

      configuration = var.codestar_connection_arn == "" ? {
        Owner      = var.github_repo_owner
        Repo       = var.github_repo_name
        Branch     = var.github_branch
        OAuthToken = "arn:aws:ssm:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:parameter/benchmark-cicd/github-oauth-token"
      } : {
        FullRepositoryId = "${var.github_repo_owner}/${var.github_repo_name}"
        BranchName       = var.github_branch
        ConnectionArn    = var.codestar_connection_arn
      }
    }
  }

  stage {
    name = "Build"

    action {
      name             = "Build"
      category         = "Build"
      owner            = "AWS"
      provider         = "CodeBuild"
      version          = "1"
      input_artifacts  = ["source_output"]
      output_artifacts = ["build_output"]

      configuration = {
        ProjectName = aws_codebuild_project.main.name
      }
    }
  }
}

# ------------------------------------------------------------------------------
# CodePipeline Webhook (AWS side)
# ------------------------------------------------------------------------------
resource "aws_codepipeline_webhook" "github" {
  name           = "benchmark-cicd-webhook"
  authentication = "GITHUB_HMAC"

  authentication_configuration {
    secret_token = aws_ssm_parameter.github_webhook_secret.value
  }

  target_action  = "Source"
  target_pipeline = aws_codepipeline.main.name

  filter {
    json_path    = "$.ref"
    match_equals = "refs/heads/${var.github_branch}"
  }
}

# ------------------------------------------------------------------------------
# CodePipeline IAM Role and Policy
# ------------------------------------------------------------------------------
resource "aws_iam_role" "codepipeline" {
  name               = "benchmark-cicd-codepipeline-role"
  assume_role_policy = data.aws_iam_policy_document.codepipeline_assume.json
}

data "aws_iam_policy_document" "codepipeline_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codepipeline.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy" "codepipeline" {
  role   = aws_iam_role.codepipeline.id
  policy = data.aws_iam_policy_document.codepipeline.json
}

data "aws_iam_policy_document" "codepipeline" {
  statement {
    sid    = "S3"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]
    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*",
    ]
  }

  statement {
    sid    = "KMS"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]
    resources = [aws_kms_key.main.arn]
  }

  statement {
    sid    = "CodeBuild"
    effect = "Allow"
    actions = [
      "codebuild:StartBuild",
    ]
    resources = [aws_codebuild_project.main.arn]
  }

  statement {
    sid    = "PassRole"
    effect = "Allow"
    actions = [
      "iam:PassRole",
    ]
    resources = [aws_iam_role.codebuild.arn]
  }

  dynamic "statement" {
    for_each = var.codestar_connection_arn == "" ? [] : [1]
    content {
      sid    = "CodeStarConnection"
      effect = "Allow"
      actions = [
        "codestar-connections:UseConnection",
      ]
      resources = [var.codestar_connection_arn]
    }
  }
}

# ------------------------------------------------------------------------------
# Optional Pipeline Notifications (EventBridge + SNS)
# ------------------------------------------------------------------------------
resource "aws_sns_topic" "pipeline_notifications" {
  count = var.enable_pipeline_notifications ? 1 : 0
  name  = "benchmark-cicd-notifications"
}

resource "aws_sns_topic_policy" "pipeline_notifications" {
  count = var.enable_pipeline_notifications ? 1 : 0
  arn   = aws_sns_topic.pipeline_notifications[0].arn
  policy = data.aws_iam_policy_document.sns_pipeline_notifications[0].json
}

data "aws_iam_policy_document" "sns_pipeline_notifications" {
  count = var.enable_pipeline_notifications ? 1 : 0
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
    actions = ["SNS:Publish"]
    resources = [aws_sns_topic.pipeline_notifications[0].arn]
  }
}

resource "aws_cloudwatch_event_rule" "pipeline_notifications" {
  count = var.enable_pipeline_notifications ? 1 : 0
  name  = "benchmark-cicd-pipeline-state-change"
  event_pattern = jsonencode({
    source      = ["aws.codepipeline"]
    detail-type = ["CodePipeline Pipeline Execution State Change"]
    resources   = [aws_codepipeline.main.arn]
  })
}

resource "aws_cloudwatch_event_target" "pipeline_notifications" {
  count = var.enable_pipeline_notifications ? 1 : 0
  rule  = aws_cloudwatch_event_rule.pipeline_notifications[0].name
  arn   = aws_sns_topic.pipeline_notifications[0].arn
}

variable "create" {
  description = "Whether to create all resources. Set to false to use the module as a no-op."
  type        = bool
  default     = true
}

variable "vpc_name" {
  description = "Name tag for the VPC."
  type        = string
  default     = "main"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnets" {
  description = <<-EOT
    List of subnet definitions. Each element is an object with:
    - name       : (string) unique name for this subnet group.
    - class      : (string) one of "public", "private", or "intra".
    - database   : (optional bool) if true, a DB subnet group is created.
    - elasticache: (optional bool) if true, an ElastiCache subnet group is created.
  EOT
  type = list(object({
    name        = string
    class       = string
    database    = optional(bool, false)
    elasticache = optional(bool, false)
  }))
  default = []
  validation {
    condition = alltrue([
      for s in var.subnets : contains(["public", "private", "intra"], s.class)
    ])
    error_message = "Each subnet definition must have class one of 'public', 'private', or 'intra'."
  }
}

variable "nat_gateway_count" {
  description = "Number of NAT gateways to create. Can be 1 (shared) or 'per_az' (one per AZ with a public subnet)."
  type        = any
  default     = 1
  validation {
    condition = var.nat_gateway_count == 1 || var.nat_gateway_count == "per_az"
    error_message = "nat_gateway_count must be either 1 or 'per_az'."
  }
}

variable "tags" {
  description = "A map of tags to apply to all resources."
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_names = data.aws_availability_zones.available.names
  az_count = length(local.az_names)

  # Determine if any public or private subnets exist
  has_public  = var.create && length([for d in var.subnets : d if d.class == "public"]) > 0
  has_private = var.create && length([for d in var.subnets : d if d.class == "private"]) > 0

  # Expand each subnet definition into a map of key -> {def, az, index}
  subnet_keys = flatten([
    for def_idx, def in var.subnets : [
      for az_idx, az in local.az_names : {
        key     = "${def.name}-${az}"
        def_idx = def_idx
        az_idx  = az_idx
        def     = def
        az      = az
      }
    ]
  ])

  # Map of subnet key to its full object for for_each
  subnet_map = { for sk in local.subnet_keys : sk.key => sk }

  # Determine NAT gateway placement
  # Find AZs that have at least one public subnet definition
  public_azs = distinct(flatten([
    for def in var.subnets : [
      for az_idx, az in local.az_names : az if def.class == "public"
    ]
  ]))
  nat_gateway_azs = var.nat_gateway_count == 1 ? (length(local.public_azs) > 0 ? [local.public_azs[0]] : []) : local.public_azs
}

# VPC – always created when var.create is true
resource "aws_vpc" "this" {
  count = var.create ? 1 : 0

  cidr_block           = var.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = false

  tags = merge(var.tags, { Name = var.vpc_name })

  lifecycle {
    prevent_destroy = true
  }
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  count = local.has_public ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, { Name = "${var.vpc_name}-igw" })
}

# Elastic IPs for NAT Gateways
resource "aws_eip" "nat" {
  for_each = local.has_private ? toset(local.nat_gateway_azs) : toset([])

  domain = "vpc"

  tags = merge(var.tags, { Name = "${var.vpc_name}-nat-eip-${each.key}" })
}

# NAT Gateways
resource "aws_nat_gateway" "nat" {
  for_each = local.has_private ? toset(local.nat_gateway_azs) : toset([])

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = [for sk in local.subnet_keys : aws_subnet.this[sk.key].id if sk.def.class == "public" && sk.az == each.key][0]

  tags = merge(var.tags, { Name = "${var.vpc_name}-nat-${each.key}" })
}

# Subnets (one per AZ per definition)
resource "aws_subnet" "this" {
  for_each = var.create ? local.subnet_map : {}

  vpc_id            = aws_vpc.this[0].id
  availability_zone = each.value.az
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, each.value.def_idx * local.az_count + each.value.az_idx)

  tags = merge(var.tags, {
    Name      = "${each.value.def.name}-${each.value.az}"
    SubnetClass = each.value.def.class
  })
}

# Public route table
resource "aws_route_table" "public" {
  count = local.has_public ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw[0].id
  }

  tags = merge(var.tags, { Name = "${var.vpc_name}-public" })
}

# Private route tables (one per NAT gateway)
resource "aws_route_table" "private" {
  for_each = local.has_private ? toset(local.nat_gateway_azs) : toset([])

  vpc_id = aws_vpc.this[0].id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[each.key].id
  }

  tags = merge(var.tags, { Name = "${var.vpc_name}-private-${each.key}" })
}

# Intra route table (local only, no default route)
resource "aws_route_table" "intra" {
  count = var.create && length([for d in var.subnets : d if d.class == "intra"]) > 0 ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, { Name = "${var.vpc_name}-intra" })
}

# Route table associations
resource "aws_route_table_association" "public" {
  for_each = var.create ? {
    for sk in local.subnet_keys : sk.key => sk if sk.def.class == "public"
  } : {}

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table_association" "private" {
  for_each = var.create ? {
    for sk in local.subnet_keys : sk.key => sk if sk.def.class == "private"
  } : {}

  subnet_id      = aws_subnet.this[each.key].id
  # Route table per AZ
  route_table_id = aws_route_table.private[each.value.az].id
}

resource "aws_route_table_association" "intra" {
  for_each = var.create ? {
    for sk in local.subnet_keys : sk.key => sk if sk.def.class == "intra"
  } : {}

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.intra[0].id
}

# DB subnet groups
resource "aws_db_subnet_group" "this" {
  for_each = var.create ? {
    for def in var.subnets : def.name => def if def.database
  } : {}

  name       = "${var.vpc_name}-${each.key}-db"
  subnet_ids = [
    for sk in local.subnet_keys : aws_subnet.this[sk.key].id if sk.def.name == each.key
  ]

  tags = merge(var.tags, { Name = "${var.vpc_name}-${each.key}-db" })

  lifecycle {
    prevent_destroy = true
  }
}

# ElastiCache subnet groups
resource "aws_elasticache_subnet_group" "this" {
  for_each = var.create ? {
    for def in var.subnets : def.name => def if def.elasticache
  } : {}

  name       = "${var.vpc_name}-${each.key}-elasticache"
  subnet_ids = [
    for sk in local.subnet_keys : aws_subnet.this[sk.key].id if sk.def.name == each.key
  ]

  tags = merge(var.tags, { Name = "${var.vpc_name}-${each.key}-elasticache" })

  lifecycle {
    prevent_destroy = true
  }
}

# Outputs
output "vpc_id" {
  description = "The ID of the VPC."
  value       = var.create ? aws_vpc.this[0].id : null
}

output "subnet_ids" {
  description = "Map of subnet definition name to map of AZ to subnet ID."
  value = var.create ? {
    for def in var.subnets : def.name => {
      for sk in local.subnet_keys : sk.az => aws_subnet.this[sk.key].id if sk.def.name == def.name
    }
  } : {}
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_iam_policy" "ssm_managed_instance_core" {
  name = "AmazonSSMManagedInstanceCore"
}

resource "aws_iam_role" "ec2_ssm_association" {
  name = "ec2-ssm-association"
  assume_role_policy = jsonencode({
