data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

variable "enable_ssm_automation_logging_and_document_sharing" {
  type        = bool
  default     = true
  description = "Single flag to enable SSM Automation logging to CloudWatch and disable public document sharing."
}

locals {
  log_group_name = "/aws/ssm/automation/executeScript"
}

resource "null_resource" "ensure_log_group_absent" {
  provisioner "local-exec" {
    command = "aws logs delete-log-group --log-group-name ${local.log_group_name} --region ${data.aws_region.current.name} 2>/dev/null || true"
  }
}

resource "aws_cloudwatch_log_group" "ssm_automation_logs" {
  name              = local.log_group_name
  retention_in_days = 14

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [null_resource.ensure_log_group_absent]
}

resource "null_resource" "ssm_automation_logging" {
  count = var.enable_ssm_automation_logging_and_document_sharing ? 1 : 0

  provisioner "local-exec" {
    command = <<EOF
      for i in 1 2 3; do
        aws ssm update-service-setting \
          --setting-id arn:aws:ssm:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:servicesetting/ssm:automation/executeScript \
          --setting-value ${aws_cloudwatch_log_group.ssm_automation_logs.arn} \
          --region ${data.aws_region.current.name} && break
        echo "Retry $i failed, sleeping 5..."
        sleep 5
      done
    EOF
  }

  depends_on = [aws_cloudwatch_log_group.ssm_automation_logs]
}

resource "null_resource" "ssm_disable_public_sharing" {
  count = var.enable_ssm_automation_logging_and_document_sharing ? 1 : 0

  provisioner "local-exec" {
    command = <<EOF
      for i in 1 2 3; do
        aws ssm update-service-setting \
          --setting-id arn:aws:ssm:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:servicesetting/ssm:document/public-sharing \
          --setting-value Disable \
          --region ${data.aws_region.current.name} && break
        echo "Retry $i failed, sleeping 5..."
        sleep 5
      done
    EOF
  }
}

