  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# IAM role for creating DynamoDB backups
resource "aws_iam_role" "create_ddb_backup_role" {
  name = "create_ddb_backup_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM policy for creating DynamoDB backups
resource "aws_iam_policy" "create_ddb_backup_policy" {
  name        = "create_ddb_backup_policy"
  description = "Allows creation of DynamoDB backups"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "dynamodb:CreateBackup"
        Resource = "*"
      }
    ]
  })
}

# Attach create backup policy to create backup role
resource "aws_iam_role_policy_attachment" "create_ddb_backup_attach" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.create_ddb_backup_policy.arn
}

# IAM role for removing DynamoDB backups
resource "aws_iam_role" "remove_ddb_backup_role" {
  name = "remove_ddb_backup_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM policy for listing and deleting DynamoDB backups
resource "aws_iam_policy" "remove_ddb_backup_policy" {
  name        = "remove_ddb_backup_policy"
  description = "Allows listing and deletion of DynamoDB backups"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "dynamodb:ListBackups",
          "dynamodb:DeleteBackup"
        ]
        Resource = "*"
      }
    ]
  })
}

# Attach remove backup policy to remove backup role
resource "aws_iam_role_policy_attachment" "remove_ddb_backup_attach" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.remove_ddb_backup_policy.arn
}

# Shared customer-managed policy for Lambda CloudWatch Logs
resource "aws_iam_policy" "lambda_logging" {
  name        = "lambda_logging"
  description = "Allows Lambda to write logs to CloudWatch Logs"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

# Attach lambda_logging policy to create backup role
resource "aws_iam_role_policy_attachment" "lambda_logging_create" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

# Attach lambda_logging policy to remove backup role
resource "aws_iam_role_policy_attachment" "lambda_logging_remove" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

# Outputs
output "create_ddb_backup_role_arn" {
  description = "ARN of the IAM role for creating DynamoDB backups"
  value       = aws_iam_role.create_ddb_backup_role.arn
}

output "remove_ddb_backup_role_arn" {
  description = "ARN of the IAM role for removing DynamoDB backups"
  value       = aws_iam_role.remove_ddb_backup_role.arn
}

