terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0, != 4.4.2"
    }
  }
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default = {
    Terraform   = "true"
    Environment = "dev"
  }
}

variable "github_actions_extra_thumbprints" {
  description = "Additional SHA‑1 thumbprints published by GitHub to combine with the dynamic root CA thumbprint"
  type        = list(string)
  default = [
    "6938fd4d98bab9fa6a959e0bca2f9b8f0c7f3b4c",
    "1c58a3a8518e8759b7c2e8c7b4c5e6f7a8b9c0d1",
  ]
}

variable "github_iam_roles" {
  description = "List of GitHub‑federated IAM roles to create (empty by default)"
  type = list(object({
    role_name       = string
    repo_org        = string
    repo_name       = string
    branch_condition = optional(string) # e.g., "main"
    policy_arns     = list(string)      # ARNs of IAM policies to attach
  }))
  default = []
}

data "tls_certificate" "github_actions" {
  url = "https://token.actions.githubusercontent.com"
}

locals {
  root_ca_thumbprint = element(
    data.tls_certificate.github_actions.certificates[*].sha1_fingerprint,
    length(data.tls_certificate.github_actions.certificates) - 1
  )

  thumbprint_list = concat(
    [local.root_ca_thumbprint],
    var.github_actions_extra_thumbprints
  )

  role_policy_attachments = flatten([
    for role in var.github_iam_roles : [
      for policy_arn in role.policy_arns : {
        role_name  = role.role_name
        policy_arn = policy_arn
      }
    ]
  ])
}

resource "aws_iam_openid_connect_provider" "github_actions" {
  url            = "https://token.actions.githubusercontent.com"
  client_id_list = ["sts.amazonaws.com"]
  thumbprint_list = local.thumbprint_list

  tags = var.tags
}

resource "aws_iam_role" "github_actions" {
  for_each = { for r in var.github_iam_roles : r.role_name => r }

  name               = each.value.role_name
  assume_role_policy = data.aws_iam_policy_document.assume_role[each.key].json

  tags = var.tags
}

data "aws_iam_policy_document" "assume_role" {
  for_each = { for r in var.github_iam_roles : r.role_name => r }

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github_actions.arn]
    }
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }
    condition {
      test     = each.value.branch_condition != null ? "StringEquals" : "StringLike"
      variable = "token.actions.githubusercontent.com:sub"
      values = each.value.branch_condition != null ? [
        "repo:${each.value.repo_org}/${each.value.repo_name}:ref:refs/heads/${each.value.branch_condition}"
      ] : [
        "repo:${each.value.repo_org}/${each.value.repo_name}:*"
      ]
    }
  }
}

resource "aws_iam_role_policy_attachment" "github_actions" {
  for_each = { for idx, att in local.role_policy_attachments : idx => att }

  role       = each.value.role_name
  policy_arn = each.value.policy_arn
}

