resource "aws_vpc" "dev" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "dev"
    Environment = "dev"
  }
}

resource "aws_vpc" "test" {
  cidr_block           = "172.24.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "test"
    Environment = "test"
  }
}

# Internet Gateways
resource "aws_internet_gateway" "dev" {
  vpc_id = aws_vpc.dev.id

  tags = {
    Name        = "dev-igw"
    Environment = "dev"
  }
}

resource "aws_internet_gateway" "test" {
  vpc_id = aws_vpc.test.id

  tags = {
    Name        = "test-igw"
    Environment = "test"
  }
}

# Subnets for dev VPC
resource "aws_subnet" "dev_public" {
  count = 2

  vpc_id            = aws_vpc.dev.id
  cidr_block        = cidrsubnet(aws_vpc.dev.cidr_block, 8, 101 + count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name        = "dev-public-${count.index + 1}"
    Environment = "dev"
    Type        = "public"
  }
}

resource "aws_subnet" "dev_private" {
  count = 2

  vpc_id            = aws_vpc.dev.id
  cidr_block        = cidrsubnet(aws_vpc.dev.cidr_block, 8, 1 + count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name        = "dev-private-${count.index + 1}"
    Environment = "dev"
    Type        = "private"
  }
}

# Subnets for test VPC
resource "aws_subnet" "test_public" {
  count = 2

  vpc_id            = aws_vpc.test.id
  cidr_block        = cidrsubnet(aws_vpc.test.cidr_block, 8, 101 + count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name        = "test-public-${count.index + 1}"
    Environment = "test"
    Type        = "public"
  }
}

resource "aws_subnet" "test_private" {
  count = 2

  vpc_id            = aws_vpc.test.id
  cidr_block        = cidrsubnet(aws_vpc.test.cidr_block, 8, 1 + count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name        = "test-private-${count.index + 1}"
    Environment = "test"
    Type        = "private"
  }
}

# VPC Peering Connection
resource "aws_vpc_peering_connection" "dev_test" {
  vpc_id      = aws_vpc.dev.id
  peer_vpc_id = aws_vpc.test.id
  auto_accept = true

  accepter {
    allow_remote_vpc_dns_resolution = true
  }

  requester {
    allow_remote_vpc_dns_resolution = true
  }

  tags = {
    Name = "dev-test-vpc-peer"
  }
}

# Route Tables
resource "aws_route_table" "dev_public" {
  vpc_id = aws_vpc.dev.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.dev.id
  }

  route {
    cidr_block                = aws_vpc.test.cidr_block
    vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
  }

  tags = {
    Name        = "dev-public-rt"
    Environment = "dev"
    Type        = "public"
  }
}

resource "aws_route_table" "dev_private" {
  vpc_id = aws_vpc.dev.id

  route {
    cidr_block                = aws_vpc.test.cidr_block
    vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
  }

  tags = {
    Name        = "dev-private-rt"
    Environment = "dev"
    Type        = "private"
  }
}

resource "aws_route_table" "test_public" {
  vpc_id = aws_vpc.test.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.test.id
  }

  route {
    cidr_block                = aws_vpc.dev.cidr_block
    vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
  }

  tags = {
    Name        = "test-public-rt"
    Environment = "test"
    Type        = "public"
  }
}

resource "aws_route_table" "test_private" {
  vpc_id = aws_vpc.test.id

  route {
    cidr_block                = aws_vpc.dev.cidr_block
    vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
  }

  tags = {
    Name        = "test-private-rt"
    Environment = "test"
    Type        = "private"
  }
}

# Route Table Associations
resource "aws_route_table_association" "dev_public" {
  count = 2

  subnet_id      = aws_subnet.dev_public[count.index].id
  route_table_id = aws_route_table.dev_public.id
}

resource "aws_route_table_association" "dev_private" {
  count = 2

  subnet_id      = aws_subnet.dev_private[count.index].id
  route_table_id = aws_route_table.dev_private.id
}

resource "aws_route_table_association" "test_public" {
  count = 2

  subnet_id      = aws_subnet.test_public[count.index].id
  route_table_id = aws_route_table.test_public.id
}

resource "aws_route_table_association" "test_private" {
  count = 2

  subnet_id      = aws_subnet.test_private[count.index].id
  route_table_id = aws_route_table.test_private.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.84.0"
    }
  }
}

# IAM roles for EC2
resource "aws_iam_role" "test_role" {
  name               = "test-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

resource "aws_iam_role" "test_role2" {
  name               = "test-role2"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

# IAM policies allowing ec2:Describe*
resource "aws_iam_policy" "test_policy" {
  name   = "test-policy"
  policy = data.aws_iam_policy_document.ec2_describe.json
}

resource "aws_iam_policy" "test_policy2" {
  name   = "test-policy2"
  policy = data.aws_iam_policy_document.ec2_describe.json
}

resource "aws_iam_policy" "test_policy3" {
  name   = "test-policy3"
  policy = data.aws_iam_policy_document.ec2_describe.json
}

# Policy attachments for test_policy
resource "aws_iam_role_policy_attachment" "test_policy_role" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.test_policy.arn
}

resource "aws_iam_role_policy_attachment" "test_policy_role2" {
  role       = aws_iam_role.test_role2.name
  policy_arn = aws_iam_policy.test_policy.arn
}

# Policy attachments for test_policy2
resource "aws_iam_role_policy_attachment" "test_policy2_role" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.test_policy2.arn
}

resource "aws_iam_role_policy_attachment" "test_policy2_role2" {
  role       = aws_iam_role.test_role2.name
  policy_arn = aws_iam_policy.test_policy2.arn
}

# Single for_each attachment for test_policy3 to both roles
resource "aws_iam_role_policy_attachment" "test_attachment5" {
  for_each = toset([
    aws_iam_role.test_role.name,
    aws_iam_role.test_role2.name
  ])

  role       = each.value
  policy_arn = aws_iam_policy.test_policy3.arn
}

# Data sources for policy documents
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "ec2_describe" {
  statement {
    actions   = ["ec2:Describe*"]
    resources = ["*"]
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "github_repo_patterns" {
  type        = list(string)
  description = "List of GitHub repository patterns (e.g., ['repo:owner/repo:*']) to allow in the OIDC subject condition. AWS requires at least one pattern; replace the placeholder with actual repository patterns."
  default     = ["repo:placeholder-org/placeholder-repo:*"]
}

resource "aws_iam_openid_connect_provider" "github_actions" {
  url            = "https://token.actions.githubusercontent.com"
  client_id_list = ["sts.amazonaws.com"]
  thumbprint_list = [
    "6938fd4d98bab03faadb97b34396831e3780aea1",
    "1c58a3a8518e8759bf075b76b750d4f2df264fcd"
  ]
}

data "aws_iam_policy_document" "github_actions_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github_actions.arn]
    }
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:iss"
      values   = ["https://token.actions.githubusercontent.com"]
    }
    condition {
      test     = "ForAnyValue:StringLike"
      variable = "token.actions.githubusercontent.com:sub"
      values   = var.github_repo_patterns
    }
  }
}

resource "aws_iam_role" "github_actions_role" {
  name                 = "github-actions-role"
  path                 = "/"
  assume_role_policy   = data.aws_iam_policy_document.github_actions_assume_role.json
  force_detach_policies = true
}

output "github_actions_role_arn" {
  description = "ARN of the IAM role for GitHub Actions"
  value       = aws_iam_role.github_actions_role.arn
}

output "github_actions_role_name" {
  description = "Name of the IAM role for GitHub Actions"
  value       = aws_iam_role.github_actions_role.name
}

output "github_actions_role_path" {
  description = "Path of the IAM role for GitHub Actions"
  value       = aws_iam_role.github_actions_role.path
}

output "github_actions_role_unique_id" {
  description = "Unique ID of the IAM role for GitHub Actions"
  value       = aws_iam_role.github_actions_role.unique_id
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_iam_policy_document" "force_mfa" {
  # Basic account info and password change (no MFA required)
  statement {
    sid    = "AllowViewAccountInfoAndChangePassword"
    effect = "Allow"

    actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:GetAccountSummary",
      "iam:ListAccountAliases",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowManageOwnPasswordAndMFAWithoutMFA"
    effect = "Allow"

    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
    ]

    resources = [
      "arn:aws:iam::*:user/&{aws:username}",
    ]
  }

  # Broader self-inspection and MFA deactivation only when MFA is present
  statement {
    sid    = "AllowSelfInspectionAndMFADeactivationWithMFA"
    effect = "Allow"

    actions = [
      "iam:DeactivateMFADevice",
      "iam:ListVirtualMFADevices",
      "iam:ListMFADevices",
      "iam:GetAccessKeyLastUsed",
      "iam:GetLoginProfile",
      "iam:ListAccessKeys",
      "iam:ListSigningCertificates",
      "iam:ListSSHPublicKeys",
      "iam:ListServiceSpecificCredentials",
    ]

    resources = [
      "arn:aws:iam::*:user/&{aws:username}",
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "managed_force_mfa_policy" {
  name        = "managed-force-mfa-policy"
  path        = "/"
  description = "Allows IAM users to view basic account info, change their own password, and manage their own virtual MFA device. MFA deactivation and broader self-inspection are only permitted when authenticated with MFA."

  policy = data.aws_iam_policy_document.force_mfa.json
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# IAM Groups
resource "aws_iam_group" "billing_group" {
  name = "BillingGroup"
}

resource "aws_iam_group" "admin_group" {
  name = "AdminGroup"
}

resource "aws_iam_group" "support_group" {
  name = "SupportGroup"
}

# IAM Users
resource "aws_iam_user" "billing_user" {
  name          = "Billing"
  force_destroy = true
}

resource "aws_iam_user" "admin_user" {
  name          = "Admin"
  force_destroy = true
}

resource "aws_iam_user" "support_user" {
  name          = "Support"
  force_destroy = true
}

# Custom IAM Policy Documents
data "aws_iam_policy_document" "billing_policy_doc" {
  statement {
    sid    = "BillingReadOnly"
    effect = "Allow"
    actions = [
      "aws-portal:ViewBilling",
      "aws-portal:ViewUsage",
      "budgets:ViewBudget",
      "ce:Describe*",
      "pricing:DescribeServices",
      "pricing:GetProducts"
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "support_policy_doc" {
  statement {
    sid    = "EC2ReadOnly"
    effect = "Allow"
    actions = [
      "ec2:Describe*"
    ]
    resources = ["*"]
  }
  statement {
    sid    = "S3ReadOnly"
    effect = "Allow"
    actions = [
      "s3:ListAllMyBuckets",
      "s3:GetObject"
    ]
    resources = ["*"]
  }
  statement {
    sid    = "CloudWatchReadOnly"
    effect = "Allow"
    actions = [
      "cloudwatch:Describe*",
      "cloudwatch:Get*",
      "cloudwatch:List*"
    ]
    resources = ["*"]
  }
  statement {
    sid    = "RDSReadOnly"
    effect = "Allow"
    actions = [
      "rds:Describe*",
      "rds:List*"
    ]
    resources = ["*"]
  }
}

# Custom IAM Policies
resource "aws_iam_policy" "billing_policy" {
  name        = "BillingPolicy"
  description = "Read-only billing, usage, budget, cost, and pricing policy"
  policy      = data.aws_iam_policy_document.billing_policy_doc.json
}

resource "aws_iam_policy" "support_policy" {
  name        = "SupportPolicy"
  description = "Read-only support policy for EC2, S3, CloudWatch, and RDS"
  policy      = data.aws_iam_policy_document.support_policy_doc.json
}

# Group Policy Attachments
resource "aws_iam_group_policy_attachment" "admin_attach" {
  group      = aws_iam_group.admin_group.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

resource "aws_iam_group_policy_attachment" "billing_attach" {
  group      = aws_iam_group.billing_group.name
  policy_arn = aws_iam_policy.billing_policy.arn
}

resource "aws_iam_group_policy_attachment" "support_attach" {
  group      = aws_iam_group.support_group.name
  policy_arn = aws_iam_policy.support_policy.arn
}

# Group Memberships
resource "aws_iam_group_membership" "billing_membership" {
  group = aws_iam_group.billing_group.name
  users = [aws_iam_user.billing_user.name]
  name  = "billing-group-membership"
}

resource "aws_iam_group_membership" "admin_membership" {
  group = aws_iam_group.admin_group.name
  users = [aws_iam_user.admin_user.name]
  name  = "admin-group-membership"
}

resource "aws_iam_group_membership" "support_membership" {
  group = aws_iam_group.support_group.name
  users = [aws_iam_user.support_user.name]
  name  = "support-group-membership"
}

# Login Profiles (auto-generated 8-character passwords)
resource "aws_iam_user_login_profile" "billing_login_profile" {
  user            = aws_iam_user.billing_user.name
  password_length = 8
}

resource "aws_iam_user_login_profile" "admin_login_profile" {
  user            = aws_iam_user.admin_user.name
  password_length = 8
}

resource "aws_iam_user_login_profile" "support_login_profile" {
  user            = aws_iam_user.support_user.name
  password_length = 8
}

# Outputs
output "billing_username" {
  value = aws_iam_user.billing_user.name
}

output "admin_username" {
  value = aws_iam_user.admin_user.name
}

output "support_username" {
  value = aws_iam_user.support_user.name
}

output "billing_password" {
  value     = aws_iam_user_login_profile.billing_login_profile.password
  sensitive = true
}

output "admin_password" {
  value     = aws_iam_user_login_profile.admin_login_profile.password
  sensitive = true
}

output "support_password" {
  value     = aws_iam_user_login_profile.support_login_profile.password
  sensitive = true
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

resource "random_id" "efs_token" {
  byte_length = 8
}

resource "aws_efs_file_system" "shared_test" {
  creation_token   = random_id.efs_token.hex
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"
  encrypted        = true

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "shared-test-efs"
  }
}

resource "aws_efs_backup_policy" "shared_test" {
  file_system_id = aws_efs_file_system.shared_test.id

  backup_policy {
    status = "ENABLED"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# KMS key for Terraform state bucket encryption
resource "aws_kms_key" "terraform_state" {
  description             = "Customer-managed KMS key for Terraform state bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable root user full access"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Enable S3 service to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "terraform_state" {
  name          = "alias/terraform-state-key"
  target_key_id = aws_kms_key.terraform_state.key_id
}

# KMS key for NLP pipeline S3 bucket (customer-managed key)
resource "aws_kms_key" "nlp_pipeline" {
  description             = "Customer-managed KMS key for NLP pipeline S3 bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable root user full access"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Enable S3 service to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "nlp_pipeline" {
  name          = "alias/nlp-pipeline-key"
  target_key_id = aws_kms_key.nlp_pipeline.key_id
}

# Terraform state S3 bucket
resource "aws_s3_bucket" "terraform_state" {
  bucket = "my-terraform-state-bucket-${data.aws_caller_identity.current.account_id}"
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket                  = aws_s3_bucket.terraform_state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.terraform_state.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# DynamoDB table for Terraform state locking
resource "aws_dynamodb_table" "terraform_locks" {
  name         = "terraform-locks"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"
  attribute {
    name = "LockID"
    type = "S"
  }
  lifecycle {
    prevent_destroy = true
  }
}

# NLP pipeline S3 bucket (unique per account to avoid name collision)
resource "aws_s3_bucket" "nlp_pipeline" {
  bucket = "nlp-pipeline-bucket-${data.aws_caller_identity.current.account_id}"
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "nlp_pipeline" {
  bucket                  = aws_s3_bucket.nlp_pipeline.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "nlp_pipeline" {
  bucket = aws_s3_bucket.nlp_pipeline.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.nlp_pipeline.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# Glue service role
resource "aws_iam_role" "glue_service" {
  name = "glue-service-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "glue.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "glue_managed" {
  role       = aws_iam_role.glue_service.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSGlueServiceRole"
}

resource "aws_iam_role_policy" "glue_s3_access" {
  name = "glue-s3-access"
  role = aws_iam_role.glue_service.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.nlp_pipeline.arn,
          "${aws_s3_bucket.nlp_pipeline.arn}/*"
        ]
      }
    ]
  })
}

# Comprehend service role
resource "aws_iam_role" "comprehend_service" {
  name = "comprehend-service-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "comprehend.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "comprehend_s3_access" {
  name = "comprehend-s3-access"
  role = aws_iam_role.comprehend_service.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.nlp_pipeline.arn,
          "${aws_s3_bucket.nlp_pipeline.arn}/*"
        ]
      }
    ]
  })
}

# DynamoDB table for NLP results
resource "aws_dynamodb_table" "nlp_results" {
  name         = "NLPResults"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"
  attribute {
    name = "id"
    type = "S"
  }
  lifecycle {
    prevent_destroy = true
  }
}

# Step Functions state machine
resource "aws_sfn_state_machine" "example" {
  name     = "YourStateMachineName"
  role_arn = aws_iam_role.step_functions_service.arn
  definition = jsonencode({
    Comment = "Example state machine for NLP pipeline"
    StartAt = "PassState"
    States = {
      PassState = {
        Type     = "Pass"
        End      = true
      }
    }
  })
}

# Lambda execution role
resource "aws_iam_role" "lambda_execution" {
  name = "lambda-execution-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy" "lambda_inline" {
  name = "lambda-custom-permissions"
  role = aws_iam_role.lambda_execution.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.nlp_pipeline.arn,
          "${aws_s3_bucket.nlp_pipeline.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "dynamodb:PutItem",
          "dynamodb:UpdateItem",
          "dynamodb:GetItem",
          "dynamodb:Query",
          "dynamodb:Scan"
        ]
        Resource = aws_dynamodb_table.nlp_results.arn
      },
      {
        Effect = "Allow"
        Action = [
          "states:StartExecution"
        ]
        Resource = aws_sfn_state_machine.example.arn
      }
    ]
  })
}

# Step Functions service role
resource "aws_iam_role" "step_functions_service" {
  name = "step-functions-service-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "states.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "step_functions_inline" {
  name = "step-functions-permissions"
  role = aws_iam_role.step_functions_service.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction"
        ]
        Resource = "arn:aws:lambda:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:function:*"
      },
      {
        Effect = "Allow"
        Action = [
          "glue:StartJobRun"
        ]
        Resource = "arn:aws:glue:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:job/*"
      }
    ]
  })
}

# Import blocks to adopt existing resources into Terraform state
import {
  to = aws_kms_alias.terraform_state
  id = "alias/terraform-state-key"
}

import {
  to = aws_kms_alias.nlp_pipeline
  id = "alias/nlp-pipeline-key"
}

import {
  to = aws_s3_bucket.terraform_state
  id = "my-terraform-state-bucket-${data.aws_caller_identity.current.account_id}"
}

import {
  to = aws_s3_bucket.nlp_pipeline
  id = "nlp-pipeline-bucket-${data.aws_caller_identity.current.account_id}"
}

import {
  to = aws_dynamodb_table.terraform_locks
  id = "terraform-locks"
}

import {
  to = aws_dynamodb_table.nlp_results
  id = "NLPResults"
}

import {
  to = aws_iam_role.glue_service
  id = "glue-service-role"
}

import {
  to = aws_iam_role.comprehend_service
  id = "comprehend-service-role"
}

import {
  to = aws_iam_role.lambda_execution
  id = "lambda-execution-role"
}

import {
  to = aws_iam_role.step_functions_service
  id = "step-functions-service-role"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "6.0.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
  default_tags {
    tags = {
      managedBy   = "terraform"
      application = "demo"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

resource "aws_kms_key" "this" {
  description             = "KMS key for S3 artifact store encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 Service to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = {
    managedBy   = "terraform"
    application = "demo"
  }
}

resource "aws_s3_bucket" "this" {
  bucket        = "demo-artifact-store-${data.aws_caller_identity.current.account_id}"
  force_destroy = true
  tags = {
    managedBy   = "terraform"
    application = "demo"
  }
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "this" {
  bucket = aws_s3_bucket.this.id
  acl    = "private"
  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
  }
}

resource "aws_ecr_repository" "this" {
  name                 = "zenml-kubernetes"
  image_tag_mutability = "IMMUTABLE"
  image_scanning_configuration {
    scan_on_push = true
  }
  tags = {
    managedBy   = "terraform"
    application = "demo"
  }
}

resource "local_file" "zenml_stack" {
  filename = "zenml_stack.yaml"
  content = <<-EOF
zenml_version: "0.12.0"
artifact_store:
  path: s3://${aws_s3_bucket.this.id}
container_registry:
  uri: ${data.aws_caller_identity.current.account_id}.dkr.ecr.${data.aws_region.current.name}.amazonaws.com/${aws_ecr_repository.this.name}
secrets_manager: aws
EOF
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix used to construct resource names."
  default     = "nim"
}

# IAM role for ECS task execution
resource "aws_iam_role" "ecs_task_execution" {
  name = "${var.name_prefix}-ecs_task_execution-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach AWS-managed policy
resource "aws_iam_role_policy_attachment" "ecs_task_execution_policy" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

# Secrets Manager secret for container registry credentials
resource "aws_secretsmanager_secret" "reposecret" {
  name = "${var.name_prefix}-reposecret-"
}

# Store default credential JSON
resource "aws_secretsmanager_secret_version" "reposecret" {
  secret_id = aws_secretsmanager_secret.reposecret.id
  secret_string = jsonencode({
    username = "AWS"
    password = ""
  })
}

# Inline policy to allow reading only that secret
resource "aws_iam_role_policy" "ecs_task_access_secrets" {
  name   = "ECSTaskAccessSecretsPolicy"
  role   = aws_iam_role.ecs_task_execution.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "secretsmanager:GetSecretValue"
        Resource = [
          aws_secretsmanager_secret.reposecret.arn
        ]
      }
    ]
  })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
  required_version = ">= 1.0"
}

variable "organizational_unit_paths" {
  description = "List of slash-delimited OU paths (e.g. ['Engineering/Dev/Backend']). Supports up to five levels of nesting."
  type        = list(string)
  default     = []
}

locals {
  # Expand each path into all its prefixes (including the full path)
  all_prefixes = flatten([
    for path in var.organizational_unit_paths : [
      for i in range(1, length(split("/", path)) + 1) : join("/", slice(split("/", path), 0, i))
    ]
  ])

  # Deduplicate and sort for deterministic ordering
  unique_paths = sort(toset(local.all_prefixes))

  # Build a map of OU attributes keyed by a safe identifier (replace '/' with '_')
  ou_map = {
    for path in local.unique_paths :
    replace(path, "/", "_") => {
      name        = element(split("/", path), length(split("/", path)) - 1)
      path        = path
      parent_path = length(split("/", path)) > 1 ? join("/", slice(split("/", path), 0, length(split("/", path)) - 1)) : null
    }
  }
}

data "aws_organizations_organization" "this" {}

resource "random_id" "deployability_placeholder" {
  keepers = {
    timestamp = timestamp()
  }
  byte_length = 8
}

resource "aws_organizations_organizational_unit" "this" {
  for_each = local.ou_map

  name      = each.value.name
  parent_id = each.value.parent_path == null ? data.aws_organizations_organization.this.roots[0].id : aws_organizations_organizational_unit.this[replace(each.value.parent_path, "/", "_")].id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name           = "swe-vpc"
    ResourceGroup  = "default"
  }
}

resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.main.default_network_acl_id

  ingress {
    rule_no    = 10
    action     = "allow"
    from_port  = 0
    to_port    = 0
    protocol   = "-1"
    cidr_block = "10.0.0.0/16"
  }

  ingress {
    rule_no    = 20
    action     = "deny"
    from_port  = 22
    to_port    = 22
    protocol   = "tcp"
    cidr_block = "0.0.0.0/0"
  }

  ingress {
    rule_no    = 30
    action     = "deny"
    from_port  = 3389
    to_port    = 3389
    protocol   = "tcp"
    cidr_block = "0.0.0.0/0"
  }

  ingress {
    rule_no    = 100
    action     = "allow"
    from_port  = 0
    to_port    = 0
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
  }

  egress {
    rule_no    = 10
    action     = "allow"
    from_port  = 0
    to_port    = 0
    protocol   = "-1"
    cidr_block = "10.0.0.0/16"
  }

  egress {
    rule_no    = 100
    action     = "allow"
    from_port  = 0
    to_port    = 0
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
  }

  tags = {
    Name = "swe-vpc-default_acl"
  }
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  ingress = []
  egress  = []

  tags = {
    Name = "swe-vpc-default_sg"
  }
}

resource "aws_vpc_security_group_ingress_rule" "icmp" {
  security_group_id = aws_default_security_group.default.id
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 8
  to_port           = 0
  ip_protocol       = "icmp"
}

resource "aws_vpc_security_group_ingress_rule" "http" {
  security_group_id = aws_default_security_group.default.id
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  envs = {
    dev = { cidr_prefix = "10.16" }
    rec = { cidr_prefix = "10.32" }
  }

  subnet_types = {
    public_a   = { type = "public",   cidr_suffix = "12.0/24", az_index = 0 }
    public_b   = { type = "public",   cidr_suffix = "11.0/24", az_index = 1 }
    internal_a = { type = "internal", cidr_suffix = "1.0/24",  az_index = 0 }
    internal_b = { type = "internal", cidr_suffix = "2.0/24",  az_index = 1 }
    external_a = { type = "external", cidr_suffix = "5.0/24",  az_index = 0 }
    external_b = { type = "external", cidr_suffix = "6.0/24",  az_index = 1 }
  }

  subnet_map = {
    for pair in setproduct(keys(local.envs), keys(local.subnet_types)) :
    "${pair[0]}_${pair[1]}" => {
      env_key    = pair[0]
      type_key   = pair[1]
      cidr_block = "${local.envs[pair[0]].cidr_prefix}.${local.subnet_types[pair[1]].cidr_suffix}"
      az_index   = local.subnet_types[pair[1]].az_index
      name       = "subnet_${pair[0]}_${local.subnet_types[pair[1]].type}_${substr(pair[1], -1, 1)}"
    }
  }
}

resource "aws_vpc" "this" {
  for_each = local.envs

  cidr_block                       = "${each.value.cidr_prefix}.0.0/16"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name = "vpc_${each.key}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "this" {
  for_each = local.subnet_map

  vpc_id            = aws_vpc.this[each.value.env_key].id
  cidr_block        = each.value.cidr_block
  availability_zone = element(data.aws_availability_zones.available.names, each.value.az_index)

  tags = {
    Name = each.value.name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_internet_gateway" "this" {
  for_each = local.envs

  vpc_id = aws_vpc.this[each.key].id

  tags = {
    Name = "gatway_${each.key}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route" "ipv4_default" {
  for_each = local.envs

  route_table_id         = aws_vpc.this[each.key].main_route_table_id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[each.key].id
}

resource "aws_route" "ipv6_default" {
  for_each = local.envs

  route_table_id              = aws_vpc.this[each.key].main_route_table_id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.this[each.key].id
}

output "vpc_ids" {
  value = { for k, v in aws_vpc.this : k => v.id }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "namespace" {
  description = "Namespace, which is often the organization name or abbreviation"
  type        = string
  default     = "default"
}

variable "stage" {
  description = "Stage, e.g., dev, prod"
  type        = string
  default     = "default"
}

variable "name" {
  description = "Solution name, e.g., guardduty"
  type        = string
  default     = "guardduty"
}

variable "attributes" {
  description = "Additional attributes (e.g., 1)"
  type        = list(string)
  default     = []
}

variable "enable_notifications" {
  description = "Flag to enable EventBridge rule and SNS topic for GuardDuty findings"
  type        = bool
  default     = false
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# Fetch the existing GuardDuty detector (required for import)
data "aws_guardduty_detector" "existing" {}

# Cloud Posse label module for consistent naming and tagging
module "this" {
  source     = "cloudposse/label/null"
  version    = "~> 0.25"
  namespace  = var.namespace
  stage      = var.stage
  name       = var.name
  attributes = var.attributes
}

# GuardDuty detector – imported from the existing detector
resource "aws_guardduty_detector" "this" {
  enable = true
  datasources {
    s3_logs {
      enable = false
    }
  }
  tags = module.this.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Import the existing detector into Terraform state
import {
  to = aws_guardduty_detector.this
  id = data.aws_guardduty_detector.existing.id
}

# Unconditionally created resource to ensure at least one new resource is created
resource "terraform_data" "main" {
  input = "guardduty-detector-imported"
}

# KMS key for SNS topic encryption (conditional)
resource "aws_kms_key" "guardduty" {
  count = var.enable_notifications ? 1 : 0

  description             = "KMS key for GuardDuty SNS topic encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = data.aws_iam_policy_document.kms_key_policy[0].json
  tags = module.this.tags
}

# KMS key policy document
data "aws_iam_policy_document" "kms_key_policy" {
  count = var.enable_notifications ? 1 : 0

  statement {
    sid    = "EnableRootAccountPermissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowSNSViaService"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["sns.${data.aws_region.current.name}.amazonaws.com"]
    }
  }
}

# SNS topic for GuardDuty findings (conditional)
resource "aws_sns_topic" "guardduty" {
  count = var.enable_notifications ? 1 : 0

  name              = "${module.this.id}-guardduty-findings"
  kms_master_key_id = aws_kms_key.guardduty[0].arn
  tags              = module.this.tags
}

# SNS topic policy (conditional)
resource "aws_sns_topic_policy" "guardduty" {
  count = var.enable_notifications ? 1 : 0

  arn    = aws_sns_topic.guardduty[0].arn
  policy = data.aws_iam_policy_document.sns_topic_policy[0].json
}

data "aws_iam_policy_document" "sns_topic_policy" {
  count = var.enable_notifications ? 1 : 0

  statement {
    sid    = "AllowRootAccountToPublish"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.guardduty[0].arn]
  }

  statement {
    sid    = "AllowEventBridgeToPublish"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.guardduty[0].arn]
  }
}

# EventBridge rule for GuardDuty findings (conditional)
resource "aws_cloudwatch_event_rule" "guardduty" {
  count = var.enable_notifications ? 1 : 0

  name        = "${module.this.id}-guardduty-rule"
  description = "Captures GuardDuty findings"
  event_pattern = jsonencode({
    source      = ["aws.guardduty"]
    detail-type = ["GuardDuty Finding"]
  })
  tags = module.this.tags
}

# EventBridge target pointing to SNS topic (conditional)
resource "aws_cloudwatch_event_target" "guardduty" {
  count = var.enable_notifications ? 1 : 0

  rule      = aws_cloudwatch_event_rule.guardduty[0].name
  target_id = "SendToSNS"
  arn       = aws_sns_topic.guardduty[0].arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

resource "random_string" "suffix" {
  length  = 6
  lower   = true
  upper   = false
  numeric = true
  special = false
}

locals {
  prefix = "sudo-backup-${random_string.suffix.result}"
}

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup_role" {
  name               = "${local.prefix}-backup-role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json
}

resource "aws_iam_role_policy_attachment" "backup_service_role" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

data "aws_iam_policy_document" "backup_kms_key" {
  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
  statement {
    sid    = "Allow AWS Backup to use the key"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
      "kms:CreateGrant",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:RetireGrant"
    ]
    resources = ["*"]
  }
}

data "aws_caller_identity" "current" {}

resource "aws_kms_key" "backup_kms" {
  description             = "${local.prefix} KMS key for AWS Backup vault encryption"
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.backup_kms_key.json
  deletion_window_in_days = 7
}

resource "aws_backup_vault" "backup_vault" {
  name        = "${local.prefix}-backup-vault"
  kms_key_arn = aws_kms_key.backup_kms.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_plan" "backup_plan" {
  name = "${local.prefix}-backup-plan"

  rule {
    rule_name         = "${local.prefix}-backup-rule"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = "cron(0 12 * * ? *)"

    recovery_point_tags = {
      Name = local.prefix
    }
  }
}

resource "aws_backup_selection" "backup_selection" {
  name         = "${local.prefix}-backup-selection"
  iam_role_arn = aws_iam_role.backup_role.arn
  plan_id      = aws_backup_plan.backup_plan.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "backup"
    value = "true"
  }
}

# main.tf - Coop Tweets Cognito Infrastructure

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Local values
# ---------------------------------------------------------------------------
locals {
  user_pool_name     = "coop-tweets"
  domain_prefix      = "coop-tweets-domain"
  identity_pool_name = "coop tweets"
  auth_role_name     = "coop-tweets_cognito_auth_role"
  unauth_role_name   = "coop-tweets_cognito_unauth_role"
  auth_policy_name   = "cognito_kibana_auth_coop-tweets"
  unauth_policy_name = "cognito_kibana_unauth_coop-tweets"
}

# ---------------------------------------------------------------------------
# Random suffix for global uniqueness of domain and policies
# ---------------------------------------------------------------------------
resource "random_id" "domain_suffix" {
  byte_length = 4
}

# ---------------------------------------------------------------------------
# Cognito User Pool
# ---------------------------------------------------------------------------
resource "aws_cognito_user_pool" "coop_tweets" {
  name = local.user_pool_name

  admin_create_user_config {
    allow_admin_create_user_only = true
  }

  password_policy {
    minimum_length    = 6
    require_numbers   = true
    require_uppercase = true
    require_symbols   = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Cognito User Pool Domain
# ---------------------------------------------------------------------------
resource "aws_cognito_user_pool_domain" "coop_tweets" {
  domain       = "${local.domain_prefix}-${random_id.domain_suffix.hex}"
  user_pool_id = aws_cognito_user_pool.coop_tweets.id
}

# ---------------------------------------------------------------------------
# Cognito Identity Pool
# ---------------------------------------------------------------------------
resource "aws_cognito_identity_pool" "coop_tweets" {
  identity_pool_name               = local.identity_pool_name
  allow_unauthenticated_identities = false

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# IAM Role for Authenticated Identities
# ---------------------------------------------------------------------------
resource "aws_iam_role" "auth_role" {
  name_prefix = "${local.auth_role_name}-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.coop_tweets.id
          }
        }
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# IAM Role for Unauthenticated Identities
# ---------------------------------------------------------------------------
resource "aws_iam_role" "unauth_role" {
  name_prefix = "${local.unauth_role_name}-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.coop_tweets.id
          }
        }
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Customer-Managed IAM Policy for Authenticated Role
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "auth_policy" {
  name_prefix = "${local.auth_policy_name}-"
  description = "Policy for authenticated Cognito identities of coop-tweets"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "mobileanalytics:PutEvents",
          "cognito-sync:*",
          "cognito-identity:*"
        ]
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Customer-Managed IAM Policy for Unauthenticated Role
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "unauth_policy" {
  name_prefix = "${local.unauth_policy_name}-"
  description = "Policy for unauthenticated Cognito identities of coop-tweets"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "mobileanalytics:PutEvents",
          "cognito-sync:*",
          "cognito-identity:*"
        ]
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Attach Policies to Roles
# ---------------------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "auth_policy_attachment" {
  role       = aws_iam_role.auth_role.name
  policy_arn = aws_iam_policy.auth_policy.arn
}

resource "aws_iam_role_policy_attachment" "unauth_policy_attachment" {
  role       = aws_iam_role.unauth_role.name
  policy_arn = aws_iam_policy.unauth_policy.arn
}

# ---------------------------------------------------------------------------
# Cognito Identity Pool Roles Attachment
# ---------------------------------------------------------------------------
resource "aws_cognito_identity_pool_roles_attachment" "coop_tweets" {
  identity_pool_id = aws_cognito_identity_pool.coop_tweets.id

  roles = {
    "authenticated"   = aws_iam_role.auth_role.arn
    "unauthenticated" = aws_iam_role.unauth_role.arn
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "enable_s3_export" {
  description = "Enable exporting GuardDuty findings to an S3 bucket"
  type        = bool
  default     = false
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

resource "aws_guardduty_detector" "main" {
  enable                       = true
  finding_publishing_frequency = "FIFTEEN_MINUTES"
}

resource "aws_kms_key" "guardduty" {
  description             = "KMS key for GuardDuty findings encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow GuardDuty to use the key"
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Encrypt",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "guardduty" {
  name          = "alias/guardduty"
  target_key_id = aws_kms_key.guardduty.key_id
}

resource "aws_cloudwatch_event_rule" "guardduty_finding_events" {
  name        = "guardduty-finding-events"
  description = "Capture GuardDuty finding events"
  event_pattern = jsonencode({
    source      = ["aws.guardduty"]
    detail-type = ["GuardDuty Finding"]
  })
}

# Conditional resources for S3 export
resource "aws_iam_role" "guardduty_publishing" {
  count = var.enable_s3_export ? 1 : 0
  name  = "guardduty-publishing-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "guardduty_publishing" {
  count = var.enable_s3_export ? 1 : 0
  name  = "guardduty-publishing-policy"
  role  = aws_iam_role.guardduty_publishing[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject"
        ]
        Resource = "${aws_s3_bucket.guardduty_exports[0].arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "kms:GenerateDataKey",
          "kms:Encrypt",
          "kms:Decrypt"
        ]
        Resource = aws_kms_key.guardduty.arn
      }
    ]
  })
}

resource "aws_s3_bucket" "guardduty_exports" {
  count  = var.enable_s3_export ? 1 : 0
  bucket = "guardduty-exports-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "guardduty_exports" {
  count  = var.enable_s3_export ? 1 : 0
  bucket = aws_s3_bucket.guardduty_exports[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "guardduty_exports" {
  count  = var.enable_s3_export ? 1 : 0
  bucket = aws_s3_bucket.guardduty_exports[0].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.guardduty.arn
    }
  }
}

resource "aws_guardduty_publishing_destination" "main" {
  count           = var.enable_s3_export ? 1 : 0
  detector_id     = aws_guardduty_detector.main.id
  destination_arn = aws_s3_bucket.guardduty_exports[0].arn
  kms_key_arn     = aws_kms_key.guardduty.arn

  depends_on = [
    aws_iam_role_policy.guardduty_publishing
  ]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

data "aws_caller_identity" "current" {}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "aws_kms_key" "s3_key" {
  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_s3_bucket" "private" {
  bucket       = "my-private-bucket-${random_id.bucket_suffix.hex}"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "private" {
  bucket = aws_s3_bucket.private.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "private" {
  bucket = aws_s3_bucket.private.id

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = "Disabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "private" {
  bucket = aws_s3_bucket.private.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_key.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_ownership_controls" "private" {
  bucket = aws_s3_bucket.private.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "private" {
  bucket = aws_s3_bucket.private.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.private]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# IAM roles
# ------------------------------------------------------------------------------

resource "aws_iam_role" "billing_full_access" {
  name = "billing-full-access"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "billing_view_access" {
  name = "billing-view-access"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Customer-managed policies for roles
# ------------------------------------------------------------------------------

resource "aws_iam_policy" "billing_full_access" {
  name        = "billing-full-access"
  description = "Grants full access to billing, usage, payment methods, and budgets"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "aws-portal:*",
          "budgets:*",
          "purchase-orders:*",
          "cur:*",
          "consolidatedbilling:*",
          "tax:*",
          "account:*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "billing_view_access" {
  name        = "billing-view-access"
  description = "Grants read-only access to billing, usage, account, payment methods, and budgets"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "aws-portal:View*",
          "budgets:ViewBudget",
          "budgets:Describe*",
          "purchase-orders:View*",
          "account:Get*",
          "account:List*",
          "cur:Describe*"
        ]
        Resource = "*"
      }
    ]
  })
}

# Attach policies to roles

resource "aws_iam_role_policy_attachment" "billing_full_access" {
  role       = aws_iam_role.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access.arn
}

resource "aws_iam_role_policy_attachment" "billing_view_access" {
  role       = aws_iam_role.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access.arn
}

# ------------------------------------------------------------------------------
# IAM groups
# ------------------------------------------------------------------------------

resource "aws_iam_group" "billing_full_access" {
  name = "billing-full-access"
  path = "/"
}

resource "aws_iam_group" "billing_view_access" {
  name = "billing-view-access"
  path = "/"
}

# ------------------------------------------------------------------------------
# Customer-managed policies for groups (allow assuming the matching role)
# ------------------------------------------------------------------------------

resource "aws_iam_policy" "billing_full_access_assume_role" {
  name        = "billing-full-access-assume-role"
  description = "Allows members of the billing-full-access group to assume the billing-full-access role"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.billing_full_access.arn
      }
    ]
  })
}

resource "aws_iam_policy" "billing_view_access_assume_role" {
  name        = "billing-view-access-assume-role"
  description = "Allows members of the billing-view-access group to assume the billing-view-access role"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.billing_view_access.arn
      }
    ]
  })
}

# Attach policies to groups

resource "aws_iam_group_policy_attachment" "billing_full_access" {
  group      = aws_iam_group.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access_assume_role.arn
}

resource "aws_iam_group_policy_attachment" "billing_view_access" {
  group      = aws_iam_group.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access_assume_role.arn
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "billing_full_access_role_arn" {
  value = aws_iam_role.billing_full_access.arn
}

output "billing_view_access_role_arn" {
  value = aws_iam_role.billing_view_access.arn
}

output "billing_full_access_group_arn" {
  value = aws_iam_group.billing_full_access.arn
}

output "billing_view_access_group_arn" {
  value = aws_iam_group.billing_view_access.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.99.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

# Random pet name suffix
resource "random_pet" "suffix" {
  length    = 1
  separator = "-"
}

# Random external ID for SMS role
resource "random_string" "external_id" {
  length  = 16
  upper   = true
  lower   = false
  numeric = false
  special = false
}

# Data sources for current partition, region, and account
data "aws_partition" "current" {}
data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

# Local variables for naming
locals {
  base_name        = "cognito"
  suffix           = random_pet.suffix.id
  user_pool_name   = replace("${local.base_name}-${local.suffix}", "-", "_")
  identity_pool_name = "${local.base_name}-${local.suffix}"
  client_name      = "${local.base_name}-${local.suffix}"
  sms_role_name    = "cognito-sms-role-${local.suffix}"
  auth_role_name   = "cognito-authenticated-role-${local.suffix}"
  unauth_role_name = "cognito-unauthenticated-role-${local.suffix}"
  auth_policy_name = "cognito-authenticated-policy-${local.suffix}"
  unauth_policy_name = "cognito-unauthenticated-policy-${local.suffix}"
}

# IAM role for Cognito SMS sending
resource "aws_iam_role" "cognito_sms" {
  name = local.sms_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cognito-idp.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = random_string.external_id.result
          }
        }
      }
    ]
  })
}

# Policy for SMS role to publish to SNS
resource "aws_iam_role_policy" "cognito_sms_policy" {
  name = "${local.sms_role_name}-policy"
  role = aws_iam_role.cognito_sms.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sns:Publish"
        Resource = "*"
      }
    ]
  })
}

# Cognito User Pool
resource "aws_cognito_user_pool" "main" {
  name = local.user_pool_name

  mfa_configuration = "OFF"
  auto_verified_attributes = ["email"]

  # Standard attributes: email required & immutable, phone optional & immutable
  schema {
    name                = "email"
    attribute_data_type = "String"
    required            = true
    mutable             = false
    developer_only_attribute = false
  }

  schema {
    name                = "phone_number"
    attribute_data_type = "String"
    required            = false
    mutable             = false
    developer_only_attribute = false
  }

  # Custom attributes (all mutable strings except email/phone above)
  schema {
    name                = "profile_user_id"
    attribute_data_type = "String"
    required            = false
    mutable             = true
    developer_only_attribute = false
  }

  schema {
    name                = "profile_email"
    attribute_data_type = "String"
    required            = false
    mutable             = true
    developer_only_attribute = false
  }

  schema {
    name                = "profile_first_name"
    attribute_data_type = "String"
    required            = false
    mutable             = true
    developer_only_attribute = false
  }

  schema {
    name                = "profile_last_name"
    attribute_data_type = "String"
    required            = false
    mutable             = true
    developer_only_attribute = false
  }

  schema {
    name                = "profile_gender"
    attribute_data_type = "String"
    required            = false
    mutable             = true
    developer_only_attribute = false
  }

  schema {
    name                = "profile_age"
    attribute_data_type = "String"
    required            = false
    mutable             = true
    developer_only_attribute = false
  }

  schema {
    name                = "profile_persona"
    attribute_data_type = "String"
    required            = false
    mutable             = true
    developer_only_attribute = false
  }

  # SMS configuration using the IAM role
  sms_configuration {
    external_id    = random_string.external_id.result
    sns_caller_arn = aws_iam_role.cognito_sms.arn
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Cognito User Pool Client (no secret)
resource "aws_cognito_user_pool_client" "client" {
  name         = local.client_name
  user_pool_id = aws_cognito_user_pool.main.id
  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_USER_PASSWORD_AUTH"
  ]

  supported_identity_providers = ["COGNITO"]
}

# Cognito Identity Pool
resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = local.identity_pool_name
  allow_unauthenticated_identities = true

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.client.id
    provider_name           = aws_cognito_user_pool.main.endpoint
    server_side_token_check = false
  }

  lifecycle {
    prevent_destroy = true
  }
}

# IAM roles for identity pool (authenticated and unauthenticated)
# Trust policy: allow Cognito Federated Identities for this pool only
locals {
  identity_pool_arn = "arn:${data.aws_partition.current.partition}:cognito-identity:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:identitypool/${aws_cognito_identity_pool.main.id}"
}

resource "aws_iam_role" "authenticated" {
  name = local.auth_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.main.id
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "unauthenticated" {
  name = local.unauth_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.main.id
          }
        }
      }
    ]
  })
}

# Policy for authenticated role: cognito-identity:* and cognito-sync:* on identity pool and its resources
resource "aws_iam_policy" "authenticated" {
  name = local.auth_policy_name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "cognito-identity:*"
        Resource = local.identity_pool_arn
      },
      {
        Effect   = "Allow"
        Action   = "cognito-sync:*"
        Resource = [
          local.identity_pool_arn,
          "${local.identity_pool_arn}/identity/*"
        ]
      }
    ]
  })
}

# Policy for unauthenticated role: cognito-identity:* on identity pool only
resource "aws_iam_policy" "unauthenticated" {
  name = local.unauth_policy_name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "cognito-identity:*"
        Resource = local.identity_pool_arn
      }
    ]
  })
}

# Attach policies to roles
resource "aws_iam_role_policy_attachment" "authenticated_attach" {
  role       = aws_iam_role.authenticated.name
  policy_arn = aws_iam_policy.authenticated.arn
}

resource "aws_iam_role_policy_attachment" "unauthenticated_attach" {
  role       = aws_iam_role.unauthenticated.name
  policy_arn = aws_iam_policy.unauthenticated.arn
}

# Associate roles with identity pool
resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    "authenticated"   = aws_iam_role.authenticated.arn
    "unauthenticated" = aws_iam_role.unauthenticated.arn
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0, < 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  workspace    = terraform.workspace
  name_prefix  = "${local.workspace}-batch"
  common_tags = {
    Workspace = local.workspace
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_ami" "ecs_optimized" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-ecs-*"]
  }
}

data "aws_iam_policy" "ecs_for_ec2" {
  name = "AmazonEC2ContainerServiceforEC2Role"
}

data "aws_iam_policy" "batch_service" {
  name = "AWSBatchServiceRole"
}

resource "aws_vpc" "main" {
  cidr_block           = "192.168.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge({
    Name = "${local.name_prefix}-vpc"
  }, local.common_tags)
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.10.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge({
    Name = "${local.name_prefix}-public-subnet"
  }, local.common_tags)
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge({
    Name = "${local.name_prefix}-private-subnet"
  }, local.common_tags)
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge({
    Name = "${local.name_prefix}-igw"
  }, local.common_tags)
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge({
    Name = "${local.name_prefix}-eip"
  }, local.common_tags)
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = merge({
    Name = "${local.name_prefix}-nat"
  }, local.common_tags)
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge({
    Name = "${local.name_prefix}-public-rt"
  }, local.common_tags)
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge({
    Name = "${local.name_prefix}-private-rt"
  }, local.common_tags)
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "batch" {
  name_prefix = "${local.name_prefix}-sg-"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge({
    Name = "${local.name_prefix}-sg"
  }, local.common_tags)
}

resource "aws_iam_role" "ecs_instance" {
  name = "${local.name_prefix}-ecs-instance-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "ecs_instance" {
  role       = aws_iam_role.ecs_instance.name
  policy_arn = data.aws_iam_policy.ecs_for_ec2.arn
}

resource "aws_iam_role_policy" "ecs_s3" {
  name = "ecs_s3_policy"
  role = aws_iam_role.ecs_instance.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:List*",
          "s3:Get*"
        ]
        Resource = "arn:aws:s3:::*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "arn:aws:s3:::benchmark-batch-results-${data.aws_caller_identity.current.account_id}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.batch_results.arn
      }
    ]
  })
}

resource "aws_iam_instance_profile" "ecs_instance" {
  name = "${local.name_prefix}-ecs-instance-profile"
  role = aws_iam_role.ecs_instance.name

  tags = local.common_tags
}

resource "aws_iam_role" "batch_service" {
  name = "${local.name_prefix}-service-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "batch.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "batch_service" {
  role       = aws_iam_role.batch_service.name
  policy_arn = data.aws_iam_policy.batch_service.arn
}

resource "aws_kms_key" "batch_results" {
  description             = "${local.workspace}-batch-results-key"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge({
    Name = "${local.name_prefix}-kms-key"
  }, local.common_tags)
}

resource "aws_s3_bucket" "results" {
  bucket        = "benchmark-batch-results-${data.aws_caller_identity.current.account_id}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }

  tags = merge({
    Name = "${local.name_prefix}-bucket"
  }, local.common_tags)
}

resource "aws_s3_bucket_public_access_block" "results" {
  bucket = aws_s3_bucket.results.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "results" {
  bucket = aws_s3_bucket.results.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.batch_results.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "results" {
  bucket = aws_s3_bucket.results.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_batch_compute_environment" "batch" {
  compute_environment_name = "${local.name_prefix}-compute-env"
  type                     = "MANAGED"
  state                    = "ENABLED"
  service_role             = aws_iam_role.batch_service.arn

  compute_resources {
    type               = "EC2"
    allocation_strategy = "BEST_FIT"
    instance_role      = aws_iam_instance_profile.ecs_instance.arn
    instance_type      = ["optimal"]
    image_id           = data.aws_ami.ecs_optimized.id
    min_vcpus          = 0
    max_vcpus          = 4
    desired_vcpus      = 0
    security_group_ids = [aws_security_group.batch.id]
    subnets            = [aws_subnet.private.id]
  }

  tags = merge({
    Name = "${local.name_prefix}-compute-env"
  }, local.common_tags)
}

resource "aws_batch_job_queue" "batch" {
  name     = "${local.name_prefix}-queue"
  state    = "ENABLED"
  priority = 1
  compute_environments = [
    aws_batch_compute_environment.batch.arn
  ]

  tags = merge({
    Name = "${local.name_prefix}-queue"
  }, local.common_tags)
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0, != 6.70.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  bucket_name = "endpoint-backup-${data.aws_caller_identity.current.account_id}"
  kms_key_arn = aws_kms_key.s3_backup.arn
}

resource "aws_kms_key" "s3_backup" {
  description             = "Customer-managed KMS key for endpoint-backup S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_s3_bucket" "endpoint_backup" {
  bucket = local.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_backup.arn
    }
  }
}

resource "aws_s3_bucket_accelerate_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  status = "Suspended"
}

resource "aws_s3_bucket_policy" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  policy = data.aws_iam_policy_document.bucket_policy.json
}

data "aws_iam_policy_document" "bucket_policy" {
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*"
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "DenyTLSVersionBelow1.2"
    effect = "Deny"
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*"
    ]
    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }

  statement {
    sid    = "DenyComplianceLockOver90Days"
    effect = "Deny"
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    actions = [
      "s3:PutObject",
      "s3:PutObjectRetention"
    ]
    resources = ["${aws_s3_bucket.endpoint_backup.arn}/*"]
    condition {
      test     = "StringEquals"
      variable = "s3:object-lock-mode"
      values   = ["COMPLIANCE"]
    }
    condition {
      test     = "DateGreaterThan"
      variable = "s3:object-lock-retain-until-date"
      values   = [timeadd(timestamp(), "2160h")]
    }
  }
}

resource "aws_iam_user" "endpoint_backup" {
  name = "endpoint-backup"
}

resource "aws_iam_policy" "endpoint_backup_bucket_read_write_access" {
  name        = "endpoint-backup-bucket-read-write-access"
  description = "Grants list, read, write, delete, version, retention, and restore access to the endpoint-backup bucket and decrypt/data-key access on the AWS-managed S3 KMS key"
  policy      = data.aws_iam_policy_document.endpoint_backup_iam_policy.json
}

data "aws_iam_policy_document" "endpoint_backup_iam_policy" {
  statement {
    sid = "S3BucketAccess"
    actions = [
      "s3:ListBucket",
      "s3:ListBucketVersions",
      "s3:GetBucketLocation",
      "s3:GetBucketVersioning"
    ]
    resources = [aws_s3_bucket.endpoint_backup.arn]
  }

  statement {
    sid = "S3ObjectAccess"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetObjectTagging",
      "s3:GetObjectRetention",
      "s3:GetObjectLegalHold",
      "s3:PutObject",
      "s3:PutObjectTagging",
      "s3:PutObjectRetention",
      "s3:PutObjectLegalHold",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
      "s3:RestoreObject",
      "s3:ListMultipartUploadParts"
    ]
    resources = ["${aws_s3_bucket.endpoint_backup.arn}/*"]
  }

  statement {
    sid = "KMSAccess"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey"
    ]
    resources = [local.kms_key_arn]
  }
}

resource "aws_iam_user_policy_attachment" "endpoint_backup" {
  user       = aws_iam_user.endpoint_backup.name
  policy_arn = aws_iam_policy.endpoint_backup_bucket_read_write_access.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100"
    }
  }
}

