terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.99.0"
    }
  }
}

locals {
  app_name     = "terraform"
  environment  = "testing"
  vpc_name     = "vpc-terraform-testing"
  az_count     = 3
  public_cidrs = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24"]
  private_cidrs = ["10.0.11.0/24", "10.0.22.0/24", "10.0.33.0/24"]
  common_tags = {
    app         = local.app_name
    environment = local.environment
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = false
  enable_dns_support   = true
  tags = merge(local.common_tags, {
    Name = local.vpc_name
  })
}

resource "aws_subnet" "public" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = merge(local.common_tags, {
    Name = "public-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = merge(local.common_tags, {
    Name = "private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-public-rt"
    Tier = "public"
  })
}

resource "aws_route" "public_default" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"
  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id
  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-nat"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-private-rt"
    Tier = "private"
  })
}

resource "aws_route" "private_default" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main.id
}

resource "aws_route_table_association" "private" {
  count          = local.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_db_subnet_group" "main" {
  name        = "db-subnet-terraform-testing"
  description = "DB subnet group for ${local.app_name} ${local.environment}"
  subnet_ids  = aws_subnet.private[*].id
  tags = merge(local.common_tags, {
    Name = "db-subnet-terraform-testing"
  })
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "default_security_group_id" {
  value = aws_vpc.main.default_security_group_id
}

output "nat_gateway_id" {
  value = aws_nat_gateway.main.id
}

terraform {
  required_version = "~> 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.99.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
  }
}

# CodeCommit repositories for Argo CD GitOps bridge
resource "aws_codecommit_repository" "gitops_apps" {
  repository_name = "gitops-apps"
  description     = "Argo CD applications repository"
}

resource "aws_codecommit_repository" "gitops_platform" {
  repository_name = "gitops-platform"
  description     = "Argo CD platform configuration repository"
}

resource "aws_codecommit_repository" "gitops_addons" {
  repository_name = "gitops-addons"
  description     = "Argo CD add-ons repository"
}

# SSH key pair for the IAM user
resource "tls_private_key" "this" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

# IAM user for GitOps bridge
resource "aws_iam_user" "gitops_bridge_user" {
  name = "gitops-bridge-gitops"
}

# Upload public SSH key to IAM user
resource "aws_iam_user_ssh_key" "this" {
  username   = aws_iam_user.gitops_bridge_user.name
  encoding   = "SSH"
  public_key = tls_private_key.this.public_key_openssh
}

# IAM policy granting Git pull/push access to the three repositories only
data "aws_iam_policy_document" "gitops_bridge" {
  statement {
    actions   = ["codecommit:GitPull", "codecommit:GitPush"]
    resources = [
      aws_codecommit_repository.gitops_apps.arn,
      aws_codecommit_repository.gitops_platform.arn,
      aws_codecommit_repository.gitops_addons.arn,
    ]
  }
}

resource "aws_iam_policy" "gitops_bridge" {
  name        = "gitops-bridge-gitops"
  description = "Policy granting Git pull/push to GitOps repositories"
  policy      = data.aws_iam_policy_document.gitops_bridge.json
}

resource "aws_iam_user_policy_attachment" "this" {
  user       = aws_iam_user.gitops_bridge_user.name
  policy_arn = aws_iam_policy.gitops_bridge.arn
}

# Random suffix for secret name
resource "random_string" "suffix" {
  length  = 5
  special = false
  upper   = false
}

# Secrets Manager secret for private key
resource "aws_secretsmanager_secret" "gitops_key" {
  name = "codecommit-key-${random_string.suffix.result}"
}

resource "aws_secretsmanager_secret_version" "gitops_key" {
  secret_id     = aws_secretsmanager_secret.gitops_key.id
  secret_string = tls_private_key.this.private_key_pem
}

# Write private key to ~/.ssh/gitops_ssh.pem with secure permissions
resource "local_file" "private_key" {
  filename        = pathexpand("~/.ssh/gitops_ssh.pem")
  content         = tls_private_key.this.private_key_pem
  file_permission = "0600"
}

# Write SSH config entry for CodeCommit Git endpoints
resource "local_file" "ssh_config" {
  filename        = pathexpand("~/.ssh/config.d/gitops-codecommit.conf")
  file_permission = "0644"
  content         = <<-EOT
Host git-codecommit.*.amazonaws.com
    IdentityFile ~/.ssh/gitops_ssh.pem
    User ${aws_iam_user_ssh_key.this.ssh_public_key_id}
EOT
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "ssh_public_key" {
  description = "Public key material for SSH key pair. If empty, a temporary key is generated."
  type        = string
  default     = ""
}

variable "extra_ebs_volumes" {
  description = "List of additional EBS volumes to attach to the instance"
  type = list(object({
    size        = number
    device_name = string
  }))
  default = []
}

variable "additional_network_interfaces" {
  description = "List of additional network interfaces to create with Elastic IPs"
  type = list(object({
    subnet_id   = string
    private_ips = optional(list(string))
  }))
  default = []
}

resource "random_string" "suffix" {
  length  = 6
  special = false
  upper   = false
}

resource "tls_private_key" "generated" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "ubuntu" {
  most_recent = true
  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-jammy-22.04-amd64-server-*"]
  }
  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
  owners = ["099720109477"]
}

data "aws_region" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.70.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "benchmark-vpc"
  }
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.70.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false
  tags = {
    Name = "benchmark-subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "benchmark-igw"
  }
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = {
    Name = "benchmark-rt"
  }
}

resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.main.id
}

resource "aws_key_pair" "benchmark" {
  key_name   = "benchmark-d8bc612be4e0-key-${random_string.suffix.result}"
  public_key = var.ssh_public_key != "" ? var.ssh_public_key : tls_private_key.generated.public_key_openssh
}

resource "aws_iam_role" "benchmark" {
  name = "benchmark-instance-role-${random_string.suffix.result}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "benchmark" {
  name = "benchmark-instance-profile-${random_string.suffix.result}"
  role = aws_iam_role.benchmark.name
}

resource "aws_security_group" "benchmark" {
  name        = "benchmark-sg"
  description = "Security group for benchmark instance"
  vpc_id      = aws_vpc.main.id
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
  tags = {
    Name = "benchmark-sg"
  }
}

resource "aws_instance" "benchmark" {
  ami                    = data.aws_ami.ubuntu.id
  instance_type          = "t2.micro"
  subnet_id              = aws_subnet.main.id
  vpc_security_group_ids = [aws_security_group.benchmark.id]
  associate_public_ip_address = true
  iam_instance_profile   = aws_iam_instance_profile.benchmark.name
  key_name               = aws_key_pair.benchmark.key_name
  monitoring             = true
  metadata_options {
    http_tokens = "required"
  }
  root_block_device {
    volume_type = "gp2"
    volume_size = 10
    encrypted   = true
  }
  tags = {
    Name = "benchmark-instance"
  }
}

resource "aws_eip" "benchmark" {
  domain = "vpc"
  tags = {
    Name = "benchmark-eip"
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_eip_association" "benchmark" {
  instance_id   = aws_instance.benchmark.id
  allocation_id = aws_eip.benchmark.id
}

resource "aws_cloudwatch_metric_alarm" "status_check" {
  alarm_name          = "benchmark-status-check-failed"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 5
  metric_name         = "StatusCheckFailed_Instance"
  namespace           = "AWS/EC2"
  period              = 60
  statistic           = "Maximum"
  threshold           = 1
  alarm_description   = "Reboots instance when StatusCheckFailed_Instance >= 1 for 5 consecutive periods"
  alarm_actions       = ["arn:aws:automate:${data.aws_region.current.name}:ec2:reboot"]
  dimensions = {
    InstanceId = aws_instance.benchmark.id
  }
}

resource "aws_ebs_volume" "extra" {
  count = length(var.extra_ebs_volumes)
  availability_zone = data.aws_availability_zones.available.names[0]
  size              = var.extra_ebs_volumes[count.index].size
  type              = "gp2"
  encrypted         = true
  tags = {
    Name = "benchmark-extra-ebs-${count.index}"
  }
}

resource "aws_volume_attachment" "extra" {
  count = length(var.extra_ebs_volumes)
  device_name = var.extra_ebs_volumes[count.index].device_name
  volume_id   = aws_ebs_volume.extra[count.index].id
  instance_id = aws_instance.benchmark.id
}

resource "aws_network_interface" "additional" {
  count = length(var.additional_network_interfaces)
  subnet_id       = var.additional_network_interfaces[count.index].subnet_id
  private_ips     = try(var.additional_network_interfaces[count.index].private_ips, null)
  security_groups = [aws_security_group.benchmark.id]
  tags = {
    Name = "benchmark-eni-${count.index}"
  }
}

resource "aws_eip" "additional" {
  count = length(var.additional_network_interfaces)
  domain = "vpc"
  tags = {
    Name = "benchmark-eip-${count.index}"
  }
}

resource "aws_eip_association" "additional" {
  count = length(var.additional_network_interfaces)
  network_interface_id = aws_network_interface.additional[count.index].id
  allocation_id        = aws_eip.additional[count.index].id
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.80.0"
    }
  }
}

# Variables
variable "src2_region" {
  type    = string
  default = "us-west-2"
}
variable "replica1_region" {
  type    = string
  default = "eu-west-1"
}
variable "replica2_region" {
  type    = string
  default = "ap-southeast-1"
}

# Providers (managed externally, but aliases must be declared for resource references)
provider "aws" {
  alias  = "src1"
  region = "us-east-1"
}
provider "aws" {
  alias  = "src2"
  region = var.src2_region
}
provider "aws" {
  alias  = "replica1"
  region = var.replica1_region
}
provider "aws" {
  alias  = "replica2"
  region = var.replica2_region
}

# Account ID
data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id

  # Source bucket names
  src1_bucket1 = "log1a.veerum-${local.account_id}"
  src1_bucket2 = "log1b.veerum-${local.account_id}"
  src2_bucket1 = "log2a.veerum-${local.account_id}"
  src2_bucket2 = "log2b.veerum-${local.account_id}"

  # Replica bucket names in replica1
  r1_bucket1 = "log1a.veerum-replica1-${local.account_id}"
  r1_bucket2 = "log1b.veerum-replica1-${local.account_id}"
  r1_bucket3 = "log2a.veerum-replica1-${local.account_id}"
  r1_bucket4 = "log2b.veerum-replica1-${local.account_id}"

  # Replica bucket names in replica2
  r2_bucket1 = "log1a.veerum-replica2-${local.account_id}"
  r2_bucket2 = "log1b.veerum-replica2-${local.account_id}"
  r2_bucket3 = "log2a.veerum-replica2-${local.account_id}"
  r2_bucket4 = "log2b.veerum-replica2-${local.account_id}"

  # Maps for bucket names per region
  src1_buckets = {
    b1 = local.src1_bucket1
    b2 = local.src1_bucket2
  }
  src2_buckets = {
    b1 = local.src2_bucket1
    b2 = local.src2_bucket2
  }
  replica1_buckets = {
    r1 = local.r1_bucket1
    r2 = local.r1_bucket2
    r3 = local.r1_bucket3
    r4 = local.r1_bucket4
  }
  replica2_buckets = {
    r1 = local.r2_bucket1
    r2 = local.r2_bucket2
    r3 = local.r2_bucket3
    r4 = local.r2_bucket4
  }

  # All source bucket ARNs (for policy)
  src_bucket_arns = [
    "arn:aws:s3:::${local.src1_bucket1}",
    "arn:aws:s3:::${local.src1_bucket2}",
    "arn:aws:s3:::${local.src2_bucket1}",
    "arn:aws:s3:::${local.src2_bucket2}",
  ]
  src_bucket_arn_objects = [
    "arn:aws:s3:::${local.src1_bucket1}/*",
    "arn:aws:s3:::${local.src1_bucket2}/*",
    "arn:aws:s3:::${local.src2_bucket1}/*",
    "arn:aws:s3:::${local.src2_bucket2}/*",
  ]

  # All replica bucket ARNs (for policy)
  replica_bucket_arns = concat(
    [
      "arn:aws:s3:::${local.r1_bucket1}",
      "arn:aws:s3:::${local.r1_bucket2}",
      "arn:aws:s3:::${local.r1_bucket3}",
      "arn:aws:s3:::${local.r1_bucket4}",
    ],
    [
      "arn:aws:s3:::${local.r2_bucket1}",
      "arn:aws:s3:::${local.r2_bucket2}",
      "arn:aws:s3:::${local.r2_bucket3}",
      "arn:aws:s3:::${local.r2_bucket4}",
    ]
  )
  replica_bucket_arn_objects = [
    for arn in local.replica_bucket_arns : "${arn}/*"
  ]

  # KMS key ARNs
  source_key1_arn = aws_kms_key.source1.arn
  source_key2_arn = aws_kms_key.source2.arn
  replica_key1_arn = aws_kms_key.replica1.arn
  replica_key2_arn = aws_kms_key.replica2.arn
}

# ==================== KMS Keys ====================

resource "aws_kms_key" "source1" {
  provider                = aws.src1
  description             = "Source key 1 for S3 replication"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                 = data.aws_iam_policy_document.kms_source1_policy.json
}
resource "aws_kms_alias" "source1" {
  provider      = aws.src1
  name          = "alias/sourcekey1"
  target_key_id = aws_kms_key.source1.key_id
}

resource "aws_kms_key" "source2" {
  provider                = aws.src2
  description             = "Source key 2 for S3 replication"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                 = data.aws_iam_policy_document.kms_source2_policy.json
}
resource "aws_kms_alias" "source2" {
  provider      = aws.src2
  name          = "alias/sourcekey2"
  target_key_id = aws_kms_key.source2.key_id
}

resource "aws_kms_key" "replica1" {
  provider                = aws.replica1
  description             = "Replica key 1 for S3 replication"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                 = data.aws_iam_policy_document.kms_replica1_policy.json
}
resource "aws_kms_alias" "replica1" {
  provider      = aws.replica1
  name          = "alias/replicakey1"
  target_key_id = aws_kms_key.replica1.key_id
}

resource "aws_kms_key" "replica2" {
  provider                = aws.replica2
  description             = "Replica key 2 for S3 replication"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                 = data.aws_iam_policy_document.kms_replica2_policy.json
}
resource "aws_kms_alias" "replica2" {
  provider      = aws.replica2
  name          = "alias/replicakey2"
  target_key_id = aws_kms_key.replica2.key_id
}

# KMS key policies
data "aws_iam_policy_document" "kms_source1_policy" {
  statement {
    sid    = "EnableRootAdmin"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${local.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
  statement {
    sid    = "AllowS3Service"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }
  }
  statement {
    sid    = "AllowReplicationRoleDecrypt"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.replication_role.arn]
    }
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "kms_source2_policy" {
  statement {
    sid    = "EnableRootAdmin"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${local.account_id}:root"]
    }
    actions   = ["kms:*"]
