# ==================== IAM Role and Policy ====================

data "aws_iam_policy_document" "s3_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "replication_role" {
  provider           = aws.src1
  name               = "s3-replication-role"
  assume_role_policy = data.aws_iam_policy_document.s3_assume_role.json
}

data "aws_iam_policy_document" "replication_policy" {
  statement {
    sid    = "ListSourceBuckets"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]
    resources = local.src_bucket_arns
  }
  statement {
    sid    = "ReadSourceObjects"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetObjectTagging",
      "s3:GetObjectVersionTagging",
    ]
    resources = local.src_bucket_arn_objects
  }
  statement {
    sid    = "ReplicateToReplicaBuckets"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:PutObject",
      "s3:PutObjectTagging",
      "s3:PutObjectVersionTagging",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
    ]
    resources = local.replica_bucket_arn_objects
  }
  statement {
    sid    = "DecryptSourceKeys"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
    ]
    resources = [
      local.source_key1_arn,
      local.source_key2_arn,
    ]
  }
  statement {
    sid    = "EncryptReplicaKeys"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]
    resources = [
      local.replica_key1_arn,
      local.replica_key2_arn,
    ]
  }
}

resource "aws_iam_policy" "replication_policy" {
  provider    = aws.src1
  name        = "s3-replication-policy"
  description = "Policy for S3 cross-region replication"
  policy      = data.aws_iam_policy_document.replication_policy.json
}

resource "aws_iam_role_policy_attachment" "replication_policy_attach" {
  provider   = aws.src1
  role       = aws_iam_role.replication_role.name
  policy_arn = aws_iam_policy.replication_policy.arn
}

# ==================== S3 Buckets ====================

# Source region 1 buckets (data sources since they already exist from prior runs)
data "aws_s3_bucket" "src1" {
  provider = aws.src1
  for_each = local.src1_buckets
  bucket   = each.value
}

resource "aws_s3_bucket_versioning" "src1" {
  provider = aws.src1
  for_each = local.src1_buckets
  bucket   = data.aws_s3_bucket.src1[each.key].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "src1" {
  provider = aws.src1
  for_each = local.src1_buckets
  bucket   = data.aws_s3_bucket.src1[each.key].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "src1" {
  provider = aws.src1
  for_each = local.src1_buckets
  bucket   = data.aws_s3_bucket.src1[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = local.source_key1_arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# Source region 2 buckets (data sources since they already exist from prior runs)
data "aws_s3_bucket" "src2" {
  provider = aws.src2
  for_each = local.src2_buckets
  bucket   = each.value
