# ==================== Replication Configuration ====================

resource "aws_s3_bucket_replication_configuration" "src1_b1" {
  provider = aws.src1
  bucket   = local.src1_bucket1
  role     = aws_iam_role.replication_role.arn

  rule {
    id       = "ReplicateToReplica1"
    priority = 1
    status   = "Enabled"
    filter {}
    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
    destination {
      bucket        = "arn:aws:s3:::${local.r1_bucket1}"
      storage_class = "STANDARD"
      encryption_configuration {
        replica_kms_key_id = local.replica_key1_arn
      }
    }
    delete_marker_replication {
      status = "Enabled"
    }
  }

  rule {
    id       = "ReplicateToReplica2"
    priority = 2
    status   = "Enabled"
    filter {}
    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
    destination {
      bucket        = "arn:aws:s3:::${local.r2_bucket1}"
      storage_class = "STANDARD"
      encryption_configuration {
        replica_kms_key_id = local.replica_key2_arn
