terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.82.0, < 5.100.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

variable "repository_url" {
  type        = string
  default     = "https://github.com/example/guardduty-module"
  description = "URL of the module repository, used for tagging."
}

variable "create_findings_filter" {
  type    = bool
  default = false
}

variable "create_trusted_ip_set" {
  type    = bool
  default = false
}

variable "create_threat_intel_set" {
  type    = bool
  default = false
}

variable "create_malware_protection_plan" {
  type    = bool
  default = false
}

variable "create_export_bucket" {
  type    = bool
  default = false
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition
  common_tags = {
    RepositoryURL = var.repository_url
  }
}

resource "aws_guardduty_detector" "primary" {
  enable                       = true
  finding_publishing_frequency = "FIFTEEN_MINUTES"
  tags                         = local.common_tags
}

# ------------------------------------------------------------------------------
# GuardDuty detector features (always created)
# ------------------------------------------------------------------------------
resource "aws_guardduty_detector_feature" "s3_data_events" {
  detector_id = aws_guardduty_detector.primary.id
  name        = "S3_DATA_EVENTS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "rds_login_events" {
  detector_id = aws_guardduty_detector.primary.id
  name        = "RDS_LOGIN_EVENTS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "lambda_network_logs" {
  detector_id = aws_guardduty_detector.primary.id
  name        = "LAMBDA_NETWORK_LOGS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "eks_audit_logs" {
  detector_id = aws_guardduty_detector.primary.id
  name        = "EKS_AUDIT_LOGS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "ebs_malware_protection" {
  detector_id = aws_guardduty_detector.primary.id
  name        = "EBS_MALWARE_PROTECTION"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "runtime_monitoring" {
  detector_id = aws_guardduty_detector.primary.id
  name        = "RUNTIME_MONITORING"
  status      = "ENABLED"

  additional_configuration {
    name   = "EKS_ADDON_MANAGEMENT"
    status = "DISABLED"
  }

  additional_configuration {
    name   = "ECS_FARGATE_AGENT_MANAGEMENT"
    status = "DISABLED"
  }

  additional_configuration {
    name   = "EC2_AGENT_MANAGEMENT"
    status = "DISABLED"
  }
}

# ------------------------------------------------------------------------------
# Null resource to configure malware scan settings
# ------------------------------------------------------------------------------
resource "null_resource" "configure_malware_scan_settings" {
  triggers = {
    detector_id = aws_guardduty_detector.primary.id
  }

  provisioner "local-exec" {
    command = <<EOT
      aws guardduty update-malware-scan-settings \
        --detector-id ${aws_guardduty_detector.primary.id} \
        --region us-east-1 \
        --cli-input-json '{"EbsSnapshotPreservation":"NO_RETENTION"}'
    EOT
  }
}

# ------------------------------------------------------------------------------
# Conditional resources – findings filter
# ------------------------------------------------------------------------------
resource "aws_guardduty_filter" "findings_filter" {
  count = var.create_findings_filter ? 1 : 0

  detector_id = aws_guardduty_detector.primary.id
  name        = "example-filter"
  rank        = 1
  action      = "ARCHIVE"
  description = "Example findings filter"

  finding_criteria {
    criterion {
      field  = "service.archived"
      equals = ["false"]
    }
  }

  tags = local.common_tags
}

# ------------------------------------------------------------------------------
# Conditional resources – trusted IP set
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "trusted_ip_set" {
  count  = var.create_trusted_ip_set ? 1 : 0
  bucket = "guardduty-trusted-ip-set-${local.account_id}-${local.region}"
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "trusted_ip_set" {
  count  = var.create_trusted_ip_set ? 1 : 0
  bucket = aws_s3_bucket.trusted_ip_set[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "trusted_ip_set" {
  count  = var.create_trusted_ip_set ? 1 : 0
  bucket = aws_s3_bucket.trusted_ip_set[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "trusted_ip_set" {
  count  = var.create_trusted_ip_set ? 1 : 0
  bucket = aws_s3_bucket.trusted_ip_set[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_object" "trusted_ip_set_file" {
  count  = var.create_trusted_ip_set ? 1 : 0
  bucket = aws_s3_bucket.trusted_ip_set[0].id
  key    = "ip-set.txt"
  content = "10.0.0.0/8\n"
  etag   = md5("10.0.0.0/8\n")
}

resource "aws_guardduty_ipset" "trusted_ip_set" {
  count       = var.create_trusted_ip_set ? 1 : 0
  detector_id = aws_guardduty_detector.primary.id
  name        = "example-trusted-ip-set"
  format      = "TXT"
  location    = "arn:${local.partition}:s3:::${aws_s3_bucket.trusted_ip_set[0].id}/${aws_s3_object.trusted_ip_set_file[0].key}"
  activate    = true
  tags        = local.common_tags
}

