# ------------------------------------------------------------------------------
# Conditional resources – malware protection plan for S3
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "malware_protection_plan" {
  count  = var.create_malware_protection_plan ? 1 : 0
  bucket = "guardduty-malware-protection-plan-${local.account_id}-${local.region}"
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "malware_protection_plan" {
  count  = var.create_malware_protection_plan ? 1 : 0
  bucket = aws_s3_bucket.malware_protection_plan[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "malware_protection_plan" {
  count  = var.create_malware_protection_plan ? 1 : 0
  bucket = aws_s3_bucket.malware_protection_plan[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "malware_protection_plan" {
  count  = var.create_malware_protection_plan ? 1 : 0
  bucket = aws_s3_bucket.malware_protection_plan[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "malware_protection" {
  count = var.create_malware_protection_plan ? 1 : 0
  name  = "guardduty-malware-protection-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "malware-protection.guardduty.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_policy" "malware_protection" {
  count = var.create_malware_protection_plan ? 1 : 0
  name  = "guardduty-malware-protection-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.malware_protection_plan[0].arn,
          "${aws_s3_bucket.malware_protection_plan[0].arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "malware_protection" {
  count = var.create_malware_protection_plan ? 1 : 0
  role       = aws_iam_role.malware_protection[0].name
  policy_arn = aws_iam_policy.malware_protection[0].arn
}

resource "aws_guardduty_malware_protection_plan" "malware_protection_plan" {
  count = var.create_malware_protection_plan ? 1 : 0
  role  = aws_iam_role.malware_protection[0].arn

  protected_resource {
    s3_bucket {
      bucket_name    = aws_s3_bucket.malware_protection_plan[0].id
      object_prefixes = []
    }
  }

  tags = local.common_tags
}

# ------------------------------------------------------------------------------
# Conditional resources – export bucket with KMS, versioning, access logs
# (cross‑region replication omitted per provider block restriction)
# ------------------------------------------------------------------------------
resource "aws_kms_key" "export" {
  count                   = var.create_export_bucket ? 1 : 0
  description             = "KMS key for GuardDuty export bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "export" {
  count         = var.create_export_bucket ? 1 : 0
  name          = "alias/guardduty-export-key"
  target_key_id = aws_kms_key.export[0].key_id
}

resource "aws_s3_bucket" "export_access_logs" {
  count  = var.create_export_bucket ? 1 : 0
  bucket = "guardduty-export-logs-${local.account_id}-${local.region}"
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "export_access_logs" {
  count  = var.create_export_bucket ? 1 : 0
  bucket = aws_s3_bucket.export_access_logs[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "export_access_logs" {
  count  = var.create_export_bucket ? 1 : 0
  bucket = aws_s3_bucket.export_access_logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "export_access_logs" {
  count  = var.create_export_bucket ? 1 : 0
  bucket = aws_s3_bucket.export_access_logs[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket" "export" {
  count  = var.create_export_bucket ? 1 : 0
  bucket = "guardduty-export-${local.account_id}-${local.region}"
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "export" {
  count  = var.create_export_bucket ? 1 : 0
  bucket = aws_s3_bucket.export[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "export" {
  count  = var.create_export_bucket ? 1 : 0
  bucket = aws_s3_bucket.export[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.export[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "export" {
  count  = var.create_export_bucket ? 1 : 0
  bucket = aws_s3_bucket.export[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "export" {
  count  = var.create_export_bucket ? 1 : 0
  bucket = aws_s3_bucket.export[0].id

  target_bucket = aws_s3_bucket.export_access_logs[0].id
  target_prefix = "log/"
}

# ------------------------------------------------------------------------------
# GuardDuty publishing destination (if export bucket is created)
# ------------------------------------------------------------------------------
resource "aws_guardduty_publishing_destination" "export" {
  count           = var.create_export_bucket ? 1 : 0
  detector_id     = aws_guardduty_detector.primary.id
  destination_arn = aws_s3_bucket.export[0].arn
  kms_key_arn     = aws_kms_key.export[0].arn

  depends_on = [aws_s3_bucket_policy.export_publishing]
}

resource "aws_s3_bucket_policy" "export_publishing" {
  count  = var.create_export_bucket ? 1 : 0
  bucket = aws_s3_bucket.export[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action = "s3:PutObject"
        Resource = "${aws_s3_bucket.export[0].arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })
}

resource "aws_kms_key_policy" "export" {
  count  = var.create_export_bucket ? 1 : 0
  key_id = aws_kms_key.export[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      },
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action = "kms:*"
        Resource = "*"
      }
    ]
  })
}
